input.content:
export type ModelId = "katara" | "sokka" | "yako";

export type CategoryKey =
  | "weapons"
  | "creatures"
  | "worlds"
  | "mechanics"
  | "shaders"
  | "magic"
  | "quests"
  | "interface"
  | "audio"
  | "vehicles"
  | "items"
  | "characters";

export type GameId = "minecraft" | "skyrim" | "stardew" | "terraria" | "cyberpunk";

export type EmblemKey = "cube" | "dragon" | "sprout" | "tree" | "chip";

export interface Game {
  id: GameId;
  name: string;
  /** Short label used where space is tight. */
  short: string;
  /** Mod toolchain, e.g. "Fabric · Java 21". */
  toolchain: string;
  language: CodeLanguage;
  /** Neon accent used for the branch, as an "r g b" triple. */
  rgb: string;
  emblem: EmblemKey;
  blurb: string;
  aliases: string[];
  categories: CategoryKey[];
}

export interface CategoryMeta {
  key: CategoryKey;
  label: string;
  rgb: string;
  description: string;
  keywords: string[];
}

export type CodeLanguage = "java" | "papyrus" | "csharp" | "lua" | "json" | "markdown" | "xml" | "toml" | "text";

export interface ModFile {
  path: string;
  language: CodeLanguage;
  content: string;
}

export interface ModVersion {
  id: string;
  label: string;
  createdAt: number;
  model: ModelId;
  credits: number;
  prompt: string;
  summary: string;
  files: ModFile[];
  additions: number;
  deletions: number;
}

export interface Mod {
  id: string;
  gameId: GameId;
  category: CategoryKey;
  name: string;
  summary: string;
  createdAt: number;
  tags: string[];
  /** Seed mods have their files built lazily from the engine templates. */
  seed?: boolean;
  versions: ModVersion[];
  activeVersionId?: string;
}

export interface ModelMeta {
  id: ModelId;
  name: string;
  credits: number;
  tagline: string;
  description: string;
  rgb: string;
  /** Visual pacing for the simulated stream. */
  chunk: [number, number];
  tick: number;
}

export type Level = "core" | "game" | "category" | "mod";

export interface Selection {
  level: Level;
  gameId?: GameId;
  category?: CategoryKey;
  modId?: string;
}

/** Events streamed from /api/generate as NDJSON lines. */
export type GenEvent =
  | { type: "start"; jobId: string; model: ModelId; credits: number }
  | { type: "route"; gameId: GameId; category: CategoryKey; modName: string; modId: string; summary: string; tags: string[] }
  | { type: "think"; id: string; label: string; detail?: string }
  | { type: "think-done"; id: string }
  | { type: "file"; path: string; language: CodeLanguage }
  | { type: "chunk"; path: string; text: string }
  | { type: "file-done"; path: string }
  | { type: "done"; summary: string; notes: string }
  | { type: "error"; message: string };

