@import "tailwindcss";

@custom-variant dark (&:where(.dark, .dark *));
@custom-variant light (&:where(.light, .light *));

/* ───────────────────────── Theme tokens ───────────────────────── */

:root {
  color-scheme: dark;
  --bg: #05030b;
  --bg-2: #0a0617;
  --bg-3: #140b2b;
  --surface: rgb(15 10 32 / 0.6);
  --surface-2: rgb(22 15 46 / 0.78);
  --surface-3: rgb(40 27 80 / 0.55);
  --solid: #0e091e;
  --line: rgb(167 139 250 / 0.13);
  --line-2: rgb(167 139 250 / 0.26);
  --ink: #f2eeff;
  --ink-2: #cfc7f0;
  --muted: #958cc0;
  --faint: #5f5789;
  --accent: #a78bfa;
  --accent-ink: #c4b5fd;
  --cyan: #67e8f9;
  --pink: #f0abfc;
  --glow: 167 139 250;
  --panel-shadow: 0 30px 80px -24px rgb(0 0 0 / 0.8), inset 0 1px 0 rgb(255 255 255 / 0.04);
  --code-bg: rgb(7 4 18 / 0.55);
  --tok-k: #c792ea;
  --tok-s: #a8e6a3;
  --tok-n: #f8b26a;
  --tok-c: #6c6497;
  --tok-t: #82d8ff;
  --tok-f: #93b6ff;
  --tok-p: #8f87b8;
  --tok-a: #f0abfc;
  --tok-v: #f5c2e7;
}

:root.light {
  color-scheme: light;
  --bg: #fdfcff;
  --bg-2: #f7f4ff;
  --bg-3: #ede7ff;
  --surface: rgb(255 255 255 / 0.66);
  --surface-2: rgb(255 255 255 / 0.86);
  --surface-3: rgb(243 238 255 / 0.9);
  --solid: #ffffff;
  --line: rgb(91 33 182 / 0.1);
  --line-2: rgb(91 33 182 / 0.2);
  --ink: #160f2c;
  --ink-2: #3a3162;
  --muted: #6b6390;
  --faint: #a8a1c6;
  --accent: #7c3aed;
  --accent-ink: #6d28d9;
  --cyan: #0891b2;
  --pink: #c026d3;
  --glow: 124 58 237;
  --panel-shadow: 0 24px 60px -28px rgb(76 29 149 / 0.3), inset 0 1px 0 rgb(255 255 255 / 0.9);
  --code-bg: rgb(250 248 255 / 0.8);
  --tok-k: #8a2bc5;
  --tok-s: #23803a;
  --tok-n: #c2410c;
  --tok-c: #9c95bb;
  --tok-t: #0369a1;
  --tok-f: #4338ca;
  --tok-p: #6b6490;
  --tok-a: #be185d;
  --tok-v: #9d174d;
}

@theme inline {
  --color-bg: var(--bg);
  --color-bg-2: var(--bg-2);
  --color-bg-3: var(--bg-3);
  --color-surface: var(--surface);
  --color-surface-2: var(--surface-2);
  --color-surface-3: var(--surface-3);
  --color-solid: var(--solid);
  --color-line: var(--line);
  --color-line-2: var(--line-2);
  --color-ink: var(--ink);
  --color-ink-2: var(--ink-2);
  --color-muted: var(--muted);
  --color-faint: var(--faint);
  --color-accent: var(--accent);
  --color-accent-ink: var(--accent-ink);
  --color-cyan: var(--cyan);
  --color-pink: var(--pink);
  --font-sans: var(--font-inter), ui-sans-serif, system-ui, sans-serif;
  --font-display: var(--font-space), var(--font-inter), ui-sans-serif, sans-serif;
  --font-mono: var(--font-jb), ui-monospace, SFMono-Regular, Menlo, monospace;
  --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-spring: cubic-bezier(0.34, 1.56, 0.64, 1);
}

@property --angle {
  syntax: "<angle>";
  initial-value: 0deg;
  inherits: false;
}

html,
body {
  height: 100%;
  background: var(--bg);
  color: var(--ink);
}

body {
  overflow: hidden;
  -webkit-font-smoothing: antialiased;
  font-feature-settings: "ss01", "cv11";
}

::selection {
  background: rgb(var(--glow) / 0.35);
}

* {
  scrollbar-width: thin;
  scrollbar-color: rgb(var(--glow) / 0.28) transparent;
}

/* Theme switch: crossfade everything once instead of per-element transitions. */
.theme-swap,
.theme-swap * {
  transition:
    background-color 0.5s ease,
    border-color 0.5s ease,
    color 0.4s ease,
    fill 0.4s ease,
    box-shadow 0.5s ease !important;
}

/* ───────────────────────── Surfaces ───────────────────────── */

.glass {
  background: linear-gradient(180deg, var(--surface-2), var(--surface));
  backdrop-filter: blur(22px) saturate(160%);
  -webkit-backdrop-filter: blur(22px) saturate(160%);
  border: 1px solid var(--line);
  box-shadow: var(--panel-shadow);
}

.glass-soft {
  background: var(--surface);
  backdrop-filter: blur(14px) saturate(140%);
  -webkit-backdrop-filter: blur(14px) saturate(140%);
  border: 1px solid var(--line);
}

.hairline-top {
  position: relative;
}
.hairline-top::before {
  content: "";
  position: absolute;
  inset: 0 12% auto 12%;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgb(var(--glow) / 0.55), rgb(103 232 249 / 0.45), transparent);
  pointer-events: none;
}
.light .hairline-top::before {
  background: linear-gradient(90deg, transparent, rgb(124 58 237 / 0.35), rgb(8 145 178 / 0.3), transparent);
}

.text-glow {
  text-shadow: 0 0 18px rgb(var(--glow) / 0.55);
}
.light .text-glow {
  text-shadow: none;
}

.tint {
  --cc: rgb(var(--c));
  --cc-ink: color-mix(in oklab, rgb(var(--c)) 55%, white);
}
.light .tint {
  --cc: color-mix(in oklab, rgb(var(--c)) 70%, #1b1236);
  --cc-ink: color-mix(in oklab, rgb(var(--c)) 62%, #1b1236);
}

.btn-ghost {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.4rem;
  border-radius: 0.7rem;
  color: var(--ink-2);
  transition:
    background-color 0.2s,
    color 0.2s,
    box-shadow 0.2s,
    transform 0.2s var(--ease-spring);
}
.btn-ghost:hover {
  background: rgb(var(--glow) / 0.1);
  color: var(--ink);
}
.btn-ghost:active {
  transform: scale(0.94);
}

.kbd {
  font-family: var(--font-jb), monospace;
  font-size: 10px;
  line-height: 1;
  padding: 3px 5px;
  border-radius: 5px;
  border: 1px solid var(--line-2);
  color: var(--muted);
  background: rgb(var(--glow) / 0.06);
}

.shimmer-text {
  background: linear-gradient(
    100deg,
    var(--ink-2) 0%,
    var(--ink-2) 35%,
    #fff 46%,
    var(--cyan) 52%,
    var(--ink-2) 64%,
    var(--ink-2) 100%
  );
  background-size: 250% 100%;
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  animation: shimmer 2.2s linear infinite;
}
.light .shimmer-text {
  background-image: linear-gradient(
    100deg,
    var(--ink-2) 0%,
    var(--ink-2) 35%,
    var(--accent) 46%,
    var(--cyan) 52%,
    var(--ink-2) 64%,
    var(--ink-2) 100%
  );
}

/* ───────────────────────── Cosmos backdrop ───────────────────────── */

.cosmos {
  position: fixed;
  inset: 0;
  overflow: hidden;
  pointer-events: none;
  background:
    radial-gradient(120% 90% at 50% 46%, #150b30 0%, #0a0619 42%, #05030b 78%),
    var(--bg);
}
.light .cosmos {
  background:
    radial-gradient(110% 85% at 50% 46%, #ffffff 0%, #fbf9ff 45%, #f4f0ff 100%),
    var(--bg);
}

.nebula {
  position: absolute;
  border-radius: 50%;
  filter: blur(70px);
  opacity: 0.55;
  mix-blend-mode: screen;
  animation: nebula-drift 38s ease-in-out infinite alternate;
}
.light .nebula {
  mix-blend-mode: multiply;
  opacity: 0.32;
}

.aurora {
  position: absolute;
  left: -25%;
  width: 150%;
  height: 46vh;
  opacity: 0.38;
  filter: blur(26px) saturate(130%);
  mix-blend-mode: screen;
  background: linear-gradient(
    90deg,
    transparent 0%,
    rgb(52 211 153 / 0.85) 18%,
    rgb(103 232 249 / 0.8) 34%,
    rgb(167 139 250 / 0.9) 52%,
    rgb(240 171 252 / 0.75) 70%,
    rgb(129 140 248 / 0.7) 84%,
    transparent 100%
  );
  background-size: 200% 100%;
  -webkit-mask-image:
    repeating-linear-gradient(90deg, #000 0 3px, rgb(0 0 0 / 0.35) 3px 7px, #000 7px 9px, transparent 9px 14px),
    linear-gradient(180deg, transparent 0%, #000 38%, #000 52%, transparent 100%);
  -webkit-mask-composite: source-in;
  mask-image:
    repeating-linear-gradient(90deg, #000 0 3px, rgb(0 0 0 / 0.35) 3px 7px, #000 7px 9px, transparent 9px 14px),
    linear-gradient(180deg, transparent 0%, #000 38%, #000 52%, transparent 100%);
  mask-composite: intersect;
  animation:
    aurora-flow 26s linear infinite,
    aurora-sway 17s ease-in-out infinite alternate;
}
.aurora.soft {
  filter: blur(60px);
  opacity: 0.22;
  -webkit-mask-image: linear-gradient(180deg, transparent 0%, #000 40%, #000 55%, transparent 100%);
  mask-image: linear-gradient(180deg, transparent 0%, #000 40%, #000 55%, transparent 100%);
}
.light .aurora {
  mix-blend-mode: multiply;
  opacity: 0.2;
  filter: blur(30px) saturate(115%);
}
.light .aurora.soft {
  opacity: 0.16;
  filter: blur(60px);
}

.vignette {
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 50% 50%, transparent 52%, rgb(2 1 6 / 0.65) 100%);
}
.light .vignette {
  background: radial-gradient(ellipse at 50% 50%, transparent 60%, rgb(124 58 237 / 0.05) 100%);
}

.grain {
  position: absolute;
  inset: -50%;
  opacity: 0.05;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='180' height='180'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='2' stitchTiles='stitch'/></filter><rect width='100%' height='100%' filter='url(%23n)'/></svg>");
  animation: grain 9s steps(6) infinite;
}
.light .grain {
  opacity: 0.035;
}

/* ───────────────────────── Network stage ───────────────────────── */

.stage {
  position: absolute;
  inset: 0;
  overflow: hidden;
  touch-action: none;
  cursor: grab;
  user-select: none;
}
.stage.is-panning {
  cursor: grabbing;
}
.stage canvas {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.world {
  position: absolute;
  left: 0;
  top: 0;
  width: 0;
  height: 0;
  transform-origin: 0 0;
  opacity: 0;
  transition: opacity 1.2s ease;
}
.world.is-ready {
  opacity: 1;
}

.node {
  position: absolute;
  left: 0;
  top: 0;
  width: 0;
  height: 0;
  transition:
    opacity 0.6s ease,
    filter 0.6s ease;
}
.node[data-state="off"] {
  opacity: 0.14;
  filter: saturate(0.25);
}
.node[data-state="near"] {
  opacity: 0.6;
}
.node.is-dragging {
  z-index: 20;
}

.n-orb {
  position: absolute;
  width: var(--s);
  height: var(--s);
  left: calc(var(--s) / -2);
  top: calc(var(--s) / -2);
  display: grid;
  place-items: center;
  cursor: pointer;
  outline: none;
  transition:
    transform 0.45s var(--ease-spring),
    box-shadow 0.4s ease,
    background 0.4s ease;
}
.node:hover .n-orb,
.n-orb:focus-visible {
  transform: scale(1.12);
}
.node.is-dragging .n-orb {
  transform: scale(1.18);
  cursor: grabbing;
}

.n-aura {
  position: absolute;
  width: var(--a);
  height: var(--a);
  left: calc(var(--a) / -2);
  top: calc(var(--a) / -2);
  border-radius: 50%;
  pointer-events: none;
  background: radial-gradient(circle, rgb(var(--c) / 0.3), rgb(var(--c) / 0.08) 38%, transparent 68%);
  transition:
    transform 0.6s var(--ease-out-expo),
    opacity 0.6s;
}
.light .n-aura {
  background: radial-gradient(circle, rgb(var(--c) / 0.22), rgb(var(--c) / 0.06) 40%, transparent 68%);
}
.node:hover .n-aura,
.node.is-selected .n-aura {
  transform: scale(1.25);
}

.n-label {
  position: absolute;
  left: 0;
  top: calc(var(--s) / 2 + 9px);
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  white-space: nowrap;
  pointer-events: none;
  transition:
    opacity 0.35s ease,
    transform 0.35s var(--ease-out-expo);
}
.n-title {
  font-family: var(--font-space), sans-serif;
  font-weight: 600;
  letter-spacing: 0.01em;
  color: var(--ink);
  text-shadow:
    0 0 14px rgb(var(--c) / 0.55),
    0 1px 2px rgb(0 0 0 / 0.9);
}
.light .n-title {
  text-shadow:
    0 0 10px rgb(255 255 255 / 1),
    0 0 3px rgb(255 255 255 / 1);
}
.n-sub {
  font-size: 9.5px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--cc-ink);
  opacity: 0.85;
}
.light .n-sub {
  text-shadow: 0 0 6px #fff;
}

/* Game node — glowing orb with an orbit ring */
.n-game {
  --s: 70px;
  --a: 210px;
}
.n-game .n-orb {
  border-radius: 50%;
  color: var(--cc-ink);
  background:
    radial-gradient(circle at 34% 28%, rgb(255 255 255 / 0.28), transparent 32%),
    radial-gradient(circle at 50% 60%, rgb(var(--c) / 0.42), rgb(var(--c) / 0.12) 55%, rgb(10 6 24 / 0.92) 80%);
  border: 1px solid rgb(var(--c) / 0.65);
  box-shadow:
    0 0 26px rgb(var(--c) / 0.5),
    0 0 70px rgb(var(--c) / 0.18),
    inset 0 0 18px rgb(var(--c) / 0.4);
}
.n-game .n-orb svg {
  width: 32px;
  height: 32px;
  filter: drop-shadow(0 0 6px rgb(var(--c) / 0.9));
}
.light .n-game .n-orb {
  background:
    radial-gradient(circle at 34% 28%, #fff, transparent 40%),
    radial-gradient(circle at 50% 60%, rgb(var(--c) / 0.28), rgb(var(--c) / 0.08) 60%, #fff 85%);
  border-color: color-mix(in oklab, rgb(var(--c)) 70%, #1b1236);
  box-shadow:
    0 10px 28px -6px rgb(var(--c) / 0.55),
    0 0 0 5px rgb(var(--c) / 0.1),
    inset 0 -6px 14px rgb(var(--c) / 0.18);
}
.light .n-game .n-orb svg {
  filter: none;
}
.n-ring {
  position: absolute;
  width: calc(var(--s) + 16px);
  height: calc(var(--s) + 16px);
  left: calc((var(--s) + 16px) / -2);
  top: calc((var(--s) + 16px) / -2);
  border-radius: 50%;
  pointer-events: none;
  background: conic-gradient(
    from 0deg,
    transparent 0 12%,
    rgb(var(--c) / 0.95) 22%,
    transparent 36% 58%,
    rgb(var(--c) / 0.6) 70%,
    transparent 82%
  );
  -webkit-mask: radial-gradient(circle, transparent calc(50% - 1.6px), #000 calc(50% - 1px));
  mask: radial-gradient(circle, transparent calc(50% - 1.6px), #000 calc(50% - 1px));
  animation: spin 9s linear infinite;
}
.n-orbit {
  position: absolute;
  width: calc(var(--s) + 38px);
  height: calc(var(--s) + 38px);
  left: calc((var(--s) + 38px) / -2);
  top: calc((var(--s) + 38px) / -2);
  border-radius: 50%;
  border: 1px dashed rgb(var(--c) / 0.3);
  pointer-events: none;
  animation: spin 40s linear infinite reverse;
}
.n-game .n-label {
  top: calc(var(--s) / 2 + 24px);
}
.n-game .n-title {
  font-size: 15px;
}

/* Category node — rotated plate with a custom icon */
.n-cat {
  --s: 44px;
  --a: 120px;
}
.n-cat .n-orb {
  border-radius: 14px;
  transform: rotate(45deg);
  color: var(--cc-ink);
  background:
    linear-gradient(135deg, rgb(var(--c) / 0.32), rgb(12 8 28 / 0.9) 70%),
    rgb(12 8 28 / 0.9);
  border: 1px solid rgb(var(--c) / 0.6);
  box-shadow:
    0 0 18px rgb(var(--c) / 0.45),
    inset 0 0 12px rgb(var(--c) / 0.3);
}
.node.n-cat:hover .n-orb,
.n-cat .n-orb:focus-visible {
  transform: rotate(45deg) scale(1.12);
}
.n-cat.is-dragging .n-orb {
  transform: rotate(45deg) scale(1.18);
}
.n-cat .n-orb svg {
  transform: rotate(-45deg);
  width: 22px;
  height: 22px;
  filter: drop-shadow(0 0 5px rgb(var(--c) / 0.85));
}
.light .n-cat .n-orb {
  background: linear-gradient(135deg, rgb(var(--c) / 0.22), #fff 75%);
  border-color: color-mix(in oklab, rgb(var(--c)) 65%, #1b1236);
  box-shadow:
    0 8px 20px -6px rgb(var(--c) / 0.55),
    0 0 0 4px rgb(var(--c) / 0.08);
}
.light .n-cat .n-orb svg {
  filter: none;
}
.n-cat .n-label {
  top: calc(var(--s) / 2 + 13px);
}
.n-cat .n-title {
  font-size: 12px;
}

/* Mod node — a bright star */
.n-mod {
  --s: 15px;
  --a: 64px;
}
.n-mod .n-orb {
  border-radius: 50%;
  background: radial-gradient(circle at 38% 34%, #fff 0 18%, rgb(var(--c)) 48%, rgb(var(--c) / 0.35) 75%);
  box-shadow:
    0 0 10px rgb(var(--c) / 0.9),
    0 0 26px rgb(var(--c) / 0.35);
}
.n-mod .n-orb::after {
  content: "";
  position: absolute;
  inset: -5px;
  border-radius: 50%;
  border: 1px solid rgb(var(--c) / 0.45);
  opacity: 0;
  transition: opacity 0.3s;
}
.node.n-mod:hover .n-orb::after,
.n-mod.is-selected .n-orb::after {
  opacity: 1;
}
.light .n-mod .n-orb {
  background: radial-gradient(circle at 38% 34%, #fff 0 18%, color-mix(in oklab, rgb(var(--c)) 80%, #1b1236) 52%, rgb(var(--c) / 0.6) 80%);
  box-shadow:
    0 3px 10px rgb(var(--c) / 0.65),
    0 0 0 3px rgb(var(--c) / 0.14);
}
.n-mod .n-label {
  top: calc(var(--s) / 2 + 7px);
}
.n-mod .n-title {
  font-size: 10.5px;
  font-weight: 500;
  padding: 2px 7px;
  border-radius: 999px;
  background: rgb(10 6 24 / 0.6);
  border: 1px solid rgb(var(--c) / 0.3);
  text-shadow: none;
}
.light .n-mod .n-title {
  background: rgb(255 255 255 / 0.85);
  border-color: rgb(var(--c) / 0.4);
  text-shadow: none;
}
.n-mod.is-forging .n-orb {
  animation: forge-pulse 0.9s ease-in-out infinite;
}

/* Semantic zoom: reveal labels as you get closer, or when in context. */
.n-cat .n-label,
.n-mod .n-label {
  opacity: 0;
  transform: translate(-50%, -4px);
}
.stage[data-zoom="mid"] .n-cat .n-label,
.stage[data-zoom="near"] .n-cat .n-label,
.stage[data-zoom="near"] .n-mod .n-label,
.node[data-label="show"] .n-label,
.node:hover .n-label,
.node.is-selected .n-label,
.node.is-dragging .n-label {
  opacity: 1;
  transform: translate(-50%, 0);
}
.node[data-state="off"] .n-label {
  opacity: 0 !important;
}

.node.is-selected .n-orb {
  box-shadow:
    0 0 0 2px rgb(var(--c) / 0.9),
    0 0 34px rgb(var(--c) / 0.75),
    0 0 90px rgb(var(--c) / 0.3);
}
.light .node.is-selected .n-orb {
  box-shadow:
    0 0 0 2px color-mix(in oklab, rgb(var(--c)) 75%, #1b1236),
    0 12px 32px -6px rgb(var(--c) / 0.6),
    0 0 0 8px rgb(var(--c) / 0.12);
}

.node.is-hit .n-orb {
  animation: node-hit 0.55s var(--ease-out-expo);
}
.node.is-new {
  animation: materialize 1.1s var(--ease-out-expo) both;
}

/* ───────────────────────── Cyrus Core ───────────────────────── */

.core {
  position: absolute;
  left: 0;
  top: 0;
  width: 0;
  height: 0;
  --e: 0;
  --p: 0;
  --f: 0;
  --a1: 0deg;
  --a2: 0deg;
  --a3: 0deg;
  --a4: 0deg;
  --a5: 0deg;
}
.core > * {
  position: absolute;
  left: 50%;
  top: 50%;
  translate: -50% -50%;
  pointer-events: none;
}

.core-bloom {
  width: 640px;
  height: 640px;
  border-radius: 50%;
  background: radial-gradient(
    circle,
    rgb(196 181 253 / 0.38) 0%,
    rgb(139 92 246 / 0.22) 18%,
    rgb(103 232 249 / 0.08) 34%,
    transparent 62%
  );
  opacity: calc(0.6 + var(--e) * 0.4 + var(--p) * 0.3);
  transform: scale(calc(0.92 + var(--e) * 0.22 + var(--p) * 0.14));
  mix-blend-mode: screen;
}
.light .core-bloom {
  mix-blend-mode: multiply;
  background: radial-gradient(
    circle,
    rgb(167 139 250 / 0.35) 0%,
    rgb(167 139 250 / 0.16) 20%,
    rgb(103 232 249 / 0.08) 36%,
    transparent 62%
  );
}

.core-web {
  width: 300px;
  height: 300px;
  opacity: calc(0.55 + var(--e) * 0.45);
  transform: rotate(var(--a5));
  color: rgb(196 181 253);
}
.light .core-web {
  color: rgb(109 40 217);
  opacity: calc(0.4 + var(--e) * 0.4);
}

.core-halo {
  width: var(--hs);
  height: var(--hs);
}
.core-halo .plane {
  width: 100%;
  height: 100%;
}
.core-halo.back {
  clip-path: inset(0 0 50% 0);
}
.core-halo.front {
  clip-path: inset(50% 0 0 0);
}
.core-halo circle {
  transition: stroke-opacity 0.3s;
}

.core-crown {
  width: 196px;
  height: 196px;
  transform: rotate(var(--a4));
  opacity: calc(0.5 + var(--e) * 0.5);
  color: rgb(221 214 254);
}
.light .core-crown {
  color: rgb(109 40 217);
}

.core-orb {
  width: 124px;
  height: 124px;
  border-radius: 50%;
  overflow: hidden;
  transform: scale(calc(1 + var(--p) * 0.07 + var(--e) * 0.05));
  background: radial-gradient(circle at 50% 50%, #2a1760 0%, #120a2c 70%);
  box-shadow:
    0 0 0 1px rgb(196 181 253 / 0.35),
    0 0 calc(40px + var(--e) * 40px) rgb(167 139 250 / calc(0.55 + var(--e) * 0.35)),
    0 0 calc(110px + var(--p) * 60px) rgb(103 232 249 / calc(0.18 + var(--p) * 0.3)),
    inset 0 0 30px rgb(167 139 250 / 0.6);
}
.light .core-orb {
  background: radial-gradient(circle at 50% 50%, #ede9fe 0%, #c4b5fd 70%);
  box-shadow:
    0 0 0 1px rgb(124 58 237 / 0.35),
    0 18px 40px -8px rgb(124 58 237 / calc(0.45 + var(--e) * 0.3)),
    0 0 calc(60px + var(--e) * 40px) rgb(167 139 250 / calc(0.35 + var(--e) * 0.3)),
    inset 0 -10px 30px rgb(124 58 237 / 0.45);
}
.core-orb > div {
  position: absolute;
  inset: 0;
  border-radius: 50%;
}
.core-plasma-a {
  inset: -30% !important;
  background: conic-gradient(
    from 0deg,
    #7c3aed,
    #22d3ee,
    #a78bfa,
    #f0abfc,
    #6366f1,
    #67e8f9,
    #7c3aed
  );
  filter: blur(14px);
  opacity: 0.85;
  transform: rotate(var(--a1));
}
.core-plasma-b {
  inset: -20% !important;
  background:
    radial-gradient(circle at 30% 30%, rgb(255 255 255 / 0.55), transparent 30%),
    radial-gradient(circle at 70% 65%, rgb(103 232 249 / 0.7), transparent 38%),
    radial-gradient(circle at 35% 75%, rgb(240 171 252 / 0.6), transparent 34%);
  filter: blur(6px);
  mix-blend-mode: screen;
  transform: rotate(calc(var(--a2) * -1.4));
}
.core-nucleus {
  inset: 28% !important;
  background: radial-gradient(circle, #fff 0%, rgb(237 233 254 / 0.95) 24%, rgb(196 181 253 / 0.5) 55%, transparent 72%);
  filter: blur(2px);
  transform: scale(calc(0.85 + var(--e) * 0.35 + var(--p) * 0.4));
  opacity: calc(0.75 + var(--e) * 0.25);
}
.core-glint {
  background:
    radial-gradient(ellipse 40% 26% at 36% 22%, rgb(255 255 255 / 0.55), transparent 70%),
    radial-gradient(circle at 50% 50%, transparent 58%, rgb(10 4 30 / 0.55) 100%);
}
.light .core-glint {
  background:
    radial-gradient(ellipse 40% 26% at 36% 22%, rgb(255 255 255 / 0.85), transparent 70%),
    radial-gradient(circle at 50% 50%, transparent 60%, rgb(76 29 149 / 0.35) 100%);
}

.core-hit {
  width: 132px;
  height: 132px;
  border-radius: 50%;
  pointer-events: auto !important;
  cursor: pointer;
}

.core-ripples > span {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 130px;
  height: 130px;
  margin: -65px 0 0 -65px;
  border-radius: 50%;
  border: 1.5px solid rgb(196 181 253 / 0.8);
  box-shadow:
    0 0 18px rgb(167 139 250 / 0.6),
    inset 0 0 18px rgb(103 232 249 / 0.35);
  animation: ripple 1.25s var(--ease-out-expo) forwards;
}
.core-ripples > span.big {
  border-color: rgb(103 232 249 / 0.9);
  animation-duration: 1.8s;
}
.light .core-ripples > span {
  border-color: rgb(124 58 237 / 0.6);
  box-shadow: 0 0 14px rgb(124 58 237 / 0.25);
}
.light .core-ripples > span.big {
  border-color: rgb(8 145 178 / 0.65);
}

.core-label {
  top: calc(50% + 128px) !important;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  white-space: nowrap;
}
.core-label .t {
  font-family: var(--font-space), sans-serif;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.42em;
  margin-right: -0.42em;
  color: var(--ink);
  text-shadow: 0 0 16px rgb(167 139 250 / 0.9);
}
.light .core-label .t {
  text-shadow: 0 0 8px #fff;
}
.core-label .s {
  font-family: var(--font-jb), monospace;
  font-size: 10px;
  letter-spacing: 0.1em;
  color: var(--muted);
}

/* ───────────────────────── Prompt dock ───────────────────────── */

.prompt-shell {
  position: relative;
  border-radius: 24px;
  --spin-speed: 9s;
}
.prompt-shell::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  padding: 1px;
  background: conic-gradient(
    from var(--angle),
    rgb(var(--glow) / 0.18) 0%,
    rgb(103 232 249 / 0.75) 12%,
    rgb(var(--glow) / 0.18) 26%,
    rgb(var(--glow) / 0.18) 48%,
    rgb(240 171 252 / 0.7) 62%,
    rgb(var(--glow) / 0.18) 76%
  );
  -webkit-mask:
    linear-gradient(#000 0 0) content-box,
    linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask:
    linear-gradient(#000 0 0) content-box,
    linear-gradient(#000 0 0);
  mask-composite: exclude;
  animation: border-spin var(--spin-speed) linear infinite;
  pointer-events: none;
  z-index: 2;
}
.prompt-shell::after {
  content: "";
  position: absolute;
  inset: -1px;
  border-radius: inherit;
  background: conic-gradient(
    from var(--angle),
    transparent 0%,
    rgb(103 232 249 / 0.5) 12%,
    transparent 28%,
    transparent 50%,
    rgb(240 171 252 / 0.45) 62%,
    transparent 78%
  );
  filter: blur(18px);
  opacity: 0.25;
  z-index: -1;
  animation: border-spin var(--spin-speed) linear infinite;
  transition: opacity 0.5s;
  pointer-events: none;
}
.prompt-shell[data-active="true"] {
  --spin-speed: 3.2s;
}
.prompt-shell[data-active="true"]::after {
  opacity: 0.6;
}
.prompt-shell[data-busy="true"] {
  --spin-speed: 1.3s;
}
.prompt-shell[data-busy="true"]::after {
  opacity: 0.85;
}
.light .prompt-shell::after {
  opacity: 0.18;
}
.light .prompt-shell[data-active="true"]::after {
  opacity: 0.35;
}

.prompt-textarea::placeholder {
  color: var(--faint);
}

.mic-live {
  background: linear-gradient(135deg, #f43f5e, #d946ef);
  color: #fff;
  box-shadow:
    0 0 0 0 rgb(244 63 94 / 0.6),
    0 0 22px rgb(244 63 94 / 0.55);
  animation: mic-ring 1.4s ease-out infinite;
}
.mic-bars span {
  display: block;
  width: 2.5px;
  border-radius: 2px;
  background: currentColor;
  animation: mic-bar 0.9s ease-in-out infinite;
}

.think-node {
  animation: think-node 1.6s ease-in-out infinite;
}
.think-edge {
  stroke-dasharray: 3 4;
  animation: dash-flow 0.8s linear infinite;
}

/* ───────────────────────── Code view ───────────────────────── */

.code {
  font-family: var(--font-jb), ui-monospace, monospace;
  font-size: 12.5px;
  line-height: 1.7;
  tab-size: 4;
  font-variant-ligatures: contextual;
}
.code .ln {
  color: var(--faint);
  user-select: none;
}
.code .line-new {
  animation: line-in 0.7s ease-out;
}
.tok-k { color: var(--tok-k); }
.tok-s { color: var(--tok-s); }
.tok-n { color: var(--tok-n); }
.tok-c { color: var(--tok-c); font-style: italic; }
.tok-t { color: var(--tok-t); }
.tok-f { color: var(--tok-f); }
.tok-p { color: var(--tok-p); }
.tok-a { color: var(--tok-a); }
.tok-v { color: var(--tok-v); }

.caret {
  display: inline-block;
  width: 7px;
  height: 1.15em;
  margin-left: 1px;
  vertical-align: -0.2em;
  border-radius: 1px;
  background: var(--cyan);
  box-shadow: 0 0 10px var(--cyan);
  animation: caret 0.9s steps(1) infinite;
}

.write-head {
  background: linear-gradient(90deg, rgb(103 232 249 / 0.12), rgb(167 139 250 / 0.06) 60%, transparent);
}
.light .write-head {
  background: linear-gradient(90deg, rgb(8 145 178 / 0.1), rgb(124 58 237 / 0.04) 60%, transparent);
}

.md h1, .md h2, .md h3 {
  font-family: var(--font-space), sans-serif;
  color: var(--ink);
  font-weight: 600;
}
.md h1 { font-size: 1.05rem; margin: 0.2rem 0 0.6rem; }
.md h2 { font-size: 0.92rem; margin: 1rem 0 0.4rem; }
.md h3 { font-size: 0.85rem; margin: 0.8rem 0 0.3rem; }
.md p { margin: 0.35rem 0; color: var(--ink-2); }
.md ul, .md ol { margin: 0.3rem 0 0.5rem; padding-left: 1.1rem; color: var(--ink-2); }
.md ul { list-style: none; padding-left: 0.2rem; }
.md ul li { position: relative; padding-left: 1rem; margin: 0.22rem 0; }
.md ul li::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0.62em;
  width: 5px;
  height: 5px;
  border-radius: 2px;
  transform: rotate(45deg);
  background: var(--accent);
  box-shadow: 0 0 8px var(--accent);
}
.md ol { list-style: decimal; }
.md ol li { margin: 0.22rem 0; }
.md code {
  font-family: var(--font-jb), monospace;
  font-size: 0.8em;
  padding: 1px 5px;
  border-radius: 5px;
  background: rgb(var(--glow) / 0.1);
  color: var(--accent-ink);
}
.md pre {
  font-family: var(--font-jb), monospace;
  font-size: 11.5px;
  padding: 0.7rem 0.8rem;
  border-radius: 10px;
  background: var(--code-bg);
  border: 1px solid var(--line);
  overflow-x: auto;
  margin: 0.5rem 0;
  color: var(--ink-2);
}
.md strong { color: var(--ink); font-weight: 600; }

/* ───────────────────────── Keyframes ───────────────────────── */

@keyframes spin {
  to { transform: rotate(360deg); }
}
@keyframes border-spin {
  to { --angle: 360deg; }
}
@keyframes shimmer {
  0% { background-position: 120% 0; }
  100% { background-position: -120% 0; }
}
@keyframes nebula-drift {
  0% { transform: translate3d(0, 0, 0) scale(1); }
  50% { transform: translate3d(3%, -2%, 0) scale(1.08); }
  100% { transform: translate3d(-3%, 2%, 0) scale(0.96); }
}
@keyframes aurora-flow {
  0% { background-position: 0% 0; }
  100% { background-position: -200% 0; }
}
@keyframes aurora-sway {
  0% { transform: rotate(var(--r, -12deg)) skewX(-8deg) translateY(0) scaleY(1); }
  50% { transform: rotate(var(--r, -12deg)) skewX(6deg) translateY(-3%) scaleY(1.15); }
  100% { transform: rotate(var(--r, -12deg)) skewX(-4deg) translateY(2%) scaleY(0.9); }
}
@keyframes grain {
  0%, 100% { transform: translate(0, 0); }
  20% { transform: translate(-3%, 2%); }
  40% { transform: translate(2%, -3%); }
  60% { transform: translate(-2%, -1%); }
  80% { transform: translate(3%, 3%); }
}
@keyframes ripple {
  0% { transform: scale(0.85); opacity: 0.9; }
  100% { transform: scale(2.6); opacity: 0; }
}
@keyframes node-hit {
  0% { transform: scale(1); }
  30% { transform: scale(1.32); filter: brightness(1.8); }
  100% { transform: scale(1); }
}
@keyframes forge-pulse {
  0%, 100% { transform: scale(1); filter: brightness(1); }
  50% { transform: scale(1.5); filter: brightness(1.7); }
}
@keyframes materialize {
  0% { opacity: 0; filter: blur(8px) brightness(3); }
  40% { opacity: 1; }
  100% { opacity: 1; filter: blur(0) brightness(1); }
}
@keyframes caret {
  0%, 49% { opacity: 1; }
  50%, 100% { opacity: 0; }
}
@keyframes line-in {
  0% { background: rgb(103 232 249 / 0.14); }
  100% { background: transparent; }
}
@keyframes mic-ring {
  0% { box-shadow: 0 0 0 0 rgb(244 63 94 / 0.55), 0 0 22px rgb(244 63 94 / 0.5); }
  100% { box-shadow: 0 0 0 14px rgb(244 63 94 / 0), 0 0 22px rgb(244 63 94 / 0.5); }
}
@keyframes mic-bar {
  0%, 100% { height: 4px; }
  50% { height: 14px; }
}
@keyframes think-node {
  0%, 100% { opacity: 0.35; transform: scale(0.8); }
  50% { opacity: 1; transform: scale(1.15); }
}
@keyframes dash-flow {
  to { stroke-dashoffset: -14; }
}
@keyframes rise-in {
  from { opacity: 0; transform: translateY(10px) scale(0.98); filter: blur(4px); }
  to { opacity: 1; transform: translateY(0) scale(1); filter: blur(0); }
}
@keyframes fade-in {
  from { opacity: 0; }
  to { opacity: 1; }
}
@keyframes slide-in-right {
  from { opacity: 0; transform: translateX(28px); }
  to { opacity: 1; transform: translateX(0); }
}
@keyframes pop-in {
  from { opacity: 0; transform: translateY(6px) scale(0.96); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}
@keyframes progress-sheen {
  from { transform: translateX(-100%); }
  to { transform: translateX(250%); }
}
@keyframes orbit-dot {
  from { transform: rotate(0deg) translateX(7px) rotate(0deg); }
  to { transform: rotate(360deg) translateX(7px) rotate(-360deg); }
}

.animate-rise { animation: rise-in 0.55s var(--ease-out-expo) both; }
.animate-fade { animation: fade-in 0.4s ease both; }
.animate-slide-right { animation: slide-in-right 0.5s var(--ease-out-expo) both; }
.animate-pop { animation: pop-in 0.28s var(--ease-out-expo) both; }

@media (prefers-reduced-motion: reduce) {
  .aurora,
  .nebula,
  .grain,
  .n-ring,
  .n-orbit {
    animation: none !important;
  }
}

toolu_015usetgg6TVWZShjy3LzebW.content:
@import "tailwindcss";

@custom-variant dark (&:where(.dark, .dark *));
@custom-variant light (&:where(.light, .light *));

/* ───────────────────────── Theme tokens ───────────────────────── */

:root {
  color-scheme: dark;
  --bg: #05030b;
  --bg-2: #0a0617;
  --bg-3: #140b2b;
  --surface: rgb(15 10 32 / 0.6);
  --surface-2: rgb(22 15 46 / 0.78);
  --surface-3: rgb(40 27 80 / 0.55);
  --solid: #0e091e;
  --line: rgb(167 139 250 / 0.13);
  --line-2: rgb(167 139 250 / 0.26);
  --ink: #f2eeff;
  --ink-2: #cfc7f0;
  --muted: #958cc0;
  --faint: #5f5789;
  --accent: #a78bfa;
  --accent-ink: #c4b5fd;
  --cyan: #67e8f9;
  --pink: #f0abfc;
  --glow: 167 139 250;
  --panel-shadow: 0 30px 80px -24px rgb(0 0 0 / 0.8), inset 0 1px 0 rgb(255 255 255 / 0.04);
  --code-bg: rgb(7 4 18 / 0.55);
  --tok-k: #c792ea;
  --tok-s: #a8e6a3;
  --tok-n: #f8b26a;
  --tok-c: #6c6497;
  --tok-t: #82d8ff;
  --tok-f: #93b6ff;
  --tok-p: #8f87b8;
  --tok-a: #f0abfc;
  --tok-v: #f5c2e7;
}

:root.light {
  color-scheme: light;
  --bg: #fdfcff;
  --bg-2: #f7f4ff;
  --bg-3: #ede7ff;
  --surface: rgb(255 255 255 / 0.66);
  --surface-2: rgb(255 255 255 / 0.86);
  --surface-3: rgb(243 238 255 / 0.9);
  --solid: #ffffff;
  --line: rgb(91 33 182 / 0.1);
  --line-2: rgb(91 33 182 / 0.2);
  --ink: #160f2c;
  --ink-2: #3a3162;
  --muted: #6b6390;
  --faint: #a8a1c6;
  --accent: #7c3aed;
  --accent-ink: #6d28d9;
  --cyan: #0891b2;
  --pink: #c026d3;
  --glow: 124 58 237;
  --panel-shadow: 0 24px 60px -28px rgb(76 29 149 / 0.3), inset 0 1px 0 rgb(255 255 255 / 0.9);
  --code-bg: rgb(250 248 255 / 0.8);
  --tok-k: #8a2bc5;
  --tok-s: #23803a;
  --tok-n: #c2410c;
  --tok-c: #9c95bb;
  --tok-t: #0369a1;
  --tok-f: #4338ca;
  --tok-p: #6b6490;
  --tok-a: #be185d;
  --tok-v: #9d174d;
}

@theme inline {
  --color-bg: var(--bg);
  --color-bg-2: var(--bg-2);
  --color-bg-3: var(--bg-3);
  --color-surface: var(--surface);
  --color-surface-2: var(--surface-2);
  --color-surface-3: var(--surface-3);
  --color-solid: var(--solid);
  --color-line: var(--line);
  --color-line-2: var(--line-2);
  --color-ink: var(--ink);
  --color-ink-2: var(--ink-2);
  --color-muted: var(--muted);
  --color-faint: var(--faint);
  --color-accent: var(--accent);
  --color-accent-ink: var(--accent-ink);
  --color-cyan: var(--cyan);
  --color-pink: var(--pink);
  --font-sans: var(--font-inter), ui-sans-serif, system-ui, sans-serif;
  --font-display: var(--font-space), var(--font-inter), ui-sans-serif, sans-serif;
  --font-mono: var(--font-jb), ui-monospace, SFMono-Regular, Menlo, monospace;
  --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-spring: cubic-bezier(0.34, 1.56, 0.64, 1);
}

@property --angle {
  syntax: "<angle>";
  initial-value: 0deg;
  inherits: false;
}

html,
body {
  height: 100%;
  background: var(--bg);
  color: var(--ink);
}

body {
  overflow: hidden;
  -webkit-font-smoothing: antialiased;
  font-feature-settings: "ss01", "cv11";
}

::selection {
  background: rgb(var(--glow) / 0.35);
}

* {
  scrollbar-width: thin;
  scrollbar-color: rgb(var(--glow) / 0.28) transparent;
}

/* Theme switch: crossfade everything once instead of per-element transitions. */
.theme-swap,
.theme-swap * {
  transition:
    background-color 0.5s ease,
    border-color 0.5s ease,
    color 0.4s ease,
    fill 0.4s ease,
    box-shadow 0.5s ease !important;
}

/* ───────────────────────── Surfaces ───────────────────────── */

.glass {
  background: linear-gradient(180deg, var(--surface-2), var(--surface));
  backdrop-filter: blur(22px) saturate(160%);
  -webkit-backdrop-filter: blur(22px) saturate(160%);
  border: 1px solid var(--line);
  box-shadow: var(--panel-shadow);
}

.glass-soft {
  background: var(--surface);
  backdrop-filter: blur(14px) saturate(140%);
  -webkit-backdrop-filter: blur(14px) saturate(140%);
  border: 1px solid var(--line);
}

.hairline-top {
  position: relative;
}
.hairline-top::before {
  content: "";
  position: absolute;
  inset: 0 12% auto 12%;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgb(var(--glow) / 0.55), rgb(103 232 249 / 0.45), transparent);
  pointer-events: none;
}
.light .hairline-top::before {
  background: linear-gradient(90deg, transparent, rgb(124 58 237 / 0.35), rgb(8 145 178 / 0.3), transparent);
}

.text-glow {
  text-shadow: 0 0 18px rgb(var(--glow) / 0.55);
}
.light .text-glow {
  text-shadow: none;
}

.tint {
  --cc: rgb(var(--c));
  --cc-ink: color-mix(in oklab, rgb(var(--c)) 55%, white);
}
.light .tint {
  --cc: color-mix(in oklab, rgb(var(--c)) 70%, #1b1236);
  --cc-ink: color-mix(in oklab, rgb(var(--c)) 62%, #1b1236);
}

.btn-ghost {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.4rem;
  border-radius: 0.7rem;
  color: var(--ink-2);
  transition:
    background-color 0.2s,
    color 0.2s,
    box-shadow 0.2s,
    transform 0.2s var(--ease-spring);
}
.btn-ghost:hover {
  background: rgb(var(--glow) / 0.1);
  color: var(--ink);
}
.btn-ghost:active {
  transform: scale(0.94);
}

.kbd {
  font-family: var(--font-jb), monospace;
  font-size: 10px;
  line-height: 1;
  padding: 3px 5px;
  border-radius: 5px;
  border: 1px solid var(--line-2);
  color: var(--muted);
  background: rgb(var(--glow) / 0.06);
}

.shimmer-text {
  background: linear-gradient(
    100deg,
    var(--ink-2) 0%,
    var(--ink-2) 35%,
    #fff 46%,
    var(--cyan) 52%,
    var(--ink-2) 64%,
    var(--ink-2) 100%
  );
  background-size: 250% 100%;
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  animation: shimmer 2.2s linear infinite;
}
.light .shimmer-text {
  background-image: linear-gradient(
    100deg,
    var(--ink-2) 0%,
    var(--ink-2) 35%,
    var(--accent) 46%,
    var(--cyan) 52%,
    var(--ink-2) 64%,
    var(--ink-2) 100%
  );
}

/* ───────────────────────── Cosmos backdrop ───────────────────────── */

.cosmos {
  position: fixed;
  inset: 0;
  overflow: hidden;
  pointer-events: none;
  background:
    radial-gradient(120% 90% at 50% 46%, #150b30 0%, #0a0619 42%, #05030b 78%),
    var(--bg);
}
.light .cosmos {
  background:
    radial-gradient(110% 85% at 50% 46%, #ffffff 0%, #fbf9ff 45%, #f4f0ff 100%),
    var(--bg);
}

.nebula {
  position: absolute;
  border-radius: 50%;
  filter: blur(70px);
  opacity: 0.55;
  mix-blend-mode: screen;
  animation: nebula-drift 38s ease-in-out infinite alternate;
}
.light .nebula {
  mix-blend-mode: multiply;
  opacity: 0.32;
}

.aurora {
  position: absolute;
  left: -25%;
  width: 150%;
  height: 46vh;
  opacity: 0.38;
  filter: blur(26px) saturate(130%);
  mix-blend-mode: screen;
  background: linear-gradient(
    90deg,
    transparent 0%,
    rgb(52 211 153 / 0.85) 18%,
    rgb(103 232 249 / 0.8) 34%,
    rgb(167 139 250 / 0.9) 52%,
    rgb(240 171 252 / 0.75) 70%,
    rgb(129 140 248 / 0.7) 84%,
    transparent 100%
  );
  background-size: 200% 100%;
  -webkit-mask-image:
    repeating-linear-gradient(90deg, #000 0 3px, rgb(0 0 0 / 0.35) 3px 7px, #000 7px 9px, transparent 9px 14px),
    linear-gradient(180deg, transparent 0%, #000 38%, #000 52%, transparent 100%);
  -webkit-mask-composite: source-in;
  mask-image:
    repeating-linear-gradient(90deg, #000 0 3px, rgb(0 0 0 / 0.35) 3px 7px, #000 7px 9px, transparent 9px 14px),
    linear-gradient(180deg, transparent 0%, #000 38%, #000 52%, transparent 100%);
  mask-composite: intersect;
  animation:
    aurora-flow 26s linear infinite,
    aurora-sway 17s ease-in-out infinite alternate;
}
.aurora.soft {
  filter: blur(60px);
  opacity: 0.22;
  -webkit-mask-image: linear-gradient(180deg, transparent 0%, #000 40%, #000 55%, transparent 100%);
  mask-image: linear-gradient(180deg, transparent 0%, #000 40%, #000 55%, transparent 100%);
}
.light .aurora {
  mix-blend-mode: multiply;
  opacity: 0.2;
  filter: blur(30px) saturate(115%);
}
.light .aurora.soft {
  opacity: 0.16;
  filter: blur(60px);
}

.vignette {
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 50% 50%, transparent 52%, rgb(2 1 6 / 0.65) 100%);
}
.light .vignette {
  background: radial-gradient(ellipse at 50% 50%, transparent 60%, rgb(124 58 237 / 0.05) 100%);
}

.grain {
  position: absolute;
  inset: -50%;
  opacity: 0.05;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='180' height='180'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='2' stitchTiles='stitch'/></filter><rect width='100%' height='100%' filter='url(%23n)'/></svg>");
  animation: grain 9s steps(6) infinite;
}
.light .grain {
  opacity: 0.035;
}

/* ───────────────────────── Network stage ───────────────────────── */

.stage {
  position: absolute;
  inset: 0;
  overflow: hidden;
  touch-action: none;
  cursor: grab;
  user-select: none;
}
.stage.is-panning {
  cursor: grabbing;
}
.stage canvas {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.world {
  position: absolute;
  left: 0;
  top: 0;
  width: 0;
  height: 0;
  transform-origin: 0 0;
  opacity: 0;
  transition: opacity 1.2s ease;
}
.world.is-ready {
  opacity: 1;
}

.node {
  position: absolute;
  left: 0;
  top: 0;
  width: 0;
  height: 0;
  transition:
    opacity 0.6s ease,
    filter 0.6s ease;
}
.node[data-state="off"] {
  opacity: 0.14;
  filter: saturate(0.25);
}
.node[data-state="near"] {
  opacity: 0.6;
}
.node.is-dragging {
  z-index: 20;
}

.n-orb {
  position: absolute;
  width: var(--s);
  height: var(--s);
  left: calc(var(--s) / -2);
  top: calc(var(--s) / -2);
  display: grid;
  place-items: center;
  cursor: pointer;
  outline: none;
  transition:
    transform 0.45s var(--ease-spring),
    box-shadow 0.4s ease,
    background 0.4s ease;
}
.node:hover .n-orb,
.n-orb:focus-visible {
  transform: scale(1.12);
}
.node.is-dragging .n-orb {
  transform: scale(1.18);
  cursor: grabbing;
}

.n-aura {
  position: absolute;
  width: var(--a);
  height: var(--a);
  left: calc(var(--a) / -2);
  top: calc(var(--a) / -2);
  border-radius: 50%;
  pointer-events: none;
  background: radial-gradient(circle, rgb(var(--c) / 0.3), rgb(var(--c) / 0.08) 38%, transparent 68%);
  transition:
    transform 0.6s var(--ease-out-expo),
    opacity 0.6s;
}
.light .n-aura {
  background: radial-gradient(circle, rgb(var(--c) / 0.22), rgb(var(--c) / 0.06) 40%, transparent 68%);
}
.node:hover .n-aura,
.node.is-selected .n-aura {
  transform: scale(1.25);
}

.n-label {
  position: absolute;
  left: 0;
  top: calc(var(--s) / 2 + 9px);
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  white-space: nowrap;
  pointer-events: none;
  transition:
    opacity 0.35s ease,
    transform 0.35s var(--ease-out-expo);
}
.n-title {
  font-family: var(--font-space), sans-serif;
  font-weight: 600;
  letter-spacing: 0.01em;
  color: var(--ink);
  text-shadow:
    0 0 14px rgb(var(--c) / 0.55),
    0 1px 2px rgb(0 0 0 / 0.9);
}
.light .n-title {
  text-shadow:
    0 0 10px rgb(255 255 255 / 1),
    0 0 3px rgb(255 255 255 / 1);
}
.n-sub {
  font-size: 9.5px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--cc-ink);
  opacity: 0.85;
}
.light .n-sub {
  text-shadow: 0 0 6px #fff;
}

/* Game node — glowing orb with an orbit ring */
.n-game {
  --s: 70px;
  --a: 210px;
}
.n-game .n-orb {
  border-radius: 50%;
  color: var(--cc-ink);
  background:
    radial-gradient(circle at 34% 28%, rgb(255 255 255 / 0.28), transparent 32%),
    radial-gradient(circle at 50% 60%, rgb(var(--c) / 0.42), rgb(var(--c) / 0.12) 55%, rgb(10 6 24 / 0.92) 80%);
  border: 1px solid rgb(var(--c) / 0.65);
  box-shadow:
    0 0 26px rgb(var(--c) / 0.5),
    0 0 70px rgb(var(--c) / 0.18),
    inset 0 0 18px rgb(var(--c) / 0.4);
}
.n-game .n-orb svg {
  width: 32px;
  height: 32px;
  filter: drop-shadow(0 0 6px rgb(var(--c) / 0.9));
}
.light .n-game .n-orb {
  background:
    radial-gradient(circle at 34% 28%, #fff, transparent 40%),
    radial-gradient(circle at 50% 60%, rgb(var(--c) / 0.28), rgb(var(--c) / 0.08) 60%, #fff 85%);
  border-color: color-mix(in oklab, rgb(var(--c)) 70%, #1b1236);
  box-shadow:
    0 10px 28px -6px rgb(var(--c) / 0.55),
    0 0 0 5px rgb(var(--c) / 0.1),
    inset 0 -6px 14px rgb(var(--c) / 0.18);
}
.light .n-game .n-orb svg {
  filter: none;
}
.n-ring {
  position: absolute;
  width: calc(var(--s) + 16px);
  height: calc(var(--s) + 16px);
  left: calc((var(--s) + 16px) / -2);
  top: calc((var(--s) + 16px) / -2);
  border-radius: 50%;
  pointer-events: none;
  background: conic-gradient(
    from 0deg,
    transparent 0 12%,
    rgb(var(--c) / 0.95) 22%,
    transparent 36% 58%,
    rgb(var(--c) / 0.6) 70%,
    transparent 82%
  );
  -webkit-mask: radial-gradient(circle, transparent calc(50% - 1.6px), #000 calc(50% - 1px));
  mask: radial-gradient(circle, transparent calc(50% - 1.6px), #000 calc(50% - 1px));
  animation: spin 9s linear infinite;
}
.n-orbit {
  position: absolute;
  width: calc(var(--s) + 38px);
  height: calc(var(--s) + 38px);
  left: calc((var(--s) + 38px) / -2);
  top: calc((var(--s) + 38px) / -2);
  border-radius: 50%;
  border: 1px dashed rgb(var(--c) / 0.3);
  pointer-events: none;
  animation: spin 40s linear infinite reverse;
}
.n-game .n-label {
  top: calc(var(--s) / 2 + 24px);
}
.n-game .n-title {
  font-size: 15px;
}

/* Category node — rotated plate with a custom icon */
.n-cat {
  --s: 44px;
  --a: 120px;
}
.n-cat .n-orb {
  border-radius: 14px;
  transform: rotate(45deg);
  color: var(--cc-ink);
  background:
    linear-gradient(135deg, rgb(var(--c) / 0.32), rgb(12 8 28 / 0.9) 70%),
    rgb(12 8 28 / 0.9);
  border: 1px solid rgb(var(--c) / 0.6);
  box-shadow:
    0 0 18px rgb(var(--c) / 0.45),
    inset 0 0 12px rgb(var(--c) / 0.3);
}
.node.n-cat:hover .n-orb,
.n-cat .n-orb:focus-visible {
  transform: rotate(45deg) scale(1.12);
}
.n-cat.is-dragging .n-orb {
  transform: rotate(45deg) scale(1.18);
}
.n-cat .n-orb svg {
  transform: rotate(-45deg);
  width: 22px;
  height: 22px;
  filter: drop-shadow(0 0 5px rgb(var(--c) / 0.85));
}
.light .n-cat .n-orb {
  background: linear-gradient(135deg, rgb(var(--c) / 0.22), #fff 75%);
  border-color: color-mix(in oklab, rgb(var(--c)) 65%, #1b1236);
  box-shadow:
    0 8px 20px -6px rgb(var(--c) / 0.55),
    0 0 0 4px rgb(var(--c) / 0.08);
}
.light .n-cat .n-orb svg {
  filter: none;
}
.n-cat .n-label {
  top: calc(var(--s) / 2 + 13px);
}
.n-cat .n-title {
  font-size: 12px;
}

/* Mod node — a bright star */
.n-mod {
  --s: 15px;
  --a: 64px;
}
.n-mod .n-orb {
  border-radius: 50%;
  background: radial-gradient(circle at 38% 34%, #fff 0 18%, rgb(var(--c)) 48%, rgb(var(--c) / 0.35) 75%);
  box-shadow:
    0 0 10px rgb(var(--c) / 0.9),
    0 0 26px rgb(var(--c) / 0.35);
}
.n-mod .n-orb::after {
  content: "";
  position: absolute;
  inset: -5px;
  border-radius: 50%;
  border: 1px solid rgb(var(--c) / 0.45);
  opacity: 0;
  transition: opacity 0.3s;
}
.node.n-mod:hover .n-orb::after,
.n-mod.is-selected .n-orb::after {
  opacity: 1;
}
.light .n-mod .n-orb {
  background: radial-gradient(circle at 38% 34%, #fff 0 18%, color-mix(in oklab, rgb(var(--c)) 80%, #1b1236) 52%, rgb(var(--c) / 0.6) 80%);
  box-shadow:
    0 3px 10px rgb(var(--c) / 0.65),
    0 0 0 3px rgb(var(--c) / 0.14);
}
.n-mod .n-label {
  top: calc(var(--s) / 2 + 7px);
}
.n-mod .n-title {
  font-size: 10.5px;
  font-weight: 500;
  padding: 2px 7px;
  border-radius: 999px;
  background: rgb(10 6 24 / 0.6);
  border: 1px solid rgb(var(--c) / 0.3);
  text-shadow: none;
}
.light .n-mod .n-title {
  background: rgb(255 255 255 / 0.85);
  border-color: rgb(var(--c) / 0.4);
  text-shadow: none;
}
.n-mod.is-forging .n-orb {
  animation: forge-pulse 0.9s ease-in-out infinite;
}

/* Semantic zoom: reveal labels as you get closer, or when in context. */
.n-cat .n-label,
.n-mod .n-label {
  opacity: 0;
  transform: translate(-50%, -4px);
}
.stage[data-zoom="mid"] .n-cat .n-label,
.stage[data-zoom="near"] .n-cat .n-label,
.stage[data-zoom="near"] .n-mod .n-label,
.node[data-label="show"] .n-label,
.node:hover .n-label,
.node.is-selected .n-label,
.node.is-dragging .n-label {
  opacity: 1;
  transform: translate(-50%, 0);
}
.node[data-state="off"] .n-label {
  opacity: 0 !important;
}

.node.is-selected .n-orb {
  box-shadow:
    0 0 0 2px rgb(var(--c) / 0.9),
    0 0 34px rgb(var(--c) / 0.75),
    0 0 90px rgb(var(--c) / 0.3);
}
.light .node.is-selected .n-orb {
  box-shadow:
    0 0 0 2px color-mix(in oklab, rgb(var(--c)) 75%, #1b1236),
    0 12px 32px -6px rgb(var(--c) / 0.6),
    0 0 0 8px rgb(var(--c) / 0.12);
}

.node.is-hit .n-orb {
  animation: node-hit 0.55s var(--ease-out-expo);
}
.node.is-new {
  animation: materialize 1.1s var(--ease-out-expo) both;
}

/* ───────────────────────── Cyrus Core ───────────────────────── */

.core {
  position: absolute;
  left: 0;
  top: 0;
  width: 0;
  height: 0;
  --e: 0;
  --p: 0;
  --f: 0;
  --a1: 0deg;
  --a2: 0deg;
  --a3: 0deg;
  --a4: 0deg;
  --a5: 0deg;
}
.core > * {
  position: absolute;
  left: 50%;
  top: 50%;
  translate: -50% -50%;
  pointer-events: none;
}

.core-bloom {
  width: 640px;
  height: 640px;
  border-radius: 50%;
  background: radial-gradient(
    circle,
    rgb(196 181 253 / 0.38) 0%,
    rgb(139 92 246 / 0.22) 18%,
    rgb(103 232 249 / 0.08) 34%,
    transparent 62%
  );
  opacity: calc(0.6 + var(--e) * 0.4 + var(--p) * 0.3);
  transform: scale(calc(0.92 + var(--e) * 0.22 + var(--p) * 0.14));
  mix-blend-mode: screen;
}
.light .core-bloom {
  mix-blend-mode: multiply;
  background: radial-gradient(
    circle,
    rgb(167 139 250 / 0.35) 0%,
    rgb(167 139 250 / 0.16) 20%,
    rgb(103 232 249 / 0.08) 36%,
    transparent 62%
  );
}

.core-web {
  width: 300px;
  height: 300px;
  opacity: calc(0.55 + var(--e) * 0.45);
  transform: rotate(var(--a5));
  color: rgb(196 181 253);
}
.light .core-web {
  color: rgb(109 40 217);
  opacity: calc(0.4 + var(--e) * 0.4);
}

.core-halo {
  width: var(--hs);
  height: var(--hs);
}
.core-halo .plane {
  width: 100%;
  height: 100%;
}
.core-halo.back {
  clip-path: inset(0 0 50% 0);
}
.core-halo.front {
  clip-path: inset(50% 0 0 0);
}
.core-halo circle {
  transition: stroke-opacity 0.3s;
}

.core-crown {
  width: 196px;
  height: 196px;
  transform: rotate(var(--a4));
  opacity: calc(0.5 + var(--e) * 0.5);
  color: rgb(221 214 254);
}
.light .core-crown {
  color: rgb(109 40 217);
}

.core-orb {
  width: 124px;
  height: 124px;
  border-radius: 50%;
  overflow: hidden;
  transform: scale(calc(1 + var(--p) * 0.07 + var(--e) * 0.05));
  background: radial-gradient(circle at 50% 50%, #2a1760 0%, #120a2c 70%);
  box-shadow:
    0 0 0 1px rgb(196 181 253 / 0.35),
    0 0 calc(40px + var(--e) * 40px) rgb(167 139 250 / calc(0.55 + var(--e) * 0.35)),
    0 0 calc(110px + var(--p) * 60px) rgb(103 232 249 / calc(0.18 + var(--p) * 0.3)),
    inset 0 0 30px rgb(167 139 250 / 0.6);
}
.light .core-orb {
  background: radial-gradient(circle at 50% 50%, #ede9fe 0%, #c4b5fd 70%);
  box-shadow:
    0 0 0 1px rgb(124 58 237 / 0.35),
    0 18px 40px -8px rgb(124 58 237 / calc(0.45 + var(--e) * 0.3)),
    0 0 calc(60px + var(--e) * 40px) rgb(167 139 250 / calc(0.35 + var(--e) * 0.3)),
    inset 0 -10px 30px rgb(124 58 237 / 0.45);
}
.core-orb > div {
  position: absolute;
  inset: 0;
  border-radius: 50%;
}
.core-plasma-a {
  inset: -30% !important;
  background: conic-gradient(
    from 0deg,
    #7c3aed,
    #22d3ee,
    #a78bfa,
    #f0abfc,
    #6366f1,
    #67e8f9,
    #7c3aed
  );
  filter: blur(14px);
  opacity: 0.85;
  transform: rotate(var(--a1));
}
.core-plasma-b {
  inset: -20% !important;
  background:
    radial-gradient(circle at 30% 30%, rgb(255 255 255 / 0.55), transparent 30%),
    radial-gradient(circle at 70% 65%, rgb(103 232 249 / 0.7), transparent 38%),
    radial-gradient(circle at 35% 75%, rgb(240 171 252 / 0.6), transparent 34%);
  filter: blur(6px);
  mix-blend-mode: screen;
  transform: rotate(calc(var(--a2) * -1.4));
}
.core-nucleus {
  inset: 28% !important;
  background: radial-gradient(circle, #fff 0%, rgb(237 233 254 / 0.95) 24%, rgb(196 181 253 / 0.5) 55%, transparent 72%);
  filter: blur(2px);
  transform: scale(calc(0.85 + var(--e) * 0.35 + var(--p) * 0.4));
  opacity: calc(0.75 + var(--e) * 0.25);
}
.core-glint {
  background:
    radial-gradient(ellipse 40% 26% at 36% 22%, rgb(255 255 255 / 0.55), transparent 70%),
    radial-gradient(circle at 50% 50%, transparent 58%, rgb(10 4 30 / 0.55) 100%);
}
.light .core-glint {
  background:
    radial-gradient(ellipse 40% 26% at 36% 22%, rgb(255 255 255 / 0.85), transparent 70%),
    radial-gradient(circle at 50% 50%, transparent 60%, rgb(76 29 149 / 0.35) 100%);
}

.core-hit {
  width: 132px;
  height: 132px;
  border-radius: 50%;
  pointer-events: auto !important;
  cursor: pointer;
}

.core-ripples > span {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 130px;
  height: 130px;
  margin: -65px 0 0 -65px;
  border-radius: 50%;
  border: 1.5px solid rgb(196 181 253 / 0.8);
  box-shadow:
    0 0 18px rgb(167 139 250 / 0.6),
    inset 0 0 18px rgb(103 232 249 / 0.35);
  animation: ripple 1.25s var(--ease-out-expo) forwards;
}
.core-ripples > span.big {
  border-color: rgb(103 232 249 / 0.9);
  animation-duration: 1.8s;
}
.light .core-ripples > span {
  border-color: rgb(124 58 237 / 0.6);
  box-shadow: 0 0 14px rgb(124 58 237 / 0.25);
}
.light .core-ripples > span.big {
  border-color: rgb(8 145 178 / 0.65);
}

.core-label {
  top: calc(50% + 128px) !important;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  white-space: nowrap;
}
.core-label .t {
  font-family: var(--font-space), sans-serif;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.42em;
  margin-right: -0.42em;
  color: var(--ink);
  text-shadow: 0 0 16px rgb(167 139 250 / 0.9);
}
.light .core-label .t {
  text-shadow: 0 0 8px #fff;
}
.core-label .s {
  font-family: var(--font-jb), monospace;
  font-size: 10px;
  letter-spacing: 0.1em;
  color: var(--muted);
}

/* ───────────────────────── Prompt dock ───────────────────────── */

.prompt-shell {
  position: relative;
  border-radius: 24px;
  --spin-speed: 9s;
}
.prompt-shell::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  padding: 1px;
  background: conic-gradient(
    from var(--angle),
    rgb(var(--glow) / 0.18) 0%,
    rgb(103 232 249 / 0.75) 12%,
    rgb(var(--glow) / 0.18) 26%,
    rgb(var(--glow) / 0.18) 48%,
    rgb(240 171 252 / 0.7) 62%,
    rgb(var(--glow) / 0.18) 76%
  );
  -webkit-mask:
    linear-gradient(#000 0 0) content-box,
    linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask:
    linear-gradient(#000 0 0) content-box,
    linear-gradient(#000 0 0);
  mask-composite: exclude;
  animation: border-spin var(--spin-speed) linear infinite;
  pointer-events: none;
  z-index: 2;
}
.prompt-shell::after {
  content: "";
  position: absolute;
  inset: -1px;
  border-radius: inherit;
  background: conic-gradient(
    from var(--angle),
    transparent 0%,
    rgb(103 232 249 / 0.5) 12%,
    transparent 28%,
    transparent 50%,
    rgb(240 171 252 / 0.45) 62%,
    transparent 78%
  );
  filter: blur(18px);
  opacity: 0.25;
  z-index: -1;
  animation: border-spin var(--spin-speed) linear infinite;
  transition: opacity 0.5s;
  pointer-events: none;
}
.prompt-shell[data-active="true"] {
  --spin-speed: 3.2s;
}
.prompt-shell[data-active="true"]::after {
  opacity: 0.6;
}
.prompt-shell[data-busy="true"] {
  --spin-speed: 1.3s;
}
.prompt-shell[data-busy="true"]::after {
  opacity: 0.85;
}
.light .prompt-shell::after {
  opacity: 0.18;
}
.light .prompt-shell[data-active="true"]::after {
  opacity: 0.35;
}

.prompt-textarea::placeholder {
  color: var(--faint);
}

.mic-live {
  background: linear-gradient(135deg, #f43f5e, #d946ef);
  color: #fff;
  box-shadow:
    0 0 0 0 rgb(244 63 94 / 0.6),
    0 0 22px rgb(244 63 94 / 0.55);
  animation: mic-ring 1.4s ease-out infinite;
}
.mic-bars span {
  display: block;
  width: 2.5px;
  border-radius: 2px;
  background: currentColor;
  animation: mic-bar 0.9s ease-in-out infinite;
}

.think-node {
  animation: think-node 1.6s ease-in-out infinite;
}
.think-edge {
  stroke-dasharray: 3 4;
  animation: dash-flow 0.8s linear infinite;
}

/* ───────────────────────── Code view ───────────────────────── */

.code {
  font-family: var(--font-jb), ui-monospace, monospace;
  font-size: 12.5px;
  line-height: 1.7;
  tab-size: 4;
  font-variant-ligatures: contextual;
}
.code .ln {
  color: var(--faint);
  user-select: none;
}
.code .line-new {
  animation: line-in 0.7s ease-out;
}
.tok-k { color: var(--tok-k); }
.tok-s { color: var(--tok-s); }
.tok-n { color: var(--tok-n); }
.tok-c { color: var(--tok-c); font-style: italic; }
.tok-t { color: var(--tok-t); }
.tok-f { color: var(--tok-f); }
.tok-p { color: var(--tok-p); }
.tok-a { color: var(--tok-a); }
.tok-v { color: var(--tok-v); }

.caret {
  display: inline-block;
  width: 7px;
  height: 1.15em;
  margin-left: 1px;
  vertical-align: -0.2em;
  border-radius: 1px;
  background: var(--cyan);
  box-shadow: 0 0 10px var(--cyan);
  animation: caret 0.9s steps(1) infinite;
}

.write-head {
  background: linear-gradient(90deg, rgb(103 232 249 / 0.12), rgb(167 139 250 / 0.06) 60%, transparent);
}
.light .write-head {
  background: linear-gradient(90deg, rgb(8 145 178 / 0.1), rgb(124 58 237 / 0.04) 60%, transparent);
}

.md h1, .md h2, .md h3 {
  font-family: var(--font-space), sans-serif;
  color: var(--ink);
  font-weight: 600;
}
.md h1 { font-size: 1.05rem; margin: 0.2rem 0 0.6rem; }
.md h2 { font-size: 0.92rem; margin: 1rem 0 0.4rem; }
.md h3 { font-size: 0.85rem; margin: 0.8rem 0 0.3rem; }
.md p { margin: 0.35rem 0; color: var(--ink-2); }
.md ul, .md ol { margin: 0.3rem 0 0.5rem; padding-left: 1.1rem; color: var(--ink-2); }
.md ul { list-style: none; padding-left: 0.2rem; }
.md ul li { position: relative; padding-left: 1rem; margin: 0.22rem 0; }
.md ul li::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0.62em;
  width: 5px;
  height: 5px;
  border-radius: 2px;
  transform: rotate(45deg);
  background: var(--accent);
  box-shadow: 0 0 8px var(--accent);
}
.md ol { list-style: decimal; }
.md ol li { margin: 0.22rem 0; }
.md code {
  font-family: var(--font-jb), monospace;
  font-size: 0.8em;
  padding: 1px 5px;
  border-radius: 5px;
  background: rgb(var(--glow) / 0.1);
  color: var(--accent-ink);
}
.md pre {
  font-family: var(--font-jb), monospace;
  font-size: 11.5px;
  padding: 0.7rem 0.8rem;
  border-radius: 10px;
  background: var(--code-bg);
  border: 1px solid var(--line);
  overflow-x: auto;
  margin: 0.5rem 0;
  color: var(--ink-2);
}
.md strong { color: var(--ink); font-weight: 600; }

/* ───────────────────────── Keyframes ───────────────────────── */

@keyframes spin {
  to { transform: rotate(360deg); }
}
@keyframes border-spin {
  to { --angle: 360deg; }
}
@keyframes shimmer {
  0% { background-position: 120% 0; }
  100% { background-position: -120% 0; }
}
@keyframes nebula-drift {
  0% { transform: translate3d(0, 0, 0) scale(1); }
  50% { transform: translate3d(3%, -2%, 0) scale(1.08); }
  100% { transform: translate3d(-3%, 2%, 0) scale(0.96); }
}
@keyframes aurora-flow {
  0% { background-position: 0% 0; }
  100% { background-position: -200% 0; }
}
@keyframes aurora-sway {
  0% { transform: rotate(var(--r, -12deg)) skewX(-8deg) translateY(0) scaleY(1); }
  50% { transform: rotate(var(--r, -12deg)) skewX(6deg) translateY(-3%) scaleY(1.15); }
  100% { transform: rotate(var(--r, -12deg)) skewX(-4deg) translateY(2%) scaleY(0.9); }
}
@keyframes grain {
  0%, 100% { transform: translate(0, 0); }
  20% { transform: translate(-3%, 2%); }
  40% { transform: translate(2%, -3%); }
  60% { transform: translate(-2%, -1%); }
  80% { transform: translate(3%, 3%); }
}
@keyframes ripple {
  0% { transform: scale(0.85); opacity: 0.9; }
  100% { transform: scale(2.6); opacity: 0; }
}
@keyframes node-hit {
  0% { transform: scale(1); }
  30% { transform: scale(1.32); filter: brightness(1.8); }
  100% { transform: scale(1); }
}
@keyframes forge-pulse {
  0%, 100% { transform: scale(1); filter: brightness(1); }
  50% { transform: scale(1.5); filter: brightness(1.7); }
}
@keyframes materialize {
  0% { opacity: 0; filter: blur(8px) brightness(3); }
  40% { opacity: 1; }
  100% { opacity: 1; filter: blur(0) brightness(1); }
}
@keyframes caret {
  0%, 49% { opacity: 1; }
  50%, 100% { opacity: 0; }
}
@keyframes line-in {
  0% { background: rgb(103 232 249 / 0.14); }
  100% { background: transparent; }
}
@keyframes mic-ring {
  0% { box-shadow: 0 0 0 0 rgb(244 63 94 / 0.55), 0 0 22px rgb(244 63 94 / 0.5); }
  100% { box-shadow: 0 0 0 14px rgb(244 63 94 / 0), 0 0 22px rgb(244 63 94 / 0.5); }
}
@keyframes mic-bar {
  0%, 100% { height: 4px; }
  50% { height: 14px; }
}
@keyframes think-node {
  0%, 100% { opacity: 0.35; transform: scale(0.8); }
  50% { opacity: 1; transform: scale(1.15); }
}
@keyframes dash-flow {
  to { stroke-dashoffset: -14; }
}
@keyframes rise-in {
  from { opacity: 0; transform: translateY(10px) scale(0.98); filter: blur(4px); }
  to { opacity: 1; transform: translateY(0) scale(1); filter: blur(0); }
}
@keyframes fade-in {
  from { opacity: 0; }
  to { opacity: 1; }
}
@keyframes slide-in-right {
  from { opacity: 0; transform: translateX(28px); }
  to { opacity: 1; transform: translateX(0); }
}
@keyframes pop-in {
  from { opacity: 0; transform: translateY(6px) scale(0.96); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}
@keyframes progress-sheen {
  from { transform: translateX(-100%); }
  to { transform: translateX(250%); }
}
@keyframes orbit-dot {
  from { transform: rotate(0deg) translateX(7px) rotate(0deg); }
  to { transform: rotate(360deg) translateX(7px) rotate(-360deg); }
}

.animate-rise { animation: rise-in 0.55s var(--ease-out-expo) both; }
.animate-fade { animation: fade-in 0.4s ease both; }
.animate-slide-right { animation: slide-in-right 0.5s var(--ease-out-expo) both; }
.animate-pop { animation: pop-in 0.28s var(--ease-out-expo) both; }

@media (prefers-reduced-motion: reduce) {
  .aurora,
  .nebula,
  .grain,
  .n-ring,
  .n-orbit {
    animation: none !important;
  }
}

toolUseResult.content:
@import "tailwindcss";

@custom-variant dark (&:where(.dark, .dark *));
@custom-variant light (&:where(.light, .light *));

/* ───────────────────────── Theme tokens ───────────────────────── */

:root {
  color-scheme: dark;
  --bg: #05030b;
  --bg-2: #0a0617;
  --bg-3: #140b2b;
  --surface: rgb(15 10 32 / 0.6);
  --surface-2: rgb(22 15 46 / 0.78);
  --surface-3: rgb(40 27 80 / 0.55);
  --solid: #0e091e;
  --line: rgb(167 139 250 / 0.13);
  --line-2: rgb(167 139 250 / 0.26);
  --ink: #f2eeff;
  --ink-2: #cfc7f0;
  --muted: #958cc0;
  --faint: #5f5789;
  --accent: #a78bfa;
  --accent-ink: #c4b5fd;
  --cyan: #67e8f9;
  --pink: #f0abfc;
  --glow: 167 139 250;
  --panel-shadow: 0 30px 80px -24px rgb(0 0 0 / 0.8), inset 0 1px 0 rgb(255 255 255 / 0.04);
  --code-bg: rgb(7 4 18 / 0.55);
  --tok-k: #c792ea;
  --tok-s: #a8e6a3;
  --tok-n: #f8b26a;
  --tok-c: #6c6497;
  --tok-t: #82d8ff;
  --tok-f: #93b6ff;
  --tok-p: #8f87b8;
  --tok-a: #f0abfc;
  --tok-v: #f5c2e7;
}

:root.light {
  color-scheme: light;
  --bg: #fdfcff;
  --bg-2: #f7f4ff;
  --bg-3: #ede7ff;
  --surface: rgb(255 255 255 / 0.66);
  --surface-2: rgb(255 255 255 / 0.86);
  --surface-3: rgb(243 238 255 / 0.9);
  --solid: #ffffff;
  --line: rgb(91 33 182 / 0.1);
  --line-2: rgb(91 33 182 / 0.2);
  --ink: #160f2c;
  --ink-2: #3a3162;
  --muted: #6b6390;
  --faint: #a8a1c6;
  --accent: #7c3aed;
  --accent-ink: #6d28d9;
  --cyan: #0891b2;
  --pink: #c026d3;
  --glow: 124 58 237;
  --panel-shadow: 0 24px 60px -28px rgb(76 29 149 / 0.3), inset 0 1px 0 rgb(255 255 255 / 0.9);
  --code-bg: rgb(250 248 255 / 0.8);
  --tok-k: #8a2bc5;
  --tok-s: #23803a;
  --tok-n: #c2410c;
  --tok-c: #9c95bb;
  --tok-t: #0369a1;
  --tok-f: #4338ca;
  --tok-p: #6b6490;
  --tok-a: #be185d;
  --tok-v: #9d174d;
}

@theme inline {
  --color-bg: var(--bg);
  --color-bg-2: var(--bg-2);
  --color-bg-3: var(--bg-3);
  --color-surface: var(--surface);
  --color-surface-2: var(--surface-2);
  --color-surface-3: var(--surface-3);
  --color-solid: var(--solid);
  --color-line: var(--line);
  --color-line-2: var(--line-2);
  --color-ink: var(--ink);
  --color-ink-2: var(--ink-2);
  --color-muted: var(--muted);
  --color-faint: var(--faint);
  --color-accent: var(--accent);
  --color-accent-ink: var(--accent-ink);
  --color-cyan: var(--cyan);
  --color-pink: var(--pink);
  --font-sans: var(--font-inter), ui-sans-serif, system-ui, sans-serif;
  --font-display: var(--font-space), var(--font-inter), ui-sans-serif, sans-serif;
  --font-mono: var(--font-jb), ui-monospace, SFMono-Regular, Menlo, monospace;
  --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-spring: cubic-bezier(0.34, 1.56, 0.64, 1);
}

@property --angle {
  syntax: "<angle>";
  initial-value: 0deg;
  inherits: false;
}

html,
body {
  height: 100%;
  background: var(--bg);
  color: var(--ink);
}

body {
  overflow: hidden;
  -webkit-font-smoothing: antialiased;
  font-feature-settings: "ss01", "cv11";
}

::selection {
  background: rgb(var(--glow) / 0.35);
}

* {
  scrollbar-width: thin;
  scrollbar-color: rgb(var(--glow) / 0.28) transparent;
}

/* Theme switch: crossfade everything once instead of per-element transitions. */
.theme-swap,
.theme-swap * {
  transition:
    background-color 0.5s ease,
    border-color 0.5s ease,
    color 0.4s ease,
    fill 0.4s ease,
    box-shadow 0.5s ease !important;
}

/* ───────────────────────── Surfaces ───────────────────────── */

.glass {
  background: linear-gradient(180deg, var(--surface-2), var(--surface));
  backdrop-filter: blur(22px) saturate(160%);
  -webkit-backdrop-filter: blur(22px) saturate(160%);
  border: 1px solid var(--line);
  box-shadow: var(--panel-shadow);
}

.glass-soft {
  background: var(--surface);
  backdrop-filter: blur(14px) saturate(140%);
  -webkit-backdrop-filter: blur(14px) saturate(140%);
  border: 1px solid var(--line);
}

.hairline-top {
  position: relative;
}
.hairline-top::before {
  content: "";
  position: absolute;
  inset: 0 12% auto 12%;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgb(var(--glow) / 0.55), rgb(103 232 249 / 0.45), transparent);
  pointer-events: none;
}
.light .hairline-top::before {
  background: linear-gradient(90deg, transparent, rgb(124 58 237 / 0.35), rgb(8 145 178 / 0.3), transparent);
}

.text-glow {
  text-shadow: 0 0 18px rgb(var(--glow) / 0.55);
}
.light .text-glow {
  text-shadow: none;
}

.tint {
  --cc: rgb(var(--c));
  --cc-ink: color-mix(in oklab, rgb(var(--c)) 55%, white);
}
.light .tint {
  --cc: color-mix(in oklab, rgb(var(--c)) 70%, #1b1236);
  --cc-ink: color-mix(in oklab, rgb(var(--c)) 62%, #1b1236);
}

.btn-ghost {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.4rem;
  border-radius: 0.7rem;
  color: var(--ink-2);
  transition:
    background-color 0.2s,
    color 0.2s,
    box-shadow 0.2s,
    transform 0.2s var(--ease-spring);
}
.btn-ghost:hover {
  background: rgb(var(--glow) / 0.1);
  color: var(--ink);
}
.btn-ghost:active {
  transform: scale(0.94);
}

.kbd {
  font-family: var(--font-jb), monospace;
  font-size: 10px;
  line-height: 1;
  padding: 3px 5px;
  border-radius: 5px;
  border: 1px solid var(--line-2);
  color: var(--muted);
  background: rgb(var(--glow) / 0.06);
}

.shimmer-text {
  background: linear-gradient(
    100deg,
    var(--ink-2) 0%,
    var(--ink-2) 35%,
    #fff 46%,
    var(--cyan) 52%,
    var(--ink-2) 64%,
    var(--ink-2) 100%
  );
  background-size: 250% 100%;
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  animation: shimmer 2.2s linear infinite;
}
.light .shimmer-text {
  background-image: linear-gradient(
    100deg,
    var(--ink-2) 0%,
    var(--ink-2) 35%,
    var(--accent) 46%,
    var(--cyan) 52%,
    var(--ink-2) 64%,
    var(--ink-2) 100%
  );
}

/* ───────────────────────── Cosmos backdrop ───────────────────────── */

.cosmos {
  position: fixed;
  inset: 0;
  overflow: hidden;
  pointer-events: none;
  background:
    radial-gradient(120% 90% at 50% 46%, #150b30 0%, #0a0619 42%, #05030b 78%),
    var(--bg);
}
.light .cosmos {
  background:
    radial-gradient(110% 85% at 50% 46%, #ffffff 0%, #fbf9ff 45%, #f4f0ff 100%),
    var(--bg);
}

.nebula {
  position: absolute;
  border-radius: 50%;
  filter: blur(70px);
  opacity: 0.55;
  mix-blend-mode: screen;
  animation: nebula-drift 38s ease-in-out infinite alternate;
}
.light .nebula {
  mix-blend-mode: multiply;
  opacity: 0.32;
}

.aurora {
  position: absolute;
  left: -25%;
  width: 150%;
  height: 46vh;
  opacity: 0.38;
  filter: blur(26px) saturate(130%);
  mix-blend-mode: screen;
  background: linear-gradient(
    90deg,
    transparent 0%,
    rgb(52 211 153 / 0.85) 18%,
    rgb(103 232 249 / 0.8) 34%,
    rgb(167 139 250 / 0.9) 52%,
    rgb(240 171 252 / 0.75) 70%,
    rgb(129 140 248 / 0.7) 84%,
    transparent 100%
  );
  background-size: 200% 100%;
  -webkit-mask-image:
    repeating-linear-gradient(90deg, #000 0 3px, rgb(0 0 0 / 0.35) 3px 7px, #000 7px 9px, transparent 9px 14px),
    linear-gradient(180deg, transparent 0%, #000 38%, #000 52%, transparent 100%);
  -webkit-mask-composite: source-in;
  mask-image:
    repeating-linear-gradient(90deg, #000 0 3px, rgb(0 0 0 / 0.35) 3px 7px, #000 7px 9px, transparent 9px 14px),
    linear-gradient(180deg, transparent 0%, #000 38%, #000 52%, transparent 100%);
  mask-composite: intersect;
  animation:
    aurora-flow 26s linear infinite,
    aurora-sway 17s ease-in-out infinite alternate;
}
.aurora.soft {
  filter: blur(60px);
  opacity: 0.22;
  -webkit-mask-image: linear-gradient(180deg, transparent 0%, #000 40%, #000 55%, transparent 100%);
  mask-image: linear-gradient(180deg, transparent 0%, #000 40%, #000 55%, transparent 100%);
}
.light .aurora {
  mix-blend-mode: multiply;
  opacity: 0.2;
  filter: blur(30px) saturate(115%);
}
.light .aurora.soft {
  opacity: 0.16;
  filter: blur(60px);
}

.vignette {
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 50% 50%, transparent 52%, rgb(2 1 6 / 0.65) 100%);
}
.light .vignette {
  background: radial-gradient(ellipse at 50% 50%, transparent 60%, rgb(124 58 237 / 0.05) 100%);
}

.grain {
  position: absolute;
  inset: -50%;
  opacity: 0.05;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='180' height='180'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='2' stitchTiles='stitch'/></filter><rect width='100%' height='100%' filter='url(%23n)'/></svg>");
  animation: grain 9s steps(6) infinite;
}
.light .grain {
  opacity: 0.035;
}

/* ───────────────────────── Network stage ───────────────────────── */

.stage {
  position: absolute;
  inset: 0;
  overflow: hidden;
  touch-action: none;
  cursor: grab;
  user-select: none;
}
.stage.is-panning {
  cursor: grabbing;
}
.stage canvas {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.world {
  position: absolute;
  left: 0;
  top: 0;
  width: 0;
  height: 0;
  transform-origin: 0 0;
  opacity: 0;
  transition: opacity 1.2s ease;
}
.world.is-ready {
  opacity: 1;
}

.node {
  position: absolute;
  left: 0;
  top: 0;
  width: 0;
  height: 0;
  transition:
    opacity 0.6s ease,
    filter 0.6s ease;
}
.node[data-state="off"] {
  opacity: 0.14;
  filter: saturate(0.25);
}
.node[data-state="near"] {
  opacity: 0.6;
}
.node.is-dragging {
  z-index: 20;
}

.n-orb {
  position: absolute;
  width: var(--s);
  height: var(--s);
  left: calc(var(--s) / -2);
  top: calc(var(--s) / -2);
  display: grid;
  place-items: center;
  cursor: pointer;
  outline: none;
  transition:
    transform 0.45s var(--ease-spring),
    box-shadow 0.4s ease,
    background 0.4s ease;
}
.node:hover .n-orb,
.n-orb:focus-visible {
  transform: scale(1.12);
}
.node.is-dragging .n-orb {
  transform: scale(1.18);
  cursor: grabbing;
}

.n-aura {
  position: absolute;
  width: var(--a);
  height: var(--a);
  left: calc(var(--a) / -2);
  top: calc(var(--a) / -2);
  border-radius: 50%;
  pointer-events: none;
  background: radial-gradient(circle, rgb(var(--c) / 0.3), rgb(var(--c) / 0.08) 38%, transparent 68%);
  transition:
    transform 0.6s var(--ease-out-expo),
    opacity 0.6s;
}
.light .n-aura {
  background: radial-gradient(circle, rgb(var(--c) / 0.22), rgb(var(--c) / 0.06) 40%, transparent 68%);
}
.node:hover .n-aura,
.node.is-selected .n-aura {
  transform: scale(1.25);
}

.n-label {
  position: absolute;
  left: 0;
  top: calc(var(--s) / 2 + 9px);
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  white-space: nowrap;
  pointer-events: none;
  transition:
    opacity 0.35s ease,
    transform 0.35s var(--ease-out-expo);
}
.n-title {
  font-family: var(--font-space), sans-serif;
  font-weight: 600;
  letter-spacing: 0.01em;
  color: var(--ink);
  text-shadow:
    0 0 14px rgb(var(--c) / 0.55),
    0 1px 2px rgb(0 0 0 / 0.9);
}
.light .n-title {
  text-shadow:
    0 0 10px rgb(255 255 255 / 1),
    0 0 3px rgb(255 255 255 / 1);
}
.n-sub {
  font-size: 9.5px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--cc-ink);
  opacity: 0.85;
}
.light .n-sub {
  text-shadow: 0 0 6px #fff;
}

/* Game node — glowing orb with an orbit ring */
.n-game {
  --s: 70px;
  --a: 210px;
}
.n-game .n-orb {
  border-radius: 50%;
  color: var(--cc-ink);
  background:
    radial-gradient(circle at 34% 28%, rgb(255 255 255 / 0.28), transparent 32%),
    radial-gradient(circle at 50% 60%, rgb(var(--c) / 0.42), rgb(var(--c) / 0.12) 55%, rgb(10 6 24 / 0.92) 80%);
  border: 1px solid rgb(var(--c) / 0.65);
  box-shadow:
    0 0 26px rgb(var(--c) / 0.5),
    0 0 70px rgb(var(--c) / 0.18),
    inset 0 0 18px rgb(var(--c) / 0.4);
}
.n-game .n-orb svg {
  width: 32px;
  height: 32px;
  filter: drop-shadow(0 0 6px rgb(var(--c) / 0.9));
}
.light .n-game .n-orb {
  background:
    radial-gradient(circle at 34% 28%, #fff, transparent 40%),
    radial-gradient(circle at 50% 60%, rgb(var(--c) / 0.28), rgb(var(--c) / 0.08) 60%, #fff 85%);
  border-color: color-mix(in oklab, rgb(var(--c)) 70%, #1b1236);
  box-shadow:
    0 10px 28px -6px rgb(var(--c) / 0.55),
    0 0 0 5px rgb(var(--c) / 0.1),
    inset 0 -6px 14px rgb(var(--c) / 0.18);
}
.light .n-game .n-orb svg {
  filter: none;
}
.n-ring {
  position: absolute;
  width: calc(var(--s) + 16px);
  height: calc(var(--s) + 16px);
  left: calc((var(--s) + 16px) / -2);
  top: calc((var(--s) + 16px) / -2);
  border-radius: 50%;
  pointer-events: none;
  background: conic-gradient(
    from 0deg,
    transparent 0 12%,
    rgb(var(--c) / 0.95) 22%,
    transparent 36% 58%,
    rgb(var(--c) / 0.6) 70%,
    transparent 82%
  );
  -webkit-mask: radial-gradient(circle, transparent calc(50% - 1.6px), #000 calc(50% - 1px));
  mask: radial-gradient(circle, transparent calc(50% - 1.6px), #000 calc(50% - 1px));
  animation: spin 9s linear infinite;
}
.n-orbit {
  position: absolute;
  width: calc(var(--s) + 38px);
  height: calc(var(--s) + 38px);
  left: calc((var(--s) + 38px) / -2);
  top: calc((var(--s) + 38px) / -2);
  border-radius: 50%;
  border: 1px dashed rgb(var(--c) / 0.3);
  pointer-events: none;
  animation: spin 40s linear infinite reverse;
}
.n-game .n-label {
  top: calc(var(--s) / 2 + 24px);
}
.n-game .n-title {
  font-size: 15px;
}

/* Category node — rotated plate with a custom icon */
.n-cat {
  --s: 44px;
  --a: 120px;
}
.n-cat .n-orb {
  border-radius: 14px;
  transform: rotate(45deg);
  color: var(--cc-ink);
  background:
    linear-gradient(135deg, rgb(var(--c) / 0.32), rgb(12 8 28 / 0.9) 70%),
    rgb(12 8 28 / 0.9);
  border: 1px solid rgb(var(--c) / 0.6);
  box-shadow:
    0 0 18px rgb(var(--c) / 0.45),
    inset 0 0 12px rgb(var(--c) / 0.3);
}
.node.n-cat:hover .n-orb,
.n-cat .n-orb:focus-visible {
  transform: rotate(45deg) scale(1.12);
}
.n-cat.is-dragging .n-orb {
  transform: rotate(45deg) scale(1.18);
}
.n-cat .n-orb svg {
  transform: rotate(-45deg);
  width: 22px;
  height: 22px;
  filter: drop-shadow(0 0 5px rgb(var(--c) / 0.85));
}
.light .n-cat .n-orb {
  background: linear-gradient(135deg, rgb(var(--c) / 0.22), #fff 75%);
  border-color: color-mix(in oklab, rgb(var(--c)) 65%, #1b1236);
  box-shadow:
    0 8px 20px -6px rgb(var(--c) / 0.55),
    0 0 0 4px rgb(var(--c) / 0.08);
}
.light .n-cat .n-orb svg {
  filter: none;
}
.n-cat .n-label {
  top: calc(var(--s) / 2 + 13px);
}
.n-cat .n-title {
  font-size: 12px;
}

/* Mod node — a bright star */
.n-mod {
  --s: 15px;
  --a: 64px;
}
.n-mod .n-orb {
  border-radius: 50%;
  background: radial-gradient(circle at 38% 34%, #fff 0 18%, rgb(var(--c)) 48%, rgb(var(--c) / 0.35) 75%);
  box-shadow:
    0 0 10px rgb(var(--c) / 0.9),
    0 0 26px rgb(var(--c) / 0.35);
}
.n-mod .n-orb::after {
  content: "";
  position: absolute;
  inset: -5px;
  border-radius: 50%;
  border: 1px solid rgb(var(--c) / 0.45);
  opacity: 0;
  transition: opacity 0.3s;
}
.node.n-mod:hover .n-orb::after,
.n-mod.is-selected .n-orb::after {
  opacity: 1;
}
.light .n-mod .n-orb {
  background: radial-gradient(circle at 38% 34%, #fff 0 18%, color-mix(in oklab, rgb(var(--c)) 80%, #1b1236) 52%, rgb(var(--c) / 0.6) 80%);
  box-shadow:
    0 3px 10px rgb(var(--c) / 0.65),
    0 0 0 3px rgb(var(--c) / 0.14);
}
.n-mod .n-label {
  top: calc(var(--s) / 2 + 7px);
}
.n-mod .n-title {
  font-size: 10.5px;
  font-weight: 500;
  padding: 2px 7px;
  border-radius: 999px;
  background: rgb(10 6 24 / 0.6);
  border: 1px solid rgb(var(--c) / 0.3);
  text-shadow: none;
}
.light .n-mod .n-title {
  background: rgb(255 255 255 / 0.85);
  border-color: rgb(var(--c) / 0.4);
  text-shadow: none;
}
.n-mod.is-forging .n-orb {
  animation: forge-pulse 0.9s ease-in-out infinite;
}

/* Semantic zoom: reveal labels as you get closer, or when in context. */
.n-cat .n-label,
.n-mod .n-label {
  opacity: 0;
  transform: translate(-50%, -4px);
}
.stage[data-zoom="mid"] .n-cat .n-label,
.stage[data-zoom="near"] .n-cat .n-label,
.stage[data-zoom="near"] .n-mod .n-label,
.node[data-label="show"] .n-label,
.node:hover .n-label,
.node.is-selected .n-label,
.node.is-dragging .n-label {
  opacity: 1;
  transform: translate(-50%, 0);
}
.node[data-state="off"] .n-label {
  opacity: 0 !important;
}

.node.is-selected .n-orb {
  box-shadow:
    0 0 0 2px rgb(var(--c) / 0.9),
    0 0 34px rgb(var(--c) / 0.75),
    0 0 90px rgb(var(--c) / 0.3);
}
.light .node.is-selected .n-orb {
  box-shadow:
    0 0 0 2px color-mix(in oklab, rgb(var(--c)) 75%, #1b1236),
    0 12px 32px -6px rgb(var(--c) / 0.6),
    0 0 0 8px rgb(var(--c) / 0.12);
}

.node.is-hit .n-orb {
  animation: node-hit 0.55s var(--ease-out-expo);
}
.node.is-new {
  animation: materialize 1.1s var(--ease-out-expo) both;
}

/* ───────────────────────── Cyrus Core ───────────────────────── */

.core {
  position: absolute;
  left: 0;
  top: 0;
  width: 0;
  height: 0;
  --e: 0;
  --p: 0;
  --f: 0;
  --a1: 0deg;
  --a2: 0deg;
  --a3: 0deg;
  --a4: 0deg;
  --a5: 0deg;
}
.core > * {
  position: absolute;
  left: 50%;
  top: 50%;
  translate: -50% -50%;
  pointer-events: none;
}

.core-bloom {
  width: 640px;
  height: 640px;
  border-radius: 50%;
  background: radial-gradient(
    circle,
    rgb(196 181 253 / 0.38) 0%,
    rgb(139 92 246 / 0.22) 18%,
    rgb(103 232 249 / 0.08) 34%,
    transparent 62%
  );
  opacity: calc(0.6 + var(--e) * 0.4 + var(--p) * 0.3);
  transform: scale(calc(0.92 + var(--e) * 0.22 + var(--p) * 0.14));
  mix-blend-mode: screen;
}
.light .core-bloom {
  mix-blend-mode: multiply;
  background: radial-gradient(
    circle,
    rgb(167 139 250 / 0.35) 0%,
    rgb(167 139 250 / 0.16) 20%,
    rgb(103 232 249 / 0.08) 36%,
    transparent 62%
  );
}

.core-web {
  width: 300px;
  height: 300px;
  opacity: calc(0.55 + var(--e) * 0.45);
  transform: rotate(var(--a5));
  color: rgb(196 181 253);
}
.light .core-web {
  color: rgb(109 40 217);
  opacity: calc(0.4 + var(--e) * 0.4);
}

.core-halo {
  width: var(--hs);
  height: var(--hs);
}
.core-halo .plane {
  width: 100%;
  height: 100%;
}
.core-halo.back {
  clip-path: inset(0 0 50% 0);
}
.core-halo.front {
  clip-path: inset(50% 0 0 0);
}
.core-halo circle {
  transition: stroke-opacity 0.3s;
}

.core-crown {
  width: 196px;
  height: 196px;
  transform: rotate(var(--a4));
  opacity: calc(0.5 + var(--e) * 0.5);
  color: rgb(221 214 254);
}
.light .core-crown {
  color: rgb(109 40 217);
}

.core-orb {
  width: 124px;
  height: 124px;
  border-radius: 50%;
  overflow: hidden;
  transform: scale(calc(1 + var(--p) * 0.07 + var(--e) * 0.05));
  background: radial-gradient(circle at 50% 50%, #2a1760 0%, #120a2c 70%);
  box-shadow:
    0 0 0 1px rgb(196 181 253 / 0.35),
    0 0 calc(40px + var(--e) * 40px) rgb(167 139 250 / calc(0.55 + var(--e) * 0.35)),
    0 0 calc(110px + var(--p) * 60px) rgb(103 232 249 / calc(0.18 + var(--p) * 0.3)),
    inset 0 0 30px rgb(167 139 250 / 0.6);
}
.light .core-orb {
  background: radial-gradient(circle at 50% 50%, #ede9fe 0%, #c4b5fd 70%);
  box-shadow:
    0 0 0 1px rgb(124 58 237 / 0.35),
    0 18px 40px -8px rgb(124 58 237 / calc(0.45 + var(--e) * 0.3)),
    0 0 calc(60px + var(--e) * 40px) rgb(167 139 250 / calc(0.35 + var(--e) * 0.3)),
    inset 0 -10px 30px rgb(124 58 237 / 0.45);
}
.core-orb > div {
  position: absolute;
  inset: 0;
  border-radius: 50%;
}
.core-plasma-a {
  inset: -30% !important;
  background: conic-gradient(
    from 0deg,
    #7c3aed,
    #22d3ee,
    #a78bfa,
    #f0abfc,
    #6366f1,
    #67e8f9,
    #7c3aed
  );
  filter: blur(14px);
  opacity: 0.85;
  transform: rotate(var(--a1));
}
.core-plasma-b {
  inset: -20% !important;
  background:
    radial-gradient(circle at 30% 30%, rgb(255 255 255 / 0.55), transparent 30%),
    radial-gradient(circle at 70% 65%, rgb(103 232 249 / 0.7), transparent 38%),
    radial-gradient(circle at 35% 75%, rgb(240 171 252 / 0.6), transparent 34%);
  filter: blur(6px);
  mix-blend-mode: screen;
  transform: rotate(calc(var(--a2) * -1.4));
}
.core-nucleus {
  inset: 28% !important;
  background: radial-gradient(circle, #fff 0%, rgb(237 233 254 / 0.95) 24%, rgb(196 181 253 / 0.5) 55%, transparent 72%);
  filter: blur(2px);
  transform: scale(calc(0.85 + var(--e) * 0.35 + var(--p) * 0.4));
  opacity: calc(0.75 + var(--e) * 0.25);
}
.core-glint {
  background:
    radial-gradient(ellipse 40% 26% at 36% 22%, rgb(255 255 255 / 0.55), transparent 70%),
    radial-gradient(circle at 50% 50%, transparent 58%, rgb(10 4 30 / 0.55) 100%);
}
.light .core-glint {
  background:
    radial-gradient(ellipse 40% 26% at 36% 22%, rgb(255 255 255 / 0.85), transparent 70%),
    radial-gradient(circle at 50% 50%, transparent 60%, rgb(76 29 149 / 0.35) 100%);
}

.core-hit {
  width: 132px;
  height: 132px;
  border-radius: 50%;
  pointer-events: auto !important;
  cursor: pointer;
}

.core-ripples > span {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 130px;
  height: 130px;
  margin: -65px 0 0 -65px;
  border-radius: 50%;
  border: 1.5px solid rgb(196 181 253 / 0.8);
  box-shadow:
    0 0 18px rgb(167 139 250 / 0.6),
    inset 0 0 18px rgb(103 232 249 / 0.35);
  animation: ripple 1.25s var(--ease-out-expo) forwards;
}
.core-ripples > span.big {
  border-color: rgb(103 232 249 / 0.9);
  animation-duration: 1.8s;
}
.light .core-ripples > span {
  border-color: rgb(124 58 237 / 0.6);
  box-shadow: 0 0 14px rgb(124 58 237 / 0.25);
}
.light .core-ripples > span.big {
  border-color: rgb(8 145 178 / 0.65);
}

.core-label {
  top: calc(50% + 128px) !important;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  white-space: nowrap;
}
.core-label .t {
  font-family: var(--font-space), sans-serif;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.42em;
  margin-right: -0.42em;
  color: var(--ink);
  text-shadow: 0 0 16px rgb(167 139 250 / 0.9);
}
.light .core-label .t {
  text-shadow: 0 0 8px #fff;
}
.core-label .s {
  font-family: var(--font-jb), monospace;
  font-size: 10px;
  letter-spacing: 0.1em;
  color: var(--muted);
}

/* ───────────────────────── Prompt dock ───────────────────────── */

.prompt-shell {
  position: relative;
  border-radius: 24px;
  --spin-speed: 9s;
}
.prompt-shell::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  padding: 1px;
  background: conic-gradient(
    from var(--angle),
    rgb(var(--glow) / 0.18) 0%,
    rgb(103 232 249 / 0.75) 12%,
    rgb(var(--glow) / 0.18) 26%,
    rgb(var(--glow) / 0.18) 48%,
    rgb(240 171 252 / 0.7) 62%,
    rgb(var(--glow) / 0.18) 76%
  );
  -webkit-mask:
    linear-gradient(#000 0 0) content-box,
    linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask:
    linear-gradient(#000 0 0) content-box,
    linear-gradient(#000 0 0);
  mask-composite: exclude;
  animation: border-spin var(--spin-speed) linear infinite;
  pointer-events: none;
  z-index: 2;
}
.prompt-shell::after {
  content: "";
  position: absolute;
  inset: -1px;
  border-radius: inherit;
  background: conic-gradient(
    from var(--angle),
    transparent 0%,
    rgb(103 232 249 / 0.5) 12%,
    transparent 28%,
    transparent 50%,
    rgb(240 171 252 / 0.45) 62%,
    transparent 78%
  );
  filter: blur(18px);
  opacity: 0.25;
  z-index: -1;
  animation: border-spin var(--spin-speed) linear infinite;
  transition: opacity 0.5s;
  pointer-events: none;
}
.prompt-shell[data-active="true"] {
  --spin-speed: 3.2s;
}
.prompt-shell[data-active="true"]::after {
  opacity: 0.6;
}
.prompt-shell[data-busy="true"] {
  --spin-speed: 1.3s;
}
.prompt-shell[data-busy="true"]::after {
  opacity: 0.85;
}
.light .prompt-shell::after {
  opacity: 0.18;
}
.light .prompt-shell[data-active="true"]::after {
  opacity: 0.35;
}

.prompt-textarea::placeholder {
  color: var(--faint);
}

.mic-live {
  background: linear-gradient(135deg, #f43f5e, #d946ef);
  color: #fff;
  box-shadow:
    0 0 0 0 rgb(244 63 94 / 0.6),
    0 0 22px rgb(244 63 94 / 0.55);
  animation: mic-ring 1.4s ease-out infinite;
}
.mic-bars span {
  display: block;
  width: 2.5px;
  border-radius: 2px;
  background: currentColor;
  animation: mic-bar 0.9s ease-in-out infinite;
}

.think-node {
  animation: think-node 1.6s ease-in-out infinite;
}
.think-edge {
  stroke-dasharray: 3 4;
  animation: dash-flow 0.8s linear infinite;
}

/* ───────────────────────── Code view ───────────────────────── */

.code {
  font-family: var(--font-jb), ui-monospace, monospace;
  font-size: 12.5px;
  line-height: 1.7;
  tab-size: 4;
  font-variant-ligatures: contextual;
}
.code .ln {
  color: var(--faint);
  user-select: none;
}
.code .line-new {
  animation: line-in 0.7s ease-out;
}
.tok-k { color: var(--tok-k); }
.tok-s { color: var(--tok-s); }
.tok-n { color: var(--tok-n); }
.tok-c { color: var(--tok-c); font-style: italic; }
.tok-t { color: var(--tok-t); }
.tok-f { color: var(--tok-f); }
.tok-p { color: var(--tok-p); }
.tok-a { color: var(--tok-a); }
.tok-v { color: var(--tok-v); }

.caret {
  display: inline-block;
  width: 7px;
  height: 1.15em;
  margin-left: 1px;
  vertical-align: -0.2em;
  border-radius: 1px;
  background: var(--cyan);
  box-shadow: 0 0 10px var(--cyan);
  animation: caret 0.9s steps(1) infinite;
}

.write-head {
  background: linear-gradient(90deg, rgb(103 232 249 / 0.12), rgb(167 139 250 / 0.06) 60%, transparent);
}
.light .write-head {
  background: linear-gradient(90deg, rgb(8 145 178 / 0.1), rgb(124 58 237 / 0.04) 60%, transparent);
}

.md h1, .md h2, .md h3 {
  font-family: var(--font-space), sans-serif;
  color: var(--ink);
  font-weight: 600;
}
.md h1 { font-size: 1.05rem; margin: 0.2rem 0 0.6rem; }
.md h2 { font-size: 0.92rem; margin: 1rem 0 0.4rem; }
.md h3 { font-size: 0.85rem; margin: 0.8rem 0 0.3rem; }
.md p { margin: 0.35rem 0; color: var(--ink-2); }
.md ul, .md ol { margin: 0.3rem 0 0.5rem; padding-left: 1.1rem; color: var(--ink-2); }
.md ul { list-style: none; padding-left: 0.2rem; }
.md ul li { position: relative; padding-left: 1rem; margin: 0.22rem 0; }
.md ul li::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0.62em;
  width: 5px;
  height: 5px;
  border-radius: 2px;
  transform: rotate(45deg);
  background: var(--accent);
  box-shadow: 0 0 8px var(--accent);
}
.md ol { list-style: decimal; }
.md ol li { margin: 0.22rem 0; }
.md code {
  font-family: var(--font-jb), monospace;
  font-size: 0.8em;
  padding: 1px 5px;
  border-radius: 5px;
  background: rgb(var(--glow) / 0.1);
  color: var(--accent-ink);
}
.md pre {
  font-family: var(--font-jb), monospace;
  font-size: 11.5px;
  padding: 0.7rem 0.8rem;
  border-radius: 10px;
  background: var(--code-bg);
  border: 1px solid var(--line);
  overflow-x: auto;
  margin: 0.5rem 0;
  color: var(--ink-2);
}
.md strong { color: var(--ink); font-weight: 600; }

/* ───────────────────────── Keyframes ───────────────────────── */

@keyframes spin {
  to { transform: rotate(360deg); }
}
@keyframes border-spin {
  to { --angle: 360deg; }
}
@keyframes shimmer {
  0% { background-position: 120% 0; }
  100% { background-position: -120% 0; }
}
@keyframes nebula-drift {
  0% { transform: translate3d(0, 0, 0) scale(1); }
  50% { transform: translate3d(3%, -2%, 0) scale(1.08); }
  100% { transform: translate3d(-3%, 2%, 0) scale(0.96); }
}
@keyframes aurora-flow {
  0% { background-position: 0% 0; }
  100% { background-position: -200% 0; }
}
@keyframes aurora-sway {
  0% { transform: rotate(var(--r, -12deg)) skewX(-8deg) translateY(0) scaleY(1); }
  50% { transform: rotate(var(--r, -12deg)) skewX(6deg) translateY(-3%) scaleY(1.15); }
  100% { transform: rotate(var(--r, -12deg)) skewX(-4deg) translateY(2%) scaleY(0.9); }
}
@keyframes grain {
  0%, 100% { transform: translate(0, 0); }
  20% { transform: translate(-3%, 2%); }
  40% { transform: translate(2%, -3%); }
  60% { transform: translate(-2%, -1%); }
  80% { transform: translate(3%, 3%); }
}
@keyframes ripple {
  0% { transform: scale(0.85); opacity: 0.9; }
  100% { transform: scale(2.6); opacity: 0; }
}
@keyframes node-hit {
  0% { transform: scale(1); }
  30% { transform: scale(1.32); filter: brightness(1.8); }
  100% { transform: scale(1); }
}
@keyframes forge-pulse {
  0%, 100% { transform: scale(1); filter: brightness(1); }
  50% { transform: scale(1.5); filter: brightness(1.7); }
}
@keyframes materialize {
  0% { opacity: 0; filter: blur(8px) brightness(3); }
  40% { opacity: 1; }
  100% { opacity: 1; filter: blur(0) brightness(1); }
}
@keyframes caret {
  0%, 49% { opacity: 1; }
  50%, 100% { opacity: 0; }
}
@keyframes line-in {
  0% { background: rgb(103 232 249 / 0.14); }
  100% { background: transparent; }
}
@keyframes mic-ring {
  0% { box-shadow: 0 0 0 0 rgb(244 63 94 / 0.55), 0 0 22px rgb(244 63 94 / 0.5); }
  100% { box-shadow: 0 0 0 14px rgb(244 63 94 / 0), 0 0 22px rgb(244 63 94 / 0.5); }
}
@keyframes mic-bar {
  0%, 100% { height: 4px; }
  50% { height: 14px; }
}
@keyframes think-node {
  0%, 100% { opacity: 0.35; transform: scale(0.8); }
  50% { opacity: 1; transform: scale(1.15); }
}
@keyframes dash-flow {
  to { stroke-dashoffset: -14; }
}
@keyframes rise-in {
  from { opacity: 0; transform: translateY(10px) scale(0.98); filter: blur(4px); }
  to { opacity: 1; transform: translateY(0) scale(1); filter: blur(0); }
}
@keyframes fade-in {
  from { opacity: 0; }
  to { opacity: 1; }
}
@keyframes slide-in-right {
  from { opacity: 0; transform: translateX(28px); }
  to { opacity: 1; transform: translateX(0); }
}
@keyframes pop-in {
  from { opacity: 0; transform: translateY(6px) scale(0.96); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}
@keyframes progress-sheen {
  from { transform: translateX(-100%); }
  to { transform: translateX(250%); }
}
@keyframes orbit-dot {
  from { transform: rotate(0deg) translateX(7px) rotate(0deg); }
  to { transform: rotate(360deg) translateX(7px) rotate(-360deg); }
}

.animate-rise { animation: rise-in 0.55s var(--ease-out-expo) both; }
.animate-fade { animation: fade-in 0.4s ease both; }
.animate-slide-right { animation: slide-in-right 0.5s var(--ease-out-expo) both; }
.animate-pop { animation: pop-in 0.28s var(--ease-out-expo) both; }

@media (prefers-reduced-motion: reduce) {
  .aurora,
  .nebula,
  .grain,
  .n-ring,
  .n-orbit {
    animation: none !important;
  }
}

