          id: `${mod.id}@v${n}-${Date.now().toString(36)}`,
          label: `v${n}`,
          createdAt: Date.now(),
          model: job.model,
          credits: job.credits,
          prompt: job.prompt,
          summary: ev.summary,
          files: job.files,
          additions,
          deletions,
        };
