    "abstract assert boolean break byte case catch char class const continue default do double else enum extends final finally float for if implements import instanceof int interface long native new package private protected public return short static super switch synchronized this throw throws transient try void volatile while var record true false null yield sealed permits",
  ),
  csharp: words(
    "abstract as base bool break byte case catch char checked class const continue decimal default delegate do double else enum event explicit extern false finally fixed float for foreach goto if implicit in int interface internal is lock long namespace new null object operator out override params private protected public readonly ref return sbyte sealed short sizeof static string struct switch this throw true try typeof uint ulong unchecked unsafe ushort using virtual void volatile while var async await get set init record nameof",
  ),
  papyrus: words(
    "scriptname extends import property auto autoreadonly conditional hidden event endevent function endfunction if elseif else endif while endwhile return state endstate native global int float bool string none true false self parent new as length",
  ),
  lua: words("and break do else elseif end false for function goto if in local nil not or repeat return then true until while self"),
  glsl: words(
    "attribute const uniform varying layout in out inout float int uint void bool true false return if else for while discard struct precision highp mediump lowp break continue",
  ),
};

const GLSL_TYPES = words("vec2 vec3 vec4 ivec2 ivec3 mat2 mat3 mat4 sampler2D samplerCube");

const LINE_COMMENT: Partial<Record<CodeLanguage, string>> = {
  java: "//",
  csharp: "//",
  glsl: "//",
  lua: "--",
  papyrus: ";",
  toml: "#",
};

export interface HLState {
  block: false | "c" | "lua" | "papyrus" | "xml" | "fence";
}

const ident = /[A-Za-z_][A-Za-z0-9_]*/y;
const num = /(0x[0-9a-fA-F]+|\d+(\.\d+)?([eE][+-]?\d+)?)[fFdDLmM]?/y;

function readString(line: string, i: number, quote: string) {
  let j = i + 1;
  while (j < line.length) {
    if (line[j] === "\\") j += 2;
    else if (line[j] === quote) return j + 1;
    else j++;
  }
  return line.length;
}

function codeLine(line: string, lang: CodeLanguage, state: HLState): Tok[] {
  const out: Tok[] = [];
  const kw = KW[lang] ?? new Set<string>();
  const lc = LINE_COMMENT[lang];
  const ci = lang === "papyrus";
  let i = 0;
  const push = (c: TokClass, v: string) => {
    if (!v) return;
    const last = out[out.length - 1];
    if (last && last.c === c) last.v += v;
    else out.push({ c, v });
  };

  while (i < line.length) {
    // Inside a block comment.
    if (state.block) {
      const end = state.block === "lua" ? "]]" : state.block === "papyrus" ? "}" : "*/";
      const k = line.indexOf(end, i);
      if (k < 0) {
        push("c", line.slice(i));
        return out;
      }
      push("c", line.slice(i, k + end.length));
      i = k + end.length;
      state.block = false;
      continue;
    }
    const ch = line[i];
    const rest = line.slice(i);

    if (lang === "lua" && rest.startsWith("--[[")) {
      state.block = "lua";
      continue;
    }
    if (lc && rest.startsWith(lc)) {
      push("c", rest);
      break;
    }
    if ((lang === "java" || lang === "csharp" || lang === "glsl") && rest.startsWith("/*")) {
      state.block = "c";
      push("c", "/*");
      i += 2;
      continue;
    }
    if (lang === "papyrus" && ch === "{") {
      state.block = "papyrus";
      continue;
    }
    if (ch === '"' || (ch === "'" && lang !== "papyrus")) {
      const j = readString(line, i, ch);
      push("s", line.slice(i, j));
      i = j;
      continue;
    }
    if (lang === "csharp" && ch === "$" && line[i + 1] === '"') {
      const j = readString(line, i + 1, '"');
      push("s", line.slice(i, j));
      i = j;
      continue;
    }
    if ((lang === "java" || lang === "csharp") && ch === "@") {
      ident.lastIndex = i + 1;
      const m = ident.exec(line);
      if (m) {
        push("a", "@" + m[0]);
        i += 1 + m[0].length;
        continue;
      }
    }
    if (lang === "glsl" && ch === "#") {
      push("a", rest);
      break;
    }
    if (lang === "csharp" && ch === "[" && /^\[[A-Z]\w*(\(.*?\))?\]/.test(rest)) {
      const m = rest.match(/^\[[A-Z]\w*(\(.*?\))?\]/)!;
      push("a", m[0]);
      i += m[0].length;
      continue;
    }
    if (/[0-9]/.test(ch) && !/[A-Za-z_]/.test(line[i - 1] ?? "")) {
      num.lastIndex = i;
      const m = num.exec(line);
      if (m) {
        push("n", m[0]);
        i += m[0].length;
        continue;
      }
    }
    if (/[A-Za-z_]/.test(ch)) {
      ident.lastIndex = i;
      const m = ident.exec(line)!;
      const w = m[0];
      const key = ci ? w.toLowerCase() : w;
      let j = i + w.length;
      while (line[j] === " ") j++;
      if (kw.has(key)) push("k", w);
      else if (lang === "glsl" && GLSL_TYPES.has(w)) push("t", w);
      else if (line[j] === "(") push("f", w);
      else if (/^[A-Z]/.test(w) && lang !== "lua") push("t", w);
      else if (line[i - 1] === "." || line[i - 1] === ":") push("v", w);
      else push("", w);
      i += w.length;
      continue;
    }
    if (/[{}()[\];,.<>=+\-*/%!&|?:~^]/.test(ch)) {
      push("p", ch);
      i++;
      continue;
    }
    push("", ch);
    i++;
  }
  return out;
}

function jsonLine(line: string): Tok[] {
  const out: Tok[] = [];
  const re = /("(?:\\.|[^"\\])*")(\s*:)?|(-?\d+(?:\.\d+)?(?:[eE][+-]?\d+)?)|\b(true|false|null)\b|([{}[\],:])|(\s+)|(.)/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(line))) {
    if (m[1]) {
      out.push({ c: m[2] ? "v" : "s", v: m[1] });
      if (m[2]) out.push({ c: "p", v: m[2] });
    } else if (m[3]) out.push({ c: "n", v: m[3] });
    else if (m[4]) out.push({ c: "k", v: m[4] });
    else if (m[5]) out.push({ c: "p", v: m[5] });
    else out.push({ c: "", v: m[0] });
  }
  return out;
}

function mdLine(line: string, state: HLState): Tok[] {
  if (line.trimStart().startsWith("```")) {
    state.block = state.block === "fence" ? false : "fence";
    return [{ c: "c", v: line }];
  }
  if (state.block === "fence") return [{ c: "t", v: line }];
  if (/^#{1,6}\s/.test(line)) return [{ c: "k", v: line }];
  const out: Tok[] = [];
  const bullet = line.match(/^(\s*)([-*]|\d+\.)\s/);
  let rest = line;
  if (bullet) {
    out.push({ c: "", v: bullet[1] }, { c: "a", v: bullet[2] + " " });
    rest = line.slice(bullet[0].length);
  }
  const re = /(`[^`]+`)|(\*\*[^*]+\*\*)|(\[[^\]]+\]\([^)]+\))|([^`*[]+|.)/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(rest))) {
    if (m[1]) out.push({ c: "s", v: m[1] });
    else if (m[2]) out.push({ c: "v", v: m[2] });
    else if (m[3]) out.push({ c: "f", v: m[3] });
    else out.push({ c: "", v: m[0] });
  }
  return out;
}

function xmlLine(line: string, state: HLState): Tok[] {
  const out: Tok[] = [];
  let i = 0;
  while (i < line.length) {
    if (state.block === "xml") {
      const k = line.indexOf("-->", i);
      if (k < 0) {
        out.push({ c: "c", v: line.slice(i) });
        return out;
      }
      out.push({ c: "c", v: line.slice(i, k + 3) });
      i = k + 3;
      state.block = false;
      continue;
    }
    if (line.startsWith("<!--", i)) {
      state.block = "xml";
      continue;
    }
    if (line[i] === "<") {
      const end = line.indexOf(">", i);
      const tag = line.slice(i, end < 0 ? line.length : end + 1);
      const re = /(<\/?|\/?>|\?>)|([\w:.-]+)(=)("[^"]*")|([\w:.-]+)|(\s+)|(.)/g;
      let m: RegExpExecArray | null;
      let first = true;
      while ((m = re.exec(tag))) {
        if (m[1]) out.push({ c: "p", v: m[1] });
        else if (m[2]) out.push({ c: "v", v: m[2] }, { c: "p", v: m[3] }, { c: "s", v: m[4] });
        else if (m[5]) {
          out.push({ c: first ? "k" : "v", v: m[5] });
          first = false;
        } else out.push({ c: "", v: m[0] });
      }
      i += tag.length;
      continue;
    }
    const next = line.indexOf("<", i);
    const text = line.slice(i, next < 0 ? line.length : next);
    out.push({ c: "", v: text });
    i += text.length;
  }
  return out;
}

function tomlLine(line: string): Tok[] {
  if (/^\s*#/.test(line)) return [{ c: "c", v: line }];
  if (/^\s*\[.*\]\s*$/.test(line)) return [{ c: "k", v: line }];
  const m = line.match(/^(\s*)([\w.-]+)(\s*[=:]\s*)(.*)$/);
  if (!m) return [{ c: "", v: line }];
  const val = m[4];
  const c: TokClass = /^["']/.test(val) ? "s" : /^-?\d/.test(val) ? "n" : /^(true|false)$/.test(val) ? "k" : "";
  return [
    { c: "", v: m[1] },
    { c: "v", v: m[2] },
    { c: "p", v: m[3] },
    { c, v: val },
  ];
}

/** Tokenizes a whole file into lines of tokens. Stateful across lines for block comments. */
export function highlight(code: string, lang: CodeLanguage): Tok[][] {
  const state: HLState = { block: false };
  return code.split("\n").map((line) => {
    switch (lang) {
      case "json":
        return jsonLine(line);
      case "markdown":
        return mdLine(line, state);
      case "xml":
        return xmlLine(line, state);
      case "toml":
      case "text":
        return lang === "toml" ? tomlLine(line) : [{ c: "", v: line }];
      default:
        return codeLine(line, lang, state);
    }
  });
}

export const LANG_LABEL: Record<CodeLanguage, string> = {
  java: "Java",
  papyrus: "Papyrus",
  csharp: "C#",
  lua: "Lua",
  glsl: "GLSL",
  json: "JSON",
  markdown: "Markdown",
  xml: "XML",
  toml: "TOML",
  text: "Text",
};

export const LANG_RGB: Record<CodeLanguage, string> = {
  java: "251 146 60",
  papyrus: "125 211 252",
  csharp: "167 139 250",
  lua: "96 165 250",
  glsl: "232 121 249",
  json: "250 204 21",
  markdown: "148 163 184",
  xml: "52 211 153",
  toml: "244 114 182",
  text: "148 163 184",
};

