"use client";

import { useEffect, useRef } from "react";
import { camera } from "@/lib/camera";
import { useStore } from "@/lib/store";

interface Star {
  x: number;
  y: number;
  r: number;
  a: number;
  tw: number;
  ph: number;
  d: number;
  tint: number;
}

const TINTS_DARK = ["255 255 255", "221 214 254", "196 181 253", "165 243 252", "251 207 232"];
const TINTS_LIGHT = ["124 58 237", "139 92 246", "8 145 178", "192 38 211", "99 102 241"];

export function CosmosBackground() {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const theme = useStore((s) => s.theme);
  const themeRef = useRef(theme);
  themeRef.current = theme;

  useEffect(() => {
    const canvas = canvasRef.current!;
    const ctx = canvas.getContext("2d")!;
    let W = 0;
    let H = 0;
    let dpr = 1;
    let stars: Star[] = [];
    let shooting: { x: number; y: number; vx: number; vy: number; life: number } | null = null;
    let nextShot = performance.now() + 6000;
    let raf = 0;
    let last = 0;

    const resize = () => {
      dpr = Math.min(window.devicePixelRatio || 1, 2);
      W = window.innerWidth;
      H = window.innerHeight;
      canvas.width = W * dpr;
      canvas.height = H * dpr;
      canvas.style.width = `${W}px`;
      canvas.style.height = `${H}px`;
      const count = Math.min(520, Math.round((W * H) / 3600));
      stars = Array.from({ length: count }, () => {
        const big = Math.random() < 0.06;
        return {
          x: Math.random(),
          y: Math.random(),
          r: big ? 0.9 + Math.random() * 0.8 : 0.25 + Math.random() * 0.6,
          a: big ? 0.55 + Math.random() * 0.35 : 0.12 + Math.random() * 0.4,
          tw: 0.4 + Math.random() * 1.6,
          ph: Math.random() * Math.PI * 2,
          d: 0.2 + Math.random() * 0.8,
          tint: Math.random() < 0.7 ? 0 : 1 + Math.floor(Math.random() * 4),
        };
      });
    };
    resize();
    window.addEventListener("resize", resize);

    const frame = (now: number) => {
