/** Live camera state, written by the network loop and read by the starfield for parallax. */
export const camera = { x: 0, y: 0, k: 1 };

type Listener = (k: number) => void;

/** Commands the chrome can send to the network without going through React state. */
export const cameraApi = {
  zoomBy: (_factor: number) => {},
  listeners: new Set<Listener>(),
  onZoom(fn: Listener) {
    this.listeners.add(fn);
    return () => {
      this.listeners.delete(fn);
    };
  },
  emitZoom(k: number) {
    for (const fn of this.listeners) fn(k);
  },
};

