"use client";

import type { Ref } from "react";

interface Halo {
  size: number;
  tilt: number;
  rx: number;
  angle: string;
  from: string;
  to: string;
  width: number;
  dash: string;
  sats: number[];
}

// Each halo is a tilted ring. Its back half renders behind the orb and its front half in front,
// so the rings read as wrapping around the core in 3D.
const HALOS: Halo[] = [
  { size: 400, tilt: -14, rx: 75, angle: "--a1", from: "#c4b5fd", to: "#67e8f9", width: 1.4, dash: "2 6", sats: [0, 160] },
  { size: 300, tilt: 22, rx: 70, angle: "--a2", from: "#67e8f9", to: "#a78bfa", width: 2, dash: "60 18 6 18", sats: [90] },
  { size: 470, tilt: -32, rx: 79, angle: "--a3", from: "#f0abfc", to: "#818cf8", width: 1.1, dash: "1 7", sats: [40, 200, 300] },
];

function HaloRing({ h, idx, half }: { h: Halo; idx: number; half: "back" | "front" }) {
  const sw = (h.width / h.size) * 100;
  const gid = `halo-g-${idx}-${half}`;
  return (
    <div className={`core-halo ${half}`} style={{ ["--hs" as string]: `${h.size}px`, transform: `rotate(${h.tilt}deg)` }}>
      <div className="plane" style={{ transform: `rotateX(${h.rx}deg) rotateZ(var(${h.angle}))` }}>
        <svg viewBox="0 0 100 100" width="100%" height="100%" style={{ overflow: "visible" }}>
          <defs>
            <linearGradient id={gid} x1="0" y1="0" x2="1" y2="1">
              <stop offset="0%" stopColor={h.from} />
              <stop offset="55%" stopColor={h.to} stopOpacity="0.35" />
              <stop offset="100%" stopColor={h.from} />
            </linearGradient>
          </defs>
          {/* soft glow */}
          <circle cx="50" cy="50" r="48" fill="none" stroke={`url(#${gid})`} strokeWidth={sw * 5} strokeOpacity="0.12" />
          <circle
            cx="50"
            cy="50"
            r="48"
            fill="none"
            stroke={`url(#${gid})`}
            strokeWidth={sw}
            strokeDasharray={h.dash
              .split(" ")
              .map((n) => (Number(n) / h.size) * 100 * 1.6)
              .join(" ")}
            strokeLinecap="round"
            style={{ strokeOpacity: "calc(0.55 + var(--e) * 0.45)" as unknown as number }}
          />
          {h.sats.map((deg) => {
            const a = (deg * Math.PI) / 180;
            const x = 50 + 48 * Math.cos(a);
            const y = 50 + 48 * Math.sin(a);
            return (
              <g key={deg}>
                <circle cx={x} cy={y} r={(5 / h.size) * 100 * 2.2} fill={h.from} opacity="0.25" />
                <circle cx={x} cy={y} r={(5 / h.size) * 100 * 0.7} fill="#fff" />
              </g>
            );
          })}
        </svg>
      </div>
    </div>
  );
}

function CoreWeb() {
  const spokes = 12;
  const rings = [33, 41, 49];
  const poly = (r: number) =>
    Array.from({ length: spokes }, (_, i) => {
      const a = (i / spokes) * Math.PI * 2;
      return `${50 + r * Math.cos(a)},${50 + r * Math.sin(a)}`;
    }).join(" ");
  return (
    <svg className="core-web" viewBox="0 0 100 100" aria-hidden>
      {Array.from({ length: spokes }, (_, i) => {
        const a = (i / spokes) * Math.PI * 2;
        return (
          <line
            key={i}
            x1={50 + 24 * Math.cos(a)}
            y1={50 + 24 * Math.sin(a)}
            x2={50 + 50 * Math.cos(a)}
            y2={50 + 50 * Math.sin(a)}
            stroke="currentColor"
            strokeOpacity="0.28"
            strokeWidth="0.25"
          />
        );
      })}
      {rings.map((r, i) => (
        <polygon key={r} points={poly(r)} fill="none" stroke="currentColor" strokeOpacity={0.12 + i * 0.05} strokeWidth="0.25" strokeDasharray={i === 1 ? "0.8 1.6" : undefined} />
      ))}
    </svg>
  );
}

function CoreCrown() {
  const ticks = 72;
  return (
    <svg className="core-crown" viewBox="0 0 100 100" aria-hidden>
      {Array.from({ length: ticks }, (_, i) => {
        const a = (i / ticks) * Math.PI * 2;
        const long = i % 6 === 0;
        const r1 = long ? 43.5 : 45.5;
        return (
          <line
            key={i}
            x1={50 + r1 * Math.cos(a)}
            y1={50 + r1 * Math.sin(a)}
            x2={50 + 48 * Math.cos(a)}
            y2={50 + 48 * Math.sin(a)}
            stroke="currentColor"
            strokeOpacity={long ? 0.75 : 0.32}
            strokeWidth={long ? 0.5 : 0.3}
            strokeLinecap="round"
          />
        );
      })}
      {[0, 90, 180, 270].map((d) => {
        const a = (d * Math.PI) / 180;
        const x = 50 + 40.5 * Math.cos(a);
        const y = 50 + 40.5 * Math.sin(a);
        return <circle key={d} cx={x} cy={y} r="0.9" fill="currentColor" />;
      })}
      <circle cx="50" cy="50" r="38.5" fill="none" stroke="currentColor" strokeOpacity="0.18" strokeWidth="0.25" />
    </svg>
  );
}

export function CyrusCore({
  coreRef,
  rippleRef,
  statusRef,
  onActivate,
}: {
  coreRef: Ref<HTMLDivElement>;
  rippleRef: Ref<HTMLDivElement>;
  statusRef: Ref<HTMLSpanElement>;
  onActivate: () => void;
