import type { SimulationLinkDatum, SimulationNodeDatum } from "d3-force";
import { CATEGORY_BY_KEY, GAMES, categoryNodeId } from "@/lib/data";
import { CORE_ID } from "@/lib/store";
import type { CategoryKey, GameId, Mod, Selection } from "@/lib/types";

export type NodeType = "core" | "game" | "category" | "mod";

export interface GNode extends SimulationNodeDatum {
  id: string;
  type: NodeType;
  parent?: string;
  gameId?: GameId;
  category?: CategoryKey;
  modId?: string;
  rgb: string;
  label: string;
  sub?: string;
  phase: number;
  /** Ideal angle around the core, used for the initial bloom. */
  angle: number;
}

export interface GLink extends SimulationLinkDatum<GNode> {
  id: string;
  source: string | GNode;
  target: string | GNode;
  kind: Exclude<NodeType, "core">;
  curve: number;
}

export const CORE_RGB = "167 139 250";

function hash(s: string) {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) h = Math.imul(h ^ s.charCodeAt(i), 16777619);
  return (h >>> 0) / 4294967295;
}

export function buildGraph(mods: Mod[]) {
  const nodes: GNode[] = [{ id: CORE_ID, type: "core", rgb: CORE_RGB, label: "Cyrus Core", phase: 0, angle: 0, fx: 0, fy: 0, x: 0, y: 0 }];
  const links: GLink[] = [];

  GAMES.forEach((game, gi) => {
    const ga = -Math.PI / 2 + (gi / GAMES.length) * Math.PI * 2;
    const gameMods = mods.filter((m) => m.gameId === game.id);
    nodes.push({
      id: game.id,
      type: "game",
      parent: CORE_ID,
      gameId: game.id,
      rgb: game.rgb,
      label: game.name,
      sub: `${game.toolchain}`,
      phase: hash(game.id) * Math.PI * 2,
      angle: ga,
    });
    links.push({ id: `${CORE_ID}>${game.id}`, source: CORE_ID, target: game.id, kind: "game", curve: gi % 2 ? 0.06 : -0.06 });

    // A game's categories are its defaults plus any category a generated mod landed in.
    const cats = [...game.categories];
    for (const m of gameMods) if (!cats.includes(m.category)) cats.push(m.category);
    const spread = ((Math.PI * 2) / GAMES.length) * 0.78;

    cats.forEach((key, ci) => {
      const cid = categoryNodeId(game.id, key);
      const meta = CATEGORY_BY_KEY[key];
      const ca = ga + (cats.length === 1 ? 0 : (ci / (cats.length - 1) - 0.5) * spread);
      const catMods = gameMods.filter((m) => m.category === key);
      nodes.push({
        id: cid,
        type: "category",
        parent: game.id,
        gameId: game.id,
        category: key,
        rgb: meta.rgb,
        label: meta.label,
        sub: `${catMods.length} mod${catMods.length === 1 ? "" : "s"}`,
        phase: hash(cid) * Math.PI * 2,
        angle: ca,
      });
      links.push({ id: `${game.id}>${cid}`, source: game.id, target: cid, kind: "category", curve: (hash(cid) - 0.5) * 0.3 });

      catMods.forEach((m, mi) => {
        const ma = ca + (catMods.length === 1 ? 0 : (mi / (catMods.length - 1) - 0.5) * 0.9);
        nodes.push({
          id: m.id,
          type: "mod",
          parent: cid,
          gameId: game.id,
          category: key,
          modId: m.id,
          rgb: meta.rgb,
          label: m.name,
          phase: hash(m.id) * Math.PI * 2,
          angle: ma,
        });
        links.push({ id: `${cid}>${m.id}`, source: cid, target: m.id, kind: "mod", curve: (hash(m.id) - 0.5) * 0.35 });
      });
    });
  });

  return { nodes, links };
}

/** Ideal radius from the core for each tier — used for the initial bloom layout. */
export const TIER_RADIUS: Record<NodeType, number> = { core: 0, game: 270, category: 400, mod: 470 };

export type NodeState = "on" | "near" | "off";

export function selectedNodeId(sel: Selection): string {
  if (sel.level === "mod" && sel.modId) return sel.modId;
  if (sel.level === "category" && sel.gameId && sel.category) return categoryNodeId(sel.gameId, sel.category);
  if (sel.level === "game" && sel.gameId) return sel.gameId;
  return CORE_ID;
}

/** Dims everything outside the branch you've jumped into. */
export function computeStates(nodes: GNode[], sel: Selection): { state: Map<string, NodeState>; labels: Set<string> } {
  const state = new Map<string, NodeState>();
  const labels = new Set<string>();
  for (const n of nodes) {
    if (sel.level === "core" || n.type === "core") {
      state.set(n.id, "on");
      continue;
    }
    const sameGame = n.gameId === sel.gameId;
    const sameCat = sameGame && n.category === sel.category;
    let s: NodeState = "off";
    if (sel.level === "game") {
      s = sameGame ? "on" : "off";
      if (sameGame && n.type === "category") labels.add(n.id);
    } else if (sel.level === "category") {
      if (n.type === "game") s = sameGame ? "on" : "off";
      else if (n.type === "category") s = sameCat ? "on" : sameGame ? "near" : "off";
      else s = sameCat ? "on" : "off";
      if (sameGame && n.type === "category") labels.add(n.id);
      if (sameCat && n.type === "mod") labels.add(n.id);
    } else if (sel.level === "mod") {
      if (n.type === "game") s = sameGame ? "on" : "off";
      else if (n.type === "category") s = sameCat ? "on" : sameGame ? "near" : "off";
      else s = n.id === sel.modId ? "on" : sameCat ? "near" : "off";
