"use client";

import {
  forceCollide,
  forceLink,
  forceManyBody,
  forceRadial,
  forceSimulation,
  type Simulation,
} from "d3-force";
import { memo, useCallback, useEffect, useMemo, useRef, type PointerEvent as RPointerEvent } from "react";
import { CategoryIcon } from "@/components/icons/CategoryIcons";
import { GameEmblem } from "@/components/icons/GameEmblems";
import { camera, cameraApi } from "@/lib/camera";
import { GAME_BY_ID } from "@/lib/data";
import { fx } from "@/lib/fx";
import { CORE_ID, isJobLive, useAllMods, useStore } from "@/lib/store";
import { CyrusCore } from "./CyrusCore";
import {
  CORE_RGB,
  TIER_RADIUS,
  buildGraph,
  computeStates,
  selectedNodeId,
  type GLink,
  type GNode,
  type NodeState,
  type NodeType,
} from "./graph";

type RNode = GNode & { rx: number; ry: number; ink: string };
type RLink = GLink & { cx: number; cy: number };

interface Packet {
  path: string[];
  seg: number;
  t: number;
  speed: number;
  rgb: string;
  size: number;
  trail: number;
  ambient: boolean;
  delay: number;
}
interface Mote {
  a: number;
  r: number;
  va: number;
  vr: number;
  life: number;
  rgb: string;
  size: number;
}
interface Spark {
  x: number;
  y: number;
  vx: number;
  vy: number;
  life: number;
  rgb: string;
}
interface Ring {
  id: string;
  t: number;
  rgb: string;
}

const LINK_DIST: Record<GLink["kind"], number> = { game: 270, category: 125, mod: 58 };
const LINK_STRENGTH: Record<GLink["kind"], number> = { game: 0.5, category: 0.7, mod: 0.85 };
const CHARGE: Record<NodeType, number> = { core: -1600, game: -700, category: -260, mod: -60 };
const COLLIDE: Record<NodeType, number> = { core: 175, game: 62, category: 38, mod: 17 };
const RADIAL_STRENGTH: Record<NodeType, number> = { core: 0, game: 0.1, category: 0.04, mod: 0.02 };
const FOCUS_K: Record<NodeType, number> = { core: 1, game: 1.2, category: 1.65, mod: 2.1 };
const MOTE_COLORS = ["103 232 249", "196 181 253", "240 171 252", "165 180 252"];

const clamp = (v: number, a: number, b: number) => Math.max(a, Math.min(b, v));

/** Darkens a neon "r g b" triple so it reads on a white background. */
function inkOf(rgb: string) {
  const [r, g, b] = rgb.split(" ").map(Number);
  const m = (c: number, t: number) => Math.round(c * 0.66 + t * 0.34);
  return `${m(r, 40)} ${m(g, 20)} ${m(b, 90)}`;
}

function bez(s: RNode, l: RLink, e: RNode, t: number) {
  const u = 1 - t;
  return {
    x: u * u * s.rx + 2 * u * t * l.cx + t * t * e.rx,
    y: u * u * s.ry + 2 * u * t * l.cy + t * t * e.ry,
  };
}

export function Network() {
  const mods = useAllMods();
  const selection = useStore((s) => s.selection);
  const focus = useStore((s) => s.focus);
  const theme = useStore((s) => s.theme);
  const panelOpen = useStore((s) => s.panelOpen);
  const navOpen = useStore((s) => s.navOpen);
  const forgingId = useStore((s) => (isJobLive(s.job) ? s.job!.modId : undefined));
  const select = useStore((s) => s.select);

  const stageRef = useRef<HTMLDivElement>(null);
  const worldRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const coreRef = useRef<HTMLDivElement>(null);
  const rippleRef = useRef<HTMLDivElement>(null);
  const statusRef = useRef<HTMLSpanElement>(null);
  const nodeEls = useRef(new Map<string, HTMLDivElement>());
  const initialIds = useRef<Set<string> | null>(null);

  const graph = useMemo(() => buildGraph(mods), [mods]);
  if (!initialIds.current) initialIds.current = new Set(graph.nodes.map((n) => n.id));

  const S = useRef({
    sim: null as Simulation<RNode, RLink> | null,
    nodes: new Map<string, RNode>(),
    links: [] as RLink[],
    pairs: new Map<string, RLink>(),
    children: new Map<string, string[]>(),
    cam: { x: 0, y: 0, k: 0.3 },
    target: { x: 0, y: 0, k: 0.75 },
    follow: null as null | { kind: "node" | "path"; id: string; k: number },
    insets: { l: 72, r: 0, t: 64, b: 210 },
    W: 0,
    H: 0,
    dpr: 1,
    states: new Map<string, NodeState>(),
    hovered: null as string | null,
    drag: null as null | { id: string; sx: number; sy: number; ox: number; oy: number; moved: boolean },
    pan: null as null | { sx: number; sy: number; cx: number; cy: number; moved: boolean },
    packets: [] as Packet[],
    motes: [] as Mote[],
    sparks: [] as Spark[],
    rings: [] as Ring[],
    angles: [0, 0, 0, 0, 0],
    streamTimer: 0,
    moteAcc: 0,
    zoomLevel: "",
    lastK: 0,
    dark: true,
    modCount: 0,
    flashTimers: new Map<string, number>(),
  });

  // Keep render-loop inputs fresh without re-running effects.
  S.current.dark = theme === "dark";
  S.current.modCount = mods.length;

  const fitK = useCallback(() => {
    const st = S.current;
    const aw = st.W - st.insets.l - st.insets.r;
    const ah = st.H - st.insets.t - st.insets.b;
    return clamp(Math.min(aw / 1120, ah / 1040), 0.32, 1.1);
  }, []);

  /* ───────────── Graph sync: create or update the simulation ───────────── */
  useEffect(() => {
    const st = S.current;
    const first = !st.sim;
    const nodes: RNode[] = graph.nodes.map((g) => {
      const prev = st.nodes.get(g.id);
      if (prev) {
        prev.label = g.label;
        prev.sub = g.sub;
        prev.rgb = g.rgb;
        prev.ink = inkOf(g.rgb);
        return prev;
      }
      const n = g as RNode;
      n.ink = inkOf(g.rgb);
      if (n.type === "core") {
        n.x = n.y = n.rx = n.ry = 0;
        n.fx = 0;
        n.fy = 0;
      } else if (first) {
        // Bloom outward from the core on first load.
        const r = TIER_RADIUS[n.type] * 0.14;
        n.x = n.rx = Math.cos(n.angle) * r;
        n.y = n.ry = Math.sin(n.angle) * r;
      } else {
        const parent = n.parent ? st.nodes.get(n.parent) : undefined;
        const px = parent?.x ?? 0;
        const py = parent?.y ?? 0;
        const len = Math.hypot(px, py) || 1;
        n.x = n.rx = px + (px / len) * 24 + (Math.random() - 0.5) * 10;
        n.y = n.ry = py + (py / len) * 24 + (Math.random() - 0.5) * 10;
      }
      return n;
    });
    st.nodes = new Map(nodes.map((n) => [n.id, n]));
    const links = graph.links.map((l) => ({ ...l, cx: 0, cy: 0 })) as RLink[];

    if (!st.sim) {
      st.sim = forceSimulation<RNode, RLink>()
        .velocityDecay(0.36)
        .alphaDecay(0.016)
        .stop();
    }
    const sim = st.sim;
    sim.nodes(nodes);
    sim
      .force(
        "link",
        forceLink<RNode, RLink>(links)
          .id((d) => d.id)
          .distance((l) => LINK_DIST[l.kind])
          .strength((l) => LINK_STRENGTH[l.kind]),
      )
      .force("charge", forceManyBody<RNode>().strength((d) => CHARGE[d.type]).distanceMax(560))
      .force("collide", forceCollide<RNode>((d) => COLLIDE[d.type]).strength(0.85).iterations(2))
      .force("radial", forceRadial<RNode>((d) => TIER_RADIUS[d.type], 0, 0).strength((d) => RADIAL_STRENGTH[d.type]));
    sim.alpha(first ? 1 : Math.max(sim.alpha(), 0.35));

    // forceLink resolves string ids into node objects.
    st.links = links;
    st.pairs = new Map();
    st.children = new Map();
    for (const l of links) {
      const s = l.source as RNode;
      const t = l.target as RNode;
      st.pairs.set(`${s.id}|${t.id}`, l);
      st.pairs.set(`${t.id}|${s.id}`, l);
      st.children.set(s.id, [...(st.children.get(s.id) ?? []), t.id]);
    }
  }, [graph]);

  /* ───────────── Node states (dimming) ───────────── */
  const { state: nodeStates, labels } = useMemo(() => computeStates(graph.nodes, selection), [graph, selection]);
  useEffect(() => {
    S.current.states = nodeStates;
  }, [nodeStates]);

  /* ───────────── Insets that frame the camera ───────────── */
  useEffect(() => {
    const st = S.current;
    const wide = window.innerWidth >= 1024;
    st.insets = {
      l: window.innerWidth < 768 ? 0 : navOpen ? 300 : 72,
      r: panelOpen && wide ? Math.min(560, window.innerWidth * 0.4) : 0,
      t: 64,
      b: window.innerWidth < 768 ? 230 : 210,
    };
  }, [panelOpen, navOpen]);

  /* ───────────── Camera focus requests ───────────── */
  useEffect(() => {
    const st = S.current;
    if (focus.kind === "overview" || !focus.id || focus.id === CORE_ID) {
      st.follow = null;
      st.target = { x: 0, y: 0, k: fitK() };
      return;
    }
    const n = st.nodes.get(focus.id);
    const type: NodeType = n?.type ?? "mod";
    st.follow = { kind: focus.kind === "path" ? "path" : "node", id: focus.id, k: FOCUS_K[type] };
  }, [focus, fitK]);

  /* ───────────── The render loop ───────────── */
  useEffect(() => {
    const st = S.current;
    const stage = stageRef.current!;
    const world = worldRef.current!;
    const canvas = canvasRef.current!;
    const ctx = canvas.getContext("2d")!;
    let raf = 0;
    let last = performance.now();
    let readyAt = last + 120;

    const resize = () => {
      st.dpr = Math.min(window.devicePixelRatio || 1, 2);
      st.W = stage.clientWidth;
      st.H = stage.clientHeight;
      canvas.width = st.W * st.dpr;
      canvas.height = st.H * st.dpr;
      canvas.style.width = `${st.W}px`;
      canvas.style.height = `${st.H}px`;
    };
    resize();
    st.target.k = fitK();
    st.cam.k = st.target.k * 0.55;
    const ro = new ResizeObserver(() => {
      resize();
      if (!st.follow) st.target.k = fitK();
    });
    ro.observe(stage);

    const viewCenter = () => ({
      x: st.insets.l + (st.W - st.insets.l - st.insets.r) / 2,
      y: st.insets.t + (st.H - st.insets.t - st.insets.b) / 2,
    });

    const flash = (id: string) => {
      const el = id === CORE_ID ? null : nodeEls.current.get(id);
      if (!el) return;
      el.classList.remove("is-hit");
      void el.offsetWidth;
      el.classList.add("is-hit");
      window.clearTimeout(st.flashTimers.get(id));
      st.flashTimers.set(
        id,
        window.setTimeout(() => el.classList.remove("is-hit"), 600),
      );
    };

    const ripple = (big = false) => {
      const host = rippleRef.current;
      if (!host || host.childElementCount > 9) return;
      const span = document.createElement("span");
      if (big) span.className = "big";
      span.addEventListener("animationend", () => span.remove());
      host.appendChild(span);
    };

    const spawnPacket = (path: string[], opts: Partial<Packet> = {}) => {
      if (path.length < 2 || path.some((id) => !st.nodes.has(id))) return;
      st.packets.push({ path: [...path], seg: 0, t: 0, speed: 1, rgb: CORE_RGB, size: 1, trail: 0.22, ambient: false, delay: 0, ...opts });
    };

    const burst = (id: string, rgb: string) => {
      const n = st.nodes.get(id);
      if (!n) return;
      st.rings.push({ id, t: 0, rgb });
      for (let i = 0; i < 28; i++) {
        const a = Math.random() * Math.PI * 2;
        const v = 60 + Math.random() * 160;
        st.sparks.push({ x: n.rx, y: n.ry, vx: Math.cos(a) * v, vy: Math.sin(a) * v, life: 1, rgb: Math.random() < 0.3 ? "255 255 255" : rgb });
      }
      flash(id);
    };

    cameraApi.zoomBy = (f: number) => {
      st.target.k = clamp(st.target.k * f, 0.3, 3.2);
    };

    const loop = (now: number) => {
      raf = requestAnimationFrame(loop);
      const dt = Math.min(0.05, (now - last) / 1000);
      last = now;
      const t = now / 1000;
      const dark = st.dark;
      const { sim } = st;

      /* physics */
      if (sim && (sim.alpha() > sim.alphaMin() || st.drag?.moved)) sim.tick();

      /* energy & core rhythm */
      fx.energy = Math.max(0, fx.energy - dt * 0.5);
      const e = fx.energy;
      const mode = fx.mode;
      const pulse =
        mode === "forging"
          ? Math.pow(0.5 + 0.5 * Math.sin(t * Math.PI * 2 * 1.25), 6)
          : mode === "thinking"
            ? Math.pow(0.5 + 0.5 * Math.sin(t * Math.PI * 2 * 0.9), 4) * 0.7
            : (0.5 + 0.5 * Math.sin(t * Math.PI * 2 * 0.2)) * 0.22;
      const f = mode === "forging" ? 1 : mode === "thinking" ? 0.6 : 0;

      /* rendered positions (sim + gentle float) */
      for (const n of st.nodes.values()) {
        if (n.type === "core") continue;
        const amp = n.type === "game" ? 3 : n.type === "category" ? 4.5 : 5.5;
        const still = st.drag?.id === n.id;
        n.rx = (n.x ?? 0) + (still ? 0 : Math.sin(t * 0.55 + n.phase) * amp);
        n.ry = (n.y ?? 0) + (still ? 0 : Math.cos(t * 0.47 + n.phase * 1.7) * amp);
      }

      /* camera */
      const vc = viewCenter();
      if (st.follow) {
        const n = st.nodes.get(st.follow.id);
        if (n) {
          if (st.follow.kind === "path") {
            const dist = Math.hypot(n.rx, n.ry);
            const aw = st.W - st.insets.l - st.insets.r;
            const ah = st.H - st.insets.t - st.insets.b;
            st.target.x = n.rx * 0.5;
            st.target.y = n.ry * 0.5;
            st.target.k = clamp(Math.min(aw, ah) / (dist + 340), 0.45, 1.3);
          } else {
            st.target.x = n.rx;
            st.target.y = n.ry;
            st.target.k = st.follow.k;
          }
        }
      }
      const ease = 1 - Math.exp(-dt * 4.2);
      const cam = st.cam;
      cam.x += (st.target.x - cam.x) * ease;
      cam.y += (st.target.y - cam.y) * ease;
      cam.k = Math.exp(Math.log(cam.k) + (Math.log(st.target.k) - Math.log(cam.k)) * ease);
      camera.x = cam.x;
      camera.y = cam.y;
      camera.k = cam.k;
      const ox = vc.x - cam.x * cam.k;
      const oy = vc.y - cam.y * cam.k;
      world.style.transform = `translate3d(${ox}px, ${oy}px, 0) scale(${cam.k})`;
      if (Math.abs(cam.k - st.lastK) > 0.003) {
        st.lastK = cam.k;
        world.style.setProperty("--ls", String(clamp(0.9 / cam.k, 1, 2)));
        const level = cam.k < 0.95 ? "far" : cam.k < 1.55 ? "mid" : "near";
        if (level !== st.zoomLevel) {
          st.zoomLevel = level;
          stage.dataset.zoom = level;
        }
        cameraApi.emitZoom(cam.k);
      }
      if (now > readyAt) {
        world.classList.add("is-ready");
        readyAt = Infinity;
      }

      /* DOM nodes */
      for (const [id, el] of nodeEls.current) {
        const n = st.nodes.get(id);
        if (n) el.style.transform = `translate3d(${n.rx.toFixed(2)}px, ${n.ry.toFixed(2)}px, 0)`;
      }

      /* core */
      const a = st.angles;
      a[0] += dt * (10 + e * 150 + f * 70);
      a[1] -= dt * (16 + e * 120 + f * 55);
      a[2] += dt * (6 + e * 95 + f * 40);
      a[3] += dt * (4 + e * 55 + f * 30);
      a[4] -= dt * (2 + e * 16 + f * 9);
      const core = coreRef.current;
      if (core) {
        core.style.setProperty("--e", e.toFixed(3));
        core.style.setProperty("--p", pulse.toFixed(3));
        core.style.setProperty("--f", f.toFixed(2));
        for (let i = 0; i < 5; i++) core.style.setProperty(`--a${i + 1}`, `${(a[i] % 360).toFixed(2)}deg`);
      }
      const statusEl = statusRef.current;
      if (statusEl) {
        const g = fx.stream ? GAME_BY_ID[fx.stream.path[1] as keyof typeof GAME_BY_ID] : undefined;
        const status =
          mode === "forging"
            ? `forging → ${g?.short ?? "branch"}`
            : mode === "thinking"
              ? "thinking…"
              : e > 0.06
                ? "listening…"
                : `online · ${st.modCount} mods`;
        if (statusEl.textContent !== status) statusEl.textContent = status;
      }

      /* effects bus */
      for (const ev of fx.drain()) {
        if (ev.type === "ripple") ripple(ev.big);
        else if (ev.type === "packets") {
          for (let i = 0; i < ev.count; i++)
            spawnPacket(ev.path, { rgb: ev.rgb ?? CORE_RGB, speed: ev.speed ?? 1, size: ev.size ?? 1.2, delay: i * (ev.gap ?? 0.16), trail: 0.3 });
        } else if (ev.type === "burst") burst(ev.id, ev.rgb ?? CORE_RGB);
        else if (ev.type === "flash") flash(ev.id);
      }

      /* spawn: forging beams */
      if (fx.stream) {
        st.streamTimer -= dt;
        if (st.streamTimer <= 0) {
          spawnPacket(fx.stream.path, { rgb: fx.stream.rgb, speed: 1.15, size: 1.6, trail: 0.38 });
          st.streamTimer = 0.15;
        }
      }
      /* spawn: ambient traffic */
      let ambient = 0;
      for (const p of st.packets) if (p.ambient) ambient++;
      if (ambient < 26 && Math.random() < dt * 5) {
        const path = [CORE_ID];
        let cur = CORE_ID;
        for (let d = 0; d < 3; d++) {
          const kids = st.children.get(cur);
          if (!kids?.length) break;
          cur = kids[Math.floor(Math.random() * kids.length)];
          path.push(cur);
        }
        const g = st.nodes.get(path[1]);
        spawnPacket(path, { ambient: true, rgb: g?.rgb ?? CORE_RGB, speed: 0.35 + Math.random() * 0.3, size: 0.75, trail: 0.16 });
      }
      /* spawn: motes drawn into the core while typing / thinking */
      st.moteAcc += dt * (e * 70 + (mode === "thinking" ? 26 : mode === "forging" ? 16 : 0));
      while (st.moteAcc >= 1) {
        st.moteAcc -= 1;
        st.motes.push({
          a: Math.random() * Math.PI * 2,
          r: 190 + Math.random() * 150,
          va: 0.9 + Math.random() * 0.8,
          vr: 70 + Math.random() * 90 + e * 120,
          life: 0,
          rgb: MOTE_COLORS[Math.floor(Math.random() * MOTE_COLORS.length)],
          size: 0.6 + Math.random() * 1.1,
        });
      }

      /* ───── canvas ───── */
      const k = cam.k;
      ctx.setTransform(1, 0, 0, 1, 0, 0);
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.setTransform(st.dpr * k, 0, 0, st.dpr * k, st.dpr * ox, st.dpr * oy);
      ctx.globalCompositeOperation = dark ? "lighter" : "source-over";
      ctx.lineCap = "round";
      const px = 1 / k;
      const col = (n: RNode) => (dark ? n.rgb : n.ink);
      const stateAlpha = (id: string) => {
        const s = st.states.get(id) ?? "on";
        return s === "on" ? 1 : s === "near" ? 0.45 : 0.07;
      };

      // Orbit guides
      ctx.globalAlpha = 1;
      ctx.setLineDash([2 * px, 9 * px]);
      ctx.lineDashOffset = -t * 6;
      for (const r of [TIER_RADIUS.game, TIER_RADIUS.category + 30]) {
        ctx.strokeStyle = dark ? `rgb(196 181 253 / ${0.07 + e * 0.06})` : `rgb(91 33 182 / 0.08)`;
        ctx.lineWidth = Math.max(0.6, 0.8 * px);
        ctx.beginPath();
        ctx.arc(0, 0, r, 0, Math.PI * 2);
        ctx.stroke();
      }
      ctx.setLineDash([]);

      // Spider-web threads between siblings, sagging toward the core
      const ring = (type: NodeType, maxGap: number, alpha: number) => {
        const list = [...st.nodes.values()].filter((n) => n.type === type).sort((p, q) => Math.atan2(p.ry, p.rx) - Math.atan2(q.ry, q.rx));
        if (list.length < 2) return;
        ctx.lineWidth = Math.max(0.5, 0.7 * px);
        for (let i = 0; i < list.length; i++) {
          const p = list[i];
          const q = list[(i + 1) % list.length];
          let gap = Math.atan2(q.ry, q.rx) - Math.atan2(p.ry, p.rx);
          if (gap < 0) gap += Math.PI * 2;
          if (gap > maxGap) continue;
          const sa = Math.min(stateAlpha(p.id), stateAlpha(q.id));
          ctx.strokeStyle = dark ? `rgb(196 181 253 / ${alpha * sa * (1 + e)})` : `rgb(91 33 182 / ${alpha * sa * 0.9})`;
          ctx.beginPath();
          ctx.moveTo(p.rx, p.ry);
          ctx.quadraticCurveTo((p.rx + q.rx) * 0.43, (p.ry + q.ry) * 0.43, q.rx, q.ry);
          ctx.stroke();
        }
      };
      ring("game", Math.PI, 0.16);
      ring("category", 0.9, 0.11);
      ring("mod", 0.35, 0.07);

      // Hovered ancestry
      const hoverSet = new Set<string>();
      if (st.hovered) {
        let cur: RNode | undefined = st.nodes.get(st.hovered);
        while (cur?.parent) {
          hoverSet.add(`${cur.parent}|${cur.id}`);
          cur = st.nodes.get(cur.parent);
        }
      }
      const streamSet = new Set<string>();
      if (fx.stream) for (let i = 0; i < fx.stream.path.length - 1; i++) streamSet.add(`${fx.stream.path[i]}|${fx.stream.path[i + 1]}`);

      // Branches
      for (const l of st.links) {
        const s = l.source as RNode;
        const en = l.target as RNode;
        const mx = (s.rx + en.rx) / 2;
        const my = (s.ry + en.ry) / 2;
        const dx = en.rx - s.rx;
        const dy = en.ry - s.ry;
        l.cx = mx - dy * l.curve;
        l.cy = my + dx * l.curve;

        const key = `${s.id}|${en.id}`;
        const sa = Math.min(stateAlpha(en.id), stateAlpha(s.id) === 0.07 ? 0.07 : 1);
        const streaming = streamSet.has(key);
        const hovered = hoverSet.has(key);
        const base = l.kind === "game" ? 1.7 : l.kind === "category" ? 1.15 : 0.75;
        let boost = 1;
        if (l.kind === "game") boost += e * 1.4 + pulse * 0.5;
        if (streaming) boost += 1.5 + pulse;
        if (hovered) boost += 0.9;

        const grad = ctx.createLinearGradient(s.rx, s.ry, en.rx, en.ry);
        grad.addColorStop(0, `rgb(${col(s)})`);
        grad.addColorStop(1, `rgb(${col(en)})`);
        ctx.strokeStyle = grad;
        ctx.beginPath();
        ctx.moveTo(s.rx, s.ry);
        ctx.quadraticCurveTo(l.cx, l.cy, en.rx, en.ry);

        // glow pass
        ctx.globalAlpha = clamp((dark ? 0.075 : 0.06) * sa * boost, 0, 0.5);
        ctx.lineWidth = base * (dark ? 6 : 4.5) * Math.min(boost, 2.4);
        ctx.stroke();
        // core pass
        ctx.globalAlpha = clamp((dark ? 0.5 : 0.55) * sa * boost, 0, 1);
        ctx.lineWidth = Math.max(base * (streaming ? 1.5 : 1), 0.7 * px);
        ctx.stroke();

        if (streaming) {
          ctx.globalAlpha = dark ? 0.9 : 0.75;
          ctx.strokeStyle = dark ? "rgb(255 255 255)" : `rgb(${col(en)})`;
          ctx.lineWidth = Math.max(0.9, 1.1 * px);
          ctx.setLineDash([5, 11]);
          ctx.lineDashOffset = -t * 90;
          ctx.stroke();
          ctx.setLineDash([]);
        }
      }
      ctx.globalAlpha = 1;

      // Packets & beams
      for (let i = st.packets.length - 1; i >= 0; i--) {
        const p = st.packets[i];
        if (p.delay > 0) {
          p.delay -= dt;
          continue;
        }
        const aN = st.nodes.get(p.path[p.seg]);
        const bN = st.nodes.get(p.path[p.seg + 1]);
        const link = aN && bN ? st.pairs.get(`${aN.id}|${bN.id}`) : undefined;
        if (!aN || !bN || !link) {
          st.packets.splice(i, 1);
          continue;
        }
        const forward = (link.source as RNode).id === aN.id;
        const len = Math.hypot(bN.rx - aN.rx, bN.ry - aN.ry) * 1.04 + 1;
        p.t += (dt * p.speed * 300) / len;
        if (p.t >= 1) {
          if (!p.ambient) {
            if (bN.id === CORE_ID) ripple();
            else flash(bN.id);
          }
          p.seg++;
          p.t = 0;
          if (p.seg >= p.path.length - 1) {
            const kids = st.children.get(bN.id);
            if (p.ambient && kids?.length && Math.random() < 0.5) p.path.push(kids[Math.floor(Math.random() * kids.length)]);
            else {
              st.packets.splice(i, 1);
              continue;
            }
          }
          continue;
        }
        const s = link.source as RNode;
        const en = link.target as RNode;
        const at = (tt: number) => bez(s, link, en, forward ? tt : 1 - tt);
        const sa = Math.min(stateAlpha(aN.id), stateAlpha(bN.id));
        const alpha = (p.ambient ? 0.55 : 1) * (p.ambient ? sa : Math.max(sa, 0.6));
        const c = dark ? p.rgb : inkOf(p.rgb);
        const head = at(p.t);
        // trail
        const steps = 7;
        let prev = head;
        for (let j = 1; j <= steps; j++) {
          const tt = p.t - (j / steps) * p.trail;
          if (tt < 0) break;
          const pt = at(tt);
          ctx.strokeStyle = `rgb(${c} / ${alpha * (1 - j / steps) * 0.8})`;
          ctx.lineWidth = p.size * 1.8 * (1 - j / (steps + 1));
          ctx.beginPath();
          ctx.moveTo(prev.x, prev.y);
          ctx.lineTo(pt.x, pt.y);
          ctx.stroke();
          prev = pt;
        }
        ctx.fillStyle = `rgb(${c} / ${alpha * 0.22})`;
        ctx.beginPath();
        ctx.arc(head.x, head.y, p.size * 4.5, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = dark ? `rgb(255 255 255 / ${alpha})` : `rgb(${c} / ${alpha})`;
        ctx.beginPath();
        ctx.arc(head.x, head.y, p.size * 1.3, 0, Math.PI * 2);
        ctx.fill();
      }

      // Motes spiralling into the core
      for (let i = st.motes.length - 1; i >= 0; i--) {
        const m = st.motes[i];
        const x0 = Math.cos(m.a) * m.r;
        const y0 = Math.sin(m.a) * m.r;
        m.r -= m.vr * dt;
        m.a += m.va * dt;
        m.life += dt;
        if (m.r < 64) {
          st.motes.splice(i, 1);
          continue;
        }
        const x1 = Math.cos(m.a) * m.r;
        const y1 = Math.sin(m.a) * m.r;
        const alpha = Math.min(1, m.life * 2.5) * Math.min(1, (m.r - 64) / 50) * (dark ? 0.9 : 0.6);
        const c = dark ? m.rgb : inkOf(m.rgb);
        ctx.strokeStyle = `rgb(${c} / ${alpha * 0.6})`;
        ctx.lineWidth = m.size;
        ctx.beginPath();
        ctx.moveTo(x0 - (x1 - x0) * 2, y0 - (y1 - y0) * 2);
        ctx.lineTo(x1, y1);
        ctx.stroke();
        ctx.fillStyle = `rgb(${c} / ${alpha})`;
        ctx.beginPath();
        ctx.arc(x1, y1, m.size, 0, Math.PI * 2);
        ctx.fill();
      }

      // Creation bursts
      for (let i = st.rings.length - 1; i >= 0; i--) {
        const r = st.rings[i];
        r.t += dt;
        const n = st.nodes.get(r.id);
        if (!n || r.t > 1.1) {
          st.rings.splice(i, 1);
          continue;
        }
        const q = r.t / 1.1;
        const ez = 1 - Math.pow(1 - q, 3);
        const c = dark ? r.rgb : inkOf(r.rgb);
        for (const [mult, w] of [
          [1, 2],
          [0.6, 1],
        ] as const) {
          ctx.strokeStyle = `rgb(${c} / ${(1 - q) * 0.9})`;
          ctx.lineWidth = w;
          ctx.beginPath();
          ctx.arc(n.rx, n.ry, 8 + ez * 110 * mult, 0, Math.PI * 2);
          ctx.stroke();
        }
      }
      const drag = Math.exp(-dt * 3.2);
      for (let i = st.sparks.length - 1; i >= 0; i--) {
        const s = st.sparks[i];
        s.x += s.vx * dt;
        s.y += s.vy * dt;
        s.vx *= drag;
        s.vy *= drag;
        s.life -= dt * 1.1;
        if (s.life <= 0) {
          st.sparks.splice(i, 1);
          continue;
        }
        const c = dark ? s.rgb : inkOf(s.rgb === "255 255 255" ? "167 139 250" : s.rgb);
        ctx.fillStyle = `rgb(${c} / ${s.life})`;
        ctx.beginPath();
        ctx.arc(s.x, s.y, 0.6 + s.life * 1.8, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.globalCompositeOperation = "source-over";
    };
    raf = requestAnimationFrame(loop);

    /* wheel zoom around the cursor */
    const onWheel = (ev: WheelEvent) => {
      ev.preventDefault();
      const k0 = st.cam.k;
      const k1 = clamp(k0 * Math.exp(-ev.deltaY * (ev.ctrlKey ? 0.012 : 0.0016)), 0.3, 3.2);
      const vc = viewCenter();
      const ox = vc.x - st.cam.x * k0;
      const oy = vc.y - st.cam.y * k0;
      const wx = (ev.clientX - ox) / k0;
      const wy = (ev.clientY - oy) / k0;
      st.cam.k = st.target.k = k1;
      st.cam.x = st.target.x = (vc.x - (ev.clientX - wx * k1)) / k1;
      st.cam.y = st.target.y = (vc.y - (ev.clientY - wy * k1)) / k1;
      st.follow = null;
    };
    stage.addEventListener("wheel", onWheel, { passive: false });

    return () => {
      cancelAnimationFrame(raf);
      ro.disconnect();
      stage.removeEventListener("wheel", onWheel);
      for (const id of st.flashTimers.values()) window.clearTimeout(id);
    };
  }, [fitK]);

  /* ───────────── Pointer: drag branches, pan space ───────────── */
  const toWorld = (clientX: number, clientY: number) => {
    const st = S.current;
    const vc = { x: st.insets.l + (st.W - st.insets.l - st.insets.r) / 2, y: st.insets.t + (st.H - st.insets.t - st.insets.b) / 2 };
    return { x: (clientX - vc.x) / st.cam.k + st.cam.x, y: (clientY - vc.y) / st.cam.k + st.cam.y };
  };

  const selectNode = useCallback(
    (id: string) => {
      const n = S.current.nodes.get(id);
      if (!n) return;
      if (n.type === "core") select({ level: "core" });
      else if (n.type === "game") select({ level: "game", gameId: n.gameId });
      else if (n.type === "category") select({ level: "category", gameId: n.gameId, category: n.category });
      else select({ level: "mod", gameId: n.gameId, category: n.category, modId: n.modId }, { openPanel: true });
    },
    [select],
  );

  const onNodeDown = useCallback((e: RPointerEvent, id: string) => {
    if (e.button !== 0) return;
    e.stopPropagation();
    const st = S.current;
    const n = st.nodes.get(id);
    if (!n) return;
    const w = toWorld(e.clientX, e.clientY);
    st.drag = { id, sx: e.clientX, sy: e.clientY, ox: (n.x ?? 0) - w.x, oy: (n.y ?? 0) - w.y, moved: false };
    stageRef.current?.setPointerCapture(e.pointerId);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const onStageDown = (e: RPointerEvent) => {
    if (e.button !== 0) return;
    const st = S.current;
    st.pan = { sx: e.clientX, sy: e.clientY, cx: st.cam.x, cy: st.cam.y, moved: false };
    stageRef.current?.setPointerCapture(e.pointerId);
  };

  const onStageMove = (e: RPointerEvent) => {
    const st = S.current;
    if (st.drag) {
      const d = st.drag;
      if (!d.moved && Math.hypot(e.clientX - d.sx, e.clientY - d.sy) > 4) {
        d.moved = true;
        nodeEls.current.get(d.id)?.classList.add("is-dragging");
        st.sim?.alphaTarget(0.28);
      }
      if (d.moved) {
        const n = st.nodes.get(d.id);
        const w = toWorld(e.clientX, e.clientY);
        if (n) {
          n.fx = w.x + d.ox;
          n.fy = w.y + d.oy;
        }
      }
      return;
    }
    if (st.pan) {
      const p = st.pan;
      const dx = e.clientX - p.sx;
      const dy = e.clientY - p.sy;
      if (!p.moved && Math.hypot(dx, dy) > 3) {
        p.moved = true;
        st.follow = null;
        stageRef.current?.classList.add("is-panning");
      }
      if (p.moved) {
        st.cam.x = st.target.x = p.cx - dx / st.cam.k;
        st.cam.y = st.target.y = p.cy - dy / st.cam.k;
      }
    }
  };

  const onStageUp = (e: RPointerEvent) => {
    const st = S.current;
    stageRef.current?.releasePointerCapture?.(e.pointerId);
    if (st.drag) {
      const d = st.drag;
      const n = st.nodes.get(d.id);
      if (d.moved) {
        if (n) {
          n.fx = null;
          n.fy = null;
        }
        st.sim?.alphaTarget(0);
        nodeEls.current.get(d.id)?.classList.remove("is-dragging");
      } else {
        selectNode(d.id);
      }
      st.drag = null;
    }
    if (st.pan) {
      st.pan = null;
      stageRef.current?.classList.remove("is-panning");
    }
  };

  const setRef = useCallback((id: string, el: HTMLDivElement | null) => {
    if (el) nodeEls.current.set(id, el);
    else nodeEls.current.delete(id);
  }, []);

  const onHover = useCallback((id: string | null) => {
    S.current.hovered = id;
  }, []);

  const selectedId = selectedNodeId(selection);

  return (
    <div
      ref={stageRef}
      className="stage"
      data-zoom="far"
      onPointerDown={onStageDown}
      onPointerMove={onStageMove}
      onPointerUp={onStageUp}
      onPointerCancel={onStageUp}
    >
      <canvas ref={canvasRef} />
      <div ref={worldRef} className="world">
        <CyrusCore coreRef={coreRef} rippleRef={rippleRef} statusRef={statusRef} onActivate={() => select({ level: "core" })} />
        {graph.nodes
          .filter((n) => n.type !== "core")
          .map((n) => (
            <NodeView
              key={n.id}
              n={n}
              state={nodeStates.get(n.id) ?? "on"}
              showLabel={labels.has(n.id)}
              selected={selectedId === n.id}
              forging={forgingId === n.id}
              isNew={!initialIds.current!.has(n.id)}
              setRef={setRef}
              onDown={onNodeDown}
              onHover={onHover}
              onKeySelect={selectNode}
            />
          ))}
      </div>
    </div>
  );
}

const NodeView = memo(function NodeView({
  n,
  state,
  showLabel,
  selected,
  forging,
  isNew,
  setRef,
  onDown,
  onHover,
  onKeySelect,
}: {
  n: GNode;
  state: NodeState;
  showLabel: boolean;
  selected: boolean;
  forging: boolean;
  isNew: boolean;
  setRef: (id: string, el: HTMLDivElement | null) => void;
  onDown: (e: RPointerEvent, id: string) => void;
  onHover: (id: string | null) => void;
  onKeySelect: (id: string) => void;
}) {
  const kind = n.type === "category" ? "cat" : n.type;
  const cls = ["node", "tint", `n-${kind}`, selected && "is-selected", forging && "is-forging", isNew && "is-new"].filter(Boolean).join(" ");
  return (
    <div
      ref={(el) => setRef(n.id, el)}
      className={cls}
      data-state={state}
      data-label={showLabel ? "show" : undefined}
      style={{ ["--c" as string]: n.rgb }}
    >
      <div className="n-aura" />
      {n.type === "game" && (
        <>
          <div className="n-orbit" />
          <div className="n-ring" />
        </>
      )}
      <button
        type="button"
        className="n-orb"
        aria-label={`${n.type === "mod" ? "Mod" : n.type === "category" ? "Category" : "Game"}: ${n.label}`}
        onPointerDown={(e) => onDown(e, n.id)}
        onPointerEnter={() => onHover(n.id)}
        onPointerLeave={() => onHover(null)}
        onClick={(e) => {
          // Mouse clicks are resolved on pointer-up (so drags don't select); this handles keyboard activation.
          if (e.detail === 0) onKeySelect(n.id);
        }}
      >
        {n.type === "game" && n.gameId && <GameEmblem emblem={GAME_BY_ID[n.gameId].emblem} />}
        {n.type === "category" && n.category && <CategoryIcon k={n.category} />}
      </button>
      <div className="n-label">
        <span className="n-title">{n.label}</span>
        {n.sub && n.type !== "mod" && <span className="n-sub">{n.sub}</span>}
      </div>
    </div>
  );
});

