"use client";

import { useEffect, useRef, useState } from "react";
import { MicIcon } from "@/components/icons/ui";
import { fx } from "@/lib/fx";
import { useStore } from "@/lib/store";

/* Minimal typings for the Web Speech API (not in lib.dom for all TS versions). */
interface SpeechResult {
  isFinal: boolean;
  0: { transcript: string };
}
interface SpeechEvent {
  resultIndex: number;
  results: ArrayLike<SpeechResult>;
}
interface Recognition {
  continuous: boolean;
  interimResults: boolean;
  lang: string;
  start(): void;
  stop(): void;
  onresult: ((e: SpeechEvent) => void) | null;
  onend: (() => void) | null;
  onerror: ((e: { error: string }) => void) | null;
}
type RecognitionCtor = new () => Recognition;

export function VoiceButton({ onTranscript, onStart, disabled }: { onTranscript: (text: string) => void; onStart: () => void; disabled?: boolean }) {
  const [listening, setListening] = useState(false);
  const recRef = useRef<Recognition | null>(null);
  const toast = useStore((s) => s.toast);

  // Keep the core "listening" while the mic is open.
  useEffect(() => {
    if (!listening) return;
    const id = window.setInterval(() => fx.keystroke(0.35), 220);
    return () => window.clearInterval(id);
  }, [listening]);

  useEffect(() => () => recRef.current?.stop(), []);

  const toggle = () => {
    if (listening) {
      recRef.current?.stop();
      return;
    }
    const w = window as unknown as { SpeechRecognition?: RecognitionCtor; webkitSpeechRecognition?: RecognitionCtor };
    const Ctor = w.SpeechRecognition ?? w.webkitSpeechRecognition;
    if (!Ctor) {
      toast({ tone: "info", title: "Voice input unavailable", body: "This browser doesn't support speech recognition. Try Chrome or Edge." });
      return;
    }
    const rec = new Ctor();
    rec.continuous = true;
    rec.interimResults = true;
    rec.lang = navigator.language || "en-US";
    let finalText = "";
    rec.onresult = (e) => {
      let interim = "";
      for (let i = e.resultIndex; i < e.results.length; i++) {
        const r = e.results[i];
        if (r.isFinal) finalText += r[0].transcript;
        else interim += r[0].transcript;
      }
      onTranscript((finalText + interim).trim());
      fx.keystroke(1.2);
    };
    rec.onend = () => setListening(false);
    rec.onerror = (e) => {
      setListening(false);
      if (e.error === "not-allowed" || e.error === "service-not-allowed") {
        toast({ tone: "error", title: "Microphone blocked", body: "Allow microphone access to dictate prompts." });
      }
    };
    recRef.current = rec;
    onStart();
    try {
      rec.start();
      setListening(true);
      fx.ripple(true);
    } catch {
      setListening(false);
    }
  };

  return (
    <div className="flex items-center gap-2">
      {listening && (
        <span className="animate-pop hidden items-center gap-1.5 rounded-full bg-rose-500/10 px-2.5 py-1 text-[11px] font-medium text-rose-400 sm:inline-flex light:text-rose-600">
