"use client";

import { CategoryIcon } from "@/components/icons/CategoryIcons";
import { CATEGORY_BY_KEY, GAME_BY_ID, STARTER_IDEAS } from "@/lib/data";

export type StarterIdea = (typeof STARTER_IDEAS)[number];

export function StarterIdeas({ onPick }: { onPick: (idea: StarterIdea) => void }) {
  return (
    <div className="mt-3 flex flex-wrap items-center justify-center gap-2">
      <span className="hidden text-[10px] font-semibold uppercase tracking-[0.2em] text-faint md:inline">Try</span>
      {STARTER_IDEAS.map((idea, i) => {
        const cat = CATEGORY_BY_KEY[idea.category];
        const game = GAME_BY_ID[idea.gameId];
        return (
          <button
            key={idea.label}
            type="button"
            onClick={() => onPick(idea)}
            title={idea.prompt}
            className="tint glass-soft group animate-rise flex items-center gap-2 rounded-full py-1.5 pl-1.5 pr-3 text-[12px] text-ink-2 transition hover:-translate-y-0.5 hover:border-line-2 hover:text-ink"
            style={{ ["--c" as string]: cat.rgb, animationDelay: `${0.25 + i * 0.06}s` }}
          >
            <span
              className="grid h-6 w-6 place-items-center rounded-full text-[13px] transition group-hover:scale-110"
              style={{ color: "var(--cc)", background: `rgb(${cat.rgb} / 0.14)`, boxShadow: `inset 0 0 0 1px rgb(${cat.rgb} / 0.3)` }}
            >
              <CategoryIcon k={idea.category} />
            </span>
            <span className="whitespace-nowrap">{idea.label}</span>
            <span className="hidden whitespace-nowrap text-[10.5px] text-faint lg:inline">· {game.short}</span>
          </button>
        );
      })}
    </div>
  );
}

