      style={{ background: `rgb(${LANG_RGB[language]})`, boxShadow: `0 0 6px rgb(${LANG_RGB[language]} / 0.6)` }}
    />
  );
}

export function FileTabs({
  files,
  active,
  writing,
  onPick,
}: {
  files: ModFile[];
  active?: string;
  writing?: string;
  onPick: (path: string) => void;
}) {
  const ref = useRef<HTMLDivElement>(null);
  useEffect(() => {
    ref.current?.querySelector<HTMLElement>("[data-active='true']")?.scrollIntoView({ block: "nearest", inline: "nearest", behavior: "smooth" });
  }, [active]);
  return (
    <div ref={ref} className="flex gap-1 overflow-x-auto border-b border-line px-3 pt-2" style={{ scrollbarWidth: "none" }}>
      {files.map((f) => {
        const name = f.path.split("/").pop();
        const on = f.path === active;
        return (
          <button
            key={f.path}
            type="button"
            data-active={on}
            onClick={() => onPick(f.path)}
            title={f.path}
            className={`relative flex shrink-0 items-center gap-2 rounded-t-lg px-3 py-2 font-mono text-[11.5px] transition ${
              on ? "bg-[rgb(var(--glow)/0.1)] text-ink" : "text-muted hover:bg-[rgb(var(--glow)/0.05)] hover:text-ink-2"
            }`}
          >
            <FileDot language={f.language} />
            {name}
            {f.path === writing && <span className="h-1.5 w-1.5 animate-pulse rounded-full bg-cyan shadow-[0_0_8px_var(--cyan)]" />}
            {on && <span className="absolute inset-x-2 -bottom-px h-[2px] rounded-full bg-gradient-to-r from-accent to-cyan" />}
          </button>
        );
      })}
    </div>
  );
}

export function CodeView({ file, writing }: { file: ModFile; writing: boolean }) {
  const scroller = useRef<HTMLDivElement>(null);
  const stick = useRef(true);
  const [copied, setCopied] = useState(false);
  const lines = useMemo(() => highlight(file.content, file.language), [file.content, file.language]);

  // Follow the write head unless the reader has scrolled away.
  useEffect(() => {
    const el = scroller.current;
    if (el && writing && stick.current) el.scrollTop = el.scrollHeight;
  }, [file.content, writing]);

  useEffect(() => {
    stick.current = true;
    if (scroller.current && !writing) scroller.current.scrollTop = 0;
  }, [file.path, writing]);

  const copy = async () => {
    try {
      await navigator.clipboard.writeText(file.content);
      setCopied(true);
      window.setTimeout(() => setCopied(false), 1400);
    } catch {
      /* clipboard blocked */
    }
  };

  const bytes = new Blob([file.content]).size;

  return (
    <div className="flex min-h-0 flex-1 flex-col">
      <div className="flex items-center gap-2 px-4 py-2 text-[11px] text-muted">
        <span className="truncate font-mono">{file.path}</span>
        <span
          className="shrink-0 rounded-md px-1.5 py-0.5 font-medium"
          style={{ color: `rgb(${LANG_RGB[file.language]})`, background: `rgb(${LANG_RGB[file.language]} / 0.12)` }}
        >
          {LANG_LABEL[file.language]}
        </span>
        <span className="ml-auto shrink-0 tabular-nums">
          {lines.length} lines · {formatBytes(bytes)}
        </span>
        <button type="button" onClick={copy} className="btn-ghost h-7 shrink-0 px-2 text-[11px]" aria-label="Copy file">
          {copied ? <CheckIcon className="text-emerald-400" /> : <CopyIcon />}
          {copied ? "Copied" : "Copy"}
        </button>
      </div>
      <div
        ref={scroller}
        onScroll={(e) => {
          const el = e.currentTarget;
          stick.current = el.scrollHeight - el.scrollTop - el.clientHeight < 40;
        }}
        className="code mx-3 mb-3 min-h-0 flex-1 overflow-auto rounded-xl border border-line py-3"
        style={{ background: "var(--code-bg)" }}
      >
        {lines.map((toks, i) => {
          const isLast = i === lines.length - 1;
          return (
            <div key={i} className={`flex min-w-max pr-4 ${writing ? "line-new" : ""} ${writing && isLast ? "write-head" : ""}`}>
              <span className="ln sticky left-0 w-11 shrink-0 bg-inherit pr-4 text-right tabular-nums">{i + 1}</span>
              <span className="whitespace-pre">
                {toks.map((t, j) =>
                  t.c ? (
                    <span key={j} className={`tok-${t.c}`}>
                      {t.v}
                    </span>
                  ) : (
                    t.v
                  ),
                )}
                {writing && isLast && <span className="caret" />}
              </span>
            </div>
          );
        })}
      </div>
    </div>
  );
}

