"use client";

import { ModelGlyph } from "@/components/icons/ModelGlyphs";
import { BoltIcon, CodeIcon, RestoreIcon } from "@/components/icons/ui";
import { MODEL_BY_ID } from "@/lib/data";
import { timeAgo } from "@/lib/hooks";
import type { Job } from "@/lib/store";
import type { ModVersion } from "@/lib/types";

export function VersionsTab({
  versions,
  activeId,
  job,
  rgb,
  onRestore,
  onView,
}: {
  versions: ModVersion[];
  activeId?: string;
  job: Job | null;
  rgb: string;
  onRestore: (id: string) => void;
  onView: (id: string) => void;
}) {
  const list = [...versions].reverse();
  const latestId = versions[versions.length - 1]?.id;

  return (
    <div className="min-h-0 flex-1 overflow-y-auto px-4 py-4">
      <ol className="relative">
        <span
          className="absolute bottom-3 left-[13px] top-3 w-px"
          style={{ background: `linear-gradient(180deg, rgb(${rgb} / 0.7), rgb(var(--glow) / 0.15))` }}
        />
        {job && (
