"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import { BrainIcon, EditIcon } from "@/components/icons/ui";
import { CATEGORY_BY_KEY, GAME_BY_ID } from "@/lib/data";
import { buildModNotes } from "@/lib/engine";
import { useStore } from "@/lib/store";
import type { Mod, ModVersion } from "@/lib/types";
import { Markdown } from "./Markdown";

export function NotesTab({ mod, version }: { mod: Mod; version?: ModVersion }) {
  const stored = useStore((s) => s.notes[mod.id] ?? "");
  const aiNotes = useStore((s) => s.aiNotes[mod.id]);
  const setNote = useStore((s) => s.setNote);
  const [draft, setDraft] = useState(stored);
  const [saved, setSaved] = useState<"idle" | "saving" | "saved">("idle");
  const timer = useRef(0);

  useEffect(() => {
    setDraft(useStore.getState().notes[mod.id] ?? "");
  }, [mod.id]);

  const cyrusNotes = useMemo(() => {
    if (aiNotes) return aiNotes;
    return buildModNotes({
      game: GAME_BY_ID[mod.gameId],
      category: CATEGORY_BY_KEY[mod.category],
      modName: mod.name,
      prompt: `${mod.name}: ${mod.summary}`,
      model: version?.model ?? "katara",
      version: Number(version?.label.slice(1) ?? 1),
    });
  }, [aiNotes, mod, version]);

  const onChange = (v: string) => {
    setDraft(v);
    setSaved("saving");
    window.clearTimeout(timer.current);
    timer.current = window.setTimeout(() => {
      setNote(mod.id, v);
      setSaved("saved");
    }, 450);
  };

  return (
    <div className="min-h-0 flex-1 space-y-4 overflow-y-auto px-4 py-4">
      <section className="rounded-xl border border-line bg-[rgb(var(--glow)/0.04)]">
        <header className="flex items-center gap-2 border-b border-line px-4 py-2.5">
          <EditIcon className="text-accent" />
          <h3 className="font-display text-[13px] font-semibold text-ink">Your notes</h3>
          <span className="ml-auto text-[10.5px] text-faint">
            {saved === "saving" ? "Saving…" : saved === "saved" ? "Saved locally" : `${draft.length} chars`}
          </span>
        </header>
        <textarea
          value={draft}
          onChange={(e) => onChange(e.target.value)}
          placeholder="Ideas, balance tweaks, bugs to fix in the next version…"
          className="block min-h-[120px] w-full resize-y bg-transparent px-4 py-3 text-[13px] leading-relaxed text-ink outline-none placeholder:text-faint"
        />
      </section>

      <section className="rounded-xl border border-line">
        <header className="flex items-center gap-2 border-b border-line px-4 py-2.5">
          <BrainIcon className="text-cyan" />
          <h3 className="font-display text-[13px] font-semibold text-ink">Cyrus notes</h3>
          <span className="ml-auto text-[10.5px] text-faint">{version ? `for ${version.label}` : "draft"}</span>
        </header>
        <div className="px-4 py-3">
          <Markdown source={cyrusNotes} />
        </div>
      </section>
    </div>
  );
}

