"use client";

import { CategoryIcon } from "@/components/icons/CategoryIcons";
import { GameEmblem } from "@/components/icons/GameEmblems";
import { ArrowRightIcon, PlusIcon } from "@/components/icons/ui";
import { CATEGORY_BY_KEY, GAMES, GAME_BY_ID } from "@/lib/data";
import { useAllMods, useStore } from "@/lib/store";
import type { Mod, Selection } from "@/lib/types";

function ModCard({ mod, i }: { mod: Mod; i: number }) {
  const select = useStore((s) => s.select);
  const cat = CATEGORY_BY_KEY[mod.category];
  return (
    <button
      type="button"
      onClick={() => select({ level: "mod", gameId: mod.gameId, category: mod.category, modId: mod.id }, { openPanel: true })}
      className="tint animate-rise group flex w-full items-start gap-3 rounded-xl border border-line p-3 text-left transition hover:-translate-y-0.5 hover:border-line-2 hover:bg-[rgb(var(--glow)/0.06)]"
      style={{ ["--c" as string]: cat.rgb, animationDelay: `${i * 0.04}s` }}
    >
      <span
        className="mt-0.5 h-2.5 w-2.5 shrink-0 rounded-full"
        style={{ background: `rgb(${cat.rgb})`, boxShadow: `0 0 10px rgb(${cat.rgb} / 0.8)` }}
      />
