  const tab = useStore((s) => s.panelTab);
  const setTab = useStore((s) => s.setPanelTab);
  const activeFile = useStore((s) => s.activeFile);
  const setActiveFile = useStore((s) => s.setActiveFile);
  const restoreVersion = useStore((s) => s.restoreVersion);
  const select = useStore((s) => s.select);
  const [viewing, setViewing] = useState<string | null>(null);

  useEffect(() => setViewing(null), [modId]);

  const streaming = isJobLive(job) && job!.modId === modId;
  const viewed = viewing ? versions.find((v) => v.id === viewing) : undefined;
  const shown = viewed ?? active;
  const files = streaming ? job!.files : (shown?.files ?? []);
  const writingPath = streaming ? job!.activeFile : undefined;
  const current = files.find((f) => f.path === activeFile) ?? files.find((f) => f.path === writingPath) ?? files[0];

  if (!mod) {
    return (
      <PanelShell>
        <div className="grid flex-1 place-items-center p-8 text-[13px] text-muted">
          This mod is no longer in the network.
          <button type="button" onClick={onClose} className="btn-ghost mt-3 px-3 py-1.5">
            Close
          </button>
        </div>
      </PanelShell>
    );
  }

  const game = GAME_BY_ID[mod.gameId];
  const cat = CATEGORY_BY_KEY[mod.category];

  const download = () => {
    if (!files.length) return;
    downloadBlob(zipFiles(files), `${slugify(mod.name)}-${shown?.label ?? "draft"}.zip`);
  };

  const counts: Partial<Record<PanelTab, number>> = { files: files.length, versions: versions.length };

  return (
    <PanelShell>
      <header className="tint hairline-top px-5 pt-5" style={{ ["--c" as string]: cat.rgb }}>
        <div className="flex items-start gap-3">
          <span
            className="mt-0.5 grid h-11 w-11 shrink-0 rotate-45 place-items-center rounded-[13px] text-[21px]"
            style={{ color: "var(--cc)", background: `rgb(${cat.rgb} / 0.14)`, boxShadow: `inset 0 0 0 1px rgb(${cat.rgb} / 0.45), 0 0 24px rgb(${cat.rgb} / 0.35)` }}
          >
            <CategoryIcon k={cat.key} className="-rotate-45" />
          </span>
          <div className="min-w-0 flex-1">
            <nav className="flex items-center gap-1 text-[11px] text-muted">
              <button type="button" className="hover:text-ink" onClick={() => select({ level: "game", gameId: game.id })}>
                {game.name}
              </button>
              <span className="text-faint">›</span>
              <button type="button" className="hover:text-ink" onClick={() => select({ level: "category", gameId: game.id, category: cat.key })}>
                {cat.label}
              </button>
            </nav>
            <h2 className="truncate font-display text-[19px] font-semibold leading-tight text-ink">{mod.name}</h2>
            <p className="mt-0.5 line-clamp-1 text-[12px] text-ink-2">{mod.summary}</p>
          </div>
          <div className="flex shrink-0 items-center gap-1">
            {streaming ? (
              <span className="flex items-center gap-1.5 rounded-full bg-cyan/10 px-2.5 py-1 text-[11px] font-medium text-cyan">
                <span className="h-1.5 w-1.5 animate-pulse rounded-full bg-cyan" />
                Forging v{job!.version}
              </span>
            ) : (
              shown && (
                <span className="rounded-full px-2.5 py-1 text-[11px] font-semibold" style={{ color: "var(--cc-ink)", background: `rgb(${cat.rgb} / 0.13)` }}>
                  {shown.label}
                </span>
              )
            )}
            <button type="button" onClick={download} disabled={streaming || !files.length} className="btn-ghost h-9 w-9 text-muted disabled:opacity-40" aria-label="Download zip" title="Download .zip">
              <DownloadIcon />
            </button>
            <button type="button" onClick={onClose} className="btn-ghost h-9 w-9 text-muted" aria-label="Close panel">
              <CloseIcon />
            </button>
          </div>
        </div>

        <div role="tablist" className="mt-4 flex gap-1">
          {TABS.map((t) => {
            const on = t.id === tab;
            return (
              <button
                key={t.id}
                role="tab"
                aria-selected={on}
                type="button"
                onClick={() => setTab(t.id)}
                className={`relative flex items-center gap-1.5 rounded-t-lg px-3 pb-2.5 pt-1.5 text-[12.5px] font-medium transition ${on ? "text-ink" : "text-muted hover:text-ink-2"}`}
              >
                <span className={on ? "text-accent" : ""}>{t.icon}</span>
                {t.label}
                {counts[t.id] !== undefined && (
                  <span className="rounded-md bg-[rgb(var(--glow)/0.1)] px-1.5 text-[10px] tabular-nums text-muted">{counts[t.id]}</span>
                )}
                {on && <span className="absolute inset-x-2 bottom-0 h-[2px] rounded-full bg-gradient-to-r from-accent via-pink to-cyan shadow-[0_0_10px_var(--accent)]" />}
              </button>
            );
          })}
        </div>
      </header>
      <div className="h-px bg-line" />

      {viewed && !streaming && (
        <div className="flex items-center gap-2 border-b border-line bg-[rgb(var(--glow)/0.06)] px-4 py-2 text-[12px] text-ink-2">
          <HistoryIcon className="text-accent" /> Viewing {viewed.label} (read-only)
          <button type="button" onClick={() => restoreVersion(mod.id, viewed.id)} className="ml-auto font-medium text-accent-ink hover:underline">
            Restore
          </button>
          <button type="button" onClick={() => setViewing(null)} className="font-medium text-muted hover:text-ink">
            Back to current
          </button>
        </div>
      )}

      {tab === "code" &&
        (current ? (
          <>
            <FileTabs files={files} active={current.path} writing={writingPath} onPick={setActiveFile} />
            <CodeView file={current} writing={streaming && current.path === writingPath} />
          </>
        ) : (
          <div className="grid flex-1 place-items-center p-8 text-center text-[13px] text-muted">
            {streaming ? <span className="shimmer-text">Cyrus is planning the files…</span> : "No code yet."}
          </div>
        ))}
      {tab === "files" && (
        <FilesTab
          files={files}
          active={current?.path}
          writing={writingPath}
          onOpen={(p) => {
            setActiveFile(p);
            setTab("code");
          }}
          onDownload={download}
        />
      )}
      {tab === "versions" && (
        <VersionsTab
          versions={versions}
          activeId={active?.id}
          job={streaming ? job : null}
          rgb={cat.rgb}
          onRestore={(id) => {
            restoreVersion(mod.id, id);
            setViewing(null);
          }}
          onView={(id) => {
            setViewing(id === active?.id ? null : id);
            setTab("code");
          }}
        />
      )}
      {tab === "notes" && <NotesTab mod={mod} version={shown} />}
    </PanelShell>
  );
}

