"use client";

import { Fragment } from "react";
import { CategoryIcon } from "@/components/icons/CategoryIcons";
import { GameEmblem } from "@/components/icons/GameEmblems";
import { BoltIcon, ChevronRightIcon, MoonIcon, PanelRightIcon, SearchIcon, SunIcon } from "@/components/icons/ui";
import { CATEGORY_BY_KEY, GAME_BY_ID } from "@/lib/data";
import { useMod, useStore } from "@/lib/store";

export function CyrusMark({ size = 30 }: { size?: number }) {
  return (
    <svg width={size} height={size} viewBox="0 0 32 32" aria-hidden>
      <defs>
        <radialGradient id="cm-orb" cx="40%" cy="35%" r="65%">
          <stop offset="0%" stopColor="#ffffff" />
          <stop offset="35%" stopColor="#c4b5fd" />
          <stop offset="75%" stopColor="#7c3aed" />
          <stop offset="100%" stopColor="#312e81" />
        </radialGradient>
        <linearGradient id="cm-ring" x1="0" x2="1">
          <stop offset="0%" stopColor="#67e8f9" />
          <stop offset="100%" stopColor="#f0abfc" />
        </linearGradient>
      </defs>
      <ellipse cx="16" cy="16" rx="14.5" ry="5.2" transform="rotate(-24 16 16)" fill="none" stroke="url(#cm-ring)" strokeWidth="1.3" strokeOpacity="0.55" />
      <circle cx="16" cy="16" r="7.2" fill="url(#cm-orb)" />
      <path d="M3.3 21.6 A14.5 5.2 -24 0 0 28.7 10.4" transform="" fill="none" stroke="url(#cm-ring)" strokeWidth="1.5" strokeLinecap="round" />
      <circle cx="27.2" cy="11.6" r="1.4" fill="#fff" />
    </svg>
  );
}

function Crumb({ onClick, active, children, rgb }: { onClick: () => void; active: boolean; children: React.ReactNode; rgb?: string }) {
  return (
    <button
      type="button"
      onClick={onClick}
      className={`tint flex min-w-0 items-center gap-1.5 rounded-lg px-2 py-1 text-[12.5px] transition ${
        active ? "bg-[rgb(var(--glow)/0.12)] font-medium text-ink" : "text-muted hover:bg-[rgb(var(--glow)/0.07)] hover:text-ink"
      }`}
      style={rgb ? { ["--c" as string]: rgb } : undefined}
    >
      {children}
    </button>
  );
}

export function TopBar() {
  const selection = useStore((s) => s.selection);
  const select = useStore((s) => s.select);
  const credits = useStore((s) => s.credits);
  const theme = useStore((s) => s.theme);
  const toggleTheme = useStore((s) => s.toggleTheme);
  const setPaletteOpen = useStore((s) => s.setPaletteOpen);
  const panelOpen = useStore((s) => s.panelOpen);
  const setPanelOpen = useStore((s) => s.setPanelOpen);
  const mod = useMod(selection.modId);
  const game = selection.gameId ? GAME_BY_ID[selection.gameId] : undefined;
  const cat = selection.category ? CATEGORY_BY_KEY[selection.category] : undefined;

  const crumbs = [
    <Crumb key="core" active={selection.level === "core"} onClick={() => select({ level: "core" })}>
      <span className="h-2.5 w-2.5 rounded-full bg-gradient-to-br from-white via-accent to-cyan shadow-[0_0_8px_var(--accent)]" />
      <span className="hidden sm:inline">Core</span>
    </Crumb>,
  ];
  if (game)
    crumbs.push(
      <Crumb key="g" rgb={game.rgb} active={selection.level === "game"} onClick={() => select({ level: "game", gameId: game.id })}>
        <span className="text-[14px]" style={{ color: "var(--cc)" }}>
          <GameEmblem emblem={game.emblem} />
        </span>
        <span className="truncate">{game.short}</span>
      </Crumb>,
    );
  if (game && cat)
    crumbs.push(
      <Crumb key="c" rgb={cat.rgb} active={selection.level === "category"} onClick={() => select({ level: "category", gameId: game.id, category: cat.key })}>
        <span className="text-[14px]" style={{ color: "var(--cc)" }}>
          <CategoryIcon k={cat.key} />
        </span>
        <span className="truncate">{cat.label}</span>
      </Crumb>,
    );
  if (mod && cat)
    crumbs.push(
      <Crumb key="m" rgb={cat.rgb} active onClick={() => select({ level: "mod", gameId: mod.gameId, category: mod.category, modId: mod.id }, { openPanel: true })}>
        <span className="h-2 w-2 rounded-full" style={{ background: `rgb(${cat.rgb})`, boxShadow: `0 0 8px rgb(${cat.rgb})` }} />
        <span className="max-w-[180px] truncate">{mod.name}</span>
      </Crumb>,
    );

  return (
    <header className="pointer-events-none fixed inset-x-0 top-0 z-40 flex h-16 items-center gap-3 px-3 md:px-5">
      <button type="button" onClick={() => select({ level: "core" })} className="pointer-events-auto flex shrink-0 items-center gap-2.5" aria-label="Cyrus home">
        <CyrusMark />
        <span className="hidden flex-col leading-none sm:flex">
          <span className="font-display text-[19px] font-bold tracking-tight text-ink text-glow">Cyrus</span>
          <span className="mt-0.5 text-[8.5px] font-semibold uppercase tracking-[0.32em] text-muted">Mod Forge</span>
        </span>
      </button>

      <nav aria-label="Location" className="glass-soft pointer-events-auto ml-1 flex min-w-0 items-center gap-0.5 rounded-xl p-1 md:ml-4">
        {crumbs.map((c, i) => (
          <Fragment key={i}>
            {i > 0 && <ChevronRightIcon className="shrink-0 text-[11px] text-faint" />}
            {c}
          </Fragment>
        ))}
      </nav>

      <div className="pointer-events-auto ml-auto flex shrink-0 items-center gap-1.5">
        <button
          type="button"
          onClick={() => setPaletteOpen(true)}
          className="glass-soft hidden h-9 items-center gap-2 rounded-xl px-3 text-[12.5px] text-muted transition hover:text-ink md:flex"
        >
          <SearchIcon />
          Jump to…
          <span className="kbd ml-3">Ctrl K</span>
        </button>
        <button type="button" onClick={() => setPaletteOpen(true)} className="glass-soft grid h-9 w-9 place-items-center rounded-xl text-ink-2 md:hidden" aria-label="Search">
          <SearchIcon />
        </button>
        <div className="glass-soft flex h-9 items-center gap-1.5 rounded-xl px-3 text-[12.5px] font-semibold tabular-nums text-ink" title="Forge credits">
          <BoltIcon className="text-amber-400 drop-shadow-[0_0_6px_rgb(251_191_36/0.7)] light:text-amber-500" />
          {credits}
        </div>
        <button
          type="button"
          onClick={toggleTheme}
          className="glass-soft group relative grid h-9 w-9 place-items-center overflow-hidden rounded-xl text-[16px] text-ink-2 transition hover:text-ink"
          aria-label={`Switch to ${theme === "dark" ? "light" : "dark"} mode`}
          title={`Switch to ${theme === "dark" ? "light" : "dark"} mode`}
        >
          <span className={`absolute transition duration-500 ${theme === "dark" ? "rotate-0 opacity-100" : "-rotate-90 scale-50 opacity-0"}`}>
            <MoonIcon />
          </span>
          <span className={`absolute transition duration-500 ${theme === "light" ? "rotate-0 opacity-100" : "rotate-90 scale-50 opacity-0"}`}>
            <SunIcon />
          </span>
        </button>
        <button
          type="button"
          onClick={() => setPanelOpen(!panelOpen)}
          className={`glass-soft grid h-9 w-9 place-items-center rounded-xl text-[16px] transition ${panelOpen ? "text-accent" : "text-ink-2 hover:text-ink"}`}
          aria-label="Toggle preview panel"
          aria-pressed={panelOpen}
        >
          <PanelRightIcon />
        </button>
      </div>
    </header>
  );
}

