        {crumbs.map((c, i) => (
          <Fragment key={i}>
            {i > 0 && <ChevronRightIcon className="shrink-0 text-[11px] text-faint" />}
            {c}
          </Fragment>
        ))}
      </nav>

      <div className="pointer-events-auto ml-auto flex shrink-0 items-center gap-1.5">
        <button
          type="button"
          onClick={() => setPaletteOpen(true)}
          className="glass-soft hidden h-9 items-center gap-2 rounded-xl px-3 text-[12.5px] text-muted transition hover:text-ink md:flex"
        >
          <SearchIcon />
          Jump to…
          <span className="kbd ml-3">Ctrl K</span>
        </button>
        <button type="button" onClick={() => setPaletteOpen(true)} className="glass-soft grid h-9 w-9 place-items-center rounded-xl text-ink-2 md:hidden" aria-label="Search">
          <SearchIcon />
        </button>
        <div className="glass-soft flex h-9 items-center gap-1.5 rounded-xl px-3 text-[12.5px] font-semibold tabular-nums text-ink" title="Forge credits">
          <BoltIcon className="text-amber-400 drop-shadow-[0_0_6px_rgb(251_191_36/0.7)] light:text-amber-500" />
          {credits}
        </div>
        <button
          type="button"
          onClick={toggleTheme}
          className="glass-soft group relative grid h-9 w-9 place-items-center overflow-hidden rounded-xl text-[16px] text-ink-2 transition hover:text-ink"
          aria-label={`Switch to ${theme === "dark" ? "light" : "dark"} mode`}
          title={`Switch to ${theme === "dark" ? "light" : "dark"} mode`}
        >
          <span className={`absolute transition duration-500 ${theme === "dark" ? "rotate-0 opacity-100" : "-rotate-90 scale-50 opacity-0"}`}>
            <MoonIcon />
          </span>
          <span className={`absolute transition duration-500 ${theme === "light" ? "rotate-0 opacity-100" : "rotate-90 scale-50 opacity-0"}`}>
            <SunIcon />
          </span>
        </button>
        <button
          type="button"
          onClick={() => setPanelOpen(!panelOpen)}
          className={`glass-soft grid h-9 w-9 place-items-center rounded-xl text-[16px] transition ${panelOpen ? "text-accent" : "text-ink-2 hover:text-ink"}`}
          aria-label="Toggle preview panel"
          aria-pressed={panelOpen}
        >
          <PanelRightIcon />
        </button>
      </div>
    </header>
  );
}

