"use client";

import { useMemo, useState } from "react";
import { CategoryIcon } from "@/components/icons/CategoryIcons";
import { GameEmblem } from "@/components/icons/GameEmblems";
import { ChevronRightIcon, PanelLeftIcon, SearchIcon } from "@/components/icons/ui";
import { CATEGORY_BY_KEY, GAMES } from "@/lib/data";
import { isJobLive, useAllMods, useStore } from "@/lib/store";
import type { CategoryKey, GameId } from "@/lib/types";

/** Left rail (collapsed) or full constellation tree (expanded) for jumping around the network. */
export function Navigator() {
  const open = useStore((s) => s.navOpen);
  const setOpen = useStore((s) => s.setNavOpen);
  const selection = useStore((s) => s.selection);
  const select = useStore((s) => s.select);
  const forgingId = useStore((s) => (isJobLive(s.job) ? s.job!.modId : undefined));
  const mods = useAllMods();
  const [query, setQuery] = useState("");

  const tree = useMemo(() => {
    const q = query.trim().toLowerCase();
    return GAMES.map((g) => {
      const gMods = mods.filter((m) => m.gameId === g.id);
      const cats = [...new Set([...g.categories, ...gMods.map((m) => m.category)])].map((key) => ({
        key,
        mods: gMods.filter((m) => m.category === key && (!q || m.name.toLowerCase().includes(q))),
        match: !q || CATEGORY_BY_KEY[key].label.toLowerCase().includes(q),
      }));
      const gameMatch = !q || g.name.toLowerCase().includes(q);
      return { g, count: gMods.length, cats: cats.filter((c) => gameMatch || c.match || c.mods.length) };
    }).filter((x) => x.cats.length || !q);
  }, [mods, query]);

  if (!open) {
    return (
      <aside className="glass fixed bottom-5 left-4 top-[76px] z-30 hidden w-[52px] flex-col items-center gap-1.5 rounded-2xl py-2.5 md:flex" aria-label="Games">
        <button
          type="button"
          onClick={() => select({ level: "core" })}
          className={`grid h-10 w-10 place-items-center rounded-xl transition ${selection.level === "core" ? "bg-[rgb(var(--glow)/0.16)]" : "hover:bg-[rgb(var(--glow)/0.08)]"}`}
          title="Cyrus Core"
          aria-label="Cyrus Core"
        >
          <span className="h-3.5 w-3.5 rounded-full bg-gradient-to-br from-white via-accent to-cyan shadow-[0_0_12px_var(--accent)]" />
        </button>
        <span className="my-1 h-px w-6 bg-line" />
        {GAMES.map((g) => {
          const on = selection.gameId === g.id;
          return (
            <button
              key={g.id}
              type="button"
              onClick={() => select({ level: "game", gameId: g.id })}
              className="tint group relative grid h-10 w-10 place-items-center rounded-xl text-[19px] transition hover:bg-[rgb(var(--glow)/0.08)]"
              style={{ ["--c" as string]: g.rgb, color: "var(--cc)", background: on ? `rgb(${g.rgb} / 0.14)` : undefined, boxShadow: on ? `inset 0 0 0 1px rgb(${g.rgb} / 0.5), 0 0 16px rgb(${g.rgb} / 0.3)` : undefined }}
              aria-label={g.name}
            >
              <GameEmblem emblem={g.emblem} />
              <span className="glass pointer-events-none absolute left-[calc(100%+12px)] whitespace-nowrap rounded-lg px-2.5 py-1 text-[12px] font-medium text-ink opacity-0 transition group-hover:opacity-100">
                {g.name}
              </span>
            </button>
          );
        })}
        <button
          type="button"
          onClick={() => setOpen(true)}
          className="btn-ghost mt-auto h-10 w-10 text-[17px] text-muted"
          aria-label="Expand navigator"
          title="Expand navigator"
        >
          <PanelLeftIcon />
        </button>
      </aside>
    );
  }

  const go = (gameId: GameId, category?: CategoryKey, modId?: string) => {
    if (modId) select({ level: "mod", gameId, category, modId }, { openPanel: true });
    else if (category) select({ level: "category", gameId, category });
    else select({ level: "game", gameId });
  };

  return (
    <aside className="glass animate-slide-right fixed bottom-5 left-4 top-[76px] z-30 flex w-[272px] flex-col overflow-hidden rounded-2xl" style={{ animationName: "pop-in" }} aria-label="Navigator">
      <div className="flex items-center gap-2 px-4 pb-2 pt-3.5">
        <h2 className="font-display text-[13px] font-semibold text-ink">Constellations</h2>
        <span className="rounded-md bg-[rgb(var(--glow)/0.1)] px-1.5 text-[10px] tabular-nums text-muted">{mods.length}</span>
        <button type="button" onClick={() => setOpen(false)} className="btn-ghost ml-auto h-8 w-8 text-muted" aria-label="Collapse navigator">
          <PanelLeftIcon />
        </button>
      </div>
      <label className="mx-3 mb-2 flex items-center gap-2 rounded-xl border border-line bg-[rgb(var(--glow)/0.05)] px-3 py-2 text-[12.5px] focus-within:border-line-2">
        <SearchIcon className="text-muted" />
        <input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Filter mods…" className="w-full bg-transparent text-ink outline-none placeholder:text-faint" />
      </label>
      <div className="min-h-0 flex-1 overflow-y-auto px-2 pb-3">
        <button
          type="button"
          onClick={() => select({ level: "core" })}
          className={`mb-1 flex w-full items-center gap-2.5 rounded-lg px-2 py-1.5 text-[12.5px] transition ${selection.level === "core" ? "bg-[rgb(var(--glow)/0.12)] text-ink" : "text-ink-2 hover:bg-[rgb(var(--glow)/0.06)]"}`}
        >
          <span className="h-3 w-3 rounded-full bg-gradient-to-br from-white via-accent to-cyan shadow-[0_0_10px_var(--accent)]" />
          Cyrus Core
        </button>
        {tree.map(({ g, count, cats }) => {
          const gOn = selection.gameId === g.id;
          const expanded = gOn || !!query;
          return (
            <div key={g.id} className="tint" style={{ ["--c" as string]: g.rgb }}>
              <button
                type="button"
                onClick={() => go(g.id)}
                className={`flex w-full items-center gap-2.5 rounded-lg px-2 py-1.5 text-left text-[13px] transition ${
                  gOn && selection.level === "game" ? "bg-[rgb(var(--glow)/0.12)] text-ink" : "text-ink-2 hover:bg-[rgb(var(--glow)/0.06)]"
                }`}
              >
                <ChevronRightIcon className={`text-[10px] text-faint transition ${expanded ? "rotate-90" : ""}`} />
                <span className="text-[16px]" style={{ color: "var(--cc)" }}>
                  <GameEmblem emblem={g.emblem} />
                </span>
                <span className="flex-1 truncate font-medium">{g.name}</span>
                <span className="text-[10.5px] tabular-nums text-faint">{count}</span>
              </button>
              {expanded && (
                <div className="relative ml-[15px] border-l border-line pl-2">
                  {cats.map(({ key, mods: cMods }) => {
                    const c = CATEGORY_BY_KEY[key];
                    const cOn = gOn && selection.category === key;
                    return (
                      <div key={key} className="tint" style={{ ["--c" as string]: c.rgb }}>
                        <button
                          type="button"
                          onClick={() => go(g.id, key)}
                          className={`flex w-full items-center gap-2 rounded-lg px-2 py-1 text-left text-[12.5px] transition ${
                            cOn && selection.level === "category" ? "bg-[rgb(var(--glow)/0.12)] text-ink" : "text-ink-2 hover:bg-[rgb(var(--glow)/0.06)]"
                          }`}
                        >
                          <span className="text-[14px]" style={{ color: "var(--cc)" }}>
                            <CategoryIcon k={key} />
                          </span>
                          <span className="flex-1 truncate">{c.label}</span>
                          <span className="text-[10.5px] tabular-nums text-faint">{cMods.length}</span>
                        </button>
                        {(cOn || !!query) &&
                          cMods.map((m) => {
                            const mOn = selection.modId === m.id;
                            return (
                              <button
                                key={m.id}
                                type="button"
                                onClick={() => go(g.id, key, m.id)}
                                className={`ml-4 flex w-[calc(100%-16px)] items-center gap-2 rounded-lg px-2 py-1 text-left text-[12px] transition ${
                                  mOn ? "bg-[rgb(var(--glow)/0.12)] text-ink" : "text-muted hover:bg-[rgb(var(--glow)/0.06)] hover:text-ink-2"
                                }`}
                              >
                                <span
                                  className={`h-1.5 w-1.5 shrink-0 rounded-full ${forgingId === m.id ? "animate-ping" : ""}`}
                                  style={{ background: `rgb(${c.rgb})`, boxShadow: `0 0 6px rgb(${c.rgb})` }}
                                />
                                <span className="truncate">{m.name}</span>
                              </button>
                            );
                          })}
                      </div>
                    );
                  })}
                </div>
              )}
            </div>
          );
        })}
      </div>
    </aside>
  );
}

