"use client";

import { useEffect, useState } from "react";
import { CheckIcon, CloseIcon, MinusIcon, PlusIcon, RecenterIcon, SparkleIcon } from "@/components/icons/ui";
import { cameraApi } from "@/lib/camera";
import { useStore } from "@/lib/store";

export function ZoomControls() {
  const [k, setK] = useState(1);
  const navOpen = useStore((s) => s.navOpen);
  const select = useStore((s) => s.select);
  useEffect(() => cameraApi.onZoom(setK), []);

  return (
    <div
      className="fixed bottom-6 z-20 hidden flex-col items-start gap-2 transition-[left] duration-500 md:flex"
      style={{ left: navOpen ? 304 : 84 }}
    >
      <div className="glass-soft hidden flex-col gap-1.5 rounded-xl px-3 py-2.5 text-[10.5px] text-muted xl:flex">
        <span className="mb-0.5 text-[9.5px] font-semibold uppercase tracking-[0.18em] text-faint">Hierarchy</span>
        <span className="flex items-center gap-2">
          <span className="h-3 w-3 rounded-full bg-gradient-to-br from-white via-accent to-cyan shadow-[0_0_8px_var(--accent)]" /> Cyrus Core
        </span>
        <span className="flex items-center gap-2">
          <span className="h-3 w-3 rounded-full border border-emerald-400/80 bg-emerald-400/15" /> Game
        </span>
        <span className="flex items-center gap-2">
          <span className="ml-[1px] h-2.5 w-2.5 rotate-45 rounded-[3px] border border-rose-400/80 bg-rose-400/15" /> Category
        </span>
        <span className="flex items-center gap-2">
          <span className="ml-[2px] h-2 w-2 rounded-full bg-amber-300 shadow-[0_0_6px_rgb(252_211_77)]" /> Mod
        </span>
        <span className="mt-1 border-t border-line pt-1.5 text-faint">Drag branches · scroll to zoom</span>
      </div>
      <div className="glass-soft flex items-center gap-0.5 rounded-xl p-1">
        <button type="button" onClick={() => cameraApi.zoomBy(1 / 1.25)} className="btn-ghost h-8 w-8" aria-label="Zoom out">
          <MinusIcon />
        </button>
        <span className="w-11 text-center font-mono text-[11px] tabular-nums text-muted">{Math.round(k * 100)}%</span>
        <button type="button" onClick={() => cameraApi.zoomBy(1.25)} className="btn-ghost h-8 w-8" aria-label="Zoom in">
          <PlusIcon />
        </button>
        <span className="mx-0.5 h-5 w-px bg-line" />
        <button type="button" onClick={() => select({ level: "core" })} className="btn-ghost h-8 w-8" aria-label="Recenter on the core" title="Recenter">
          <RecenterIcon />
        </button>
      </div>
    </div>
  );
}

export function Toasts() {
  const toasts = useStore((s) => s.toasts);
  const dismiss = useStore((s) => s.dismissToast);
  return (
    <div className="pointer-events-none fixed right-4 top-[76px] z-[70] flex w-[min(340px,calc(100vw-32px))] flex-col gap-2" aria-live="polite">
      {toasts.map((t) => {
        const rgb = t.rgb ?? (t.tone === "error" ? "244 63 94" : t.tone === "success" ? "52 211 153" : "167 139 250");
        return (
          <div key={t.id} className="glass animate-slide-right tint pointer-events-auto flex items-start gap-3 rounded-2xl p-3.5" style={{ ["--c" as string]: rgb }}>
            <span className="mt-0.5 grid h-7 w-7 shrink-0 place-items-center rounded-lg text-[13px]" style={{ color: "var(--cc)", background: `rgb(${rgb} / 0.15)`, boxShadow: `0 0 16px rgb(${rgb} / 0.3)` }}>
              {t.tone === "success" ? <CheckIcon /> : t.tone === "error" ? <CloseIcon /> : <SparkleIcon />}
            </span>
            <div className="min-w-0 flex-1">
              <div className="text-[13px] font-semibold text-ink">{t.title}</div>
              {t.body && <div className="mt-0.5 text-[12px] leading-snug text-ink-2">{t.body}</div>}
            </div>
            <button type="button" onClick={() => dismiss(t.id)} className="btn-ghost h-6 w-6 text-[11px] text-muted" aria-label="Dismiss">
              <CloseIcon />
            </button>
          </div>
        );
      })}
    </div>
  );
}

