toolUseResult.content:
"use client";

import { useEffect, useMemo, useRef, useState, type ReactNode } from "react";
import { CategoryIcon } from "@/components/icons/CategoryIcons";
import { GameEmblem } from "@/components/icons/GameEmblems";
import { ArrowRightIcon, EditIcon, MoonIcon, PanelRightIcon, RecenterIcon, SearchIcon, SunIcon } from "@/components/icons/ui";
import { CATEGORY_BY_KEY, GAMES } from "@/lib/data";
import { useAllMods, useStore } from "@/lib/store";

interface Item {
  id: string;
  group: "Games" | "Categories" | "Mods" | "Actions";
  title: string;
  hint?: string;
  rgb?: string;
  icon: ReactNode;
  run: () => void;
  hay: string;
}

export function CommandPalette() {
  const open = useStore((s) => s.paletteOpen);
  const setOpen = useStore((s) => s.setPaletteOpen);
  const select = useStore((s) => s.select);
  const theme = useStore((s) => s.theme);
  const mods = useAllMods();
  const [q, setQ] = useState("");
  const [idx, setIdx] = useState(0);
  const inputRef = useRef<HTMLInputElement>(null);
  const listRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (open) {
      setQ("");
      setIdx(0);
      requestAnimationFrame(() => inputRef.current?.focus());
    }
  }, [open]);

  const items = useMemo<Item[]>(() => {
    const st = useStore.getState;
    const out: Item[] = [];
    for (const g of GAMES) {
      out.push({
        id: g.id,
        group: "Games",
        title: g.name,
        hint: g.toolchain,
        rgb: g.rgb,
        icon: <GameEmblem emblem={g.emblem} />,
        run: () => select({ level: "game", gameId: g.id }),
        hay: `${g.name} ${g.aliases.join(" ")}`.toLowerCase(),
      });
      const cats = [...new Set([...g.categories, ...mods.filter((m) => m.gameId === g.id).map((m) => m.category)])];
      for (const key of cats) {
        const c = CATEGORY_BY_KEY[key];
        out.push({
          id: `${g.id}:${key}`,
          group: "Categories",
          title: c.label,
          hint: g.name,
          rgb: c.rgb,
          icon: <CategoryIcon k={key} />,
          run: () => select({ level: "category", gameId: g.id, category: key }),
          hay: `${c.label} ${g.name} ${g.short}`.toLowerCase(),
        });
      }
    }
    for (const m of mods) {
      const c = CATEGORY_BY_KEY[m.category];
      const g = GAMES.find((x) => x.id === m.gameId)!;
      out.push({
        id: m.id,
        group: "Mods",
        title: m.name,
        hint: `${g.short} › ${c.label}`,
        rgb: c.rgb,
        icon: <span className="block h-2 w-2 rounded-full" style={{ background: `rgb(${c.rgb})`, boxShadow: `0 0 8px rgb(${c.rgb})` }} />,
        run: () => select({ level: "mod", gameId: m.gameId, category: m.category, modId: m.id }, { openPanel: true }),
        hay: `${m.name} ${m.summary} ${m.tags.join(" ")} ${g.name} ${c.label}`.toLowerCase(),
      });
    }
    out.push(
      {
        id: "act-theme",
        group: "Actions",
        title: `Switch to ${theme === "dark" ? "light" : "dark"} mode`,
        icon: theme === "dark" ? <SunIcon /> : <MoonIcon />,
        run: () => st().toggleTheme(),
        hay: "theme light dark mode toggle",
      },
      { id: "act-center", group: "Actions", title: "Recenter on the core", icon: <RecenterIcon />, run: () => select({ level: "core" }), hay: "recenter core overview home zoom" },
      { id: "act-panel", group: "Actions", title: "Toggle preview panel", icon: <PanelRightIcon />, run: () => st().setPanelOpen(!st().panelOpen), hay: "panel preview code files versions notes" },
      { id: "act-new", group: "Actions", title: "Forge a new mod", icon: <EditIcon />, run: () => st().focusPrompt(), hay: "new create forge prompt write" },
    );
    return out;
  }, [mods, select, theme]);

  const results = useMemo(() => {
    const terms = q.toLowerCase().split(/\s+/).filter(Boolean);
    const hits = terms.length ? items.filter((it) => terms.every((t) => it.hay.includes(t) || it.title.toLowerCase().includes(t))) : items.filter((it) => it.group !== "Categories");
    return hits.slice(0, 40);
  }, [items, q]);

  useEffect(() => setIdx(0), [q]);
  useEffect(() => {
    listRef.current?.querySelector(`[data-idx="${idx}"]`)?.scrollIntoView({ block: "nearest" });
  }, [idx]);

  if (!open) return null;

  const run = (it: Item | undefined) => {
    if (!it) return;
    setOpen(false);
    it.run();
  };

  let lastGroup = "";
  return (
    <div className="animate-fade fixed inset-0 z-[60] flex items-start justify-center bg-[rgb(5_3_11/0.45)] px-3 pt-[12vh] backdrop-blur-[6px] light:bg-[rgb(91_33_182/0.08)]" onPointerDown={() => setOpen(false)}>
      <div
        className="glass animate-rise hairline-top w-full max-w-[600px] overflow-hidden rounded-2xl"
        onPointerDown={(e) => e.stopPropagation()}
        role="dialog"
        aria-label="Jump to"
      >
        <div className="flex items-center gap-3 border-b border-line px-4 py-3.5">
          <SearchIcon className="text-[17px] text-accent" />
          <input
            ref={inputRef}
            value={q}
            onChange={(e) => setQ(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "ArrowDown") {
                e.preventDefault();
                setIdx((i) => Math.min(results.length - 1, i + 1));
              } else if (e.key === "ArrowUp") {
                e.preventDefault();
                setIdx((i) => Math.max(0, i - 1));
              } else if (e.key === "Enter") {
                e.preventDefault();
                run(results[idx]);
              } else if (e.key === "Escape") setOpen(false);
            }}
            placeholder="Jump to a game, category or mod…"
            className="flex-1 bg-transparent text-[15px] text-ink outline-none placeholder:text-faint"
          />
          <span className="kbd">Esc</span>
        </div>
        <div ref={listRef} className="max-h-[52vh] overflow-y-auto p-2">
          {results.length === 0 && <div className="p-6 text-center text-[13px] text-muted">Nothing in the network matches “{q}”.</div>}
          {results.map((it, i) => {
            const header = it.group !== lastGroup ? it.group : null;
            lastGroup = it.group;
            const on = i === idx;
            return (
              <div key={it.id}>
                {header && <div className="px-3 pb-1 pt-2.5 text-[10px] font-semibold uppercase tracking-[0.18em] text-faint">{header}</div>}
                <button
                  type="button"
                  data-idx={i}
                  onMouseMove={() => setIdx(i)}
                  onClick={() => run(it)}
                  className={`tint flex w-full items-center gap-3 rounded-xl px-3 py-2 text-left transition ${on ? "bg-[rgb(var(--glow)/0.12)]" : ""}`}
                  style={it.rgb ? { ["--c" as string]: it.rgb } : undefined}
                >
                  <span
                    className="grid h-7 w-7 shrink-0 place-items-center rounded-lg text-[15px]"
                    style={{ color: it.rgb ? "var(--cc)" : "var(--accent)", background: it.rgb ? `rgb(${it.rgb} / 0.12)` : "rgb(var(--glow) / 0.1)" }}
                  >
                    {it.icon}
                  </span>
                  <span className="min-w-0 flex-1 truncate text-[13.5px] text-ink">{it.title}</span>
                  {it.hint && <span className="shrink-0 truncate text-[11.5px] text-muted">{it.hint}</span>}
                  <ArrowRightIcon className={`shrink-0 text-muted transition ${on ? "opacity-100" : "opacity-0"}`} />
                </button>
              </div>
            );
          })}
        </div>
        <div className="flex items-center gap-3 border-t border-line px-4 py-2 text-[11px] text-faint">
          <span>
            <span className="kbd">↑</span> <span className="kbd">↓</span> navigate
          </span>
          <span>
            <span className="kbd">Enter</span> jump
          </span>
          <span className="ml-auto">Camera flies to whatever you pick</span>
        </div>
      </div>
    </div>
  );
}

