function minecraft(input: TemplateInput) {
  const { cls, snake } = identity(input.modName);
  const n = numbers(input);
  const fxs = effectsFor(input);
  const arch = ARCH[input.category.key];
  const pkg = `dev.cyrus.${snake}`;
  const base = `src/main/java/dev/cyrus/${snake}`;
  const model = MODEL_NAME[input.model];
  const yako = input.model === "yako";
  const vNote = input.version > 1 ? `// v${input.version}: rebalanced numbers${yako ? ", added tooltip lore" : ""}` : "";
  const header = code`
    /**
     * ${input.modName} — ${input.category.label.toLowerCase()} for Minecraft (Fabric)
     * Forged by Cyrus · ${model} · v${input.version}
     */`;

  let main: ModFile;
  let register: string;

  if (arch === "item") {
    const sword = input.category.key === "weapons";
    const baseCls = sword ? "SwordItem" : "Item";
    const effects = fxs.map((e) => sub(e.java, "target", "attacker", { WORLD: "server", POWER: "POWER" }));
    main = file(
      `${base}/item/${cls}.java`,
      code`
        package ${pkg}.item;

        import net.minecraft.entity.EntityType;
        import net.minecraft.entity.LightningEntity;
        import net.minecraft.entity.LivingEntity;
        import net.minecraft.entity.effect.StatusEffectInstance;
        import net.minecraft.entity.effect.StatusEffects;
        import net.minecraft.entity.player.PlayerEntity;
        import net.minecraft.item.${baseCls};
        import net.minecraft.item.ItemStack;
        ${sword ? "import net.minecraft.item.ToolMaterials;" : ""}
        import net.minecraft.particle.ParticleTypes;
        import net.minecraft.server.world.ServerWorld;
        import net.minecraft.sound.SoundCategory;
        import net.minecraft.sound.SoundEvents;
        import net.minecraft.util.Hand;
        import net.minecraft.util.TypedActionResult;
        import net.minecraft.world.World;

        ${header}
        ${vNote}
        public class ${cls} extends ${baseCls} {
            public static final float POWER = ${n.power}F;
            public static final int EFFECT_TICKS = ${n.duration * 20};
            public static final int COOLDOWN_TICKS = ${Math.round(n.cooldown * 20)};
            public static final double AURA_RADIUS = ${n.radius}.0;

            public ${cls}(Settings settings) {
                super(${sword ? `ToolMaterials.NETHERITE, settings.attributeModifiers(SwordItem.createAttributeModifiers(ToolMaterials.NETHERITE, ${Math.round(n.power / 2)}, -2.6F))` : "settings.maxCount(1)"});
            }

            @Override
            public boolean postHit(ItemStack stack, LivingEntity target, LivingEntity attacker) {
                World world = attacker.getWorld();
                if (!world.isClient && world instanceof ServerWorld server) {
                    target.damage(server.getDamageSources().magic(), POWER * 0.4F);
                    ${effects}
                    server.spawnParticles(${fxs[0].particle}, target.getX(), target.getBodyY(0.5), target.getZ(), 24, 0.4, 0.6, 0.4, 0.02);
                }
                return super.postHit(stack, target, attacker);
            }

            @Override
            public TypedActionResult<ItemStack> use(World world, PlayerEntity user, Hand hand) {
                ItemStack stack = user.getStackInHand(hand);
                if (user.getItemCooldownManager().isCoolingDown(this)) {
                    return TypedActionResult.fail(stack);
                }
                if (!world.isClient) {
                    // Active ability: pulse the on-hit effect through everything nearby.
                    world.getEntitiesByClass(LivingEntity.class, user.getBoundingBox().expand(AURA_RADIUS), e -> e != user && e.isAlive())
                        .forEach(target -> postHit(stack, target, user));
                    world.playSound(null, user.getBlockPos(), ${fxs[0].sound}, SoundCategory.PLAYERS, 1.0F, 1.15F);
                    user.getItemCooldownManager().set(this, COOLDOWN_TICKS);
                }
                return TypedActionResult.success(stack, world.isClient());
            }
            ${
              fxs.some((e) => e.key === "summon")
                ? code`

                  private static void spawnEcho(ServerWorld world, net.minecraft.util.math.BlockPos pos) {
                      var echo = EntityType.VEX.create(world);
                      if (echo == null) return;
                      echo.refreshPositionAndAngles(pos.up(), 0, 0);
                      echo.setLifeTicks(EFFECT_TICKS);
                      world.spawnEntity(echo);
                  }`
                : ""
            }
            ${
              yako
                ? code`

                  @Override
                  public boolean hasGlint(ItemStack stack) {
                      // Glint only while the ability is ready, so players can read the cooldown at a glance.
                      return true;
                  }`
                : ""
            }
        }`,
    );
    register = `Registry.register(Registries.ITEM, id("${snake}"), new ${cls}(new Item.Settings().rarity(Rarity.EPIC)));`;
  } else if (arch === "entity") {
    const hostile = input.category.key === "creatures";
    const baseCls = hostile ? "HostileEntity" : "PathAwareEntity";
    const effects = fxs.map((e) => sub(e.java, "living", "this", { WORLD: "server", POWER: "POWER" }));
    const goals =
      input.category.key === "creatures"
        ? ["this.goalSelector.add(2, new MeleeAttackGoal(this, 1.15, false));", "this.goalSelector.add(5, new WanderAroundFarGoal(this, 0.8));", "this.targetSelector.add(1, new ActiveTargetGoal<>(this, PlayerEntity.class, true));"]
        : input.category.key === "characters"
          ? ["this.goalSelector.add(2, new LookAtEntityGoal(this, PlayerEntity.class, 8.0F));", "this.goalSelector.add(3, new WanderAroundFarGoal(this, 0.6));", "this.goalSelector.add(4, new LookAroundGoal(this));"]
          : ["// Vehicles are steered by the rider; no autonomous goals.", "this.goalSelector.add(5, new LookAroundGoal(this));"];
    main = file(
      `${base}/entity/${cls}Entity.java`,
      code`
        package ${pkg}.entity;

        import net.minecraft.entity.Entity;
        import net.minecraft.entity.EntityType;
        import net.minecraft.entity.LightningEntity;
        import net.minecraft.entity.LivingEntity;
        import net.minecraft.entity.ai.goal.*;
        import net.minecraft.entity.attribute.DefaultAttributeContainer;
        import net.minecraft.entity.attribute.EntityAttributes;
        import net.minecraft.entity.effect.StatusEffectInstance;
        import net.minecraft.entity.effect.StatusEffects;
        import net.minecraft.entity.mob.${baseCls};
        import net.minecraft.entity.player.PlayerEntity;
        import net.minecraft.server.world.ServerWorld;
        import net.minecraft.world.World;

        ${header}
        ${vNote}
        public class ${cls}Entity extends ${baseCls} {
            public static final float POWER = ${n.power}F;
            public static final int EFFECT_TICKS = ${n.duration * 20};
            private static final int ABILITY_TICKS = ${Math.round(n.cooldown * 20)};
            private int abilityCooldown = ABILITY_TICKS;
            private boolean enraged = false;

            public ${cls}Entity(EntityType<? extends ${baseCls}> type, World world) {
                super(type, world);
                this.experiencePoints = ${n.xp};
            }

            public static DefaultAttributeContainer.Builder createAttributes() {
                return ${hostile ? "HostileEntity.createHostileAttributes()" : "PathAwareEntity.createMobAttributes()"}
                    .add(EntityAttributes.GENERIC_MAX_HEALTH, ${n.health / 10}.0)
                    .add(EntityAttributes.GENERIC_MOVEMENT_SPEED, ${n.speed})
                    .add(EntityAttributes.GENERIC_ATTACK_DAMAGE, ${n.power})
                    .add(EntityAttributes.GENERIC_FOLLOW_RANGE, 32.0);
            }

            @Override
            protected void initGoals() {
                this.goalSelector.add(0, new SwimGoal(this));
                ${goals}
            }

            @Override
            public boolean tryAttack(Entity target) {
                boolean hit = super.tryAttack(target);
                if (hit && target instanceof LivingEntity living && this.getWorld() instanceof ServerWorld server) {
                    ${effects}
                }
                return hit;
            }

            @Override
            public void tick() {
                super.tick();
                if (this.getWorld().isClient) return;
                if (!enraged && this.getHealth() < this.getMaxHealth() * 0.4F) {
                    // Phase two: faster, angrier, glowing.
                    enraged = true;
                    this.addStatusEffect(new StatusEffectInstance(StatusEffects.SPEED, Integer.MAX_VALUE, 1));
                    this.addStatusEffect(new StatusEffectInstance(StatusEffects.GLOWING, Integer.MAX_VALUE, 0));
                }
                if (--abilityCooldown <= 0) {
                    abilityCooldown = enraged ? ABILITY_TICKS / 2 : ABILITY_TICKS;
                    LivingEntity target = this.getTarget();
                    if (target != null && this.squaredDistanceTo(target) < ${n.radius * n.radius * 4}.0) {
                        this.tryAttack(target);
                    }
                }
            }
        }`,
    );
    register = `FabricDefaultAttributeRegistry.register(${cls.toUpperCase()}, ${cls}Entity.createAttributes());`;
  } else if (arch === "world") {
    main = file(
      `${base}/world/${cls}Feature.java`,
      code`
        package ${pkg}.world;

        import com.mojang.serialization.Codec;
        import net.minecraft.block.BlockState;
        import net.minecraft.block.Blocks;
        import net.minecraft.util.math.BlockPos;
        import net.minecraft.util.math.random.Random;
        import net.minecraft.world.StructureWorldAccess;
        import net.minecraft.world.gen.feature.DefaultFeatureConfig;
        import net.minecraft.world.gen.feature.Feature;
        import net.minecraft.world.gen.feature.util.FeatureContext;

        ${header}
        ${vNote}
        public class ${cls}Feature extends Feature<DefaultFeatureConfig> {
            private static final int RADIUS = ${n.radius + 4};
            private static final int LAYERS = ${n.interval + 3};
            private static final float ORE_CHANCE = ${n.chance}F;

            public ${cls}Feature(Codec<DefaultFeatureConfig> codec) {
                super(codec);
            }

            @Override
            public boolean generate(FeatureContext<DefaultFeatureConfig> ctx) {
                StructureWorldAccess world = ctx.getWorld();
                BlockPos origin = ctx.getOrigin();
                Random random = ctx.getRandom();

                // Carve an inverted cone: wide at the top, tapering into a crystal root.
                for (int layer = 0; layer < LAYERS; layer++) {
                    int r = RADIUS - layer * RADIUS / LAYERS;
                    for (int dx = -r; dx <= r; dx++) {
                        for (int dz = -r; dz <= r; dz++) {
                            if (dx * dx + dz * dz > r * r + random.nextInt(3)) continue;
                            BlockPos pos = origin.add(dx, -layer, dz);
                            world.setBlockState(pos, pick(layer, random), 3);
                        }
                    }
                }
                decorate(world, origin.up(), random);
                return true;
            }

            private BlockState pick(int layer, Random random) {
                if (layer == 0) return Blocks.MOSS_BLOCK.getDefaultState();
                if (random.nextFloat() < ORE_CHANCE) return Blocks.AMETHYST_BLOCK.getDefaultState();
                return layer < 2 ? Blocks.DIRT.getDefaultState() : Blocks.CALCITE.getDefaultState();
            }

            private void decorate(StructureWorldAccess world, BlockPos top, Random random) {
                for (int i = 0; i < RADIUS; i++) {
                    BlockPos p = top.add(random.nextInt(RADIUS) - RADIUS / 2, 0, random.nextInt(RADIUS) - RADIUS / 2);
                    if (world.isAir(p)) world.setBlockState(p, Blocks.GLOW_LICHEN.getDefaultState(), 3);
                }
            }
        }`,
    );
    register = `Registry.register(Registries.FEATURE, id("${snake}"), new ${cls}Feature(DefaultFeatureConfig.CODEC));`;
  } else if (arch === "system") {
    const k = input.category.key;
    const body =
      k === "interface"
        ? code`
            HudRenderCallback.EVENT.register((ctx, tickCounter) -> {
                MinecraftClient client = MinecraftClient.getInstance();
                if (client.player == null || client.options.hudHidden) return;
                int x = client.getWindow().getScaledWidth() - PANEL_WIDTH - 8;
                ctx.fill(x, 8, x + PANEL_WIDTH, 8 + PANEL_HEIGHT, 0x99_120A26);
                ctx.drawBorder(x, 8, PANEL_WIDTH, PANEL_HEIGHT, ACCENT);
                ctx.drawText(client.textRenderer, Text.translatable("hud.${snake}.title"), x + 6, 14, ACCENT, true);
                float hp = client.player.getHealth() / client.player.getMaxHealth();
                ctx.fill(x + 6, 28, x + 6 + (int) ((PANEL_WIDTH - 12) * hp), 32, ACCENT);
            });`
        : k === "audio"
