function cyberpunk(input: TemplateInput) {
  const { cls, snake } = identity(input.modName);
  const n = numbers(input);
  const fxs = effectsFor(input);
  const k = input.category.key;
  const model = MODEL_NAME[input.model];
  const effects = fxs.map((e) => sub(e.lua, "target", "player", { Power: "Config.power" }));
  const vNote = input.version > 1 ? `-- v${input.version}: retuned values, smoother cooldowns` : "";

  const drawBlock =
    k === "interface"
      ? code`
          registerForEvent("onDraw", function()
              if not state.visible then return end
              ImGui.SetNextWindowPos(24, 220, ImGuiCond.FirstUseEver)
              ImGui.PushStyleColor(ImGuiCol.WindowBg, 0.04, 0.02, 0.09, 0.72)
              ImGui.PushStyleColor(ImGuiCol.Border, 1.0, 0.25, 0.8, 0.9)
              if ImGui.Begin("${input.modName}", ImGuiWindowFlags.NoTitleBar + ImGuiWindowFlags.AlwaysAutoResize) then
                  local ram = ${snake}.ram(player)
                  ImGui.Text(string.format("RAM  %d / %d", ram.current, ram.max))
                  ImGui.ProgressBar(ram.current / math.max(ram.max, 1), 220, 8, "")
                  for _, hack in ipairs(${snake}.cooldowns(player)) do
                      ImGui.Text(string.format("%-14s %4.1fs", hack.name, hack.remaining))
                  end
              end
              ImGui.End()
              ImGui.PopStyleColor(2)
          end)`
      : code`
          registerForEvent("onDraw", function()
              if not state.overlay then return end
              if ImGui.Begin("${input.modName}") then
                  Config.power = ImGui.SliderFloat("Power", Config.power, 1, 20)
                  Config.cooldown = ImGui.SliderFloat("Cooldown", Config.cooldown, 0.5, 15)
              end
              ImGui.End()
          end)`;

  const updateBody =
    k === "vehicles"
      ? code`
          local vehicle = Game.GetMountedVehicle(player)
          if vehicle and ${snake}.isOwned(vehicle) then
              ${snake}.applyHandling(vehicle, Config)
          end`
      : k === "worlds"
        ? code`
            if not state.spawned and ${snake}.nearAnchor(player, Config.radius * 40) then
                ${snake}.spawnProps(Config)
                state.spawned = true
            end`
        : k === "shaders"
          ? code`
              local weather = Game.GetWeatherSystem():GetWeatherState().name.value
              ${snake}.applyGrade(weather, Config.intensity)`
          : k === "audio"
            ? code`
                local combat = player:IsInCombat()
                if combat ~= state.combat then
                    state.combat = combat
                    Game.GetAudioSystem():Play(combat and "cyrus_${snake}_combat" or "cyrus_${snake}_cruise")
                end`
            : code`
                local target = Game.GetTargetingSystem():GetLookAtObject(player, false, false)
                if target and target:IsNPC() and ${snake}.ready(state, Config.cooldown) then
                    ${effects}
                    state.lastFire = os.clock()
                end`;

  const main = file(
    "init.lua",
    code`
      -- ${input.modName} — ${input.category.label} for Cyberpunk 2077 (Cyber Engine Tweaks)
      -- Forged by Cyrus · ${model} · v${input.version}
      ${vNote}

      local ${snake} = require("modules/${snake}")
      local Config = ${snake}.loadConfig()

      local state = {
          visible = true,
          overlay = false,
          lastFire = 0,
          spawned = false,
          combat = false,
      }

      registerForEvent("onInit", function()
          ${k === "weapons" || k === "items" ? `TweakDB:SetFlat("Items.Preset_${cls}.damagePerHit", ${(n.power * 9).toFixed(1)})\nTweakDB:SetFlat("Items.Preset_${cls}.cycleTime", ${(n.cooldown / 10).toFixed(2)})` : ""}
          Observe("PlayerPuppet", "OnAction", function(self, action)
              if ListenerAction.GetName(action).value == "${snake}_toggle" and ListenerAction.IsButtonJustPressed(action) then
                  state.visible = not state.visible
              end
          end)
          print("[${input.modName}] online — v${input.version}")
      end)

      registerForEvent("onUpdate", function(delta)
          local player = Game.GetPlayer()
          if not player then return end
          ${updateBody}
      end)

      registerForEvent("onOverlayOpen", function() state.overlay = true end)
      registerForEvent("onOverlayClose", function()
          state.overlay = false
          ${snake}.saveConfig(Config)
      end)

      ${drawBlock}

      registerInput("${snake}_toggle", "Toggle ${input.modName}", function(down)
          if down then state.visible = not state.visible end
      end)

      return ${snake}`,
  );

  const module = file(
    `modules/${snake}.lua`,
    code`
      -- ${input.modName} helpers
      local M = {}

      local DEFAULTS = {
          power = ${n.power},
          cooldown = ${n.cooldown},
          radius = ${n.radius},
          intensity = ${n.intensity},
      }

      function M.loadConfig()
          local f = io.open("config.json", "r")
          if not f then return DEFAULTS end
          local ok, data = pcall(json.decode, f:read("*a"))
          f:close()
          if not ok or type(data) ~= "table" then return DEFAULTS end
          for k, v in pairs(DEFAULTS) do
              if data[k] == nil then data[k] = v end
          end
          return data
      end

      function M.saveConfig(config)
          local f = io.open("config.json", "w")
          if f then
              f:write(json.encode(config))
              f:close()
          end
      end

      function M.ready(state, cooldown)
          return os.clock() - state.lastFire >= cooldown
      end

      function M.ram(player)
          local pools = Game.GetStatPoolsSystem()
          local id = player:GetEntityID()
          return {
              current = math.floor(pools:GetStatPoolValue(id, gamedataStatPoolType.Memory, false)),
              max = math.floor(Game.GetStatsSystem():GetStatValue(id, gamedataStatType.Memory)),
          }
      end

      function M.cooldowns(player)
          return {
              { name = "Short Circuit", remaining = 0 },
              { name = "Overheat", remaining = ${n.cooldown} },
          }
      end

      function M.isOwned(vehicle)
          return vehicle:GetRecord():GetID().value:find("${snake}") ~= nil
      end

      function M.applyHandling(vehicle, config)
          vehicle:GetVehicleComponent():SetSpeedMultiplier(1 + config.power / 40)
      end

      function M.applyGrade(weather, intensity)
          local wet = weather:find("rain") ~= nil
          GameOptions.SetFloat("Rendering", "LUTIntensity", intensity * (wet and 1.15 or 0.9))
      end

      function M.nearAnchor(player, range)
          local p = player:GetWorldPosition()
          return Vector4.Distance(p, Vector4.new(-1350, 1200, 25, 1)) < range
      end

      function M.spawnProps(config)
          for i = 1, config.radius do
              local angle = (i / config.radius) * math.pi * 2
              local pos = Vector4.new(-1350 + math.cos(angle) * 12, 1200 + math.sin(angle) * 12, 25, 1)
              exEntitySpawner.Spawn("base\\\\environment\\\\neon_sign_${snake}.ent", WorldTransform.new(pos, EulerAngles.new(0, 0, 0)))
          end
      end

      return M`,
  );

  const config = file("config.json", JSON.stringify({ power: n.power, cooldown: n.cooldown, radius: n.radius, intensity: n.intensity }, null, 2) + "\n");

  const shader =
    k === "shaders"
      ? file(
          `reshade/${snake}.fx`,
          code`
            // ${input.modName} — ReShade grade · Forged by Cyrus v${input.version}
            uniform float Intensity < ui_type = "slider"; ui_min = 0.0; ui_max = 2.0; > = ${n.intensity};
            uniform float Timer < source = "timer"; >;
            texture BackBufferTex : COLOR;
            sampler BackBuffer { Texture = BackBufferTex; };

            float3 Grade(float3 c)
            {
                float l = dot(c, float3(0.2126, 0.7152, 0.0722));
                float3 teal = float3(0.0, 0.55, 0.6);
                float3 magenta = float3(0.95, 0.2, 0.75);
                return lerp(c, lerp(teal, magenta, l) * (l + 0.3), 0.35 * Intensity);
            }

            float4 PS_Grade(float4 pos : SV_Position, float2 uv : TEXCOORD) : SV_Target
            {
                float3 c = tex2D(BackBuffer, uv).rgb;
                c = Grade(c);
                c += frac(sin(dot(uv * Timer, float2(12.9898, 78.233))) * 43758.5453) * 0.03;
                return float4(c, 1.0);
            }

            technique ${cls} { pass { VertexShader = PostProcessVS; PixelShader = PS_Grade; } }`,
        )
      : undefined;

  const test = file(
    `tests/${snake}_spec.lua`,
    code`
      -- busted spec for ${input.modName}
      package.path = "./?.lua;" .. package.path
      _G.json = { decode = function() return {} end, encode = function() return "{}" end }
      local M = require("modules/${snake}")

      describe("${input.modName}", function()
          it("fills missing config with defaults", function()
              local cfg = M.loadConfig()
              assert.is_true(cfg.power > 0)
              assert.is_true(cfg.cooldown >= 0.5)
          end)

          it("respects the cooldown", function()
              local state = { lastFire = os.clock() }
              assert.is_false(M.ready(state, 60))
          end)
      end)`,
  );

  return { files: shader ? [main, shader, module] : [main, module], config, l10n: undefined as ModFile | undefined, test };
}

/* ═════════════════════════ assembly ═════════════════════════ */

const INSTALL: Record<Game["id"], string[]> = {
  minecraft: ["Install Fabric Loader 0.16+ and Fabric API for 1.21.", "Build with `./gradlew build`.", "Drop the jar from `build/libs` into `.minecraft/mods`."],
  skyrim: ["Compile the `.psc` scripts with the Creation Kit (or Papyrus Compiler).", "Pack with the generated FOMOD folder.", "Install through Mod Organizer 2 or Vortex and enable the plugin."],
  stardew: ["Install SMAPI 4.0+.", "Build the project with `dotnet build` (ModBuildConfig deploys it).", "Launch the game through SMAPI."],
  terraria: ["Open tModLoader → Workshop → Develop Mods.", "Place this folder in `ModSources` and click **Build + Reload**.", "Enable the mod in the Mods menu."],
  cyberpunk: ["Install Cyber Engine Tweaks 1.32+.", "Copy this folder to `bin/x64/plugins/cyber_engine_tweaks/mods/`.", "Bind the toggle key in the CET overlay → Bindings."],
};

function readme(input: TemplateInput, files: ModFile[]) {
  const features = deriveFeatures(input);
  return code`
    # ${input.modName}

    > ${input.category.label} mod for **${input.game.name}** · ${input.game.toolchain} · v${input.version}

    ${input.prompt ? `_Prompt:_ ${input.prompt}` : ""}

    ## Features

    ${features.map((f) => `- ${f}`)}

    ## Install

    ${INSTALL[input.game.id].map((s, i) => `${i + 1}. ${s}`)}

    ## Files

    ${files.map((f) => `- \`${f.path}\``)}

    ---
    Forged by Cyrus (${MODEL_NAME[input.model]}).`;
}

function changelog(input: TemplateInput) {
  const lines: string[] = [];
  for (let v = input.version; v >= 1; v--) {
    lines.push(`## v${v}.0.0`);
    lines.push(v === 1 ? "- Initial forge." : v === 2 ? "- Balance pass; numbers moved to config." : "- Tests, docs and polish.");
    lines.push("");
  }
  return `# Changelog\n\n${lines.join("\n")}`;
}

export function buildModFiles(input: TemplateInput): ModFile[] {
  const built =
    input.game.id === "minecraft"
      ? minecraft(input)
      : input.game.id === "skyrim"
        ? skyrim(input)
        : input.game.id === "stardew"
          ? stardew(input)
          : input.game.id === "terraria"
            ? terraria(input)
            : cyberpunk(input);

  const out: ModFile[] = [...built.files];
  if (input.model === "katara") return out.slice(0, 3);

  if (built.config) out.push(built.config);
  if (built.l10n) out.push(built.l10n);
  if (input.model === "yako") out.push(built.test);
  out.push(file("README.md", readme(input, out)));
  if (input.model === "yako" || input.version > 1) out.push(file("CHANGELOG.md", changelog(input)));
  return out;
}

export function buildModNotes(input: TemplateInput): string {
  const n = numbers(input);
  const features = deriveFeatures(input);
  const fxs = effectsFor(input);
  return code`
    # ${input.modName}

    A ${input.category.label.toLowerCase()} mod for ${input.game.name}, built on ${input.game.toolchain}. ${input.category.description}

    ## What it does

    ${features.map((f) => `- ${f}`)}

    ## Install

    ${INSTALL[input.game.id].map((s, i) => `${i + 1}. ${s}`)}

    ## Tuning

    - **Power** \`${n.power}\` — raise for late-game saves, lower for vanilla feel.
    - **Cooldown** \`${n.cooldown}s\` — under 2s gets spammy in multiplayer.
    - **Radius** \`${n.radius}\` — affects ${fxs[0].label.toLowerCase()}.

    ## Known limitations

    - Visual assets are placeholders; drop real textures/models into the asset folder.
    - ${input.game.id === "skyrim" ? "Properties must be filled in the Creation Kit before the scripts do anything." : input.game.id === "cyberpunk" ? "Record IDs assume vanilla TweakDB; other overhauls may conflict." : "Not tested against other mods that touch the same hooks."}

    ## Next ideas

    - Ask Cyrus for a v${input.version + 1} that adds a crafting recipe or a config menu.
    - Try **Yako** for tests and a full changelog.`;
}

