            @Override
            public void tick() {
                super.tick();
                if (this.getWorld().isClient) return;
                if (!enraged && this.getHealth() < this.getMaxHealth() * 0.4F) {
                    // Phase two: faster, angrier, glowing.
                    enraged = true;
                    this.addStatusEffect(new StatusEffectInstance(StatusEffects.SPEED, Integer.MAX_VALUE, 1));
                    this.addStatusEffect(new StatusEffectInstance(StatusEffects.GLOWING, Integer.MAX_VALUE, 0));
                }
                if (--abilityCooldown <= 0) {
                    abilityCooldown = enraged ? ABILITY_TICKS / 2 : ABILITY_TICKS;
                    LivingEntity target = this.getTarget();
                    if (target != null && this.squaredDistanceTo(target) < ${n.radius * n.radius * 4}.0) {
                        this.tryAttack(target);
                    }
                }
            }
        }`,
    );
    register = `FabricDefaultAttributeRegistry.register(${cls.toUpperCase()}, ${cls}Entity.createAttributes());`;
  } else if (arch === "world") {
    main = file(
      `${base}/world/${cls}Feature.java`,
      code`
        package ${pkg}.world;

        import com.mojang.serialization.Codec;
        import net.minecraft.block.BlockState;
        import net.minecraft.block.Blocks;
        import net.minecraft.util.math.BlockPos;
        import net.minecraft.util.math.random.Random;
        import net.minecraft.world.StructureWorldAccess;
        import net.minecraft.world.gen.feature.DefaultFeatureConfig;
        import net.minecraft.world.gen.feature.Feature;
        import net.minecraft.world.gen.feature.util.FeatureContext;

        ${header}
        ${vNote}
        public class ${cls}Feature extends Feature<DefaultFeatureConfig> {
            private static final int RADIUS = ${n.radius + 4};
            private static final int LAYERS = ${n.interval + 3};
            private static final float ORE_CHANCE = ${n.chance}F;

            public ${cls}Feature(Codec<DefaultFeatureConfig> codec) {
                super(codec);
            }

            @Override
            public boolean generate(FeatureContext<DefaultFeatureConfig> ctx) {
                StructureWorldAccess world = ctx.getWorld();
                BlockPos origin = ctx.getOrigin();
                Random random = ctx.getRandom();

                // Carve an inverted cone: wide at the top, tapering into a crystal root.
                for (int layer = 0; layer < LAYERS; layer++) {
                    int r = RADIUS - layer * RADIUS / LAYERS;
                    for (int dx = -r; dx <= r; dx++) {
                        for (int dz = -r; dz <= r; dz++) {
                            if (dx * dx + dz * dz > r * r + random.nextInt(3)) continue;
                            BlockPos pos = origin.add(dx, -layer, dz);
                            world.setBlockState(pos, pick(layer, random), 3);
                        }
                    }
                }
                decorate(world, origin.up(), random);
                return true;
            }

            private BlockState pick(int layer, Random random) {
                if (layer == 0) return Blocks.MOSS_BLOCK.getDefaultState();
                if (random.nextFloat() < ORE_CHANCE) return Blocks.AMETHYST_BLOCK.getDefaultState();
                return layer < 2 ? Blocks.DIRT.getDefaultState() : Blocks.CALCITE.getDefaultState();
            }

            private void decorate(StructureWorldAccess world, BlockPos top, Random random) {
                for (int i = 0; i < RADIUS; i++) {
                    BlockPos p = top.add(random.nextInt(RADIUS) - RADIUS / 2, 0, random.nextInt(RADIUS) - RADIUS / 2);
                    if (world.isAir(p)) world.setBlockState(p, Blocks.GLOW_LICHEN.getDefaultState(), 3);
                }
            }
        }`,
    );
    register = `Registry.register(Registries.FEATURE, id("${snake}"), new ${cls}Feature(DefaultFeatureConfig.CODEC));`;
  } else if (arch === "system") {
    const k = input.category.key;
    const body =
      k === "interface"
        ? code`
            HudRenderCallback.EVENT.register((ctx, tickCounter) -> {
                MinecraftClient client = MinecraftClient.getInstance();
                if (client.player == null || client.options.hudHidden) return;
                int x = client.getWindow().getScaledWidth() - PANEL_WIDTH - 8;
                ctx.fill(x, 8, x + PANEL_WIDTH, 8 + PANEL_HEIGHT, 0x99_120A26);
                ctx.drawBorder(x, 8, PANEL_WIDTH, PANEL_HEIGHT, ACCENT);
                ctx.drawText(client.textRenderer, Text.translatable("hud.${snake}.title"), x + 6, 14, ACCENT, true);
                float hp = client.player.getHealth() / client.player.getMaxHealth();
                ctx.fill(x + 6, 28, x + 6 + (int) ((PANEL_WIDTH - 12) * hp), 32, ACCENT);
            });`
        : k === "audio"
          ? code`
              ServerTickEvents.END_WORLD_TICK.register(world -> {
                  if (world.getTime() % INTERVAL_TICKS != 0) return;
                  for (ServerPlayerEntity player : world.getPlayers()) {
                      // Crossfade layers by time of day and danger nearby.
                      boolean danger = !world.getEntitiesByClass(HostileEntity.class, player.getBoundingBox().expand(16), e -> true).isEmpty();
                      SoundEvent layer = danger ? TENSION : (world.isNight() ? NIGHT : DAY);
                      player.playSoundToPlayer(layer, SoundCategory.MUSIC, 0.8F, 1.0F);
                  }
              });`
          : k === "quests"
            ? code`
                ServerPlayConnectionEvents.JOIN.register((handler, sender, server) -> {
                    ServerPlayerEntity player = handler.getPlayer();
                    QuestState state = QuestState.of(server);
                    if (state.stage(player) == 0) {
                        player.sendMessage(Text.translatable("quest.${snake}.hook").formatted(Formatting.GOLD));
                        state.advance(player);
                    }
                });
                ServerLivingEntityEvents.AFTER_DEATH.register((entity, source) -> {
                    if (source.getAttacker() instanceof ServerPlayerEntity player) {
                        QuestState.of(player.getServer()).progress(player, entity.getType());
                    }
                });`
            : code`
                ServerTickEvents.END_WORLD_TICK.register(world -> {
                    if (world.getTime() % INTERVAL_TICKS != 0) return;
                    for (ServerPlayerEntity player : world.getPlayers()) {
                        apply(world, player);
                    }
                });`;
    const effects = fxs.map((e) => sub(e.java, "player", "player", { WORLD: "world", POWER: "POWER" }));
    main = file(
      `${base}/${cls}System.java`,
      code`
        package ${pkg};

        import net.fabricmc.fabric.api.event.lifecycle.v1.ServerTickEvents;
        ${k === "interface" ? "import net.fabricmc.fabric.api.client.rendering.v1.HudRenderCallback;\nimport net.minecraft.client.MinecraftClient;" : ""}
        ${k === "quests" ? "import net.fabricmc.fabric.api.networking.v1.ServerPlayConnectionEvents;\nimport net.fabricmc.fabric.api.entity.event.v1.ServerLivingEntityEvents;\nimport net.minecraft.util.Formatting;" : ""}
        ${k === "audio" ? "import net.minecraft.entity.mob.HostileEntity;\nimport net.minecraft.sound.SoundCategory;\nimport net.minecraft.sound.SoundEvent;" : ""}
        import net.minecraft.entity.effect.StatusEffectInstance;
        import net.minecraft.entity.effect.StatusEffects;
        import net.minecraft.server.network.ServerPlayerEntity;
        import net.minecraft.server.world.ServerWorld;
        import net.minecraft.text.Text;

        ${header}
        ${vNote}
        public final class ${cls}System {
            public static final float POWER = ${n.power}F;
            public static final int EFFECT_TICKS = ${n.duration * 20};
            private static final int INTERVAL_TICKS = ${n.interval * 20};
            ${k === "interface" ? `private static final int PANEL_WIDTH = 132, PANEL_HEIGHT = 40;\nprivate static final int ACCENT = 0xFF_${n.hue.toString(16).padStart(2, "0").slice(0, 2)}C4FF;` : ""}
            ${k === "audio" ? `private static final SoundEvent DAY = ${cls}Mod.sound("day"), NIGHT = ${cls}Mod.sound("night"), TENSION = ${cls}Mod.sound("tension");` : ""}

            private ${cls}System() {}

            public static void register() {
                ${body}
            }

            static void apply(ServerWorld world, ServerPlayerEntity player) {
                ${effects}
            }
        }`,
    );
    register = `${cls}System.register();`;
  } else {
    const [r, g, b] = fxs[0].tint;
    main = file(
      "shaders/program/composite.fsh",
      code`
        #version 330 compatibility
        // ${input.modName} — composite pass · Forged by Cyrus (${model}) v${input.version}
        ${vNote}

        uniform sampler2D colortex0;
        uniform sampler2D depthtex0;
        uniform float frameTimeCounter;
        uniform float rainStrength;
        uniform int worldTime;
        uniform vec3 skyColor;

        in vec2 texcoord;
        layout(location = 0) out vec4 fragColor;

        const vec3 GRADE_TINT = vec3(${r.toFixed(2)}, ${g.toFixed(2)}, ${b.toFixed(2)});
        const float INTENSITY = ${n.intensity};
        const float BLOOM_RADIUS = ${(n.radius / 3).toFixed(2)};

        float luma(vec3 c) { return dot(c, vec3(0.2126, 0.7152, 0.0722)); }

        vec3 bloom(vec2 uv) {
            vec3 acc = vec3(0.0);
            for (int i = 0; i < 8; i++) {
                float a = float(i) * 0.785398;
                vec2 off = vec2(cos(a), sin(a)) * BLOOM_RADIUS * 0.004;
                vec3 s = texture(colortex0, uv + off).rgb;
                acc += s * smoothstep(0.65, 1.0, luma(s));
            }
            return acc / 8.0;
        }

        void main() {
            vec3 color = texture(colortex0, texcoord).rgb;
            float depth = texture(depthtex0, texcoord).r;

            // Night-weighted tint so the grade breathes with the day cycle.
            float night = smoothstep(12000.0, 13500.0, float(worldTime)) * (1.0 - smoothstep(22500.0, 24000.0, float(worldTime)));
            color = mix(color, color * GRADE_TINT * 1.25, INTENSITY * (0.35 + night * 0.5));

            // Height fog that thickens in the rain.
            float fog = smoothstep(0.92, 1.0, depth) * (0.25 + rainStrength * 0.5);
            color = mix(color, skyColor * GRADE_TINT, fog);

            color += bloom(texcoord) * INTENSITY;

            // Subtle shimmer + vignette.
            color *= 1.0 + 0.015 * sin(frameTimeCounter * 1.7 + texcoord.y * 40.0);
            vec2 v = texcoord - 0.5;
            color *= 1.0 - dot(v, v) * 0.55;

            fragColor = vec4(color, 1.0);
        }`,
    );
    register = "";
  }

  const init = file(
    `${base}/${cls}Mod.java`,
    code`
      package ${pkg};

      import net.fabricmc.api.ModInitializer;
      import net.minecraft.registry.Registries;
      import net.minecraft.registry.Registry;
      import net.minecraft.util.Identifier;
      ${arch === "item" ? "import net.minecraft.item.Item;\nimport net.minecraft.util.Rarity;" : ""}
      import org.slf4j.Logger;
      import org.slf4j.LoggerFactory;

      public class ${cls}Mod implements ModInitializer {
          public static final String MOD_ID = "${snake}";
          public static final Logger LOGGER = LoggerFactory.getLogger(MOD_ID);

          public static Identifier id(String path) {
              return Identifier.of(MOD_ID, path);
          }

          @Override
          public void onInitialize() {
              ${register || "// Shader packs load through Iris; nothing to register server-side."}
              LOGGER.info("${input.modName} v${input.version} forged by Cyrus");
          }
      }`,
  );

  const manifest = file(
    "src/main/resources/fabric.mod.json",
    JSON.stringify(
      {
        schemaVersion: 1,
        id: snake,
        version: `${input.version}.0.0`,
        name: input.modName,
        description: deriveFeatures(input)[0],
        authors: ["Cyrus"],
        license: "MIT",
        environment: "*",
        entrypoints: { main: [`${pkg}.${cls}Mod`] },
        depends: { fabricloader: ">=0.16.0", minecraft: "~1.21", java: ">=21", "fabric-api": "*" },
      },
      null,
      2,
    ) + "\n",
  );

  const lang = file(
    `src/main/resources/assets/${snake}/lang/en_us.json`,
    JSON.stringify({ [`item.${snake}.${snake}`]: input.modName, [`hud.${snake}.title`]: input.modName, [`quest.${snake}.hook`]: `Something stirs: ${input.modName}.` }, null, 2) + "\n",
  );

  const config = file(
    `src/main/resources/config/${snake}.json`,
    JSON.stringify({ power: n.power, effectSeconds: n.duration, cooldownSeconds: n.cooldown, radius: n.radius, enableParticles: true }, null, 2) + "\n",
  );

  const test = file(
    `src/test/java/dev/cyrus/${snake}/${cls}Test.java`,
    code`
      package ${pkg};

      import org.junit.jupiter.api.Test;
      import static org.junit.jupiter.api.Assertions.*;

      class ${cls}Test {
          @Test
          void numbersStayInBalancedRange() {
              assertTrue(${n.power}F > 0 && ${n.power}F < 20F, "power should stay below netherite-sword burst");
              assertTrue(${Math.round(n.cooldown * 20)} >= 20, "cooldown must be at least one second");
          }

          @Test
          void modIdIsNamespaced() {
              assertEquals("${snake}", ${cls}Mod.MOD_ID);
              assertTrue(${cls}Mod.id("x").toString().startsWith("${snake}:"));
          }
      }`,
  );

  const files = input.category.key === "shaders" ? [main, file("shaders/shaders.properties", code`
    # ${input.modName} — Iris/OptiFine properties
    sliders=INTENSITY BLOOM_RADIUS
    screen=INTENSITY BLOOM_RADIUS [Advanced]
    profile.HIGH=INTENSITY:${n.intensity}
    profile.LOW=INTENSITY:${(n.intensity * 0.6).toFixed(2)}
    `)] : [main, init, manifest];
  return { files, config, l10n: input.category.key === "shaders" ? undefined : lang, test };
}

/* ═════════════════════════ Skyrim · Papyrus ═════════════════════════ */

function skyrim(input: TemplateInput) {
  const { cls } = identity(input.modName);
  const n = numbers(input);
  const fxs = effectsFor(input);
  const arch = ARCH[input.category.key];
  const script = `CY_${cls}`;
  const model = MODEL_NAME[input.model];
  const props = [
    "Float Property Power = " + n.power.toFixed(1) + " Auto",
    "Float Property Cooldown = " + n.cooldown.toFixed(1) + " Auto",
    ...fxs.flatMap((e) =>
      e.key === "frost" ? ["Spell Property FrostSlowSpell Auto"]
      : e.key === "fire" ? ["Spell Property FireCloakSpell Auto"]
      : e.key === "storm" ? ["Spell Property ChainLightningSpell Auto"]
      : e.key === "poison" ? ["Spell Property PoisonSpell Auto"]
      : e.key === "summon" ? ["ActorBase Property SummonedEcho Auto"]
      : e.key === "lunar" ? ["GlobalVariable Property GameHour Auto", "EffectShader Property AuroraShader Auto"]
      : [],
    ),
  ];
  const vNote = input.version > 1 ? `; v${input.version}: retuned Power/Cooldown` : "";
  const header = code`
    ; ${input.modName} — ${input.category.label} for Skyrim
    ; Forged by Cyrus · ${model} · v${input.version}
    ${vNote}`;

  let body: string;
  let ext: string;
  if (arch === "item") {
    ext = "ActiveMagicEffect";
    const effects = fxs.map((e) => sub(e.papyrus, "akTarget", "akCaster"));
    body = code`
      Event OnEffectStart(Actor akTarget, Actor akCaster)
          If akTarget == None || akTarget.IsDead()
              Return
          EndIf
          akTarget.DamageActorValue("Health", Power)
          ${effects}
          If akCaster == Game.GetPlayer()
              Debug.Notification("${input.modName} resonates.")
          EndIf
      EndEvent

      Event OnEffectFinish(Actor akTarget, Actor akCaster)
          ; Nothing lingers — keeps saves clean if the mod is removed.
      EndEvent`;
  } else if (arch === "entity") {
    ext = "Actor";
    const effects = fxs.map((e) => sub(e.papyrus, "akAggressor as Actor", "Self"));
    body = code`
      Bool Property Enraged = False Auto Hidden

      Event OnInit()
          SetActorValue("Health", ${n.health}.0)
          SetActorValue("SpeedMult", ${Math.round(n.speed * 300)}.0)
          ${input.category.key === "characters" ? 'SetRelationshipRank(Game.GetPlayer(), 3)\nAddToFaction(CurrentFollowerFaction)' : ""}
      EndEvent

      Event OnHit(ObjectReference akAggressor, Form akSource, Projectile akProjectile, Bool abPowerAttack, Bool abSneakAttack, Bool abBashAttack, Bool abHitBlocked)
          If !Enraged && GetActorValuePercentage("Health") < 0.4
              Enraged = True
              ModActorValue("SpeedMult", 25.0)
              Debug.Notification(GetDisplayName() + " is enraged!")
          EndIf
          If akAggressor as Actor && Utility.RandomFloat() < ${n.chance}
              ${effects}
          EndIf
      EndEvent

      Event OnCombatStateChanged(Actor akTarget, Int aeCombatState)
          If aeCombatState == 1
              RegisterForSingleUpdate(Cooldown)
          Else
              UnregisterForUpdate()
          EndIf
      EndEvent

      Event OnUpdate()
          Actor target = GetCombatTarget()
          If target
              target.DamageActorValue("Health", Power * 0.5)
              RegisterForSingleUpdate(Cooldown)
          EndIf
      EndEvent`;
  } else {
    ext = "Quest";
    const stageLines =
      input.category.key === "quests"
        ? ["SetObjectiveDisplayed(10)", 'Debug.Notification("New quest: ' + input.modName + '")']
        : input.category.key === "shaders"
          ? ["ImageSpaceModifier.Apply(" + n.intensity.toFixed(2) + ")"]
          : ["Debug.Trace(\"[" + script + "] online\")"];
    body = code`
      ${input.category.key === "shaders" ? "ImageSpaceModifier Property ImageSpaceModifier Auto" : ""}
      Float Property TickSeconds = ${n.interval}.0 Auto

      Event OnInit()
          ${stageLines}
          RegisterForSingleUpdate(TickSeconds)
      EndEvent

      Event OnUpdate()
          Actor player = Game.GetPlayer()
          ${input.category.key === "quests" ? "If GetStage() < 50 && player.GetCurrentLocation().HasKeyword(DungeonKeyword)\n    SetStage(GetStage() + 10)\n    SetObjectiveCompleted(GetStage())\nEndIf" : ""}
          ${input.category.key === "shaders" ? "Float hour = GameHour.GetValue()\nImageSpaceModifier.Remove()\nImageSpaceModifier.Apply(" + n.intensity.toFixed(2) + " * (hour > 19.0 || hour < 6.0) as Float)" : ""}
          ${fxs.map((e) => sub(e.papyrus, "player", "player"))}
          RegisterForSingleUpdate(TickSeconds)
      EndEvent

      Function Shutdown()
          UnregisterForUpdate()
          Stop()
      EndFunction`;
  }

  const main = file(
    `Scripts/Source/${script}.psc`,
    code`
      Scriptname ${script} extends ${ext}
      {${input.modName} — ${deriveFeatures(input)[0]}}
      ${header}

      ${props}
      ${input.category.key === "quests" ? "Keyword Property DungeonKeyword Auto" : ""}
      ${input.category.key === "shaders" ? "GlobalVariable Property GameHour Auto" : ""}
      ${input.category.key === "characters" ? "Faction Property CurrentFollowerFaction Auto" : ""}

      ${body}`,
  );

  const formId = (i: number) => `0x${(0x000d62 + i * 7 + (hashStr(cls) % 900)).toString(16).toUpperCase().padStart(6, "0")}`;
  const records = file(
    `${script}.esp.manifest.json`,
    JSON.stringify(
      {
        plugin: `${cls}.esp`,
        author: "Cyrus",
        masters: ["Skyrim.esm", "Update.esm"],
        records: [
          { type: arch === "entity" ? "NPC_" : arch === "item" ? (input.category.key === "weapons" ? "WEAP" : "SPEL") : "QUST", editorId: `CY_${cls}`, formId: formId(0) },
          { type: "MGEF", editorId: `CY_${cls}Effect`, formId: formId(1), script },
          ...fxs.map((e, i) => ({ type: "SPEL", editorId: `CY_${cls}_${e.key}`, formId: formId(2 + i) })),
        ],
      },
      null,
      2,
    ) + "\n",
  );

  const info = file(
    "fomod/info.xml",
    code`
      <?xml version="1.0" encoding="UTF-8"?>
      <fomod>
          <Name>${input.modName}</Name>
          <Author>Cyrus</Author>
          <Version>${input.version}.0</Version>
          <Description>${deriveFeatures(input).join(". ")}.</Description>
          <Groups>
              <element>${input.category.label}</element>
          </Groups>
      </fomod>`,
  );

  const moduleConfig = file(
    "fomod/ModuleConfig.xml",
    code`
      <?xml version="1.0" encoding="UTF-8"?>
      <config xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance">
          <moduleName>${input.modName}</moduleName>
          <installSteps order="Explicit">
              <installStep name="Main">
                  <optionalFileGroups order="Explicit">
                      <group name="Intensity" type="SelectExactlyOne">
                          <plugins order="Explicit">
                              <plugin name="Balanced">
                                  <description>Numbers tuned against vanilla Legendary difficulty.</description>
                                  <files><file source="${cls}.esp" destination="${cls}.esp" /></files>
                                  <typeDescriptor><type name="Recommended" /></typeDescriptor>
                              </plugin>
                          </plugins>
                      </group>
                  </optionalFileGroups>
              </installStep>
          </installSteps>
      </config>`,
  );

  const config = file(
    "MCM/config/" + script + "/settings.ini.json",
    JSON.stringify({ Power: n.power, Cooldown: n.cooldown, ProcChance: n.chance, ShowNotifications: true }, null, 2) + "\n",
  );

  const test = file(
    `Scripts/Source/${script}_Test.psc`,
    code`
      Scriptname ${script}_Test extends Quest
      { Smoke tests — run with "startquest ${script}_Test" in the console. }

      Event OnInit()
          Int failures = 0
          If ${n.power} <= 0.0 || ${n.power} > 20.0
              Debug.Trace("[${script}_Test] Power out of range")
              failures += 1
          EndIf
          If ${n.cooldown} < 1.0
              Debug.Trace("[${script}_Test] Cooldown too short")
              failures += 1
          EndIf
          Debug.Notification("${script} tests: " + failures + " failure(s)")
          Stop()
      EndEvent`,
  );

  return { files: [main, records, info], config, l10n: input.model === "yako" ? moduleConfig : undefined, test };
}

/* ═════════════════════════ Stardew Valley · SMAPI · C# ═════════════════════════ */

function stardew(input: TemplateInput) {
  const { cls, snake } = identity(input.modName);
  const n = numbers(input);
  const fxs = effectsFor(input);
  const k = input.category.key;
  const model = MODEL_NAME[input.model];
  const hasConfig = input.model !== "katara";
  const effects = fxs.map((e) => e.sv);
  const vNote = input.version > 1 ? `// v${input.version}: retuned values${hasConfig ? ", moved them into ModConfig" : ""}` : "";

  const hooks =
    k === "interface"
      ? code`
          helper.Events.Display.RenderedHud += this.OnRenderedHud;`
      : k === "shaders"
        ? code`
            helper.Events.Display.RenderedWorld += this.OnRenderedWorld;`
        : k === "characters" || k === "items" || k === "worlds" || k === "quests"
          ? code`
              helper.Events.Content.AssetRequested += this.OnAssetRequested;
              helper.Events.GameLoop.DayStarted += this.OnDayStarted;`
          : code`
              helper.Events.GameLoop.DayStarted += this.OnDayStarted;
              helper.Events.GameLoop.OneSecondUpdateTicked += this.OnSecondTicked;
              helper.Events.Input.ButtonPressed += this.OnButtonPressed;`;

  const methods: string[] = [];
  if (k === "interface") {
    methods.push(code`
      private void OnRenderedHud(object? sender, RenderedHudEventArgs e)
      {
          if (!Context.IsWorldReady || Game1.eventUp) return;
          var b = e.SpriteBatch;
          var area = new Rectangle(Game1.uiViewport.Width - 236, 96, 220, 92);
          IClickableMenu.drawTextureBox(b, area.X, area.Y, area.Width, area.Height, Color.White);
          b.DrawString(Game1.smallFont, this.Helper.Translation.Get("hud.title"), new Vector2(area.X + 20, area.Y + 18), Game1.textColor);
          int friends = Game1.player.friendshipData.Values.Count(f => f.Points >= 2000);
          b.DrawString(Game1.smallFont, $"{friends} close friends · day {Game1.dayOfMonth}", new Vector2(area.X + 20, area.Y + 50), Game1.textShadowColor);
      }`);
  } else if (k === "shaders") {
    methods.push(code`
      private void OnRenderedWorld(object? sender, RenderedWorldEventArgs e)
      {
          if (!Context.IsWorldReady) return;
          float night = Utility.Clamp((Game1.timeOfDay - 1800) / 600f, 0f, 1f);
          var tint = new Color(${Math.round(fxs[0].tint[0] * 255)}, ${Math.round(fxs[0].tint[1] * 255)}, ${Math.round(fxs[0].tint[2] * 255)}) * (${n.intensity}f * 0.25f * (0.4f + night));
          e.SpriteBatch.Draw(Game1.staminaRect, new Rectangle(0, 0, Game1.viewport.Width, Game1.viewport.Height), tint);
      }`);
  } else if (k === "characters" || k === "items" || k === "worlds" || k === "quests") {
    const asset = k === "characters" ? "Data/Characters" : k === "items" ? "Data/Objects" : k === "worlds" ? "Data/Locations" : "Data/Quests";
    methods.push(code`
      private void OnAssetRequested(object? sender, AssetRequestedEventArgs e)
      {
          if (!e.NameWithoutLocale.IsEquivalentTo("${asset}")) return;
          e.Edit(asset =>
          {
              ${
                k === "items"
                  ? `var data = asset.AsDictionary<string, ObjectData>().Data;\ndata["Cyrus.${cls}"] = new ObjectData\n{\n    Name = "${cls}",\n    DisplayName = this.Helper.Translation.Get("item.name"),\n    Description = this.Helper.Translation.Get("item.description"),\n    Type = "Basic",\n    Category = -26,\n    Price = ${Math.round(n.power * 60)}\n};`
                  : k === "characters"
                    ? `var data = asset.AsDictionary<string, CharacterData>().Data;\ndata["${cls}"] = new CharacterData\n{\n    DisplayName = "${input.modName.split(" ").slice(-1)[0]}",\n    BirthSeason = Season.Fall,\n    BirthDay = ${(hashStr(cls) % 27) + 1},\n    HomeRegion = "Town",\n    CanBeRomanced = true\n};`
                    : k === "quests"
                      ? `var data = asset.AsDictionary<string, string>().Data;\ndata["${(hashStr(cls) % 9000) + 1000}"] = "Basic/${input.modName}/${this_desc(input)}/Talk to the wizard at night./null/-1/${Math.round(n.power * 100)}/-1/true";`
                      : `var data = asset.AsDictionary<string, LocationData>().Data;\ndata["Cyrus_${cls}"] = new LocationData { DisplayName = "${input.modName}", CanPlantHere = true };`
              }
          });
      }`);
    methods.push(code`
      private void OnDayStarted(object? sender, DayStartedEventArgs e)
      {
          ${effects}
      }`);
  } else {
    methods.push(code`
      private void OnDayStarted(object? sender, DayStartedEventArgs e)
      {
          this.cooldown = 0;
          ${k === "mechanics" ? "this.HarvestReadyCrops(Game1.getFarm());" : ""}
      }

      private void OnSecondTicked(object? sender, OneSecondUpdateTickedEventArgs e)
      {
          if (!Context.IsWorldReady || this.cooldown-- > 0) return;
          ${k === "audio" ? 'Game1.changeMusicTrack(Game1.timeOfDay >= 2000 ? "Cyrus.' + cls + '.Night" : "Cyrus.' + cls + '.Day");' : ""}
          ${k === "vehicles" ? "if (Game1.player.mount is not null) Game1.player.mount.addedSpeed = " + Math.round(n.speed * 10) + ";" : ""}
          ${k === "creatures" ? "if (Game1.random.NextDouble() < " + n.chance + ") Game1.currentLocation.addCritter(new Butterfly(Game1.currentLocation, Game1.player.Tile + new Vector2(2, -1)));" : ""}
      }

      private void OnButtonPressed(object? sender, ButtonPressedEventArgs e)
      {
          if (!Context.IsPlayerFree || e.Button != ${hasConfig ? "this.Config.AbilityKey" : "SButton.G"}) return;
          ${effects}
          this.cooldown = ${hasConfig ? "this.Config.CooldownSeconds" : Math.round(n.cooldown)};
          Game1.playSound("wand");
      }`);
    if (k === "mechanics")
      methods.push(code`
        private void HarvestReadyCrops(GameLocation location)
        {
            int harvested = 0;
            foreach (var pair in location.terrainFeatures.Pairs.ToList())
            {
                if (pair.Value is HoeDirt { crop: { } crop } dirt && crop.currentPhase.Value >= crop.phaseDays.Count - 1 && !crop.dead.Value)
                {
                    if (crop.harvest((int)pair.Key.X, (int)pair.Key.Y, dirt)) harvested++;
                }
            }
            if (harvested > 0) Game1.addHUDMessage(new HUDMessage($"{harvested} crops harvested", HUDMessage.achievement_type));
        }`);
  }

  const main = file(
    `${cls}/ModEntry.cs`,
    code`
      using System.Linq;
      using Microsoft.Xna.Framework;
      using StardewModdingAPI;
      using StardewModdingAPI.Events;
      using StardewValley;
      using StardewValley.Buffs;
      using StardewValley.BellsAndWhistles;
      using StardewValley.GameData.Characters;
      using StardewValley.GameData.Locations;
      using StardewValley.GameData.Objects;
      using StardewValley.Menus;
      using StardewValley.TerrainFeatures;

      namespace Cyrus.${cls}
      {
          /// <summary>${input.modName} — forged by Cyrus (${model}) v${input.version}.</summary>
          ${vNote}
          internal sealed class ModEntry : Mod
          {
              private const int EffectMillis = ${n.duration * 1000};
              private const float Power = ${n.power}f;
              ${hasConfig ? "private ModConfig Config = new();" : ""}
              private int cooldown;

              public override void Entry(IModHelper helper)
              {
                  ${hasConfig ? "this.Config = helper.ReadConfig<ModConfig>();" : ""}
                  ${hooks}
                  this.Monitor.Log("${input.modName} ready.", LogLevel.Info);
              }

              ${methods.join("\n\n")}
          }
      }`,
  );

  const manifest = file(
    `${cls}/manifest.json`,
    JSON.stringify(
      {
        Name: input.modName,
        Author: "Cyrus",
        Version: `${input.version}.0.0`,
        Description: deriveFeatures(input)[0],
        UniqueID: `Cyrus.${cls}`,
        EntryDll: `${cls}.dll`,
        MinimumApiVersion: "4.0.0",
        UpdateKeys: [],
      },
      null,
      2,
    ) + "\n",
  );

  const config = file(
    `${cls}/ModConfig.cs`,
    code`
      using StardewModdingAPI;

      namespace Cyrus.${cls}
      {
          internal sealed class ModConfig
          {
              public SButton AbilityKey { get; set; } = SButton.G;
              public int CooldownSeconds { get; set; } = ${Math.round(n.cooldown)};
              public float Power { get; set; } = ${n.power}f;
              public bool ShowHudMessages { get; set; } = true;
          }
      }`,
  );

  const l10n = file(
    `${cls}/i18n/default.json`,
    JSON.stringify({ "hud.title": input.modName, "item.name": input.modName, "item.description": deriveFeatures(input)[0] }, null, 2) + "\n",
  );

  const test = file(
    `${cls}.Tests/ModConfigTests.cs`,
    code`
      using Cyrus.${cls};
      using NUnit.Framework;

      namespace Cyrus.${cls}.Tests
      {
          public class ModConfigTests
          {
              [Test]
              public void DefaultsAreBalanced()
              {
                  var config = new ModConfig();
                  Assert.That(config.CooldownSeconds, Is.GreaterThanOrEqualTo(1));
                  Assert.That(config.Power, Is.InRange(1f, 20f));
              }
          }
      }`,
  );

  return { files: [main, manifest], config: hasConfig ? config : undefined, l10n, test, configCs: true, snake };
}

function this_desc(input: TemplateInput) {
  return input.prompt ? input.prompt.replace(/[/"]/g, " ").slice(0, 80) : `Investigate ${input.modName}.`;
}

/* ═════════════════════════ Terraria · tModLoader · C# ═════════════════════════ */

function terraria(input: TemplateInput) {
  const { cls } = identity(input.modName);
  const n = numbers(input);
  const fxs = effectsFor(input);
  const k = input.category.key;
  const arch = ARCH[k];
  const model = MODEL_NAME[input.model];
  const ns = `${cls}Mod`;
  const vNote = input.version > 1 ? `// v${input.version}: retuned damage and cooldowns` : "";
  const folder = { item: "Items", entity: k === "vehicles" ? "Mounts" : "NPCs", world: "Systems", system: k === "audio" ? "Music" : "Systems", visual: "Effects" }[arch];

  let main: ModFile;
  if (arch === "item") {
    const effects = fxs.map((e) => sub(e.tml, "target", "player", { SOURCE_SRC: "player.GetSource_OnHit(target)", Power: "Item.damage", EffectTicks: String(n.duration * 60) }));
    const magic = k === "magic";
    main = file(
      `Content/Items/${cls}.cs`,
      code`
        using Microsoft.Xna.Framework;
        using Terraria;
        using Terraria.DataStructures;
        using Terraria.ID;
        using Terraria.ModLoader;

        namespace ${ns}.Content.Items
        {
            /// <summary>${input.modName} — forged by Cyrus (${model}) v${input.version}.</summary>
            ${vNote}
            public class ${cls} : ModItem
            {
                public override void SetDefaults()
                {
                    Item.width = 40;
                    Item.height = 40;
                    Item.damage = ${Math.round(n.power * 6)};
                    Item.DamageType = DamageClass.${magic ? "Magic" : k === "items" ? "Generic" : "Melee"};
                    Item.useTime = ${Math.round(n.cooldown * 6)};
                    Item.useAnimation = ${Math.round(n.cooldown * 6)};
                    Item.useStyle = ItemUseStyleID.${magic ? "Shoot" : "Swing"};
                    Item.knockBack = ${(n.power / 2).toFixed(1)}f;
                    Item.value = Item.sellPrice(gold: ${Math.round(n.power)});
                    Item.rare = ItemRarityID.${n.power > 10 ? "Red" : "Pink"};
                    Item.UseSound = SoundID.${magic ? "Item20" : "Item1"};
                    Item.autoReuse = true;
                    ${magic ? `Item.mana = ${Math.round(n.power)};\nItem.shoot = ProjectileID.${fxs[0].key === "frost" ? "FrostBoltStaff" : fxs[0].key === "fire" ? "BallofFire" : "AmethystBolt"};\nItem.shootSpeed = 11f;` : ""}
                }

                public override void OnHitNPC(Player player, NPC target, NPC.HitInfo hit, int damageDone)
                {
                    ${effects}
                    for (int i = 0; i < 12; i++)
                    {
                        Dust.NewDust(target.position, target.width, target.height, DustID.${fxs[0].key === "frost" ? "IceTorch" : fxs[0].key === "fire" ? "Torch" : "PurpleTorch"}, 0f, -2f);
                    }
                }

                public override void AddRecipes()
                {
                    CreateRecipe()
                        .AddIngredient(ItemID.${magic ? "SpellTome" : "HallowedBar"}, ${Math.round(n.radius + 4)})
                        .AddIngredient(ItemID.SoulofMight, ${Math.round(n.interval + 2)})
                        .AddTile(TileID.MythrilAnvil)
                        .Register();
                }
            }
        }`,
    );
  } else if (arch === "entity" && k !== "vehicles") {
    const boss = k === "creatures";
    const effects = fxs.map((e) => sub(e.tml, "target", "NPC", { SOURCE_SRC: "NPC.GetSource_FromAI()", Power: "NPC.damage", EffectTicks: String(n.duration * 60) }));
    main = file(
      `Content/NPCs/${cls}.cs`,
      code`
        using Microsoft.Xna.Framework;
        using Terraria;
        using Terraria.ID;
        using Terraria.ModLoader;

        namespace ${ns}.Content.NPCs
        {
            /// <summary>${input.modName} — forged by Cyrus (${model}) v${input.version}.</summary>
            ${vNote}
            ${boss ? "[AutoloadBossHead]" : ""}
            public class ${cls} : ModNPC
            {
                private enum Phase { Stalk, Dash, Frenzy }
                private Phase CurrentPhase
                {
                    get => (Phase)NPC.ai[0];
                    set => NPC.ai[0] = (float)value;
                }
                private ref float Timer => ref NPC.ai[1];

                public override void SetDefaults()
                {
                    NPC.width = 72;
                    NPC.height = 72;
                    NPC.lifeMax = ${n.health * (boss ? 40 : 2)};
                    NPC.damage = ${Math.round(n.power * 5)};
                    NPC.defense = ${Math.round(n.power * 2)};
                    NPC.knockBackResist = ${boss ? "0f" : "0.4f"};
                    NPC.noGravity = true;
                    NPC.noTileCollide = ${boss ? "true" : "false"};
                    NPC.value = Item.buyPrice(gold: ${Math.round(n.xp / 4)});
                    ${boss ? "NPC.boss = true;\nMusic = MusicID.Boss3;" : k === "characters" ? "NPC.townNPC = true;\nNPC.friendly = true;" : ""}
                }

                public override void AI()
                {
                    NPC.TargetClosest();
                    Player target = Main.player[NPC.target];
                    Timer++;
                    if (NPC.life < NPC.lifeMax * 0.4f && CurrentPhase != Phase.Frenzy)
                    {
                        CurrentPhase = Phase.Frenzy;
                        ${fxs.some((e) => e.key === "summon") ? `for (int i = 0; i < 3; i++) NPC.NewNPC(NPC.GetSource_FromAI(), (int)NPC.Center.X, (int)NPC.Center.Y, Type);` : "SoundEngine.PlaySound(SoundID.Roar, NPC.Center);"}
                    }

                    switch (CurrentPhase)
                    {
                        case Phase.Stalk:
                            NPC.velocity = Vector2.Lerp(NPC.velocity, NPC.DirectionTo(target.Center) * ${(n.speed * 16).toFixed(1)}f, 0.05f);
                            if (Timer > ${Math.round(n.cooldown * 60)}) { CurrentPhase = Phase.Dash; Timer = 0; }
                            break;
                        case Phase.Dash:
                            if (Timer == 1) NPC.velocity = NPC.DirectionTo(target.Center) * ${(n.speed * 40).toFixed(1)}f;
                            NPC.velocity *= 0.97f;
                            if (Timer > 50) { CurrentPhase = Phase.Stalk; Timer = 0; }
                            break;
                        case Phase.Frenzy:
                            NPC.velocity = Vector2.Lerp(NPC.velocity, NPC.DirectionTo(target.Center) * ${(n.speed * 26).toFixed(1)}f, 0.09f);
                            break;
                    }
                    Lighting.AddLight(NPC.Center, ${fxs[0].tint.map((c) => c.toFixed(2) + "f").join(", ")});
                }

                public override void OnHitPlayer(Player target, Player.HurtInfo hurtInfo)
                {
                    ${effects}
                }
            }
        }`,
    );
  } else if (k === "vehicles") {
    main = file(
      `Content/Mounts/${cls}.cs`,
      code`
        using Terraria;
        using Terraria.ID;
        using Terraria.ModLoader;

        namespace ${ns}.Content.Mounts
        {
            /// <summary>${input.modName} — forged by Cyrus (${model}) v${input.version}.</summary>
            ${vNote}
            public class ${cls} : ModMount
            {
                public override void SetStaticDefaults()
                {
                    MountData.runSpeed = ${(n.speed * 40).toFixed(1)}f;
                    MountData.dashSpeed = ${(n.speed * 55).toFixed(1)}f;
                    MountData.acceleration = 0.35f;
                    MountData.flightTimeMax = ${fxs.some((e) => e.key === "flight") ? 320 : 0};
                    MountData.jumpHeight = 12;
                    MountData.fallDamage = 0f;
                    MountData.buff = ModContent.BuffType<${cls}Buff>();
                    MountData.spawnDust = DustID.Electric;
                    MountData.totalFrames = 4;
                    MountData.playerYOffsets = Enumerable.Repeat(22, MountData.totalFrames).ToArray();
                }

                public override void UpdateEffects(Player player)
                {
                    // Drift boost: holding down while moving converts speed into a short burst.
                    if (player.controlDown && System.Math.Abs(player.velocity.X) > 4f)
                    {
                        player.velocity.X *= 1.04f;
                        Dust.NewDust(player.Bottom, 8, 4, DustID.Electric);
                    }
                    Lighting.AddLight(player.Center, ${fxs[0].tint.map((c) => c.toFixed(2) + "f").join(", ")});
                }
            }
        }`,
    );
  } else if (arch === "visual") {
    main = file(
      `Content/Effects/${cls}System.cs`,
      code`
        using Terraria;
        using Terraria.Graphics.Effects;
        using Terraria.Graphics.Shaders;
        using Terraria.ModLoader;

        namespace ${ns}.Content.Effects
        {
            /// <summary>${input.modName} — screen shader. Forged by Cyrus (${model}) v${input.version}.</summary>
            public class ${cls}System : ModSystem
            {
                private const string Key = "${ns}:${cls}";
                private const float Intensity = ${n.intensity}f;

                public override void Load()
                {
                    if (Main.dedServ) return;
                    var shader = new Ref<Effect>(Mod.Assets.Request<Effect>("Assets/Effects/${cls}", AssetRequestMode.ImmediateLoad).Value);
                    Filters.Scene[Key] = new Filter(new ScreenShaderData(shader, "GradePass"), EffectPriority.Medium);
                    Filters.Scene[Key].GetShader().UseColor(${fxs[0].tint.map((c) => c.toFixed(2) + "f").join(", ")}).UseIntensity(Intensity);
                }

                public override void PostUpdateEverything()
                {
                    if (Main.dedServ) return;
                    bool wanted = !Main.dayTime || Main.raining;
                    if (wanted && !Filters.Scene[Key].IsActive()) Filters.Scene.Activate(Key);
                    else if (!wanted && Filters.Scene[Key].IsActive()) Filters.Scene.Deactivate(Key);
                }
            }
        }`,
    );
  } else {
    const isAudio = k === "audio";
    main = file(
      `Content/${folder}/${cls}${isAudio ? "Scene" : "System"}.cs`,
      code`
        using Terraria;
        using Terraria.ModLoader;
        using Terraria.WorldBuilding;
        using System.Collections.Generic;

        namespace ${ns}.Content.${folder}
        {
            /// <summary>${input.modName} — forged by Cyrus (${model}) v${input.version}.</summary>
            ${vNote}
            ${
              isAudio
                ? code`
                  public class ${cls}Scene : ModSceneEffect
                  {
                      public override int Music => Main.dayTime
                          ? MusicLoader.GetMusicSlot(Mod, "Assets/Music/${cls}Day")
                          : MusicLoader.GetMusicSlot(Mod, "Assets/Music/${cls}Night");

                      public override SceneEffectPriority Priority => SceneEffectPriority.BiomeMedium;

                      // Layer in the boss mix whenever a boss is alive.
                      public override bool IsSceneEffectActive(Player player) => player.ZoneOverworldHeight || Main.CurrentFrameFlags.AnyActiveBossNPC;
                  }`
                : k === "worlds"
                  ? code`
                    public class ${cls}System : ModSystem
                    {
                        public override void ModifyWorldGenTasks(List<GenPass> tasks, ref double totalWeight)
                        {
                            int index = tasks.FindIndex(t => t.Name.Equals("Shinies"));
                            if (index == -1) return;
                            tasks.Insert(index + 1, new PassLegacy("${input.modName}", (progress, config) =>
                            {
                                progress.Message = "Forging ${input.modName}";
                                for (int i = 0; i < Main.maxTilesX / ${n.interval * 40}; i++)
                                {
                                    int x = WorldGen.genRand.Next(100, Main.maxTilesX - 100);
                                    int y = WorldGen.genRand.Next((int)GenVars.rockLayer, Main.maxTilesY - 300);
                                    WorldGen.TileRunner(x, y, ${n.radius + 4}, ${n.radius + 8}, TileID.Amethyst);
                                }
                            }));
                        }
                    }`
                  : code`
                    public class ${cls}System : ModPlayer
                    {
                        private int cooldown;

                        public override void PostUpdate()
                        {
                            if (cooldown > 0) { cooldown--; return; }
                            ${fxs.map((e) => sub(e.tml, "Player", "Player", { SOURCE_SRC: "Player.GetSource_FromThis()", Power: String(Math.round(n.power * 5)), EffectTicks: String(n.duration * 60) }))}
                            cooldown = ${n.interval * 60};
                        }
                    }`
            }
        }`,
    );
  }

  const modFile = file(
    `${ns}.cs`,
    code`
      using Terraria.ModLoader;

      namespace ${ns}
      {
          public class ${ns} : Mod
          {
          }
      }`,
  );
  const build = file("build.txt", code`
    displayName = ${input.modName}
    author = Cyrus
    version = ${input.version}.0
    homepage =
    hideCode = false
    `);
  const description = file("description.txt", `${input.modName}\n\n${deriveFeatures(input).map((f) => `- ${f}`).join("\n")}\n\nForged by Cyrus.\n`);
  const config = file(
    `Common/${cls}Config.cs`,
    code`
      using System.ComponentModel;
      using Terraria.ModLoader.Config;

      namespace ${ns}.Common
      {
          public class ${cls}Config : ModConfig
          {
              public override ConfigScope Mode => ConfigScope.ServerSide;

              [DefaultValue(${n.power}f)]
              [Range(1f, 20f)]
              public float Power;

              [DefaultValue(${Math.round(n.cooldown)})]
              public int CooldownSeconds;
          }
      }`,
  );
  const test = file(
    `Tests/${cls}Tests.cs`,
    code`
      using NUnit.Framework;

      namespace ${ns}.Tests
      {
          public class ${cls}Tests
          {
              [Test]
              public void CooldownIsHumane() => Assert.That(${Math.round(n.cooldown * 6)}, Is.GreaterThan(4));

              [Test]
              public void DamageIsBelowEndgameCap() => Assert.That(${Math.round(n.power * 6)}, Is.LessThan(150));
          }
      }`,
  );
  return { files: [main, modFile, build], config, l10n: description, test };
}

/* ═════════════════════════ Cyberpunk 2077 · CET · Lua ═════════════════════════ */

function cyberpunk(input: TemplateInput) {
  const { cls, snake } = identity(input.modName);
  const n = numbers(input);
  const fxs = effectsFor(input);
  const k = input.category.key;
  const model = MODEL_NAME[input.model];
  const effects = fxs.map((e) => sub(e.lua, "target", "player", { Power: "Config.power" }));
  const vNote = input.version > 1 ? `-- v${input.version}: retuned values, smoother cooldowns` : "";

  const drawBlock =
    k === "interface"
      ? code`
          registerForEvent("onDraw", function()
              if not state.visible then return end
              ImGui.SetNextWindowPos(24, 220, ImGuiCond.FirstUseEver)
              ImGui.PushStyleColor(ImGuiCol.WindowBg, 0.04, 0.02, 0.09, 0.72)
              ImGui.PushStyleColor(ImGuiCol.Border, 1.0, 0.25, 0.8, 0.9)
              if ImGui.Begin("${input.modName}", ImGuiWindowFlags.NoTitleBar + ImGuiWindowFlags.AlwaysAutoResize) then
                  local ram = ${snake}.ram(player)
                  ImGui.Text(string.format("RAM  %d / %d", ram.current, ram.max))
                  ImGui.ProgressBar(ram.current / math.max(ram.max, 1), 220, 8, "")
                  for _, hack in ipairs(${snake}.cooldowns(player)) do
                      ImGui.Text(string.format("%-14s %4.1fs", hack.name, hack.remaining))
                  end
              end
              ImGui.End()
              ImGui.PopStyleColor(2)
          end)`
      : code`
          registerForEvent("onDraw", function()
              if not state.overlay then return end
              if ImGui.Begin("${input.modName}") then
                  Config.power = ImGui.SliderFloat("Power", Config.power, 1, 20)
                  Config.cooldown = ImGui.SliderFloat("Cooldown", Config.cooldown, 0.5, 15)
              end
              ImGui.End()
          end)`;

  const updateBody =
    k === "vehicles"
      ? code`
          local vehicle = Game.GetMountedVehicle(player)
          if vehicle and ${snake}.isOwned(vehicle) then
              ${snake}.applyHandling(vehicle, Config)
          end`
      : k === "worlds"
        ? code`
            if not state.spawned and ${snake}.nearAnchor(player, Config.radius * 40) then
                ${snake}.spawnProps(Config)
                state.spawned = true
            end`
        : k === "shaders"
          ? code`
              local weather = Game.GetWeatherSystem():GetWeatherState().name.value
              ${snake}.applyGrade(weather, Config.intensity)`
          : k === "audio"
            ? code`
                local combat = player:IsInCombat()
                if combat ~= state.combat then
                    state.combat = combat
                    Game.GetAudioSystem():Play(combat and "cyrus_${snake}_combat" or "cyrus_${snake}_cruise")
                end`
            : code`
                local target = Game.GetTargetingSystem():GetLookAtObject(player, false, false)
                if target and target:IsNPC() and ${snake}.ready(state, Config.cooldown) then
                    ${effects}
                    state.lastFire = os.clock()
                end`;

  const main = file(
    "init.lua",
    code`
      -- ${input.modName} — ${input.category.label} for Cyberpunk 2077 (Cyber Engine Tweaks)
      -- Forged by Cyrus · ${model} · v${input.version}
      ${vNote}

      local ${snake} = require("modules/${snake}")
      local Config = ${snake}.loadConfig()

      local state = {
          visible = true,
          overlay = false,
          lastFire = 0,
          spawned = false,
          combat = false,
      }

      registerForEvent("onInit", function()
          ${k === "weapons" || k === "items" ? `TweakDB:SetFlat("Items.Preset_${cls}.damagePerHit", ${(n.power * 9).toFixed(1)})\nTweakDB:SetFlat("Items.Preset_${cls}.cycleTime", ${(n.cooldown / 10).toFixed(2)})` : ""}
          Observe("PlayerPuppet", "OnAction", function(self, action)
              if ListenerAction.GetName(action).value == "${snake}_toggle" and ListenerAction.IsButtonJustPressed(action) then
                  state.visible = not state.visible
              end
          end)
          print("[${input.modName}] online — v${input.version}")
      end)

      registerForEvent("onUpdate", function(delta)
          local player = Game.GetPlayer()
          if not player then return end
          ${updateBody}
      end)

      registerForEvent("onOverlayOpen", function() state.overlay = true end)
      registerForEvent("onOverlayClose", function()
          state.overlay = false
          ${snake}.saveConfig(Config)
      end)

      ${drawBlock}

      registerInput("${snake}_toggle", "Toggle ${input.modName}", function(down)
          if down then state.visible = not state.visible end
      end)

      return ${snake}`,
  );

  const module = file(
    `modules/${snake}.lua`,
    code`
      -- ${input.modName} helpers
      local M = {}

      local DEFAULTS = {
          power = ${n.power},
          cooldown = ${n.cooldown},
          radius = ${n.radius},
          intensity = ${n.intensity},
      }

      function M.loadConfig()
          local f = io.open("config.json", "r")
          if not f then return DEFAULTS end
          local ok, data = pcall(json.decode, f:read("*a"))
          f:close()
          if not ok or type(data) ~= "table" then return DEFAULTS end
          for k, v in pairs(DEFAULTS) do
              if data[k] == nil then data[k] = v end
          end
          return data
      end

      function M.saveConfig(config)
          local f = io.open("config.json", "w")
          if f then
              f:write(json.encode(config))
              f:close()
          end
      end

      function M.ready(state, cooldown)
          return os.clock() - state.lastFire >= cooldown
      end

      function M.ram(player)
          local pools = Game.GetStatPoolsSystem()
          local id = player:GetEntityID()
          return {
              current = math.floor(pools:GetStatPoolValue(id, gamedataStatPoolType.Memory, false)),
              max = math.floor(Game.GetStatsSystem():GetStatValue(id, gamedataStatType.Memory)),
          }
      end

      function M.cooldowns(player)
          return {
              { name = "Short Circuit", remaining = 0 },
              { name = "Overheat", remaining = ${n.cooldown} },
          }
      end

      function M.isOwned(vehicle)
          return vehicle:GetRecord():GetID().value:find("${snake}") ~= nil
      end

      function M.applyHandling(vehicle, config)
          vehicle:GetVehicleComponent():SetSpeedMultiplier(1 + config.power / 40)
      end

      function M.applyGrade(weather, intensity)
          local wet = weather:find("rain") ~= nil
          GameOptions.SetFloat("Rendering", "LUTIntensity", intensity * (wet and 1.15 or 0.9))
      end

      function M.nearAnchor(player, range)
          local p = player:GetWorldPosition()
          return Vector4.Distance(p, Vector4.new(-1350, 1200, 25, 1)) < range
      end

      function M.spawnProps(config)
          for i = 1, config.radius do
              local angle = (i / config.radius) * math.pi * 2
              local pos = Vector4.new(-1350 + math.cos(angle) * 12, 1200 + math.sin(angle) * 12, 25, 1)
              exEntitySpawner.Spawn("base\\\\environment\\\\neon_sign_${snake}.ent", WorldTransform.new(pos, EulerAngles.new(0, 0, 0)))
          end
      end

      return M`,
  );

  const config = file("config.json", JSON.stringify({ power: n.power, cooldown: n.cooldown, radius: n.radius, intensity: n.intensity }, null, 2) + "\n");

  const shader =
    k === "shaders"
      ? file(
          `reshade/${snake}.fx`,
          code`
            // ${input.modName} — ReShade grade · Forged by Cyrus v${input.version}
            uniform float Intensity < ui_type = "slider"; ui_min = 0.0; ui_max = 2.0; > = ${n.intensity};
            uniform float Timer < source = "timer"; >;
            texture BackBufferTex : COLOR;
            sampler BackBuffer { Texture = BackBufferTex; };

            float3 Grade(float3 c)
            {
                float l = dot(c, float3(0.2126, 0.7152, 0.0722));
                float3 teal = float3(0.0, 0.55, 0.6);
                float3 magenta = float3(0.95, 0.2, 0.75);
                return lerp(c, lerp(teal, magenta, l) * (l + 0.3), 0.35 * Intensity);
            }

            float4 PS_Grade(float4 pos : SV_Position, float2 uv : TEXCOORD) : SV_Target
            {
                float3 c = tex2D(BackBuffer, uv).rgb;
                c = Grade(c);
                c += frac(sin(dot(uv * Timer, float2(12.9898, 78.233))) * 43758.5453) * 0.03;
                return float4(c, 1.0);
            }

            technique ${cls} { pass { VertexShader = PostProcessVS; PixelShader = PS_Grade; } }`,
        )
      : undefined;

  const test = file(
    `tests/${snake}_spec.lua`,
    code`
      -- busted spec for ${input.modName}
      package.path = "./?.lua;" .. package.path
      _G.json = { decode = function() return {} end, encode = function() return "{}" end }
      local M = require("modules/${snake}")

      describe("${input.modName}", function()
          it("fills missing config with defaults", function()
              local cfg = M.loadConfig()
              assert.is_true(cfg.power > 0)
              assert.is_true(cfg.cooldown >= 0.5)
          end)

          it("respects the cooldown", function()
              local state = { lastFire = os.clock() }
              assert.is_false(M.ready(state, 60))
          end)
      end)`,
  );

  return { files: shader ? [main, shader, module] : [main, module], config, l10n: undefined as ModFile | undefined, test };
}

/* ═════════════════════════ assembly ═════════════════════════ */

const INSTALL: Record<Game["id"], string[]> = {
  minecraft: ["Install Fabric Loader 0.16+ and Fabric API for 1.21.", "Build with `./gradlew build`.", "Drop the jar from `build/libs` into `.minecraft/mods`."],
  skyrim: ["Compile the `.psc` scripts with the Creation Kit (or Papyrus Compiler).", "Pack with the generated FOMOD folder.", "Install through Mod Organizer 2 or Vortex and enable the plugin."],
  stardew: ["Install SMAPI 4.0+.", "Build the project with `dotnet build` (ModBuildConfig deploys it).", "Launch the game through SMAPI."],
  terraria: ["Open tModLoader → Workshop → Develop Mods.", "Place this folder in `ModSources` and click **Build + Reload**.", "Enable the mod in the Mods menu."],
  cyberpunk: ["Install Cyber Engine Tweaks 1.32+.", "Copy this folder to `bin/x64/plugins/cyber_engine_tweaks/mods/`.", "Bind the toggle key in the CET overlay → Bindings."],
};

function readme(input: TemplateInput, files: ModFile[]) {
  const features = deriveFeatures(input);
  return code`
    # ${input.modName}

    > ${input.category.label} mod for **${input.game.name}** · ${input.game.toolchain} · v${input.version}

    ${input.prompt ? `_Prompt:_ ${input.prompt}` : ""}

    ## Features

    ${features.map((f) => `- ${f}`)}

    ## Install

    ${INSTALL[input.game.id].map((s, i) => `${i + 1}. ${s}`)}

    ## Files

    ${files.map((f) => `- \`${f.path}\``)}

    ---
    Forged by Cyrus (${MODEL_NAME[input.model]}).`;
}

function changelog(input: TemplateInput) {
  const lines: string[] = [];
  for (let v = input.version; v >= 1; v--) {
    lines.push(`## v${v}.0.0`);
    lines.push(v === 1 ? "- Initial forge." : v === 2 ? "- Balance pass; numbers moved to config." : "- Tests, docs and polish.");
    lines.push("");
  }
  return `# Changelog\n\n${lines.join("\n")}`;
}

export function buildModFiles(input: TemplateInput): ModFile[] {
  const built =
    input.game.id === "minecraft"
      ? minecraft(input)
      : input.game.id === "skyrim"
        ? skyrim(input)
        : input.game.id === "stardew"
          ? stardew(input)
          : input.game.id === "terraria"
            ? terraria(input)
            : cyberpunk(input);

  const out: ModFile[] = [...built.files];
  if (input.model === "katara") return out.slice(0, 3);

  if (built.config) out.push(built.config);
  if (built.l10n) out.push(built.l10n);
  if (input.model === "yako") out.push(built.test);
  out.push(file("README.md", readme(input, out)));
  if (input.model === "yako" || input.version > 1) out.push(file("CHANGELOG.md", changelog(input)));
  return out;
}

export function buildModNotes(input: TemplateInput): string {
  const n = numbers(input);
  const features = deriveFeatures(input);
  const fxs = effectsFor(input);
  return code`
    # ${input.modName}

    A ${input.category.label.toLowerCase()} mod for ${input.game.name}, built on ${input.game.toolchain}. ${input.category.description}

    ## What it does

    ${features.map((f) => `- ${f}`)}

    ## Install

    ${INSTALL[input.game.id].map((s, i) => `${i + 1}. ${s}`)}

    ## Tuning

    - **Power** \`${n.power}\` — raise for late-game saves, lower for vanilla feel.
    - **Cooldown** \`${n.cooldown}s\` — under 2s gets spammy in multiplayer.
    - **Radius** \`${n.radius}\` — affects ${fxs[0].label.toLowerCase()}.

    ## Known limitations

    - Visual assets are placeholders; drop real textures/models into the asset folder.
    - ${input.game.id === "skyrim" ? "Properties must be filled in the Creation Kit before the scripts do anything." : input.game.id === "cyberpunk" ? "Record IDs assume vanilla TweakDB; other overhauls may conflict." : "Not tested against other mods that touch the same hooks."}

    ## Next ideas

    - Ask Cyrus for a v${input.version + 1} that adds a crafting recipe or a config menu.
    - Try **Yako** for tests and a full changelog.`;
}

// Keep the fence constant referenced so markdown helpers stay available to future templates.
void FENCE;

