                  for (ServerPlayerEntity player : world.getPlayers()) {
                      // Crossfade layers by time of day and danger nearby.
                      boolean danger = !world.getEntitiesByClass(HostileEntity.class, player.getBoundingBox().expand(16), e -> true).isEmpty();
                      SoundEvent layer = danger ? TENSION : (world.isNight() ? NIGHT : DAY);
                      player.playSoundToPlayer(layer, SoundCategory.MUSIC, 0.8F, 1.0F);
                  }
              });`
          : k === "quests"
            ? code`
                ServerPlayConnectionEvents.JOIN.register((handler, sender, server) -> {
                    ServerPlayerEntity player = handler.getPlayer();
                    QuestState state = QuestState.of(server);
                    if (state.stage(player) == 0) {
                        player.sendMessage(Text.translatable("quest.${snake}.hook").formatted(Formatting.GOLD));
                        state.advance(player);
                    }
                });
                ServerLivingEntityEvents.AFTER_DEATH.register((entity, source) -> {
                    if (source.getAttacker() instanceof ServerPlayerEntity player) {
                        QuestState.of(player.getServer()).progress(player, entity.getType());
                    }
                });`
            : code`
                ServerTickEvents.END_WORLD_TICK.register(world -> {
                    if (world.getTime() % INTERVAL_TICKS != 0) return;
                    for (ServerPlayerEntity player : world.getPlayers()) {
                        apply(world, player);
                    }
                });`;
    const effects = fxs.map((e) => sub(e.java, "player", "player", { WORLD: "world", POWER: "POWER" }));
    main = file(
      `${base}/${cls}System.java`,
      code`
        package ${pkg};

        import net.fabricmc.fabric.api.event.lifecycle.v1.ServerTickEvents;
        ${k === "interface" ? "import net.fabricmc.fabric.api.client.rendering.v1.HudRenderCallback;\nimport net.minecraft.client.MinecraftClient;" : ""}
        ${k === "quests" ? "import net.fabricmc.fabric.api.networking.v1.ServerPlayConnectionEvents;\nimport net.fabricmc.fabric.api.entity.event.v1.ServerLivingEntityEvents;\nimport net.minecraft.util.Formatting;" : ""}
        ${k === "audio" ? "import net.minecraft.entity.mob.HostileEntity;\nimport net.minecraft.sound.SoundCategory;\nimport net.minecraft.sound.SoundEvent;" : ""}
        import net.minecraft.entity.effect.StatusEffectInstance;
        import net.minecraft.entity.effect.StatusEffects;
        import net.minecraft.server.network.ServerPlayerEntity;
        import net.minecraft.server.world.ServerWorld;
        import net.minecraft.text.Text;

        ${header}
        ${vNote}
        public final class ${cls}System {
            public static final float POWER = ${n.power}F;
            public static final int EFFECT_TICKS = ${n.duration * 20};
            private static final int INTERVAL_TICKS = ${n.interval * 20};
            ${k === "interface" ? `private static final int PANEL_WIDTH = 132, PANEL_HEIGHT = 40;\nprivate static final int ACCENT = 0xFF_${n.hue.toString(16).padStart(2, "0").slice(0, 2)}C4FF;` : ""}
            ${k === "audio" ? `private static final SoundEvent DAY = ${cls}Mod.sound("day"), NIGHT = ${cls}Mod.sound("night"), TENSION = ${cls}Mod.sound("tension");` : ""}

            private ${cls}System() {}

            public static void register() {
                ${body}
            }

            static void apply(ServerWorld world, ServerPlayerEntity player) {
                ${effects}
            }
        }`,
    );
    register = `${cls}System.register();`;
  } else {
    const [r, g, b] = fxs[0].tint;
    main = file(
      "shaders/program/composite.fsh",
      code`
        #version 330 compatibility
        // ${input.modName} — composite pass · Forged by Cyrus (${model}) v${input.version}
        ${vNote}

        uniform sampler2D colortex0;
        uniform sampler2D depthtex0;
        uniform float frameTimeCounter;
        uniform float rainStrength;
        uniform int worldTime;
        uniform vec3 skyColor;

        in vec2 texcoord;
        layout(location = 0) out vec4 fragColor;

        const vec3 GRADE_TINT = vec3(${r.toFixed(2)}, ${g.toFixed(2)}, ${b.toFixed(2)});
        const float INTENSITY = ${n.intensity};
        const float BLOOM_RADIUS = ${(n.radius / 3).toFixed(2)};

        float luma(vec3 c) { return dot(c, vec3(0.2126, 0.7152, 0.0722)); }

        vec3 bloom(vec2 uv) {
            vec3 acc = vec3(0.0);
            for (int i = 0; i < 8; i++) {
                float a = float(i) * 0.785398;
                vec2 off = vec2(cos(a), sin(a)) * BLOOM_RADIUS * 0.004;
                vec3 s = texture(colortex0, uv + off).rgb;
                acc += s * smoothstep(0.65, 1.0, luma(s));
            }
            return acc / 8.0;
        }

        void main() {
            vec3 color = texture(colortex0, texcoord).rgb;
            float depth = texture(depthtex0, texcoord).r;

            // Night-weighted tint so the grade breathes with the day cycle.
            float night = smoothstep(12000.0, 13500.0, float(worldTime)) * (1.0 - smoothstep(22500.0, 24000.0, float(worldTime)));
            color = mix(color, color * GRADE_TINT * 1.25, INTENSITY * (0.35 + night * 0.5));

            // Height fog that thickens in the rain.
            float fog = smoothstep(0.92, 1.0, depth) * (0.25 + rainStrength * 0.5);
            color = mix(color, skyColor * GRADE_TINT, fog);

            color += bloom(texcoord) * INTENSITY;

            // Subtle shimmer + vignette.
            color *= 1.0 + 0.015 * sin(frameTimeCounter * 1.7 + texcoord.y * 40.0);
            vec2 v = texcoord - 0.5;
            color *= 1.0 - dot(v, v) * 0.55;

            fragColor = vec4(color, 1.0);
        }`,
    );
    register = "";
  }

  const init = file(
    `${base}/${cls}Mod.java`,
    code`
      package ${pkg};

      import net.fabricmc.api.ModInitializer;
      import net.minecraft.registry.Registries;
      import net.minecraft.registry.Registry;
      import net.minecraft.util.Identifier;
      ${arch === "item" ? "import net.minecraft.item.Item;\nimport net.minecraft.util.Rarity;" : ""}
      import org.slf4j.Logger;
      import org.slf4j.LoggerFactory;

      public class ${cls}Mod implements ModInitializer {
          public static final String MOD_ID = "${snake}";
          public static final Logger LOGGER = LoggerFactory.getLogger(MOD_ID);

          public static Identifier id(String path) {
              return Identifier.of(MOD_ID, path);
          }

          @Override
          public void onInitialize() {
              ${register || "// Shader packs load through Iris; nothing to register server-side."}
              LOGGER.info("${input.modName} v${input.version} forged by Cyrus");
          }
      }`,
  );

  const manifest = file(
    "src/main/resources/fabric.mod.json",
    JSON.stringify(
      {
        schemaVersion: 1,
        id: snake,
        version: `${input.version}.0.0`,
        name: input.modName,
        description: deriveFeatures(input)[0],
        authors: ["Cyrus"],
        license: "MIT",
        environment: "*",
        entrypoints: { main: [`${pkg}.${cls}Mod`] },
        depends: { fabricloader: ">=0.16.0", minecraft: "~1.21", java: ">=21", "fabric-api": "*" },
      },
      null,
      2,
    ) + "\n",
  );

  const lang = file(
    `src/main/resources/assets/${snake}/lang/en_us.json`,
    JSON.stringify({ [`item.${snake}.${snake}`]: input.modName, [`hud.${snake}.title`]: input.modName, [`quest.${snake}.hook`]: `Something stirs: ${input.modName}.` }, null, 2) + "\n",
  );

  const config = file(
    `src/main/resources/config/${snake}.json`,
    JSON.stringify({ power: n.power, effectSeconds: n.duration, cooldownSeconds: n.cooldown, radius: n.radius, enableParticles: true }, null, 2) + "\n",
  );

  const test = file(
    `src/test/java/dev/cyrus/${snake}/${cls}Test.java`,
    code`
      package ${pkg};

      import org.junit.jupiter.api.Test;
      import static org.junit.jupiter.api.Assertions.*;

      class ${cls}Test {
          @Test
          void numbersStayInBalancedRange() {
              assertTrue(${n.power}F > 0 && ${n.power}F < 20F, "power should stay below netherite-sword burst");
              assertTrue(${Math.round(n.cooldown * 20)} >= 20, "cooldown must be at least one second");
          }

          @Test
          void modIdIsNamespaced() {
              assertEquals("${snake}", ${cls}Mod.MOD_ID);
              assertTrue(${cls}Mod.id("x").toString().startsWith("${snake}:"));
          }
      }`,
  );

  const files = input.category.key === "shaders" ? [main, file("shaders/shaders.properties", code`
    # ${input.modName} — Iris/OptiFine properties
    sliders=INTENSITY BLOOM_RADIUS
    screen=INTENSITY BLOOM_RADIUS [Advanced]
    profile.HIGH=INTENSITY:${n.intensity}
    profile.LOW=INTENSITY:${(n.intensity * 0.6).toFixed(2)}
    `)] : [main, init, manifest];
  return { files, config, l10n: input.category.key === "shaders" ? undefined : lang, test };
}

/* ═════════════════════════ Skyrim · Papyrus ═════════════════════════ */

function skyrim(input: TemplateInput) {
  const { cls } = identity(input.modName);
  const n = numbers(input);
  const fxs = effectsFor(input);
  const arch = ARCH[input.category.key];
  const script = `CY_${cls}`;
  const model = MODEL_NAME[input.model];
  const props = [
    "Float Property Power = " + n.power.toFixed(1) + " Auto",
    "Float Property Cooldown = " + n.cooldown.toFixed(1) + " Auto",
    ...fxs.flatMap((e) =>
      e.key === "frost" ? ["Spell Property FrostSlowSpell Auto"]
      : e.key === "fire" ? ["Spell Property FireCloakSpell Auto"]
      : e.key === "storm" ? ["Spell Property ChainLightningSpell Auto"]
      : e.key === "poison" ? ["Spell Property PoisonSpell Auto"]
      : e.key === "summon" ? ["ActorBase Property SummonedEcho Auto"]
      : e.key === "lunar" ? ["GlobalVariable Property GameHour Auto", "EffectShader Property AuroraShader Auto"]
      : [],
    ),
  ];
  const vNote = input.version > 1 ? `; v${input.version}: retuned Power/Cooldown` : "";
  const header = code`
    ; ${input.modName} — ${input.category.label} for Skyrim
    ; Forged by Cyrus · ${model} · v${input.version}
    ${vNote}`;

  let body: string;
  let ext: string;
  if (arch === "item") {
    ext = "ActiveMagicEffect";
    const effects = fxs.map((e) => sub(e.papyrus, "akTarget", "akCaster"));
    body = code`
      Event OnEffectStart(Actor akTarget, Actor akCaster)
          If akTarget == None || akTarget.IsDead()
              Return
          EndIf
          akTarget.DamageActorValue("Health", Power)
          ${effects}
          If akCaster == Game.GetPlayer()
              Debug.Notification("${input.modName} resonates.")
          EndIf
      EndEvent

      Event OnEffectFinish(Actor akTarget, Actor akCaster)
          ; Nothing lingers — keeps saves clean if the mod is removed.
      EndEvent`;
  } else if (arch === "entity") {
    ext = "Actor";
    const effects = fxs.map((e) => sub(e.papyrus, "akAggressor as Actor", "Self"));
    body = code`
      Bool Property Enraged = False Auto Hidden

      Event OnInit()
          SetActorValue("Health", ${n.health}.0)
          SetActorValue("SpeedMult", ${Math.round(n.speed * 300)}.0)
          ${input.category.key === "characters" ? 'SetRelationshipRank(Game.GetPlayer(), 3)\nAddToFaction(CurrentFollowerFaction)' : ""}
      EndEvent

      Event OnHit(ObjectReference akAggressor, Form akSource, Projectile akProjectile, Bool abPowerAttack, Bool abSneakAttack, Bool abBashAttack, Bool abHitBlocked)
          If !Enraged && GetActorValuePercentage("Health") < 0.4
              Enraged = True
              ModActorValue("SpeedMult", 25.0)
              Debug.Notification(GetDisplayName() + " is enraged!")
          EndIf
          If akAggressor as Actor && Utility.RandomFloat() < ${n.chance}
              ${effects}
          EndIf
      EndEvent

      Event OnCombatStateChanged(Actor akTarget, Int aeCombatState)
          If aeCombatState == 1
              RegisterForSingleUpdate(Cooldown)
          Else
              UnregisterForUpdate()
          EndIf
      EndEvent

      Event OnUpdate()
          Actor target = GetCombatTarget()
          If target
              target.DamageActorValue("Health", Power * 0.5)
              RegisterForSingleUpdate(Cooldown)
          EndIf
      EndEvent`;
  } else {
    ext = "Quest";
    const stageLines =
      input.category.key === "quests"
        ? ["SetObjectiveDisplayed(10)", 'Debug.Notification("New quest: ' + input.modName + '")']
        : input.category.key === "shaders"
          ? ["ImageSpaceModifier.Apply(" + n.intensity.toFixed(2) + ")"]
          : ["Debug.Trace(\"[" + script + "] online\")"];
    body = code`
      ${input.category.key === "shaders" ? "ImageSpaceModifier Property ImageSpaceModifier Auto" : ""}
      Float Property TickSeconds = ${n.interval}.0 Auto

      Event OnInit()
          ${stageLines}
          RegisterForSingleUpdate(TickSeconds)
      EndEvent

      Event OnUpdate()
          Actor player = Game.GetPlayer()
          ${input.category.key === "quests" ? "If GetStage() < 50 && player.GetCurrentLocation().HasKeyword(DungeonKeyword)\n    SetStage(GetStage() + 10)\n    SetObjectiveCompleted(GetStage())\nEndIf" : ""}
          ${input.category.key === "shaders" ? "Float hour = GameHour.GetValue()\nImageSpaceModifier.Remove()\nImageSpaceModifier.Apply(" + n.intensity.toFixed(2) + " * (hour > 19.0 || hour < 6.0) as Float)" : ""}
          ${fxs.map((e) => sub(e.papyrus, "player", "player"))}
          RegisterForSingleUpdate(TickSeconds)
      EndEvent

      Function Shutdown()
          UnregisterForUpdate()
          Stop()
      EndFunction`;
  }

  const main = file(
    `Scripts/Source/${script}.psc`,
    code`
      Scriptname ${script} extends ${ext}
      {${input.modName} — ${deriveFeatures(input)[0]}}
      ${header}

      ${props}
      ${input.category.key === "quests" ? "Keyword Property DungeonKeyword Auto" : ""}
      ${input.category.key === "shaders" ? "GlobalVariable Property GameHour Auto" : ""}
      ${input.category.key === "characters" ? "Faction Property CurrentFollowerFaction Auto" : ""}

      ${body}`,
  );

  const formId = (i: number) => `0x${(0x000d62 + i * 7 + (hashStr(cls) % 900)).toString(16).toUpperCase().padStart(6, "0")}`;
  const records = file(
    `${script}.esp.manifest.json`,
    JSON.stringify(
      {
        plugin: `${cls}.esp`,
        author: "Cyrus",
        masters: ["Skyrim.esm", "Update.esm"],
        records: [
          { type: arch === "entity" ? "NPC_" : arch === "item" ? (input.category.key === "weapons" ? "WEAP" : "SPEL") : "QUST", editorId: `CY_${cls}`, formId: formId(0) },
          { type: "MGEF", editorId: `CY_${cls}Effect`, formId: formId(1), script },
          ...fxs.map((e, i) => ({ type: "SPEL", editorId: `CY_${cls}_${e.key}`, formId: formId(2 + i) })),
        ],
      },
      null,
      2,
    ) + "\n",
  );

  const info = file(
    "fomod/info.xml",
    code`
      <?xml version="1.0" encoding="UTF-8"?>
      <fomod>
          <Name>${input.modName}</Name>
          <Author>Cyrus</Author>
          <Version>${input.version}.0</Version>
          <Description>${deriveFeatures(input).join(". ")}.</Description>
          <Groups>
              <element>${input.category.label}</element>
          </Groups>
      </fomod>`,
  );

  const moduleConfig = file(
    "fomod/ModuleConfig.xml",
    code`
      <?xml version="1.0" encoding="UTF-8"?>
      <config xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance">
          <moduleName>${input.modName}</moduleName>
          <installSteps order="Explicit">
              <installStep name="Main">
                  <optionalFileGroups order="Explicit">
                      <group name="Intensity" type="SelectExactlyOne">
                          <plugins order="Explicit">
                              <plugin name="Balanced">
                                  <description>Numbers tuned against vanilla Legendary difficulty.</description>
                                  <files><file source="${cls}.esp" destination="${cls}.esp" /></files>
                                  <typeDescriptor><type name="Recommended" /></typeDescriptor>
                              </plugin>
                          </plugins>
                      </group>
                  </optionalFileGroups>
              </installStep>
          </installSteps>
      </config>`,
  );

  const config = file(
    "MCM/config/" + script + "/settings.ini.json",
    JSON.stringify({ Power: n.power, Cooldown: n.cooldown, ProcChance: n.chance, ShowNotifications: true }, null, 2) + "\n",
  );

  const test = file(
    `Scripts/Source/${script}_Test.psc`,
    code`
      Scriptname ${script}_Test extends Quest
      { Smoke tests — run with "startquest ${script}_Test" in the console. }

      Event OnInit()
          Int failures = 0
          If ${n.power} <= 0.0 || ${n.power} > 20.0
              Debug.Trace("[${script}_Test] Power out of range")
              failures += 1
          EndIf
          If ${n.cooldown} < 1.0
              Debug.Trace("[${script}_Test] Cooldown too short")
              failures += 1
          EndIf
          Debug.Notification("${script} tests: " + failures + " failure(s)")
          Stop()
      EndEvent`,
  );

  return { files: [main, records, info], config, l10n: input.model === "yako" ? moduleConfig : undefined, test };
}

/* ═════════════════════════ Stardew Valley · SMAPI · C# ═════════════════════════ */

function stardew(input: TemplateInput) {
  const { cls, snake } = identity(input.modName);
  const n = numbers(input);
  const fxs = effectsFor(input);
  const k = input.category.key;
  const model = MODEL_NAME[input.model];
  const hasConfig = input.model !== "katara";
  const effects = fxs.map((e) => e.sv);
  const vNote = input.version > 1 ? `// v${input.version}: retuned values${hasConfig ? ", moved them into ModConfig" : ""}` : "";

  const hooks =
    k === "interface"
      ? code`
          helper.Events.Display.RenderedHud += this.OnRenderedHud;`
      : k === "shaders"
        ? code`
            helper.Events.Display.RenderedWorld += this.OnRenderedWorld;`
        : k === "characters" || k === "items" || k === "worlds" || k === "quests"
          ? code`
              helper.Events.Content.AssetRequested += this.OnAssetRequested;
              helper.Events.GameLoop.DayStarted += this.OnDayStarted;`
          : code`
              helper.Events.GameLoop.DayStarted += this.OnDayStarted;
              helper.Events.GameLoop.OneSecondUpdateTicked += this.OnSecondTicked;
              helper.Events.Input.ButtonPressed += this.OnButtonPressed;`;

  const methods: string[] = [];
  if (k === "interface") {
    methods.push(code`
      private void OnRenderedHud(object? sender, RenderedHudEventArgs e)
      {
          if (!Context.IsWorldReady || Game1.eventUp) return;
          var b = e.SpriteBatch;
          var area = new Rectangle(Game1.uiViewport.Width - 236, 96, 220, 92);
          IClickableMenu.drawTextureBox(b, area.X, area.Y, area.Width, area.Height, Color.White);
          b.DrawString(Game1.smallFont, this.Helper.Translation.Get("hud.title"), new Vector2(area.X + 20, area.Y + 18), Game1.textColor);
          int friends = Game1.player.friendshipData.Values.Count(f => f.Points >= 2000);
          b.DrawString(Game1.smallFont, $"{friends} close friends · day {Game1.dayOfMonth}", new Vector2(area.X + 20, area.Y + 50), Game1.textShadowColor);
      }`);
  } else if (k === "shaders") {
    methods.push(code`
      private void OnRenderedWorld(object? sender, RenderedWorldEventArgs e)
      {
          if (!Context.IsWorldReady) return;
          float night = Utility.Clamp((Game1.timeOfDay - 1800) / 600f, 0f, 1f);
          var tint = new Color(${Math.round(fxs[0].tint[0] * 255)}, ${Math.round(fxs[0].tint[1] * 255)}, ${Math.round(fxs[0].tint[2] * 255)}) * (${n.intensity}f * 0.25f * (0.4f + night));
          e.SpriteBatch.Draw(Game1.staminaRect, new Rectangle(0, 0, Game1.viewport.Width, Game1.viewport.Height), tint);
      }`);
  } else if (k === "characters" || k === "items" || k === "worlds" || k === "quests") {
    const asset = k === "characters" ? "Data/Characters" : k === "items" ? "Data/Objects" : k === "worlds" ? "Data/Locations" : "Data/Quests";
    methods.push(code`
      private void OnAssetRequested(object? sender, AssetRequestedEventArgs e)
      {
          if (!e.NameWithoutLocale.IsEquivalentTo("${asset}")) return;
          e.Edit(asset =>
          {
              ${
                k === "items"
                  ? `var data = asset.AsDictionary<string, ObjectData>().Data;\ndata["Cyrus.${cls}"] = new ObjectData\n{\n    Name = "${cls}",\n    DisplayName = this.Helper.Translation.Get("item.name"),\n    Description = this.Helper.Translation.Get("item.description"),\n    Type = "Basic",\n    Category = -26,\n    Price = ${Math.round(n.power * 60)}\n};`
                  : k === "characters"
                    ? `var data = asset.AsDictionary<string, CharacterData>().Data;\ndata["${cls}"] = new CharacterData\n{\n    DisplayName = "${input.modName.split(" ").slice(-1)[0]}",\n    BirthSeason = Season.Fall,\n    BirthDay = ${(hashStr(cls) % 27) + 1},\n    HomeRegion = "Town",\n    CanBeRomanced = true\n};`
                    : k === "quests"
                      ? `var data = asset.AsDictionary<string, string>().Data;\ndata["${(hashStr(cls) % 9000) + 1000}"] = "Basic/${input.modName}/${this_desc(input)}/Talk to the wizard at night./null/-1/${Math.round(n.power * 100)}/-1/true";`
                      : `var data = asset.AsDictionary<string, LocationData>().Data;\ndata["Cyrus_${cls}"] = new LocationData { DisplayName = "${input.modName}", CanPlantHere = true };`
              }
          });
      }`);
    methods.push(code`
      private void OnDayStarted(object? sender, DayStartedEventArgs e)
      {
          ${effects}
      }`);
  } else {
    methods.push(code`
      private void OnDayStarted(object? sender, DayStartedEventArgs e)
      {
          this.cooldown = 0;
          ${k === "mechanics" ? "this.HarvestReadyCrops(Game1.getFarm());" : ""}
      }

      private void OnSecondTicked(object? sender, OneSecondUpdateTickedEventArgs e)
      {
          if (!Context.IsWorldReady || this.cooldown-- > 0) return;
          ${k === "audio" ? 'Game1.changeMusicTrack(Game1.timeOfDay >= 2000 ? "Cyrus.' + cls + '.Night" : "Cyrus.' + cls + '.Day");' : ""}
          ${k === "vehicles" ? "if (Game1.player.mount is not null) Game1.player.mount.addedSpeed = " + Math.round(n.speed * 10) + ";" : ""}
          ${k === "creatures" ? "if (Game1.random.NextDouble() < " + n.chance + ") Game1.currentLocation.addCritter(new Butterfly(Game1.currentLocation, Game1.player.Tile + new Vector2(2, -1)));" : ""}
      }

      private void OnButtonPressed(object? sender, ButtonPressedEventArgs e)
      {
          if (!Context.IsPlayerFree || e.Button != ${hasConfig ? "this.Config.AbilityKey" : "SButton.G"}) return;
          ${effects}
          this.cooldown = ${hasConfig ? "this.Config.CooldownSeconds" : Math.round(n.cooldown)};
          Game1.playSound("wand");
      }`);
    if (k === "mechanics")
      methods.push(code`
        private void HarvestReadyCrops(GameLocation location)
        {
            int harvested = 0;
            foreach (var pair in location.terrainFeatures.Pairs.ToList())
            {
                if (pair.Value is HoeDirt { crop: { } crop } dirt && crop.currentPhase.Value >= crop.phaseDays.Count - 1 && !crop.dead.Value)
                {
                    if (crop.harvest((int)pair.Key.X, (int)pair.Key.Y, dirt)) harvested++;
                }
            }
            if (harvested > 0) Game1.addHUDMessage(new HUDMessage($"{harvested} crops harvested", HUDMessage.achievement_type));
        }`);
  }

  const main = file(
    `${cls}/ModEntry.cs`,
    code`
      using System.Linq;
      using Microsoft.Xna.Framework;
      using StardewModdingAPI;
      using StardewModdingAPI.Events;
      using StardewValley;
      using StardewValley.Buffs;
      using StardewValley.BellsAndWhistles;
      using StardewValley.GameData.Characters;
      using StardewValley.GameData.Locations;
      using StardewValley.GameData.Objects;
      using StardewValley.Menus;
      using StardewValley.TerrainFeatures;

      namespace Cyrus.${cls}
      {
          /// <summary>${input.modName} — forged by Cyrus (${model}) v${input.version}.</summary>
          ${vNote}
          internal sealed class ModEntry : Mod
          {
              private const int EffectMillis = ${n.duration * 1000};
              private const float Power = ${n.power}f;
              ${hasConfig ? "private ModConfig Config = new();" : ""}
              private int cooldown;

              public override void Entry(IModHelper helper)
              {
                  ${hasConfig ? "this.Config = helper.ReadConfig<ModConfig>();" : ""}
                  ${hooks}
                  this.Monitor.Log("${input.modName} ready.", LogLevel.Info);
              }

              ${methods.join("\n\n")}
          }
      }`,
  );

  const manifest = file(
    `${cls}/manifest.json`,
    JSON.stringify(
      {
        Name: input.modName,
        Author: "Cyrus",
        Version: `${input.version}.0.0`,
        Description: deriveFeatures(input)[0],
        UniqueID: `Cyrus.${cls}`,
        EntryDll: `${cls}.dll`,
        MinimumApiVersion: "4.0.0",
        UpdateKeys: [],
      },
      null,
      2,
    ) + "\n",
  );

  const config = file(
    `${cls}/ModConfig.cs`,
    code`
      using StardewModdingAPI;

      namespace Cyrus.${cls}
      {
          internal sealed class ModConfig
          {
              public SButton AbilityKey { get; set; } = SButton.G;
              public int CooldownSeconds { get; set; } = ${Math.round(n.cooldown)};
              public float Power { get; set; } = ${n.power}f;
              public bool ShowHudMessages { get; set; } = true;
          }
      }`,
  );

  const l10n = file(
    `${cls}/i18n/default.json`,
    JSON.stringify({ "hud.title": input.modName, "item.name": input.modName, "item.description": deriveFeatures(input)[0] }, null, 2) + "\n",
  );

  const test = file(
    `${cls}.Tests/ModConfigTests.cs`,
    code`
      using Cyrus.${cls};
      using NUnit.Framework;

      namespace Cyrus.${cls}.Tests
      {
          public class ModConfigTests
          {
              [Test]
              public void DefaultsAreBalanced()
              {
                  var config = new ModConfig();
                  Assert.That(config.CooldownSeconds, Is.GreaterThanOrEqualTo(1));
                  Assert.That(config.Power, Is.InRange(1f, 20f));
              }
          }
      }`,
  );

  return { files: [main, manifest], config: hasConfig ? config : undefined, l10n, test, configCs: true, snake };
}

function this_desc(input: TemplateInput) {
