s=open(p,encoding='utf-8').read()
def rep(old,new):
    global s
    assert old in s, "MISSING "+old[:80]
    s=s.replace(old,new,1)

rep('''            st.target.x = n.rx * 0.5;
            st.target.y = n.ry * 0.5;''','''            st.target.x = (n.x ?? 0) * 0.5;
            st.target.y = (n.y ?? 0) * 0.5;''')
rep('''            st.target.x = n.rx;
            st.target.y = n.ry;''','''            st.target.x = n.x ?? 0;
            st.target.y = n.y ?? 0;''')

rep('''    flashTimers: new Map<string, number>(),
  });''','''    flashTimers: new Map<string, number>(),
    worldTransform: "",
    coreVars: "",
    spinEls: [] as { el: HTMLElement; idx: number; base: string; mult: number }[],
  });''')

# core: rotate elements directly; only write --e/--p/--f when they change
rep('''      const core = coreRef.current;
      if (core) {
        core.style.setProperty("--e", e.toFixed(3));
        core.style.setProperty("--p", pulse.toFixed(3));
        core.style.setProperty("--f", f.toFixed(2));
        for (let i = 0; i < 5; i++) core.style.setProperty(`--a${i + 1}`, `${(a[i] % 360).toFixed(2)}deg`);
      }''','''      const core = coreRef.current;
      if (core) {
        // Writing inherited custom properties restyles the whole core subtree, so only do it on change.
        const vars = `${e.toFixed(2)}|${pulse.toFixed(2)}|${f}`;
        if (vars !== st.coreVars) {
          st.coreVars = vars;
          core.style.setProperty("--e", e.toFixed(2));
          core.style.setProperty("--p", pulse.toFixed(2));
          core.style.setProperty("--f", String(f));
        }
        if (!st.spinEls.length) {
          st.spinEls = Array.from(core.querySelectorAll<HTMLElement>("[data-spin]")).map((el) => ({
            el,
            idx: Number(el.dataset.spin),
            base: el.dataset.base ?? "",
            mult: Number(el.dataset.mult ?? 1),
          }));
        }
        for (const s of st.spinEls) s.el.style.transform = `${s.base} rotate(${((a[s.idx] * s.mult) % 360).toFixed(2)}deg)`;
      }''')

# DPR caps
rep('''      st.dpr = Math.min(window.devicePixelRatio || 1, 2);''','''      st.dpr = Math.min(window.devicePixelRatio || 1, 1.5);''')
open(p,'w',encoding='utf-8').write(s)

p='components/cosmos/CosmosBackground.tsx'
s=open(p,encoding='utf-8').read()
s=s.replace('dpr = Math.min(window.devicePixelRatio || 1, 2);','dpr = Math.min(window.devicePixelRatio || 1, 1.5);')
open(p,'w',encoding='utf-8').write(s)

p='components/cosmos/CyrusCore.tsx'
s=open(p,encoding='utf-8').read()
def rep2(old,new):
    global s
    assert old in s, "MISSING "+old[:80]
    s=s.replace(old,new,1)
rep2('''      <div className="plane" style={{ transform: `rotateX(${h.rx}deg) rotateZ(var(${h.angle}))` }}>''','''      <div className="plane" data-spin={h.spin} data-base={`rotateX(${h.rx}deg)`} style={{ transform: `rotateX(${h.rx}deg)` }}>''')
rep2('''  angle: string;''','''  spin: number;''')
s=s.replace('angle: "--a1"','spin: 0').replace('angle: "--a2"','spin: 1').replace('angle: "--a3"','spin: 2')
rep2('''<svg className="core-web" viewBox="0 0 100 100" aria-hidden>''','''<svg className="core-web" viewBox="0 0 100 100" aria-hidden data-spin="4">''')
rep2('''<svg className="core-crown" viewBox="0 0 100 100" aria-hidden>''','''<svg className="core-crown" viewBox="0 0 100 100" aria-hidden data-spin="3">''')
rep2('''        <div className="core-plasma-a" />
        <div className="core-plasma-b" />''','''        <div className="core-plasma-a" data-spin="0" />
        <div className="core-plasma-b" data-spin="1" data-mult="-1.4" />''')
open(p,'w',encoding='utf-8').write(s)
print('ok')
EOF
