  { pos: [420, -25], cats: [[180, -128, "right"], [210, 0, "right"], [180, 128, "right"], [55, -200, "up"], [70, 215, "down"]] },
  { pos: [265, 235], cats: [[200, -28, "right"], [145, 108, "right"], [-40, 178, "right"], [0, 290, "down"]] },
  { pos: [-265, 235], cats: [[-200, -28, "left"], [-145, 108, "left"], [40, 178, "left"], [0, 290, "down"]] },
  { pos: [-420, -25], cats: [[-180, -128, "left"], [-210, 0, "left"], [-180, 128, "left"], [-55, -200, "up"], [-70, 215, "down"]] },
];

function hash(s: string) {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) h = Math.imul(h ^ s.charCodeAt(i), 16777619);
  return (h >>> 0) / 4294967295;
}

