"use client";

import type { Ref } from "react";
import { CyrusLogo } from "@/components/icons/CyrusLogo";

// Round so server (Node) and browser trig agree to the digit during hydration.
const r3 = (v: number) => Math.round(v * 1000) / 1000;
const cos = (a: number) => r3(Math.cos(a));
const sin = (a: number) => r3(Math.sin(a));

interface Halo {
  size: number;
  tilt: number;
  rx: number;
  spin: number;
  from: string;
  to: string;
  sats: number[];
}

// Two faint tilted halos. The back half renders behind the orb and the front half in front,
// so they read as orbiting around it.
const HALOS: Halo[] = [
  { size: 300, tilt: -18, rx: 74, spin: 0, from: "var(--h-cyan)", to: "var(--h-violet)", sats: [30] },
  { size: 360, tilt: 24, rx: 77, spin: 1, from: "var(--h-pink)", to: "var(--h-indigo)", sats: [200, 320] },
];

function HaloRing({ h, idx, half }: { h: Halo; idx: number; half: "back" | "front" }) {
  const gid = `halo-${idx}-${half}`;
  return (
    <div className={`core-halo ${half}`} style={{ ["--hs" as string]: `${h.size}px`, transform: `rotate(${h.tilt}deg)` }}>
      <div className="plane" data-spin={h.spin} data-base={`rotateX(${h.rx}deg)`} style={{ transform: `rotateX(${h.rx}deg)` }}>
        <svg viewBox="0 0 100 100" width="100%" height="100%" style={{ overflow: "visible" }}>
          <defs>
            <linearGradient id={gid} x1="0" y1="0" x2="1" y2="1">
              <stop offset="0%" style={{ stopColor: h.from }} />
              <stop offset="50%" style={{ stopColor: h.to, stopOpacity: 0.2 }} />
              <stop offset="100%" style={{ stopColor: h.from }} />
            </linearGradient>
          </defs>
          <circle cx="50" cy="50" r="48" fill="none" stroke={`url(#${gid})`} strokeWidth={(1.2 / h.size) * 100} strokeOpacity="0.7" />
          {h.sats.map((deg) => {
            const a = (deg * Math.PI) / 180;
            return <circle key={deg} cx={r3(50 + 48 * cos(a))} cy={r3(50 + 48 * sin(a))} r={(2.6 / h.size) * 100} style={{ fill: "var(--h-sat)" }} />;
          })}
        </svg>
      </div>
    </div>
  );
}

/** Jagged electric arcs that crackle around the rim. */
function Sparks() {
  const arcs = [
    { a0: -150, a1: -112, r: 103, c: "#67e8f9" },
    { a0: -40, a1: -8, r: 104, c: "#e879f9" },
    { a0: 28, a1: 60, r: 102, c: "#f472b6" },
    { a0: 120, a1: 158, r: 104, c: "#60a5fa" },
    { a0: 190, a1: 214, r: 103, c: "#a78bfa" },
  ];
  return (
    <svg className="core-sparks" viewBox="-120 -120 240 240" aria-hidden data-spin="2">
      {arcs.map((arc, i) => {
        const steps = 9;
        const pts = Array.from({ length: steps + 1 }, (_, k) => {
          const a = ((arc.a0 + ((arc.a1 - arc.a0) * k) / steps) * Math.PI) / 180;
          const jitter = k % 2 ? 4.5 : -2.5;
          const r = arc.r + (k === 0 || k === steps ? 0 : jitter);
          return `${r3(r * cos(a))},${r3(r * sin(a))}`;
        }).join(" ");
        return (
          <polyline
            key={i}
            points={pts}
            fill="none"
            stroke={arc.c}
            strokeWidth="1.1"
            strokeLinejoin="round"
            className="spark"
            style={{ animationDelay: `${i * 0.37}s` }}
          />
        );
      })}
    </svg>
  );
}

function Specks() {
  const pts = [
    [62, 48], [140, 60], [48, 120], [150, 132], [96, 34], [118, 160], [70, 150], [36, 84], [160, 92], [128, 40],
  ];
  return (
    <svg className="core-specks" viewBox="0 0 192 192" aria-hidden>
      {pts.map(([x, y], i) => (
        <circle key={i} cx={x} cy={y} r={i % 3 === 0 ? 1 : 0.6} fill="#fff" opacity={0.25 + (i % 4) * 0.12} />
      ))}
    </svg>
  );
}

export function CyrusCore({
  coreRef,
  rippleRef,
  statusRef,
  onActivate,
}: {
  coreRef: Ref<HTMLDivElement>;
  rippleRef: Ref<HTMLDivElement>;
  statusRef: Ref<HTMLSpanElement>;
  onActivate: () => void;
}) {
  return (
    <div className="core" ref={coreRef} data-id="core">
      <div className="core-aura" />
      {HALOS.map((h, i) => (
        <HaloRing key={`b${i}`} h={h} idx={i} half="back" />
      ))}
      <div className="core-ripples" ref={rippleRef} />
      <div className="core-rim-glow" data-spin="3" />
      <div className="core-orb">
        <div className="core-nebula" data-spin="4" />
        <Specks />
        <div className="core-glint" />
        <div className="core-brand">
          <CyrusLogo id="core-logo" className="core-logo" />
          <span>Cyrus</span>
        </div>
      </div>
      <div className="core-rim" data-spin="3" />
      <Sparks />
      {HALOS.map((h, i) => (
        <HaloRing key={`f${i}`} h={h} idx={i} half="front" />
      ))}
      <button
        type="button"
        className="core-hit"
        aria-label="Cyrus Core — return to overview"
        onClick={onActivate}
        onPointerDown={(e) => e.stopPropagation()}
      />
      <div className="core-label">
        <span className="s" ref={statusRef}>
          online
        </span>
      </div>
    </div>
  );
}

