"use client";

import type { Ref } from "react";

// Round so server (Node) and browser trig agree to the digit during hydration.
const r3 = (v: number) => Math.round(v * 1000) / 1000;
const cos = (a: number) => r3(Math.cos(a));
const sin = (a: number) => r3(Math.sin(a));

interface Halo {
  size: number;
  tilt: number;
  rx: number;
  spin: number;
  from: string;
  to: string;
  width: number;
  dash: string;
  sats: number[];
}

// Each halo is a tilted ring. Its back half renders behind the orb and its front half in front,
// so the rings read as wrapping around the core in 3D.
const HALOS: Halo[] = [
  { size: 400, tilt: -14, rx: 75, spin: 0, from: "var(--h-violet)", to: "var(--h-cyan)", width: 1.4, dash: "2 6", sats: [0, 160] },
  { size: 300, tilt: 22, rx: 70, spin: 1, from: "var(--h-cyan)", to: "var(--h-indigo)", width: 2, dash: "60 18 6 18", sats: [90] },
  { size: 470, tilt: -32, rx: 79, spin: 2, from: "var(--h-pink)", to: "var(--h-indigo)", width: 1.1, dash: "1 7", sats: [40, 200, 300] },
];

function HaloRing({ h, idx, half }: { h: Halo; idx: number; half: "back" | "front" }) {
  const sw = (h.width / h.size) * 100;
  const gid = `halo-g-${idx}-${half}`;
  return (
    <div className={`core-halo ${half}`} style={{ ["--hs" as string]: `${h.size}px`, transform: `rotate(${h.tilt}deg)` }}>
      <div className="plane" data-spin={h.spin} data-base={`rotateX(${h.rx}deg)`} style={{ transform: `rotateX(${h.rx}deg)` }}>
        <svg viewBox="0 0 100 100" width="100%" height="100%" style={{ overflow: "visible" }}>
          <defs>
            <linearGradient id={gid} x1="0" y1="0" x2="1" y2="1">
              <stop offset="0%" style={{ stopColor: h.from }} />
              <stop offset="55%" style={{ stopColor: h.to, stopOpacity: 0.35 }} />
              <stop offset="100%" style={{ stopColor: h.from }} />
            </linearGradient>
          </defs>
          {/* soft glow */}
          <circle cx="50" cy="50" r="48" fill="none" stroke={`url(#${gid})`} strokeWidth={sw * 5} strokeOpacity="0.12" />
          <circle
            cx="50"
            cy="50"
            r="48"
            fill="none"
            stroke={`url(#${gid})`}
            strokeWidth={sw}
            strokeDasharray={h.dash
              .split(" ")
              .map((n) => (Number(n) / h.size) * 100 * 1.6)
              .join(" ")}
            strokeLinecap="round"
            style={{ strokeOpacity: "calc(0.55 + var(--e) * 0.45)" as unknown as number }}
          />
          {h.sats.map((deg) => {
            const a = (deg * Math.PI) / 180;
            const x = 50 + 48 * cos(a);
            const y = 50 + 48 * sin(a);
            return (
              <g key={deg}>
                <circle cx={x} cy={y} r={(5 / h.size) * 100 * 2.2} style={{ fill: h.from }} opacity="0.25" />
                <circle cx={x} cy={y} r={(5 / h.size) * 100 * 0.7} style={{ fill: "var(--h-sat)" }} />
              </g>
            );
          })}
        </svg>
      </div>
    </div>
  );
}

function CoreWeb() {
  const spokes = 12;
  const rings = [33, 41, 49];
  const poly = (r: number) =>
    Array.from({ length: spokes }, (_, i) => {
      const a = (i / spokes) * Math.PI * 2;
      return `${50 + r * cos(a)},${50 + r * sin(a)}`;
    }).join(" ");
  return (
    <svg className="core-web" viewBox="0 0 100 100" aria-hidden data-spin="4">
      {Array.from({ length: spokes }, (_, i) => {
        const a = (i / spokes) * Math.PI * 2;
        return (
          <line
            key={i}
            x1={50 + 24 * cos(a)}
            y1={50 + 24 * sin(a)}
            x2={50 + 50 * cos(a)}
            y2={50 + 50 * sin(a)}
            stroke="currentColor"
            strokeOpacity="0.28"
            strokeWidth="0.25"
          />
        );
      })}
      {rings.map((r, i) => (
        <polygon key={r} points={poly(r)} fill="none" stroke="currentColor" strokeOpacity={0.12 + i * 0.05} strokeWidth="0.25" strokeDasharray={i === 1 ? "0.8 1.6" : undefined} />
      ))}
    </svg>
  );
}

function CoreCrown() {
  const ticks = 72;
  return (
    <svg className="core-crown" viewBox="0 0 100 100" aria-hidden data-spin="3">
      {Array.from({ length: ticks }, (_, i) => {
        const a = (i / ticks) * Math.PI * 2;
        const long = i % 6 === 0;
        const r1 = long ? 43.5 : 45.5;
        return (
          <line
            key={i}
            x1={50 + r1 * cos(a)}
            y1={50 + r1 * sin(a)}
            x2={50 + 48 * cos(a)}
            y2={50 + 48 * sin(a)}
            stroke="currentColor"
            strokeOpacity={long ? 0.75 : 0.32}
            strokeWidth={long ? 0.5 : 0.3}
            strokeLinecap="round"
          />
        );
      })}
      {[0, 90, 180, 270].map((d) => {
        const a = (d * Math.PI) / 180;
        const x = 50 + 40.5 * cos(a);
        const y = 50 + 40.5 * sin(a);
        return <circle key={d} cx={x} cy={y} r="0.9" fill="currentColor" />;
      })}
      <circle cx="50" cy="50" r="38.5" fill="none" stroke="currentColor" strokeOpacity="0.18" strokeWidth="0.25" />
    </svg>
  );
}

export function CyrusCore({
  coreRef,
  rippleRef,
  statusRef,
  onActivate,
}: {
  coreRef: Ref<HTMLDivElement>;
  rippleRef: Ref<HTMLDivElement>;
  statusRef: Ref<HTMLSpanElement>;
  onActivate: () => void;
}) {
  return (
    <div className="core" ref={coreRef} data-id="core">
      <div className="core-bloom" />
      <CoreWeb />
      {HALOS.map((h, i) => (
        <HaloRing key={`b${i}`} h={h} idx={i} half="back" />
      ))}
      <CoreCrown />
      <div className="core-ripples" ref={rippleRef} />
      <div className="core-orb">
        <div className="core-plasma-a" data-spin="0" />
        <div className="core-plasma-b" data-spin="1" data-mult="-1.4" />
        <div className="core-nucleus" />
        <div className="core-glint" />
      </div>
      {HALOS.map((h, i) => (
        <HaloRing key={`f${i}`} h={h} idx={i} half="front" />
      ))}
      <button
        type="button"
        className="core-hit"
        aria-label="Cyrus Core — return to overview"
        onClick={onActivate}
        onPointerDown={(e) => e.stopPropagation()}
      />
      <div className="core-label">
        <span className="t">CYRUS CORE</span>
        <span className="s" ref={statusRef}>
          online
        </span>
      </div>
    </div>
  );
}

