"use client";

import { memo, useCallback, useEffect, useMemo, useRef, type PointerEvent as RPointerEvent } from "react";
import { CategoryIcon } from "@/components/icons/CategoryIcons";
import { GameEmblem } from "@/components/icons/GameEmblems";
import { camera, cameraApi } from "@/lib/camera";
import { GAME_BY_ID } from "@/lib/data";
import { fx } from "@/lib/fx";
import { CORE_ID, isJobLive, useAllMods, useStore } from "@/lib/store";
import { CyrusCore } from "./CyrusCore";
import {
  CORE_RGB,
  RADIUS,
  buildGraph,
  computeStates,
  layoutExtent,
  pillOffset,
  selectedNodeId,
  type LLink,
  type LNode,
  type NodeState,
} from "./graph";

/** A node with live physics state. */
type PNode = LNode & { x: number; y: number; vx: number; vy: number; rx: number; ry: number; ink: string };
/** A link with its current cubic curve. */
type PLink = LLink & { a: PNode; b: PNode; p: number[] };

interface Packet {
  path: string[];
  seg: number;
  t: number;
  speed: number;
  rgb: string;
  size: number;
  trail: number;
  ambient: boolean;
  delay: number;
}
interface Mote {
  a: number;
  r: number;
  va: number;
  vr: number;
  life: number;
  rgb: string;
  size: number;
}
interface Spark {
  x: number;
  y: number;
  vx: number;
  vy: number;
  life: number;
  rgb: string;
}

const SPRING = 95;
const DAMP = 13;
const FOCUS_K = { game: 1.15, category: 1.45, mod: 1.7 } as const;
const MOTE_COLORS = ["103 232 249", "196 181 253", "240 171 252", "147 197 253"];

const clamp = (v: number, a: number, b: number) => Math.max(a, Math.min(b, v));
const easeOut = (t: number) => 1 - Math.pow(1 - clamp(t, 0, 1), 3);

/** Darkens a neon "r g b" triple so it reads on a white background. */
function inkOf(rgb: string) {
  const [r, g, b] = rgb.split(" ").map(Number);
  const m = (c: number, t: number) => Math.round(c * 0.7 + t * 0.3);
  return `${m(r, 40)} ${m(g, 20)} ${m(b, 90)}`;
}

function mix(rgb: string, t: number) {
  const [r, g, b] = rgb.split(" ").map(Number);
  return `${Math.round(r + (255 - r) * t)} ${Math.round(g + (255 - g) * t)} ${Math.round(b + (255 - b) * t)}`;
}

function cubic(p: number[], t: number) {
  const u = 1 - t;
  const a = u * u * u;
  const b = 3 * u * u * t;
  const c = 3 * u * t * t;
  const d = t * t * t;
  return { x: a * p[0] + b * p[2] + c * p[4] + d * p[6], y: a * p[1] + b * p[3] + c * p[5] + d * p[7] };
}

/** Where a pill sits: its inner edge, the point a branch connects to. */
function pillAnchor(n: PNode, cat: PNode) {
  const [dx, dy] = pillOffset(n.side, n.row, n.rows);
  return { x: cat.rx + dx, y: cat.ry + dy };
}

export function Network() {
  const mods = useAllMods();
  const selection = useStore((s) => s.selection);
  const focus = useStore((s) => s.focus);
  const theme = useStore((s) => s.theme);
  const panelOpen = useStore((s) => s.panelOpen);
  const navOpen = useStore((s) => s.navOpen);
  const forgingId = useStore((s) => (isJobLive(s.job) ? s.job!.modId : undefined));
  const select = useStore((s) => s.select);
  const focusPrompt = useStore((s) => s.focusPrompt);

  const stageRef = useRef<HTMLDivElement>(null);
  const worldRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const coreRef = useRef<HTMLDivElement>(null);
  const rippleRef = useRef<HTMLDivElement>(null);
  const statusRef = useRef<HTMLSpanElement>(null);
  const nodeEls = useRef(new Map<string, HTMLDivElement>());
  const initialIds = useRef<Set<string> | null>(null);

  const graph = useMemo(() => buildGraph(mods), [mods]);
  if (!initialIds.current) initialIds.current = new Set(graph.nodes.map((n) => n.id));

  const S = useRef({
    nodes: new Map<string, PNode>(),
    order: [] as PNode[],
    links: [] as PLink[],
    pairs: new Map<string, PLink>(),
    children: new Map<string, string[]>(),
    extent: { halfW: 900, halfH: 560 },
    born: 0,
    cam: { x: 0, y: 0, k: 0.3 },
    target: { x: 0, y: 0, k: 0.75 },
    follow: null as null | { kind: "node" | "path"; id: string; k: number },
    insets: { l: 72, r: 0, t: 64, b: 165 },
    W: 0,
    H: 0,
    dpr: 1,
    states: new Map<string, NodeState>(),
    hovered: null as string | null,
    drag: null as null | { id: string; sx: number; sy: number; ox: number; oy: number; moved: boolean },
    pan: null as null | { sx: number; sy: number; cx: number; cy: number; moved: boolean },
    packets: [] as Packet[],
    motes: [] as Mote[],
    sparks: [] as Spark[],
    rings: [] as { id: string; t: number; rgb: string }[],
    angles: [0, 0, 0, 0, 0],
    streamTimer: 0,
    moteAcc: 0,
    zoomLevel: "",
    lastK: 0,
    dark: true,
    modCount: 0,
    flashTimers: new Map<string, number>(),
    worldTransform: "",
    coreVars: "",
    spinEls: [] as { el: HTMLElement; idx: number; base: string; mult: number }[],
  });

  S.current.dark = theme === "dark";
  S.current.modCount = mods.length;

  const fitK = useCallback(() => {
    const st = S.current;
    const aw = st.W - st.insets.l - st.insets.r;
    const ah = st.H - st.insets.t - st.insets.b;
    return clamp(Math.min(aw / (st.extent.halfW * 2 + 40), ah / (st.extent.halfH * 2 + 40)), 0.3, 1.1);
  }, []);

  /* ───────────── Graph sync: keep physics state for nodes that survive ───────────── */
  useEffect(() => {
    const st = S.current;
    const first = st.nodes.size === 0;
    if (first) st.born = performance.now();
    const next = new Map<string, PNode>();
    for (const g of graph.nodes) {
      const prev = st.nodes.get(g.id);
      if (prev) {
        // Layout fields refresh (rows change as mods are added); dragged homes are kept.
        Object.assign(prev, { ...g, hx: prev.hx, hy: prev.hy, ink: inkOf(g.rgb) });
        next.set(g.id, prev);
        continue;
      }
      const parent = g.parent ? (next.get(g.parent) ?? st.nodes.get(g.parent)) : undefined;
      const px = parent?.x ?? 0;
      const py = parent?.y ?? 0;
      next.set(g.id, { ...g, x: px, y: py, vx: 0, vy: 0, rx: px, ry: py, ink: inkOf(g.rgb) });
    }
    st.nodes = next;
    st.order = graph.nodes.map((n) => next.get(n.id)!);
    st.links = graph.links.map((l) => ({ ...l, a: next.get(l.from)!, b: next.get(l.to)!, p: [0, 0, 0, 0, 0, 0, 0, 0] }));
    st.pairs = new Map();
    st.children = new Map();
    for (const l of st.links) {
      st.pairs.set(`${l.from}|${l.to}`, l);
      st.pairs.set(`${l.to}|${l.from}`, l);
      st.children.set(l.from, [...(st.children.get(l.from) ?? []), l.to]);
    }
    st.extent = layoutExtent(graph.nodes);
    if (!st.follow) st.target.k = fitK();
  }, [graph, fitK]);

  /* ───────────── Node states (dimming) ───────────── */
  const nodeStates = useMemo(() => computeStates(graph.nodes, selection), [graph, selection]);
  useEffect(() => {
    S.current.states = nodeStates;
  }, [nodeStates]);

  /* ───────────── Insets that frame the camera ───────────── */
  useEffect(() => {
    const st = S.current;
    const wide = window.innerWidth >= 1024;
    st.insets = {
      l: window.innerWidth < 768 ? 0 : navOpen ? 300 : 72,
      r: panelOpen && wide ? Math.min(560, window.innerWidth * 0.4) : 0,
      t: 64,
      b: window.innerWidth < 768 ? 220 : 165,
    };
    if (!st.follow) st.target.k = fitK();
  }, [panelOpen, navOpen, fitK]);

  /* ───────────── Camera focus requests ───────────── */
  useEffect(() => {
    const st = S.current;
    if (focus.kind === "overview" || !focus.id || focus.id === CORE_ID) {
      st.follow = null;
      st.target = { x: 0, y: 0, k: fitK() };
      return;
    }
    const n = st.nodes.get(focus.id);
    const k = n?.type === "game" ? FOCUS_K.game : n?.type === "category" ? FOCUS_K.category : FOCUS_K.mod;
    st.follow = { kind: focus.kind === "path" ? "path" : "node", id: focus.id, k };
  }, [focus, fitK]);

  /* ───────────── The render loop ───────────── */
  useEffect(() => {
    const st = S.current;
    const stage = stageRef.current!;
    const world = worldRef.current!;
    const canvas = canvasRef.current!;
    const ctx = canvas.getContext("2d")!;
    let raf = 0;
    let last = performance.now();
    let readyAt = last + 120;

    const resize = () => {
      st.dpr = Math.min(window.devicePixelRatio || 1, 1.5);
      st.W = stage.clientWidth;
      st.H = stage.clientHeight;
      canvas.width = st.W * st.dpr;
      canvas.height = st.H * st.dpr;
      canvas.style.width = `${st.W}px`;
      canvas.style.height = `${st.H}px`;
    };
    resize();
    st.target.k = fitK();
    st.cam.k = st.target.k * 0.6;
    const ro = new ResizeObserver(() => {
      resize();
      if (!st.follow) st.target.k = fitK();
    });
    ro.observe(stage);

    const viewCenter = () => ({
      x: st.insets.l + (st.W - st.insets.l - st.insets.r) / 2,
      y: st.insets.t + (st.H - st.insets.t - st.insets.b) / 2,
    });

    const flash = (id: string) => {
      const el = nodeEls.current.get(id);
      if (!el) return;
      el.classList.remove("is-hit");
      void el.offsetWidth;
      el.classList.add("is-hit");
      window.clearTimeout(st.flashTimers.get(id));
      st.flashTimers.set(
        id,
        window.setTimeout(() => el.classList.remove("is-hit"), 600),
      );
    };

    const ripple = (big = false) => {
      const host = rippleRef.current;
      if (!host || host.childElementCount > 8) return;
      const span = document.createElement("span");
      if (big) span.className = "big";
      span.addEventListener("animationend", () => span.remove());
      host.appendChild(span);
    };

    const spawnPacket = (path: string[], opts: Partial<Packet> = {}) => {
      if (path.length < 2 || path.some((id) => !st.nodes.has(id))) return;
      st.packets.push({ path: [...path], seg: 0, t: 0, speed: 1, rgb: CORE_RGB, size: 1, trail: 0.22, ambient: false, delay: 0, ...opts });
    };

    /** Point a link connects to on a node: rim of round nodes, inner edge of pills. */
    const endpoint = (n: PNode, toward: PNode) => {
      if (n.type === "mod" || n.type === "more") {
        const cat = st.nodes.get(n.parent!)!;
        const a = pillAnchor(n, cat);
        if (n.side === "up") return { x: a.x, y: a.y + 12 };
        if (n.side === "down") return { x: a.x, y: a.y - 12 };
        return a;
      }
      const r = n.type === "core" ? RADIUS.core : n.type === "game" ? RADIUS.game : RADIUS.category;
      if (n.type === "category" && (toward.type === "mod" || toward.type === "more")) {
        // Lists leave the category from the side they open toward.
        const d = { left: [-1, 0], right: [1, 0], up: [0, -1], down: [0, 1] }[n.side];
        return { x: n.rx + d[0] * r, y: n.ry + d[1] * r };
      }
      const dx = toward.rx - n.rx;
      const dy = toward.ry - n.ry;
      const len = Math.hypot(dx, dy) || 1;
      return { x: n.rx + (dx / len) * r, y: n.ry + (dy / len) * r };
    };

    const posOf = (n: PNode) => {
      if (n.type === "mod" || n.type === "more") return pillAnchor(n, st.nodes.get(n.parent!)!);
      return { x: n.rx, y: n.ry };
    };

    const burst = (id: string, rgb: string) => {
      const n = st.nodes.get(id);
      if (!n) return;
      const p = posOf(n);
      st.rings.push({ id, t: 0, rgb });
      for (let i = 0; i < 26; i++) {
        const a = Math.random() * Math.PI * 2;
        const v = 60 + Math.random() * 150;
        st.sparks.push({ x: p.x, y: p.y, vx: Math.cos(a) * v, vy: Math.sin(a) * v, life: 1, rgb: Math.random() < 0.3 ? "255 255 255" : rgb });
      }
      flash(id);
    };

    cameraApi.zoomBy = (f: number) => {
      st.target.k = clamp(st.target.k * f, 0.3, 3);
    };

    const loop = (now: number) => {
      raf = requestAnimationFrame(loop);
      const dt = Math.min(0.033, (now - last) / 1000);
      last = now;
      const t = now / 1000;
      const dark = st.dark;
      const age = (now - st.born) / 1000;

      /* ── springs: every node is pulled toward parent + home offset; branches follow with a lag ── */
      const bloomGame = easeOut((age - 0.1) / 1.1);
      const bloomCat = easeOut((age - 0.45) / 1.1);
      for (const n of st.order) {
        if (n.type !== "game" && n.type !== "category") continue;
        if (st.drag?.id === n.id && st.drag.moved) continue;
        const p = st.nodes.get(n.parent!)!;
        const bloom = n.type === "game" ? bloomGame : bloomCat;
        const tx = p.x + n.hx * bloom;
        const ty = p.y + n.hy * bloom;
        n.vx += ((tx - n.x) * SPRING - n.vx * DAMP) * dt;
        n.vy += ((ty - n.y) * SPRING - n.vy * DAMP) * dt;
        n.x += n.vx * dt;
        n.y += n.vy * dt;
      }
      for (const n of st.order) {
        if (n.type === "core") {
          n.rx = n.ry = 0;
          continue;
        }
        if (n.type === "mod" || n.type === "more") continue;
        const amp = n.type === "game" ? 2.5 : 3;
        const still = st.drag?.id === n.id;
        n.rx = n.x + (still ? 0 : Math.sin(t * 0.5 + n.phase) * amp);
        n.ry = n.y + (still ? 0 : Math.cos(t * 0.43 + n.phase * 1.7) * amp);
      }

      /* energy & core rhythm */
      fx.energy = Math.max(0, fx.energy - dt * 0.5);
      const e = fx.energy;
      const mode = fx.mode;
      const pulse =
        mode === "forging"
          ? Math.pow(0.5 + 0.5 * Math.sin(t * Math.PI * 2 * 1.25), 6)
          : mode === "thinking"
            ? Math.pow(0.5 + 0.5 * Math.sin(t * Math.PI * 2 * 0.9), 4) * 0.7
            : (0.5 + 0.5 * Math.sin(t * Math.PI * 2 * 0.2)) * 0.2;
      const f = mode === "forging" ? 1 : mode === "thinking" ? 0.6 : 0;

      /* camera */
      const vc = viewCenter();
      if (st.follow) {
        const n = st.nodes.get(st.follow.id);
        if (n) {
          const p = n.type === "mod" || n.type === "more" ? pillAnchor(n, st.nodes.get(n.parent!)!) : { x: n.x, y: n.y };
          const aw = st.W - st.insets.l - st.insets.r;
          const ah = st.H - st.insets.t - st.insets.b;
          if (st.follow.kind === "path") {
            st.target.x = p.x * 0.5;
            st.target.y = p.y * 0.5;
            st.target.k = clamp(Math.min(aw / (Math.abs(p.x) + 420), ah / (Math.abs(p.y) + 300)), 0.45, 1.3);
          } else {
            // Bias toward the side a list opens so the pills are in frame.
            const bias = n.type === "category" ? { left: [-120, 0], right: [120, 0], up: [0, -70], down: [0, 70] }[n.side] : n.type === "mod" || n.type === "more" ? { left: [-80, 0], right: [80, 0], up: [0, 0], down: [0, 0] }[n.side] : [0, 0];
            st.target.x = p.x + bias[0];
            st.target.y = p.y + bias[1];
            st.target.k = Math.min(st.follow.k, Math.max(fitK() * 1.2, st.follow.k * Math.min(1, aw / 1100)));
          }
        }
      }
      const ease = 1 - Math.exp(-dt * 4.2);
      const cam = st.cam;
      cam.x += (st.target.x - cam.x) * ease;
      cam.y += (st.target.y - cam.y) * ease;
      cam.k = Math.exp(Math.log(cam.k) + (Math.log(st.target.k) - Math.log(cam.k)) * ease);
      if (Math.abs(st.target.x - cam.x) < 0.05) cam.x = st.target.x;
      if (Math.abs(st.target.y - cam.y) < 0.05) cam.y = st.target.y;
      if (Math.abs(st.target.k - cam.k) < 0.0005) cam.k = st.target.k;
      camera.x = cam.x;
      camera.y = cam.y;
      camera.k = cam.k;
      const ox = vc.x - cam.x * cam.k;
      const oy = vc.y - cam.y * cam.k;
      const worldTransform = `translate3d(${ox.toFixed(1)}px, ${oy.toFixed(1)}px, 0) scale(${cam.k.toFixed(4)})`;
      if (worldTransform !== st.worldTransform) {
        world.style.transform = worldTransform;
        st.worldTransform = worldTransform;
      }
      if (Math.abs(cam.k - st.lastK) > 0.003) {
        st.lastK = cam.k;
        const level = cam.k < 0.8 ? "far" : cam.k < 1.3 ? "mid" : "near";
        if (level !== st.zoomLevel) {
          st.zoomLevel = level;
          stage.dataset.zoom = level;
        }
        cameraApi.emitZoom(cam.k);
      }
      if (now > readyAt) {
        world.classList.add("is-ready");
        readyAt = Infinity;
      }

      /* DOM nodes */
      for (const [id, el] of nodeEls.current) {
        const n = st.nodes.get(id);
        if (!n) continue;
        const p = posOf(n);
        el.style.transform = `translate3d(${p.x.toFixed(2)}px, ${p.y.toFixed(2)}px, 0)`;
      }

      /* core */
      const a = st.angles;
      a[0] += dt * (9 + e * 120 + f * 60);
      a[1] -= dt * (7 + e * 100 + f * 50);
      a[2] -= dt * (16 + e * 140 + f * 90);
      a[3] += dt * (14 + e * 110 + f * 80);
      a[4] -= dt * (4 + e * 30 + f * 20);
      const core = coreRef.current;
      if (core) {
        const vars = `${e.toFixed(2)}|${pulse.toFixed(2)}|${f}`;
        if (vars !== st.coreVars) {
          st.coreVars = vars;
          core.style.setProperty("--e", e.toFixed(2));
          core.style.setProperty("--p", pulse.toFixed(2));
          core.style.setProperty("--f", String(f));
        }
        if (!st.spinEls.length || !st.spinEls[0].el.isConnected) {
          st.spinEls = Array.from(core.querySelectorAll<HTMLElement>("[data-spin]")).map((el) => ({
            el,
            idx: Number(el.dataset.spin),
            base: el.dataset.base ?? "",
            mult: Number(el.dataset.mult ?? 1),
          }));
        }
        for (const s of st.spinEls) s.el.style.transform = `${s.base} rotate(${((a[s.idx] * s.mult) % 360).toFixed(2)}deg)`;
      }
      const statusEl = statusRef.current;
      if (statusEl) {
        const g = fx.stream ? GAME_BY_ID[fx.stream.path[1] as keyof typeof GAME_BY_ID] : undefined;
        const status =
          mode === "forging" ? `forging → ${g?.short ?? "branch"}` : mode === "thinking" ? "thinking…" : e > 0.06 ? "listening…" : `online · ${st.modCount} mods`;
        if (statusEl.textContent !== status) statusEl.textContent = status;
      }

      /* effects bus */
      for (const ev of fx.drain()) {
        if (ev.type === "ripple") ripple(ev.big);
        else if (ev.type === "packets") {
          for (let i = 0; i < ev.count; i++)
            spawnPacket(ev.path, { rgb: ev.rgb ?? CORE_RGB, speed: ev.speed ?? 1, size: ev.size ?? 1.2, delay: i * (ev.gap ?? 0.16), trail: 0.3 });
        } else if (ev.type === "burst") burst(ev.id, ev.rgb ?? CORE_RGB);
        else if (ev.type === "flash") flash(ev.id);
      }

      if (fx.stream) {
        st.streamTimer -= dt;
        if (st.streamTimer <= 0) {
          spawnPacket(fx.stream.path, { rgb: fx.stream.rgb, speed: 1.15, size: 1.6, trail: 0.36 });
          st.streamTimer = 0.15;
        }
      }
      let ambient = 0;
      for (const p of st.packets) if (p.ambient) ambient++;
      if (age > 2 && ambient < 12 && Math.random() < dt * 2.2) {
        const path = [CORE_ID];
        let cur = CORE_ID;
        for (let d = 0; d < 3; d++) {
          const kids = st.children.get(cur);
          if (!kids?.length) break;
          cur = kids[Math.floor(Math.random() * kids.length)];
          path.push(cur);
        }
        const g = st.nodes.get(path[1]);
        spawnPacket(path, { ambient: true, rgb: g?.rgb ?? CORE_RGB, speed: 0.35 + Math.random() * 0.25, size: 0.8, trail: 0.14 });
      }
      st.moteAcc += dt * (e * 60 + (mode === "thinking" ? 22 : mode === "forging" ? 14 : 0));
      while (st.moteAcc >= 1) {
        st.moteAcc -= 1;
        st.motes.push({
          a: Math.random() * Math.PI * 2,
          r: 200 + Math.random() * 140,
          va: 0.9 + Math.random() * 0.8,
          vr: 70 + Math.random() * 90 + e * 110,
          life: 0,
          rgb: MOTE_COLORS[Math.floor(Math.random() * MOTE_COLORS.length)],
          size: 0.6 + Math.random() * 1,
        });
      }

      /* ───── canvas ───── */
      const k = cam.k;
      ctx.setTransform(1, 0, 0, 1, 0, 0);
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.setTransform(st.dpr * k, 0, 0, st.dpr * k, st.dpr * ox, st.dpr * oy);
      ctx.globalCompositeOperation = dark ? "lighter" : "source-over";
      ctx.lineCap = "round";
      const px = 1 / k;
      const col = (rgb: string) => (dark ? rgb : inkOf(rgb));
      const stateAlpha = (id: string) => {
        const s = st.states.get(id) ?? "on";
        return s === "on" ? 1 : s === "near" ? 0.4 : 0.07;
      };

      // The faint web around the core: concentric rings and radial threads.
      ctx.globalAlpha = 1;
      ctx.lineWidth = Math.max(0.5, 0.7 * px);
      const web = dark ? `rgb(147 160 255 / ${0.06 + e * 0.05})` : "rgb(91 33 182 / 0.06)";
      ctx.strokeStyle = web;
      for (const r of [140, 185, 250, 340]) {
        ctx.beginPath();
        ctx.arc(0, 0, r, 0, Math.PI * 2);
        ctx.stroke();
      }
      ctx.setLineDash([2 * px, 10 * px]);
      ctx.lineDashOffset = -t * 4;
      ctx.beginPath();
      ctx.arc(0, 0, 440, 0, Math.PI * 2);
      ctx.stroke();
      ctx.setLineDash([]);
      ctx.strokeStyle = dark ? `rgb(147 160 255 / ${0.035 + e * 0.03})` : "rgb(91 33 182 / 0.04)";
      ctx.beginPath();
      for (let i = 0; i < 32; i++) {
        const ang = (i / 32) * Math.PI * 2;
        ctx.moveTo(Math.cos(ang) * 112, Math.sin(ang) * 112);
        ctx.lineTo(Math.cos(ang) * 360, Math.sin(ang) * 360);
      }
      ctx.stroke();

      // Hovered ancestry
      const hoverSet = new Set<string>();
      if (st.hovered) {
        let cur = st.nodes.get(st.hovered);
        while (cur?.parent) {
          hoverSet.add(`${cur.parent}|${cur.id}`);
          cur = st.nodes.get(cur.parent);
        }
      }
      const streamSet = new Set<string>();
      if (fx.stream) for (let i = 0; i < fx.stream.path.length - 1; i++) streamSet.add(`${fx.stream.path[i]}|${fx.stream.path[i + 1]}`);

      // Branches: smooth S-curves with a bright core and a soft glow.
      for (const l of st.links) {
        const A = endpoint(l.a, l.b);
        const B = endpoint(l.b, l.a);
        const dx = B.x - A.x;
        const dy = B.y - A.y;
        const p = l.p;
        p[0] = A.x;
        p[1] = A.y;
        p[6] = B.x;
        p[7] = B.y;
        if (l.kind === "game") {
          // Leave the core radially, arrive at the game on its dominant axis.
          const len = Math.hypot(dx, dy) || 1;
          p[2] = A.x + (A.x / (Math.hypot(A.x, A.y) || 1)) * len * 0.42;
          p[3] = A.y + (A.y / (Math.hypot(A.x, A.y) || 1)) * len * 0.42;
          const horiz = Math.abs(dx) > Math.abs(dy) * 0.8;
          p[4] = horiz ? B.x - dx * 0.45 : B.x;
          p[5] = horiz ? B.y : B.y - dy * 0.45;
        } else {
          const horiz = l.kind === "mod" ? l.b.side === "left" || l.b.side === "right" : Math.abs(dx) >= Math.abs(dy) * 0.7;
          p[2] = horiz ? A.x + dx * 0.5 : A.x;
          p[3] = horiz ? A.y : A.y + dy * 0.5;
          p[4] = horiz ? B.x - dx * 0.5 : B.x;
          p[5] = horiz ? B.y : B.y - dy * 0.5;
        }

        const key = `${l.from}|${l.to}`;
        const sa = Math.min(stateAlpha(l.to), stateAlpha(l.from) < 0.1 ? 0.07 : 1);
        const streaming = streamSet.has(key);
        const hovered = hoverSet.has(key);
        const base = l.kind === "game" ? 2.1 : l.kind === "category" ? 1.6 : 1.05;
        let boost = 1;
        if (l.kind === "game") boost += e * 1.2 + pulse * 0.4;
        if (streaming) boost += 1.4 + pulse;
        if (hovered) boost += 0.8;

        const rgb = l.b.rgb;
        const grad = ctx.createLinearGradient(A.x, A.y, B.x, B.y);
        grad.addColorStop(0, `rgb(${col(l.kind === "game" ? mix(rgb, 0.35) : rgb)})`);
        grad.addColorStop(1, `rgb(${col(rgb)})`);
        ctx.strokeStyle = grad;
        ctx.beginPath();
        ctx.moveTo(p[0], p[1]);
        ctx.bezierCurveTo(p[2], p[3], p[4], p[5], p[6], p[7]);
        ctx.globalAlpha = clamp((dark ? 0.14 : 0.08) * sa * boost, 0, 0.6);
        ctx.lineWidth = base * (dark ? 5 : 3.5) * Math.min(boost, 2.2);
        ctx.stroke();
        ctx.globalAlpha = clamp((dark ? 0.85 : 0.75) * sa * Math.min(boost, 1.6), 0, 1);
        ctx.lineWidth = Math.max(base * (streaming ? 1.5 : 1), 0.8 * px);
        ctx.stroke();

        if (streaming) {
          ctx.globalAlpha = dark ? 0.9 : 0.7;
          ctx.strokeStyle = dark ? "rgb(255 255 255)" : `rgb(${col(rgb)})`;
          ctx.lineWidth = Math.max(0.9, 1 * px);
          ctx.setLineDash([4, 10]);
          ctx.lineDashOffset = -t * 90;
          ctx.stroke();
          ctx.setLineDash([]);
        }

        // Glowing beads along the branch, and a node dot where it meets a pill.
        const beads = l.kind === "game" ? [0.3, 0.62] : l.kind === "category" ? [0.5] : [1];
        for (const bt of beads) {
          const q = cubic(p, bt);
          const r = l.kind === "mod" ? 2 : 2.4;
          ctx.globalAlpha = clamp(0.3 * sa, 0, 1);
          ctx.fillStyle = `rgb(${col(rgb)})`;
          ctx.beginPath();
          ctx.arc(q.x, q.y, r * 2.6, 0, Math.PI * 2);
          ctx.fill();
          ctx.globalAlpha = clamp(sa, 0, 1);
          ctx.fillStyle = dark ? `rgb(${mix(rgb, 0.65)})` : `rgb(${col(rgb)})`;
          ctx.beginPath();
          ctx.arc(q.x, q.y, r, 0, Math.PI * 2);
          ctx.fill();
        }
      }
      ctx.globalAlpha = 1;

      // Packets & beams
      for (let i = st.packets.length - 1; i >= 0; i--) {
        const pk = st.packets[i];
        if (pk.delay > 0) {
          pk.delay -= dt;
          continue;
        }
        const aId = pk.path[pk.seg];
        const bId = pk.path[pk.seg + 1];
        const link = st.pairs.get(`${aId}|${bId}`);
        if (!link) {
          st.packets.splice(i, 1);
          continue;
        }
        const forward = link.from === aId;
        const len = Math.hypot(link.p[6] - link.p[0], link.p[7] - link.p[1]) * 1.1 + 1;
        pk.t += (dt * pk.speed * 300) / len;
        if (pk.t >= 1) {
          if (!pk.ambient) {
            if (bId === CORE_ID) ripple();
            else flash(bId);
          }
          pk.seg++;
          pk.t = 0;
          if (pk.seg >= pk.path.length - 1) {
            st.packets.splice(i, 1);
          }
          continue;
        }
        const at = (tt: number) => cubic(link.p, forward ? tt : 1 - tt);
        const sa = Math.min(stateAlpha(aId), stateAlpha(bId));
        const alpha = pk.ambient ? 0.6 * sa : Math.max(sa, 0.6);
        const c = dark ? pk.rgb : inkOf(pk.rgb);
        const head = at(pk.t);
        let prev = head;
        for (let j = 1; j <= 7; j++) {
          const tt = pk.t - (j / 7) * pk.trail;
          if (tt < 0) break;
          const pt = at(tt);
          ctx.strokeStyle = `rgb(${c} / ${alpha * (1 - j / 7) * 0.85})`;
          ctx.lineWidth = pk.size * 1.8 * (1 - j / 8);
          ctx.beginPath();
          ctx.moveTo(prev.x, prev.y);
          ctx.lineTo(pt.x, pt.y);
          ctx.stroke();
          prev = pt;
        }
        ctx.fillStyle = `rgb(${c} / ${alpha * 0.25})`;
        ctx.beginPath();
        ctx.arc(head.x, head.y, pk.size * 4.5, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = dark ? `rgb(255 255 255 / ${alpha})` : `rgb(${c} / ${alpha})`;
        ctx.beginPath();
        ctx.arc(head.x, head.y, pk.size * 1.3, 0, Math.PI * 2);
        ctx.fill();
      }

      // Motes spiralling into the core
      for (let i = st.motes.length - 1; i >= 0; i--) {
        const m = st.motes[i];
        const x0 = Math.cos(m.a) * m.r;
        const y0 = Math.sin(m.a) * m.r;
        m.r -= m.vr * dt;
        m.a += m.va * dt;
        m.life += dt;
        if (m.r < 104) {
          st.motes.splice(i, 1);
          continue;
        }
        const x1 = Math.cos(m.a) * m.r;
        const y1 = Math.sin(m.a) * m.r;
        const alpha = Math.min(1, m.life * 2.5) * Math.min(1, (m.r - 104) / 50) * (dark ? 0.9 : 0.6);
        const c = dark ? m.rgb : inkOf(m.rgb);
        ctx.strokeStyle = `rgb(${c} / ${alpha * 0.6})`;
        ctx.lineWidth = m.size;
        ctx.beginPath();
        ctx.moveTo(x0 - (x1 - x0) * 2, y0 - (y1 - y0) * 2);
        ctx.lineTo(x1, y1);
        ctx.stroke();
        ctx.fillStyle = `rgb(${c} / ${alpha})`;
        ctx.beginPath();
        ctx.arc(x1, y1, m.size, 0, Math.PI * 2);
        ctx.fill();
      }

      // Creation bursts
      for (let i = st.rings.length - 1; i >= 0; i--) {
        const r = st.rings[i];
        r.t += dt;
        const n = st.nodes.get(r.id);
        if (!n || r.t > 1.1) {
          st.rings.splice(i, 1);
          continue;
        }
        const p = posOf(n);
        const q = r.t / 1.1;
        const ez = 1 - Math.pow(1 - q, 3);
        const c = dark ? r.rgb : inkOf(r.rgb);
        ctx.strokeStyle = `rgb(${c} / ${(1 - q) * 0.9})`;
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.arc(p.x, p.y, 8 + ez * 100, 0, Math.PI * 2);
        ctx.stroke();
      }
      const drag = Math.exp(-dt * 3.2);
      for (let i = st.sparks.length - 1; i >= 0; i--) {
        const s = st.sparks[i];
        s.x += s.vx * dt;
        s.y += s.vy * dt;
        s.vx *= drag;
        s.vy *= drag;
        s.life -= dt * 1.1;
        if (s.life <= 0) {
          st.sparks.splice(i, 1);
          continue;
        }
        const c = dark ? s.rgb : inkOf(s.rgb === "255 255 255" ? "167 139 250" : s.rgb);
        ctx.fillStyle = `rgb(${c} / ${s.life})`;
        ctx.beginPath();
        ctx.arc(s.x, s.y, 0.6 + s.life * 1.8, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.globalCompositeOperation = "source-over";
    };
    raf = requestAnimationFrame(loop);

    const onWheel = (ev: WheelEvent) => {
      ev.preventDefault();
      const k0 = st.cam.k;
      const k1 = clamp(k0 * Math.exp(-ev.deltaY * (ev.ctrlKey ? 0.012 : 0.0016)), 0.3, 3);
      const vc = viewCenter();
      const ox = vc.x - st.cam.x * k0;
      const oy = vc.y - st.cam.y * k0;
      const wx = (ev.clientX - ox) / k0;
      const wy = (ev.clientY - oy) / k0;
      st.cam.k = st.target.k = k1;
      st.cam.x = st.target.x = (vc.x - (ev.clientX - wx * k1)) / k1;
      st.cam.y = st.target.y = (vc.y - (ev.clientY - wy * k1)) / k1;
      st.follow = null;
    };
    stage.addEventListener("wheel", onWheel, { passive: false });

    return () => {
      cancelAnimationFrame(raf);
      ro.disconnect();
      stage.removeEventListener("wheel", onWheel);
      for (const id of st.flashTimers.values()) window.clearTimeout(id);
    };
  }, [fitK]);

  /* ───────────── Pointer: drag branches, pan space ───────────── */
  const toWorld = (clientX: number, clientY: number) => {
    const st = S.current;
    const vc = { x: st.insets.l + (st.W - st.insets.l - st.insets.r) / 2, y: st.insets.t + (st.H - st.insets.t - st.insets.b) / 2 };
    return { x: (clientX - vc.x) / st.cam.k + st.cam.x, y: (clientY - vc.y) / st.cam.k + st.cam.y };
  };

  const selectNode = useCallback(
    (id: string) => {
      const n = S.current.nodes.get(id);
      if (!n) return;
      if (n.type === "core") select({ level: "core" });
      else if (n.type === "game") select({ level: "game", gameId: n.gameId });
      else if (n.type === "category") select({ level: "category", gameId: n.gameId, category: n.category });
      else if (n.type === "mod") select({ level: "mod", gameId: n.gameId, category: n.category, modId: n.modId }, { openPanel: true });
      else {
        select({ level: "category", gameId: n.gameId, category: n.category }, { openPanel: n.hidden > 0 });
        if (!n.hidden) focusPrompt();
      }
    },
    [select, focusPrompt],
  );

  const onNodeDown = useCallback((e: RPointerEvent, id: string) => {
    if (e.button !== 0) return;
    e.stopPropagation();
    const st = S.current;
    const n = st.nodes.get(id);
    if (!n) return;
    // Pills ride on their category: grabbing one drags the whole list.
    const grab = n.type === "mod" || n.type === "more" ? st.nodes.get(n.parent!)! : n;
    const w = toWorld(e.clientX, e.clientY);
    st.drag = { id: grab.id, sx: e.clientX, sy: e.clientY, ox: grab.x - w.x, oy: grab.y - w.y, moved: false };
    (st as { clickId?: string }).clickId = id;
    stageRef.current?.setPointerCapture(e.pointerId);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const onStageDown = (e: RPointerEvent) => {
    if (e.button !== 0) return;
    const st = S.current;
    st.pan = { sx: e.clientX, sy: e.clientY, cx: st.cam.x, cy: st.cam.y, moved: false };
    stageRef.current?.setPointerCapture(e.pointerId);
  };

  const onStageMove = (e: RPointerEvent) => {
    const st = S.current;
    if (st.drag) {
      const d = st.drag;
      if (!d.moved && Math.hypot(e.clientX - d.sx, e.clientY - d.sy) > 4) {
        d.moved = true;
        nodeEls.current.get(d.id)?.classList.add("is-dragging");
      }
      if (d.moved) {
        const n = st.nodes.get(d.id);
        const w = toWorld(e.clientX, e.clientY);
        if (n) {
          const nx = w.x + d.ox;
          const ny = w.y + d.oy;
          n.vx = (nx - n.x) * 30;
          n.vy = (ny - n.y) * 30;
          n.x = nx;
          n.y = ny;
        }
      }
      return;
    }
    if (st.pan) {
      const p = st.pan;
      const dx = e.clientX - p.sx;
      const dy = e.clientY - p.sy;
      if (!p.moved && Math.hypot(dx, dy) > 3) {
        p.moved = true;
        st.follow = null;
        stageRef.current?.classList.add("is-panning");
      }
      if (p.moved) {
        st.cam.x = st.target.x = p.cx - dx / st.cam.k;
        st.cam.y = st.target.y = p.cy - dy / st.cam.k;
      }
    }
  };

  const onStageUp = (e: RPointerEvent) => {
    const st = S.current;
    stageRef.current?.releasePointerCapture?.(e.pointerId);
    if (st.drag) {
      const d = st.drag;
      const n = st.nodes.get(d.id);
      if (d.moved && n) {
        // The branch stays where it was dropped: its new home is relative to its parent.
        const p = st.nodes.get(n.parent!)!;
        n.hx = n.x - p.x;
        n.hy = n.y - p.y;
        nodeEls.current.get(d.id)?.classList.remove("is-dragging");
      } else {
        selectNode((st as { clickId?: string }).clickId ?? d.id);
      }
      st.drag = null;
    }
    if (st.pan) {
      st.pan = null;
      stageRef.current?.classList.remove("is-panning");
    }
  };

  const setRef = useCallback((id: string, el: HTMLDivElement | null) => {
    if (el) nodeEls.current.set(id, el);
    else nodeEls.current.delete(id);
  }, []);

  const onHover = useCallback((id: string | null) => {
    S.current.hovered = id;
  }, []);

  const selectedId = selectedNodeId(selection);

  return (
    <div
      ref={stageRef}
      className="stage"
      data-zoom="far"
      onPointerDown={onStageDown}
      onPointerMove={onStageMove}
      onPointerUp={onStageUp}
      onPointerCancel={onStageUp}
    >
      <canvas ref={canvasRef} />
      <div ref={worldRef} className="world">
        <CyrusCore coreRef={coreRef} rippleRef={rippleRef} statusRef={statusRef} onActivate={() => select({ level: "core" })} />
        {graph.nodes
          .filter((n) => n.type !== "core")
          .map((n) => (
            <NodeView
              key={n.id}
              n={n}
              state={nodeStates.get(n.id) ?? "on"}
              selected={selectedId === n.id}
              forging={forgingId === n.id}
              isNew={!initialIds.current!.has(n.id)}
              setRef={setRef}
              onDown={onNodeDown}
              onHover={onHover}
              onKeySelect={selectNode}
            />
          ))}
      </div>
    </div>
  );
}

function Cube() {
  return (
    <svg viewBox="0 0 16 16" className="cube" aria-hidden>
      <path d="M8 1.5 14 4.8v6.4L8 14.5 2 11.2V4.8Z" fill="currentColor" fillOpacity="0.18" stroke="currentColor" strokeWidth="1.2" strokeLinejoin="round" />
      <path d="M2 4.8 8 8l6-3.2M8 8v6.5" fill="none" stroke="currentColor" strokeWidth="1.2" strokeLinejoin="round" />
      <path d="M8 1.5 14 4.8 8 8 2 4.8Z" fill="currentColor" fillOpacity="0.45" />
    </svg>
  );
}

const NodeView = memo(function NodeView({
  n,
  state,
  selected,
  forging,
  isNew,
  setRef,
  onDown,
  onHover,
  onKeySelect,
}: {
  n: LNode;
  state: NodeState;
  selected: boolean;
  forging: boolean;
  isNew: boolean;
  setRef: (id: string, el: HTMLDivElement | null) => void;
  onDown: (e: RPointerEvent, id: string) => void;
  onHover: (id: string | null) => void;
  onKeySelect: (id: string) => void;
}) {
  const kind = n.type === "category" ? "cat" : n.type === "game" ? "game" : "pill";
  const cls = ["node", "tint", `n-${kind}`, n.type === "more" && "is-more", selected && "is-selected", forging && "is-forging", isNew && "is-new"]
    .filter(Boolean)
    .join(" ");
  const handlers = {
    onPointerDown: (e: RPointerEvent) => onDown(e, n.id),
    onPointerEnter: () => onHover(n.id),
    onPointerLeave: () => onHover(null),
    onClick: (e: React.MouseEvent) => {
      // Mouse clicks resolve on pointer-up (so drags don't select); this handles keyboard activation.
      if (e.detail === 0) onKeySelect(n.id);
    },
  };
  const style = { ["--c" as string]: n.rgb, ["--d" as string]: `${0.5 + (n.row ?? 0) * 0.06}s` };

  if (n.type === "game") {
    return (
      <div ref={(el) => setRef(n.id, el)} className={cls} data-state={state} style={style}>
        <div className="g-glow" />
        <button type="button" className="g-orb" aria-label={`Game: ${n.label}`} {...handlers}>
          {n.gameId && <GameEmblem emblem={GAME_BY_ID[n.gameId].emblem} />}
        </button>
        <div className="g-name">{GAME_BY_ID[n.gameId!].short}</div>
      </div>
    );
  }
  if (n.type === "category") {
    return (
      <div ref={(el) => setRef(n.id, el)} className={cls} data-state={state} data-side={n.side} style={style}>
        <button type="button" className="c-orb" aria-label={`Category: ${n.label}`} {...handlers}>
          {n.category && <CategoryIcon k={n.category} />}
        </button>
        <div className="c-label">{n.label}</div>
      </div>
    );
  }
  return (
    <div ref={(el) => setRef(n.id, el)} className={cls} data-state={state} data-side={n.side} style={style}>
      <button type="button" className="pill" aria-label={n.type === "more" ? n.label : `Mod: ${n.label}`} {...handlers}>
        {n.type === "more" ? <span className="dots">{n.hidden ? "···" : "+"}</span> : <Cube />}
        <span className="txt">{n.label}</span>
      </button>
    </div>
  );
});

