  pointer-events: none;
  background:
    radial-gradient(90% 70% at 50% 46%, #0d1030 0%, #080a1f 38%, #04050f 72%, #020309 100%),
    var(--bg);
}
.light .cosmos {
  background:
    radial-gradient(110% 85% at 50% 46%, #ffffff 0%, #fafaff 50%, #f1efff 100%),
    var(--bg);
}

/* Smoky nebula ribbons in the corners. Transform-only drift keeps them on the compositor. */
.wisp {
  position: absolute;
  border-radius: 50%;
  filter: blur(48px);
  opacity: 0.55;
  will-change: transform;
  animation: wisp-drift 70s ease-in-out infinite alternate;
}
.wisp.thin {
  filter: blur(16px);
  opacity: 0.4;
}
.light .wisp {
  opacity: 0.2;
}
.light .wisp.thin {
  opacity: 0.14;
}

.vignette {
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 50% 48%, transparent 50%, rgb(1 1 5 / 0.7) 100%);
}
.light .vignette {
  background: radial-gradient(ellipse at 50% 50%, transparent 60%, rgb(124 58 237 / 0.05) 100%);
}

/* ───────────────────────── Network stage ───────────────────────── */

.stage {
  position: absolute;
  inset: 0;
  overflow: hidden;
  touch-action: none;
  cursor: grab;
  user-select: none;
}
.stage.is-panning {
  cursor: grabbing;
}
.stage canvas {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.world {
  position: absolute;
  left: 0;
  top: 0;
  width: 0;
  height: 0;
  transform-origin: 0 0;
  opacity: 0;
  transition: opacity 1.2s ease;
}
.world.is-ready {
  opacity: 1;
}

.node {
  position: absolute;
  left: 0;
  top: 0;
  width: 0;
  height: 0;
  /* Each node floats every frame; its own GPU layer means moving it never repaints its glow. */
  will-change: transform;
  transition:
    opacity 0.6s ease,
    filter 0.6s ease;
}
.node[data-state="off"] {
  opacity: 0.12;
  filter: saturate(0.3);
}
.node[data-state="near"] {
  opacity: 0.5;
}
.node.is-dragging {
  z-index: 20;
}
.node.is-new {
  animation: materialize 1.1s var(--ease-out-expo) both;
}

/* Game — big neon-ringed disc with its name on a pill */
.g-glow {
  position: absolute;
  width: 260px;
  height: 260px;
  left: -130px;
  top: -130px;
  border-radius: 50%;
  pointer-events: none;
  background: radial-gradient(circle, rgb(var(--c) / 0.3), rgb(var(--c) / 0.08) 40%, transparent 66%);
}
.light .g-glow {
  background: radial-gradient(circle, rgb(var(--c) / 0.18), rgb(var(--c) / 0.05) 42%, transparent 66%);
}
.g-orb {
  position: absolute;
  width: 108px;
  height: 108px;
  left: -54px;
  top: -54px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  cursor: pointer;
  outline: none;
  color: var(--cc-ink);
  background:
    radial-gradient(circle at 50% 30%, rgb(var(--c) / 0.22), transparent 55%),
    radial-gradient(circle at 50% 50%, #0d0f2a 0%, #06071a 80%);
  border: 2.5px solid rgb(var(--c));
  box-shadow:
    0 0 12px rgb(var(--c) / 0.95),
    0 0 40px rgb(var(--c) / 0.45),
    inset 0 0 24px rgb(var(--c) / 0.4);
  transition: transform 0.45s var(--ease-spring);
}
.g-orb svg {
  width: 48px;
  height: 48px;
  margin-top: -14px;
  filter: drop-shadow(0 0 8px rgb(var(--c) / 0.9));
}
.g-name {
  position: absolute;
  left: 0;
  top: 26px;
  translate: -50% 0;
  padding: 3px 14px 4px;
  border-radius: 999px;
  background: rgb(6 7 20 / 0.92);
  border: 1px solid rgb(var(--c) / 0.55);
  box-shadow: 0 0 14px rgb(var(--c) / 0.3);
  font-family: var(--font-space), sans-serif;
  font-size: 15px;
  font-weight: 600;
  color: #fff;
  white-space: nowrap;
  pointer-events: none;
}

/* Category — smaller ringed disc, label pill on the side facing its game */
.c-orb {
  position: absolute;
  width: 56px;
  height: 56px;
  left: -28px;
  top: -28px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  cursor: pointer;
  outline: none;
  color: var(--cc-ink);
  background: radial-gradient(circle at 50% 40%, rgb(var(--c) / 0.2), #070818 70%);
  border: 2px solid rgb(var(--c));
  box-shadow:
    0 0 9px rgb(var(--c) / 0.9),
    0 0 24px rgb(var(--c) / 0.35),
    inset 0 0 12px rgb(var(--c) / 0.32);
  transition: transform 0.45s var(--ease-spring);
}
.c-orb svg {
  width: 26px;
  height: 26px;
  filter: drop-shadow(0 0 5px rgb(var(--c) / 0.85));
}
.c-label {
  position: absolute;
  top: 0;
  padding: 4px 12px 5px;
  border-radius: 999px;
  background: rgb(6 7 20 / 0.9);
  border: 1px solid rgb(var(--c) / 0.35);
  font-family: var(--font-space), sans-serif;
  font-size: 13px;
  font-weight: 600;
  color: #fff;
  white-space: nowrap;
  pointer-events: none;
  translate: 0 -50%;
}
.n-cat[data-side="left"] .c-label {
  left: 36px;
}
.n-cat[data-side="right"] .c-label {
  left: -36px;
  translate: -100% -50%;
}
.n-cat[data-side="up"] .c-label {
  top: 36px;
  left: 0;
  translate: -50% 0;
}
.n-cat[data-side="down"] .c-label {
  top: -36px;
  left: 0;
  translate: -50% -100%;
}

.node:hover .g-orb,
.node:hover .c-orb,
.g-orb:focus-visible,
.c-orb:focus-visible {
  transform: scale(1.08);
}
.node.is-dragging .g-orb,
.node.is-dragging .c-orb {
  transform: scale(1.12);
  cursor: grabbing;
}
.node.is-selected .g-orb,
.node.is-selected .c-orb {
  box-shadow:
    0 0 0 4px rgb(var(--c) / 0.22),
    0 0 18px rgb(var(--c)),
    0 0 60px rgb(var(--c) / 0.55),
    inset 0 0 24px rgb(var(--c) / 0.5);
}
.node.is-hit .g-orb,
.node.is-hit .c-orb,
.node.is-hit .pill {
  animation: node-hit 0.55s var(--ease-out-expo);
}

/* Mod — a pill in the category's list */
.pill {
  position: absolute;
  left: 0;
  top: 0;
  display: flex;
  align-items: center;
  gap: 7px;
  height: 25px;
  max-width: 200px;
  padding: 0 11px 0 7px;
  border-radius: 8px;
  background: rgb(8 9 28 / 0.86);
  border: 1px solid rgb(var(--c) / 0.26);
  font-size: 12px;
  font-weight: 500;
  color: var(--ink-2);
  white-space: nowrap;
  cursor: pointer;
  outline: none;
  transition:
    border-color 0.2s,
    box-shadow 0.2s,
    background-color 0.2s,
    color 0.2s;
}
.pill .txt {
  overflow: hidden;
  text-overflow: ellipsis;
}
.n-pill[data-side="left"] .pill {
  translate: -100% -50%;
}
.n-pill[data-side="right"] .pill {
  translate: 0 -50%;
}
.n-pill[data-side="up"] .pill,
.n-pill[data-side="down"] .pill {
  translate: -50% -50%;
}
.pill .cube {
  width: 15px;
  height: 15px;
  flex: none;
  color: rgb(var(--c));
  filter: drop-shadow(0 0 4px rgb(var(--c) / 0.7));
}
.pill .dots {
  width: 15px;
  text-align: center;
  font-weight: 700;
  letter-spacing: -1px;
  color: rgb(var(--c));
}
.n-pill.is-more .pill {
  color: var(--muted);
  font-size: 11.5px;
  border-style: dashed;
}
.pill:hover,
.pill:focus-visible {
  color: var(--ink);
  border-color: rgb(var(--c) / 0.75);
  box-shadow: 0 0 14px rgb(var(--c) / 0.35);
}
.n-pill.is-selected .pill {
  color: #fff;
  background: rgb(var(--c) / 0.16);
  border-color: rgb(var(--c));
  box-shadow:
    0 0 0 1px rgb(var(--c) / 0.4),
    0 0 18px rgb(var(--c) / 0.55);
}
.n-pill.is-forging .pill {
  animation: pill-forge 1s ease-in-out infinite;
}

/* Light mode nodes: white discs with coloured rings, no neon bloom. */
.light .g-orb {
  background:
    radial-gradient(circle at 50% 30%, rgb(var(--c) / 0.16), transparent 60%),
    #ffffff;
  border-color: color-mix(in oklab, rgb(var(--c)) 80%, #1b1236);
  box-shadow:
    0 12px 30px -10px rgb(var(--c) / 0.6),
    0 0 0 6px rgb(var(--c) / 0.1);
}
.light .c-orb {
  background: radial-gradient(circle at 50% 35%, rgb(var(--c) / 0.14), #ffffff 70%);
  border-color: color-mix(in oklab, rgb(var(--c)) 80%, #1b1236);
  box-shadow:
    0 8px 20px -8px rgb(var(--c) / 0.6),
    0 0 0 4px rgb(var(--c) / 0.08);
}
.light .g-orb svg,
.light .c-orb svg,
.light .pill .cube {
  filter: none;
}
.light .g-name,
.light .c-label {
  background: #ffffff;
  color: var(--ink);
  border-color: rgb(var(--c) / 0.5);
  box-shadow: 0 4px 14px -6px rgb(var(--c) / 0.5);
}
.light .pill {
  background: rgb(255 255 255 / 0.92);
  border-color: rgb(var(--c) / 0.35);
}
.light .pill .cube,
.light .pill .dots {
  color: color-mix(in oklab, rgb(var(--c)) 78%, #1b1236);
}
.light .n-pill.is-selected .pill {
  color: var(--ink);
  background: rgb(var(--c) / 0.12);
}
.light .node.is-selected .g-orb,
.light .node.is-selected .c-orb {
  box-shadow:
    0 0 0 4px rgb(var(--c) / 0.25),
    0 14px 34px -8px rgb(var(--c) / 0.7);
}

/* ───────────────────────── Cyrus Core ───────────────────────── */

.core {
  --h-violet: #c4b5fd;
  --h-cyan: #67e8f9;
  --h-indigo: #a5b4fc;
  --h-pink: #f0abfc;
  --h-sat: #ffffff;
  --rim: conic-gradient(from 0deg, #22d3ee, #3b82f6, #8b5cf6, #d946ef, #ec4899, #a855f7, #3b82f6, #22d3ee);
  position: absolute;
  left: 0;
  top: 0;
  width: 0;
  height: 0;
  --e: 0;
  --p: 0;
  --f: 0;
}
.light .core {
  --h-violet: #7c3aed;
  --h-cyan: #0891b2;
  --h-indigo: #4f46e5;
  --h-pink: #c026d3;
  --h-sat: #4c1d95;
}
.core > * {
  position: absolute;
  left: 50%;
  top: 50%;
  translate: -50% -50%;
  pointer-events: none;
}

.core-aura {
  width: 520px;
  height: 520px;
  border-radius: 50%;
  background: radial-gradient(
    circle,
    rgb(139 92 246 / 0.34) 0%,
    rgb(59 130 246 / 0.16) 26%,
    rgb(236 72 153 / 0.07) 42%,
    transparent 64%
  );
  opacity: calc(0.75 + var(--e) * 0.25 + var(--p) * 0.25);
  transform: scale(calc(0.95 + var(--e) * 0.12 + var(--p) * 0.1));
  will-change: transform, opacity;
}
.light .core-aura {
  background: radial-gradient(
    circle,
    rgb(167 139 250 / 0.3) 0%,
    rgb(96 165 250 / 0.12) 28%,
    rgb(236 72 153 / 0.05) 44%,
    transparent 64%
  );
}

.core-halo {
  width: var(--hs);
  height: var(--hs);
  opacity: calc(0.45 + var(--e) * 0.5);
}
.core-halo .plane {
  width: 100%;
  height: 100%;
  will-change: transform;
}
.core-halo.back {
  clip-path: inset(0 0 50% 0);
}
.core-halo.front {
  clip-path: inset(50% 0 0 0);
}

.core-rim-glow {
  width: 228px;
  height: 228px;
  border-radius: 50%;
  background: var(--rim);
  filter: blur(14px);
  opacity: calc(0.6 + var(--e) * 0.4 + var(--p) * 0.3);
  -webkit-mask: radial-gradient(circle, transparent 36%, #000 50%, #000 60%, transparent 72%);
  mask: radial-gradient(circle, transparent 36%, #000 50%, #000 60%, transparent 72%);
  will-change: transform;
}
.light .core-rim-glow {
  opacity: calc(0.35 + var(--e) * 0.35);
}

.core-orb {
  width: 196px;
  height: 196px;
  border-radius: 50%;
  overflow: hidden;
  background: radial-gradient(circle at 46% 36%, #1d2160 0%, #0d0e30 42%, #06061a 72%, #030310 100%);
  box-shadow:
    inset 0 0 44px rgb(99 102 241 / 0.45),
    inset 0 -24px 50px rgb(236 72 153 / 0.14);
  transform: scale(calc(1 + var(--p) * 0.03 + var(--e) * 0.02));
  will-change: transform;
}
.light .core-orb {
  background: radial-gradient(circle at 46% 36%, #ffffff 0%, #f3f0ff 45%, #e4ddff 80%, #d6ccff 100%);
  box-shadow:
    inset 0 0 40px rgb(124 58 237 / 0.22),
    inset 0 -24px 50px rgb(236 72 153 / 0.1);
}
.core-orb > * {
  position: absolute;
}
.core-nebula {
  inset: -20%;
  background:
    radial-gradient(circle at 28% 68%, rgb(59 130 246 / 0.32), transparent 40%),
    radial-gradient(circle at 72% 30%, rgb(168 85 247 / 0.34), transparent 40%),
    radial-gradient(circle at 62% 78%, rgb(236 72 153 / 0.2), transparent 36%),
    radial-gradient(circle at 34% 26%, rgb(34 211 238 / 0.14), transparent 30%);
  filter: blur(8px);
  opacity: calc(0.8 + var(--e) * 0.2);
  will-change: transform;
}
.light .core-nebula {
  opacity: 0.45;
}
.core-specks {
  inset: 0;
  width: 100%;
  height: 100%;
}
.light .core-specks {
  display: none;
}
.core-glint {
  inset: 0;
  border-radius: 50%;
  background:
    radial-gradient(ellipse 46% 26% at 40% 16%, rgb(255 255 255 / 0.16), transparent 70%),
    radial-gradient(circle at 50% 50%, transparent 62%, rgb(2 2 12 / 0.6) 100%);
}
.light .core-glint {
  background: radial-gradient(ellipse 46% 26% at 40% 16%, rgb(255 255 255 / 0.9), transparent 70%);
}
.core-brand {
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 4px;
  padding-top: 4px;
}
.core-logo {
  font-size: 58px;
  filter: drop-shadow(0 0 12px rgb(139 92 246 / 0.8)) drop-shadow(0 0 2px rgb(103 232 249 / 0.6));
}
.core-brand span {
  font-family: var(--font-space), sans-serif;
  font-size: 30px;
  font-weight: 600;
  letter-spacing: -0.01em;
  color: #fff;
  text-shadow: 0 0 18px rgb(167 139 250 / 0.9);
}
.light .core-logo {
  filter: drop-shadow(0 4px 10px rgb(124 58 237 / 0.35));
}
.light .core-brand span {
  color: var(--ink);
  text-shadow: none;
}

.core-rim {
  width: 204px;
  height: 204px;
  border-radius: 50%;
  background: var(--rim);
  -webkit-mask: radial-gradient(circle, transparent calc(50% - 4.5px), #000 calc(50% - 3.5px), #000 calc(50% - 0.5px), transparent 50%);
  mask: radial-gradient(circle, transparent calc(50% - 4.5px), #000 calc(50% - 3.5px), #000 calc(50% - 0.5px), transparent 50%);
  will-change: transform;
}

.core-sparks {
  width: 240px;
  height: 240px;
  overflow: visible;
  opacity: calc(0.55 + var(--e) * 0.45);
  will-change: transform;
}
.core-sparks .spark {
  filter: drop-shadow(0 0 3px currentColor);
  animation: spark-flicker 2.2s steps(1) infinite;
}
.light .core-sparks {
  opacity: 0.4;
}

.core-hit {
  width: 200px;
  height: 200px;
  border-radius: 50%;
  pointer-events: auto !important;
  cursor: pointer;
}

.core-ripples > span {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 204px;
  height: 204px;
  margin: -102px 0 0 -102px;
  border-radius: 50%;
  border: 1.5px solid rgb(167 139 250 / 0.8);
  box-shadow:
    0 0 16px rgb(139 92 246 / 0.55),
    inset 0 0 14px rgb(103 232 249 / 0.3);
  animation: ripple 1.3s var(--ease-out-expo) forwards;
}
.core-ripples > span.big {
  border-color: rgb(236 72 153 / 0.8);
  animation-duration: 1.9s;
}
.light .core-ripples > span {
  border-color: rgb(124 58 237 / 0.55);
  box-shadow: 0 0 12px rgb(124 58 237 / 0.2);
}

.core-label {
  top: calc(50% + 124px) !important;
  display: flex;
  flex-direction: column;
  align-items: center;
  white-space: nowrap;
}
.core-label .s {
  font-family: var(--font-jb), monospace;
  font-size: 10.5px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--muted);
}

@keyframes wisp-drift {
  0% { transform: rotate(var(--r, 0deg)) translate3d(0, 0, 0) scale(1); }
  100% { transform: rotate(var(--r, 0deg)) translate3d(3%, -2%, 0) scale(1.06); }
}
@keyframes pill-forge {
  0%, 100% { box-shadow: 0 0 0 1px rgb(var(--c) / 0.4), 0 0 10px rgb(var(--c) / 0.4); }
  50% { box-shadow: 0 0 0 1px rgb(var(--c)), 0 0 26px rgb(var(--c) / 0.85); }
}
@keyframes spark-flicker {
  0%, 100% { opacity: 1; }
  12% { opacity: 0.15; }
  20% { opacity: 0.9; }
  46% { opacity: 0; }
  58% { opacity: 0.8; }
  80% { opacity: 0.3; }
}

