"use client";

import type { Ref } from "react";
import { CyrusLogo } from "@/components/icons/CyrusLogo";

/** A scatter of faint stars inside the sphere. Fixed positions keep SSR and client identical. */
function Specks() {
  const pts = [
    [58, 52, 1.1], [138, 58, 0.7], [44, 118, 0.8], [152, 128, 1], [94, 30, 0.6], [120, 164, 0.7],
    [66, 152, 0.9], [34, 84, 0.6], [164, 90, 0.8], [130, 38, 0.6], [80, 78, 0.5], [112, 122, 0.5],
    [150, 160, 0.6], [48, 168, 0.5], [172, 116, 0.5], [24, 128, 0.6],
  ];
  return (
    <svg className="core-specks" viewBox="0 0 196 196" aria-hidden>
      {pts.map(([x, y, r], i) => (
        <circle key={i} cx={x} cy={y} r={r} fill="#fff" opacity={0.2 + (i % 5) * 0.12} />
      ))}
    </svg>
  );
}

/**
 * The Cyrus Core's DOM half: the glassy sphere, its neon rim, logo and status. The electric
 * corona, orbiting halo lights and ripples' energy are drawn on the network canvas underneath,
 * so they can react to typing and forging every frame without restyling the DOM.
 */
export function CyrusCore({
  coreRef,
  rippleRef,
  statusRef,
  onActivate,
}: {
  coreRef: Ref<HTMLDivElement>;
  rippleRef: Ref<HTMLDivElement>;
  statusRef: Ref<HTMLSpanElement>;
  onActivate: () => void;
}) {
  return (
    <div className="core" ref={coreRef} data-id="core">
      <div className="core-ripples" ref={rippleRef} />
      <div className="core-rim-glow" />
      <div className="core-orb">
        <div className="core-nebula" data-spin="4" />
        <Specks />
        <div className="core-shade" />
        <div className="core-brand">
          <CyrusLogo id="core-logo" className="core-logo" />
          <span>Cyrus</span>
        </div>
      </div>
      <div className="core-rim" />
      <button
        type="button"
        className="core-hit"
        aria-label="Cyrus Core — return to overview"
        onClick={onActivate}
        onPointerDown={(e) => e.stopPropagation()}
      />
      <div className="core-label">
        <span className="s" ref={statusRef}>
          online
        </span>
      </div>
    </div>
  );
}

