p = "app/network.css"
s = open(p, encoding="utf-8").read()
start = s.index("/* ───────────────────────── Cyrus Core ───────────────────────── */")
end = s.index("@keyframes wisp-drift")
core = """/* ───────────────────────── Cyrus Core ───────────────────────── */

.core {
  /* Angular colour map shared with the canvas corona: violet top, pink right, cyan left. */
  --rim: conic-gradient(
    from 0deg,
    #8b5cf6 0deg,
    #d946ef 45deg,
    #ec4899 90deg,
    #c026d3 135deg,
    #7c3aed 180deg,
    #3b82f6 225deg,
    #22d3ee 270deg,
    #3b82f6 315deg,
    #8b5cf6 360deg
  );
  position: absolute;
  left: 0;
  top: 0;
  width: 0;
  height: 0;
  --e: 0;
  --p: 0;
  --f: 0;
}
.core > * {
  position: absolute;
  left: 50%;
  top: 50%;
  translate: -50% -50%;
  pointer-events: none;
}

.core-rim-glow {
  width: 248px;
  height: 248px;
  border-radius: 50%;
  background: var(--rim);
  filter: blur(9px);
  -webkit-mask: radial-gradient(circle, transparent 36%, #000 40%, #000 45%, transparent 56%);
  mask: radial-gradient(circle, transparent 36%, #000 40%, #000 45%, transparent 56%);
  opacity: calc(0.75 + var(--e) * 0.15 + var(--p) * 0.25);
}
.light .core-rim-glow {
  opacity: calc(0.4 + var(--p) * 0.2);
}

.core-orb {
  width: 198px;
  height: 198px;
  border-radius: 50%;
  overflow: hidden;
  background: radial-gradient(circle at 50% 36%, #1c1f52 0%, #0e1033 36%, #070819 66%, #030309 100%);
  box-shadow:
    inset 0 0 0 1px rgb(255 255 255 / 0.06),
    inset 0 0 40px rgb(0 0 0 / 0.55);
  transform: scale(calc(1 + var(--p) * 0.025 + var(--e) * 0.006));
  will-change: transform;
}
.light .core-orb {
  background: radial-gradient(circle at 50% 36%, #ffffff 0%, #f5f2ff 40%, #e7e0ff 75%, #d9cffd 100%);
  box-shadow:
    inset 0 0 0 1px rgb(124 58 237 / 0.12),
    inset 0 -18px 40px rgb(124 58 237 / 0.16);
}
.core-orb > * {
  position: absolute;
}
.core-nebula {
  inset: -18%;
  background:
    radial-gradient(ellipse 45% 30% at 30% 66%, rgb(59 130 246 / 0.34), transparent 70%),
    radial-gradient(ellipse 40% 34% at 70% 34%, rgb(147 51 234 / 0.34), transparent 70%),
    radial-gradient(ellipse 36% 26% at 64% 76%, rgb(219 39 119 / 0.22), transparent 70%),
    radial-gradient(ellipse 30% 22% at 32% 28%, rgb(34 211 238 / 0.16), transparent 70%);
  filter: blur(10px);
  will-change: transform;
}
.light .core-nebula {
  opacity: 0.4;
}
.core-specks {
  inset: 0;
  width: 100%;
  height: 100%;
}
.light .core-specks {
  display: none;
}
/* Sphere shading: a soft top light and darker limbs, so it reads as a ball, not a disc. */
.core-shade {
  inset: 0;
  border-radius: 50%;
  background:
    radial-gradient(ellipse 60% 38% at 50% 14%, rgb(255 255 255 / 0.1), transparent 70%),
    radial-gradient(circle at 50% 46%, transparent 56%, rgb(1 1 8 / 0.7) 100%);
}
.light .core-shade {
  background: radial-gradient(ellipse 60% 38% at 50% 14%, rgb(255 255 255 / 0.95), transparent 70%);
}
.core-brand {
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;
  padding-top: 2px;
}
.core-logo {
  font-size: 66px;
  filter: drop-shadow(0 0 10px rgb(139 92 246 / 0.75)) drop-shadow(0 0 22px rgb(59 130 246 / 0.35));
}
.core-brand span {
  font-family: var(--font-space), sans-serif;
  font-size: 32px;
  font-weight: 700;
  letter-spacing: -0.015em;
  line-height: 1;
  color: #fff;
  text-shadow: 0 0 16px rgb(167 139 250 / 0.75);
}
.light .core-logo {
  filter: drop-shadow(0 4px 10px rgb(124 58 237 / 0.3));
}
.light .core-brand span {
  color: var(--ink);
  text-shadow: none;
}

.core-rim {
  width: 204px;
  height: 204px;
  border-radius: 50%;
  background: var(--rim);
  -webkit-mask: radial-gradient(circle, transparent calc(50% - 3.5px), #000 calc(50% - 3px), #000 calc(50% - 0.5px), transparent 50%);
  mask: radial-gradient(circle, transparent calc(50% - 3.5px), #000 calc(50% - 3px), #000 calc(50% - 0.5px), transparent 50%);
}

.core-hit {
  width: 204px;
  height: 204px;
  border-radius: 50%;
  pointer-events: auto !important;
  cursor: pointer;
}

.core-ripples > span {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 204px;
  height: 204px;
  margin: -102px 0 0 -102px;
  border-radius: 50%;
  border: 1.5px solid rgb(167 139 250 / 0.75);
  box-shadow: 0 0 14px rgb(139 92 246 / 0.5);
  animation: ripple 1.3s var(--ease-out-expo) forwards;
}
.core-ripples > span.soft {
  border-color: rgb(167 139 250 / 0.3);
  box-shadow: 0 0 10px rgb(139 92 246 / 0.22);
  animation: ripple-soft 1.6s var(--ease-out-expo) forwards;
}
.core-ripples > span.big {
  border-color: rgb(236 72 153 / 0.75);
  animation-duration: 1.9s;
}
.light .core-ripples > span {
  border-color: rgb(124 58 237 / 0.5);
  box-shadow: 0 0 12px rgb(124 58 237 / 0.18);
}

.core-label {
  top: calc(50% + 132px) !important;
  display: flex;
  flex-direction: column;
  align-items: center;
  white-space: nowrap;
}
.core-label .s {
  font-family: var(--font-jb), monospace;
  font-size: 10.5px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--muted);
}

@keyframes ripple-soft {
  0% { transform: scale(0.98); opacity: 0.7; }
  100% { transform: scale(1.45); opacity: 0; }
}

"""
s = s[:start] + core + s[end:]
# the old ripple-soft keyframe now lives in the core block
first = s.index("@keyframes ripple-soft")
second = s.find("@keyframes ripple-soft", first + 10)
if second != -1:
    block_end = s.index("}\n}\n", second) + 4
    s = s[:second] + s[block_end:]
open(p, "w", encoding="utf-8").write(s)
print("css ok")

