rep("""const SPRING = 95;
const DAMP = 13;""", """const SPRING = 95;
const DAMP = 13;
/** Keep-out radius around the core for each node type (core rim + node radius + breathing room). */
const CORE_CLEAR = { game: RADIUS.core + RADIUS.game + 36, category: RADIUS.core + RADIUS.category + 32 } as const;
const CORE_LIST_CLEAR = RADIUS.core + 18;

/** Would a category's pill list, laid out from (x, y), overlap the core? */
function listHitsCore(side: LNode["side"], rows: number, x: number, y: number) {
  let x0: number, x1: number, y0: number, y1: number;
  if (side === "left" || side === "right") {
    x0 = side === "right" ? x + 70 : x - 70 - 200;
    x1 = x0 + 200;
    y0 = y - (rows * 30) / 2;
    y1 = y + (rows * 30) / 2;
  } else {
    x0 = x - 100;
    x1 = x + 100;
    y0 = side === "up" ? y - 60 - rows * 30 : y + 40;
    y1 = side === "up" ? y - 40 : y + 60 + rows * 30;
  }
  const cx = Math.max(x0, Math.min(0, x1));
  const cy = Math.max(y0, Math.min(0, y1));
  return Math.hypot(cx, cy) < CORE_LIST_CLEAR;
}""")

# continuous repulsion inside the spring loop
rep("""        n.vx += ((tx - n.x) * SPRING - n.vx * DAMP) * dt;
        n.vy += ((ty - n.y) * SPRING - n.vy * DAMP) * dt;
        n.x += n.vx * dt;
        n.y += n.vy * dt;
      }""", """        n.vx += ((tx - n.x) * SPRING - n.vx * DAMP) * dt;
        n.vy += ((ty - n.y) * SPRING - n.vy * DAMP) * dt;
        // The core is off-limits: anything inside its keep-out zone is shoved back out.
        const d = Math.hypot(n.x, n.y);
        const clear = CORE_CLEAR[n.type];
        if (age > 1.6 && d < clear) {
          const ux = d > 0.01 ? n.x / d : 1;
          const uy = d > 0.01 ? n.y / d : 0;
          const push = (clear - d) * 420 * dt;
          n.vx += ux * push;
          n.vy += uy * push;
        }
        n.x += n.vx * dt;
        n.y += n.vy * dt;
      }""")

# on drop: move the home outside the keep-out zone so the spring carries it clear
rep("""      if (d.moved && n) {
        // The branch stays where it was dropped: its new home is relative to its parent.
        const p = st.nodes.get(n.parent!)!;
        n.hx = n.x - p.x;
        n.hy = n.y - p.y;
        setNodeHome(n.id, n.hx, n.hy);""", """      if (d.moved && n) {
        // The branch stays where it was dropped — unless that's in or touching the core,
        // in which case its home is pushed clear and the spring flings it back out.
        const p = st.nodes.get(n.parent!)!;
        let ax = n.x;
        let ay = n.y;
        const clear = n.type === "game" ? CORE_CLEAR.game : CORE_CLEAR.category;
        const rows = st.order.filter((m) => m.parent === n.id).length;
        let bounced = false;
        for (let i = 0; i < 80; i++) {
          const dist = Math.hypot(ax, ay);
          const hit = dist < clear || (n.type === "category" && listHitsCore(n.side, rows, ax, ay));
          if (!hit) break;
          bounced = true;
          const ux = dist > 0.01 ? ax / dist : 1;
          const uy = dist > 0.01 ? ay / dist : 0;
          ax += ux * 8;
          ay += uy * 8;
        }
        n.hx = ax - p.x;
        n.hy = ay - p.y;
        if (bounced) {
          fx.ripple(true);
          n.vx += (ax - n.x) * 6;
          n.vy += (ay - n.y) * 6;
        }
        setNodeHome(n.id, n.hx, n.hy);""")
