// Drags a category onto the core with real mouse input, then reports where it settled.
import { spawn } from "node:child_process";
import { writeFileSync } from "node:fs";

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const port = 9800 + Math.floor(Math.random() * 100);
const chrome = spawn("C:/Program Files/Google/Chrome/Application/chrome.exe", [
  "--headless=new",
  `--remote-debugging-port=${port}`,
  "--hide-scrollbars",
  "--window-size=1600,940",
  `--user-data-dir=C:/Users/edmem/AppData/Local/Temp/cyrus-shots/prof-drag-${port}`,
  "about:blank",
]);
let targets;
for (let i = 0; i < 40; i++) {
  await sleep(250);
  try {
    targets = await (await fetch(`http://127.0.0.1:${port}/json`)).json();
    if (targets.some((t) => t.type === "page")) break;
  } catch {}
}
const ws = new WebSocket(targets.find((t) => t.type === "page").webSocketDebuggerUrl);
await new Promise((r) => (ws.onopen = r));
let id = 0;
const pending = new Map();
ws.onmessage = (m) => {
  const msg = JSON.parse(m.data);
  if (msg.id && pending.has(msg.id)) {
    pending.get(msg.id)(msg);
    pending.delete(msg.id);
  }
};
const send = (method, params = {}) =>
  new Promise((r) => {
    const i = ++id;
    pending.set(i, r);
    ws.send(JSON.stringify({ id: i, method, params }));
  });
const evaluate = async (expr) => (await send("Runtime.evaluate", { expression: expr, awaitPromise: true, returnByValue: true })).result.result.value;

await send("Emulation.setDeviceMetricsOverride", { width: 1600, height: 940, deviceScaleFactor: 1, mobile: false });
await send("Page.navigate", { url: "http://localhost:3000" });
await sleep(5000);

const pos = await evaluate(`(() => {
  const r = (el) => { const b = el.getBoundingClientRect(); return [b.x + b.width / 2, b.y + b.height / 2]; };
  const cat = document.querySelector('[aria-label="Category: Worlds"]');
  const core = document.querySelector('.core-hit');
  return { cat: r(cat), core: r(core) };
})()`);
console.log("before", JSON.stringify(pos));

const [sx, sy] = pos.cat;
const [tx, ty] = pos.core;
await send("Input.dispatchMouseEvent", { type: "mouseMoved", x: sx, y: sy });
await send("Input.dispatchMouseEvent", { type: "mousePressed", x: sx, y: sy, button: "left", clickCount: 1 });
for (let i = 1; i <= 20; i++) {
  await send("Input.dispatchMouseEvent", { type: "mouseMoved", x: sx + ((tx + 10 - sx) * i) / 20, y: sy + ((ty - sy) * i) / 20, button: "left", buttons: 1 });
  await sleep(16);
}
await send("Input.dispatchMouseEvent", { type: "mouseReleased", x: tx + 10, y: ty, button: "left", clickCount: 1 });
await sleep(300);
const mid = await evaluate(`(() => { const b = document.querySelector('[aria-label="Category: Worlds"]').getBoundingClientRect(); return [b.x + b.width/2, b.y + b.height/2]; })()`);
await sleep(2200);
const after = await evaluate(`(() => {
  const r = (el) => { const b = el.getBoundingClientRect(); return [b.x + b.width / 2, b.y + b.height / 2]; };
  const cat = r(document.querySelector('[aria-label="Category: Worlds"]'));
  const core = r(document.querySelector('.core-hit'));
  const k = Number((document.querySelector('.world').style.transform.match(/scale\\(([\\d.]+)\\)/) || [0, 1])[1]);
  const saved = JSON.parse(localStorage.getItem('cyrus-state-v1') || '{}').state?.layout;
  return { cat, core, k, worldDist: Math.round(Math.hypot(cat[0] - core[0], cat[1] - core[1]) / k), saved };
})()`);
console.log("300ms after drop", JSON.stringify(mid));
console.log("settled", JSON.stringify(after));
const shot = await send("Page.captureScreenshot", { format: "png" });
writeFileSync("drag.png", Buffer.from(shot.result.data, "base64"));
ws.close();
chrome.kill();
process.exit(0);

