/** Colour helpers shared by the network and core renderers. Colours are "r g b" triples. */

/** Darkens a neon colour so it reads on a white background. */
export function inkOf(rgb: string) {
  const [r, g, b] = rgb.split(" ").map(Number);
  const m = (c: number, t: number) => Math.round(c * 0.7 + t * 0.3);
  return `${m(r, 40)} ${m(g, 20)} ${m(b, 90)}`;
}

/** Mixes a colour toward white. */
export function mix(rgb: string, t: number) {
  const [r, g, b] = rgb.split(" ").map(Number);
  return `${Math.round(r + (255 - r) * t)} ${Math.round(g + (255 - g) * t)} ${Math.round(b + (255 - b) * t)}`;
}

/** Rim colours by canvas angle (0 = right, clockwise): pink right, violet top/bottom, cyan left. */
const RIM_STOPS: [number, number, number][] = [
  [236, 72, 153],
  [192, 38, 211],
  [124, 58, 237],
  [59, 130, 246],
  [34, 211, 238],
  [59, 130, 246],
  [139, 92, 246],
  [217, 70, 239],
];

export function rimColor(a: number) {
  const x = ((((a / (Math.PI * 2)) % 1) + 1) % 1) * 8;
  const i = Math.floor(x);
  const f = x - i;
  const c0 = RIM_STOPS[i % 8];
  const c1 = RIM_STOPS[(i + 1) % 8];
  return `${Math.round(c0[0] + (c1[0] - c0[0]) * f)} ${Math.round(c0[1] + (c1[1] - c0[1]) * f)} ${Math.round(c0[2] + (c1[2] - c0[2]) * f)}`;
}

