    float flick = 0.65 + 0.35 * sin(t * 3.0 + fbm(pf * 4.0 + t * 0.3) * 9.0);

    vec3 lightDir = normalize(vec3(-0.45, 0.55, 0.7));
    float diff = max(dot(n, lightDir), 0.0);
    float spec = pow(max(dot(reflect(-lightDir, n), vec3(0.0, 0.0, 1.0)), 0.0), 28.0);

