                      onClick={() => setEmblem(em)}
                      aria-label={em}
                      className="tint grid h-10 w-10 place-items-center rounded-full border text-[20px] transition"
                      style={{
                        ["--c" as string]: rgb,
                        color: on ? "var(--cc-ink)" : "var(--muted)",
                        borderColor: on ? `rgb(${rgb})` : "var(--line)",
                        boxShadow: on ? `0 0 14px rgb(${rgb} / 0.5)` : undefined,
                      }}
                    >
                      <GameEmblem emblem={em} />
                    </button>
                  );
                })}
              </div>
            </section>
          </div>

          <section>
            <h3 className="mb-2 flex items-center text-[10.5px] font-semibold uppercase tracking-[0.16em] text-muted">
              Categories
              <span className="ml-2 normal-case tracking-normal text-faint">{cats.length}/5 — the first three get the best spots</span>
            </h3>
            <div className="flex flex-wrap gap-1.5">
