            <p className="mt-1 text-[12.5px] leading-relaxed text-ink-2">
              It blooms out of the core with its own categories. Prompts that mention it route straight to its branch.
            </p>
            <label className="mt-3 block">
              <span className="sr-only">Game name</span>
              <input
                ref={inputRef}
                value={name}
                onChange={(e) => {
                  setName(e.target.value);
                  fx.keystroke(0.4);
                }}
                maxLength={40}
                placeholder="Game name — e.g. Valheim, Elden Ring, Hollow Knight"
                className="w-full rounded-xl border border-line bg-[rgb(var(--glow)/0.06)] px-3.5 py-2.5 text-[14px] text-ink outline-none placeholder:text-faint focus:border-line-2"
              />
            </label>
            {duplicate && <p className="mt-1.5 text-[11.5px] text-rose-400">That game is already in the network.</p>}
            {full && <p className="mt-1.5 text-[11.5px] text-rose-400">The web holds {MAX_GAMES} games. Remove one to add another.</p>}
          </div>
        </div>

        <div className="space-y-5 p-6">
          <section>
            <h3 className="mb-2 text-[10.5px] font-semibold uppercase tracking-[0.16em] text-muted">Code template</h3>
            <div className="grid grid-cols-1 gap-2 sm:grid-cols-2">
              {TEMPLATES.map((t) => {
                const on = t.key === template;
                return (
                  <button
                    key={t.key}
                    type="button"
                    onClick={() => setTemplate(t.key)}
                    className={`flex items-start gap-2.5 rounded-xl border px-3 py-2.5 text-left transition ${
                      on ? "border-accent/60 bg-[rgb(var(--glow)/0.12)]" : "border-line hover:border-line-2 hover:bg-[rgb(var(--glow)/0.05)]"
                    }`}
                  >
                    <span className={`mt-0.5 grid h-4 w-4 shrink-0 place-items-center rounded-full border text-[9px] ${on ? "border-accent bg-accent text-white" : "border-line-2"}`}>
                      {on && <CheckIcon />}
                    </span>
                    <span className="min-w-0">
                      <span className="block text-[13px] font-medium text-ink">{t.label}</span>
                      <span className="block text-[11.5px] leading-snug text-muted">{t.hint}</span>
                    </span>
                  </button>
                );
              })}
            </div>
          </section>

          <div className="grid grid-cols-1 gap-5 sm:grid-cols-2">
            <section>
              <h3 className="mb-2 text-[10.5px] font-semibold uppercase tracking-[0.16em] text-muted">Branch colour</h3>
              <div className="flex flex-wrap gap-2">
                {GAME_COLORS.map((c) => (
                  <button
                    key={c.rgb}
                    type="button"
                    onClick={() => setRgb(c.rgb)}
                    aria-label={c.name}
                    title={c.name}
                    className="grid h-8 w-8 place-items-center rounded-full transition hover:scale-110"
                    style={{
                      background: `rgb(${c.rgb})`,
                      boxShadow: c.rgb === rgb ? `0 0 0 2px var(--solid), 0 0 0 4px rgb(${c.rgb}), 0 0 16px rgb(${c.rgb} / 0.7)` : `0 0 10px rgb(${c.rgb} / 0.4)`,
                    }}
                  >
                    {c.rgb === rgb && <CheckIcon className="text-[13px] text-white drop-shadow" />}
                  </button>
                ))}
              </div>
            </section>
            <section>
              <h3 className="mb-2 text-[10.5px] font-semibold uppercase tracking-[0.16em] text-muted">Emblem</h3>
              <div className="flex flex-wrap gap-2">
                {EMBLEMS.map((em) => {
                  const on = em === emblem;
                  return (
                    <button
                      key={em}
                      type="button"
                      onClick={() => setEmblem(em)}
                      aria-label={em}
                      className="tint grid h-10 w-10 place-items-center rounded-full border text-[20px] transition"
                      style={{
                        ["--c" as string]: rgb,
                        color: on ? "var(--cc-ink)" : "var(--muted)",
                        borderColor: on ? `rgb(${rgb})` : "var(--line)",
                        boxShadow: on ? `0 0 14px rgb(${rgb} / 0.5)` : undefined,
                      }}
                    >
                      <GameEmblem emblem={em} />
                    </button>
                  );
                })}
              </div>
            </section>
          </div>

          <section>
            <h3 className="mb-2 flex items-center text-[10.5px] font-semibold uppercase tracking-[0.16em] text-muted">
              Categories
              <span className="ml-2 normal-case tracking-normal text-faint">{cats.length}/5 — the first three get the best spots</span>
            </h3>
            <div className="flex flex-wrap gap-1.5">
              {CATEGORIES.map((c) => {
                const on = cats.includes(c.key);
                return (
                  <button
                    key={c.key}
                    type="button"
                    onClick={() => toggleCat(c.key)}
                    className="tint flex items-center gap-1.5 rounded-full border py-1 pl-1.5 pr-2.5 text-[12px] transition"
                    style={{
                      ["--c" as string]: rgb,
                      color: on ? "var(--ink)" : "var(--muted)",
                      borderColor: on ? `rgb(${rgb} / 0.7)` : "var(--line)",
                      background: on ? `rgb(${rgb} / 0.12)` : undefined,
                    }}
                  >
                    <span className="text-[14px]" style={{ color: on ? "var(--cc)" : undefined }}>
                      <CategoryIcon k={c.key} />
                    </span>
                    {c.label}
                  </button>
                );
              })}
            </div>
          </section>
        </div>

        <div className="flex items-center gap-3 border-t border-line px-6 py-4">
          <span className="text-[11.5px] text-faint">
            {games.length}/{MAX_GAMES} games in the web
          </span>
          <button type="button" onClick={() => setOpen(false)} className="btn-ghost ml-auto h-9 px-3.5 text-[13px]">
            Cancel
          </button>
          <button
            type="button"
            onClick={create}
            disabled={!valid}
            className="inline-flex h-9 items-center gap-1.5 rounded-xl px-4 text-[13px] font-semibold text-white transition enabled:hover:scale-[1.03] disabled:opacity-40"
            style={{ background: `linear-gradient(135deg, rgb(${rgb}), #6366f1)`, boxShadow: valid ? `0 0 20px rgb(${rgb} / 0.5)` : undefined }}
          >
            <PlusIcon /> Add branch
          </button>
        </div>
      </div>
    </div>
  );
}

