import type { SVGProps } from "react";

/*
 * The CYRUS wordmark, redrawn as vector paths. Glassy lavender C/R/U/S with thin violet
 * outlines, and the hero "Y": a cyan arm crossing a long blue-to-magenta sweep with flared tips.
 * Coordinates are in a 1600-wide design space (viewBox below).
 */

const C_PATH =
  "M378 352 L175 352 Q95 352 95 432 L95 540 Q95 620 175 620 L380 620 L440 562 L192 562 Q165 562 165 535 L165 437 Q165 410 192 410 L440 410 Z";
const R_PATH =
  "M858 352 L965 352 Q1050 352 1050 437 Q1050 522 965 522 L908 522 L1037 662 L945 662 L762 497 Q748 487 762 477 L775 466 L960 466 Q990 466 990 438 Q990 410 960 410 L800 410 Z";
const U_PATH =
  "M1078 352 L1142 352 L1142 530 Q1142 557 1170 557 L1280 557 Q1308 557 1308 530 L1308 352 L1372 352 L1372 535 Q1372 620 1287 620 L1163 620 Q1078 620 1078 535 Z";
const S_PATH =
  "M1693 352 L1635 410 L1480 410 Q1460 410 1460 430 Q1460 455 1485 455 L1605 455 Q1688 455 1688 537 Q1688 620 1605 620 L1378 620 L1438 562 L1600 562 Q1625 562 1625 537 Q1625 512 1600 512 L1478 512 Q1395 512 1395 432 Q1395 352 1478 352 Z";
/** The long "/" sweep of the Y, tapering to a point at each end. */
const Y_SWEEP =
  "M300 668 Q420 668 470 620 L790 282 Q822 256 880 256 L1016 256 Q922 262 886 300 L566 636 Q535 668 470 668 Z";
/** The short cyan "\" arm of the Y, with a rounded foot resting on the sweep. */
const Y_ARM =
  "M288 256 L425 256 Q456 256 479 280 L598 398 Q617 420 601 440 Q580 463 548 448 L530 432 L378 290 Q345 262 288 256 Z";

function Defs({ id }: { id: string }) {
  return (
    <defs>
      {/* Glass letters: bright top, periwinkle body, a pink kiss on the lower edge. */}
      <linearGradient id={`${id}-glass`} x1="0" y1="352" x2="0" y2="620" gradientUnits="userSpaceOnUse">
        <stop offset="0%" stopColor="#ffffff" />
        <stop offset="30%" stopColor="#e3e6ff" />
        <stop offset="68%" stopColor="#a7b5ff" />
        <stop offset="100%" stopColor="#d9a3ff" />
      </linearGradient>
      <linearGradient id={`${id}-sheen`} x1="95" y1="0" x2="1693" y2="0" gradientUnits="userSpaceOnUse">
        <stop offset="0%" stopColor="#f0abfc" stopOpacity="0.45" />
        <stop offset="30%" stopColor="#60a5fa" stopOpacity="0" />
        <stop offset="70%" stopColor="#818cf8" stopOpacity="0.1" />
        <stop offset="100%" stopColor="#c084fc" stopOpacity="0.35" />
      </linearGradient>
      <linearGradient id={`${id}-edge`} x1="95" y1="0" x2="1693" y2="0" gradientUnits="userSpaceOnUse">
        <stop offset="0%" stopColor="#7c5cff" />
        <stop offset="50%" stopColor="#3b6bff" />
        <stop offset="100%" stopColor="#8b5cf6" />
      </linearGradient>
      <linearGradient id={`${id}-sweep`} x1="300" y1="668" x2="1016" y2="256" gradientUnits="userSpaceOnUse">
        <stop offset="0%" stopColor="#c026d3" />
        <stop offset="22%" stopColor="#ff3df2" />
        <stop offset="45%" stopColor="#7c3aed" />
        <stop offset="58%" stopColor="#2563eb" />
        <stop offset="78%" stopColor="#a855f7" />
        <stop offset="100%" stopColor="#ff4fd8" />
      </linearGradient>
      <linearGradient id={`${id}-arm`} x1="288" y1="256" x2="600" y2="450" gradientUnits="userSpaceOnUse">
        <stop offset="0%" stopColor="#22f0ff" />
        <stop offset="45%" stopColor="#14b8f5" />
        <stop offset="100%" stopColor="#1d4fff" />
      </linearGradient>
      <linearGradient id={`${id}-gloss`} x1="0" y1="256" x2="0" y2="480" gradientUnits="userSpaceOnUse">
        <stop offset="0%" stopColor="#ffffff" stopOpacity="0.55" />
        <stop offset="100%" stopColor="#ffffff" stopOpacity="0" />
      </linearGradient>
    </defs>
  );
}

/** Full CYRUS wordmark. Height follows `1em`, width ~3.75em. */
export function CyrusWordmark({ id = "cyrus", ...props }: { id?: string } & SVGProps<SVGSVGElement>) {
  return (
    <svg viewBox="88 248 1616 428" width="3.78em" height="1em" role="img" aria-label="Cyrus" {...props}>
      <Defs id={id} />
      <g strokeLinejoin="round">
        {[C_PATH, R_PATH, U_PATH, S_PATH].map((d) => (
          <g key={d.slice(0, 12)}>
            <path d={d} fill={`url(#${id}-glass)`} />
            <path d={d} fill={`url(#${id}-sheen)`} />
            <path d={d} fill="none" stroke={`url(#${id}-edge)`} strokeWidth="4" />
          </g>
        ))}
        <path d={Y_SWEEP} fill={`url(#${id}-sweep)`} />
        <path d={Y_SWEEP} fill={`url(#${id}-gloss)`} />
        <path d={Y_SWEEP} fill="none" stroke="#fdf4ff" strokeOpacity="0.55" strokeWidth="3" />
        <path d={Y_ARM} fill={`url(#${id}-arm)`} />
        <path d={Y_ARM} fill={`url(#${id}-gloss)`} />
        <path d={Y_ARM} fill="none" stroke="#e0fbff" strokeOpacity="0.6" strokeWidth="3" />
      </g>
    </svg>
  );
}

/** Just the hero "Y" — for tight spots like the favicon or a collapsed header. */
export function CyrusGlyph({ id = "cyrus-glyph", ...props }: { id?: string } & SVGProps<SVGSVGElement>) {
  return (
    <svg viewBox="270 240 770 444" width="1.73em" height="1em" role="img" aria-label="Cyrus" {...props}>
      <Defs id={id} />
      <path d={Y_SWEEP} fill={`url(#${id}-sweep)`} />
      <path d={Y_SWEEP} fill={`url(#${id}-gloss)`} />
      <path d={Y_ARM} fill={`url(#${id}-arm)`} />
      <path d={Y_ARM} fill={`url(#${id}-gloss)`} />
    </svg>
  );
}

/** Back-compat name used across the app: the hero Y glyph. */
export const CyrusLogo = CyrusGlyph;

