        <stop offset="100%" stopColor="#8b5cf6" />
      </linearGradient>
      <linearGradient id={`${id}-sweep`} x1="300" y1="668" x2="1016" y2="256" gradientUnits="userSpaceOnUse">
        <stop offset="0%" stopColor="#c026d3" />
        <stop offset="22%" stopColor="#ff3df2" />
        <stop offset="45%" stopColor="#7c3aed" />
        <stop offset="58%" stopColor="#2563eb" />
        <stop offset="78%" stopColor="#a855f7" />
        <stop offset="100%" stopColor="#ff4fd8" />
      </linearGradient>
      <linearGradient id={`${id}-arm`} x1="288" y1="256" x2="600" y2="450" gradientUnits="userSpaceOnUse">
        <stop offset="0%" stopColor="#22f0ff" />
        <stop offset="45%" stopColor="#14b8f5" />
