/**
 * The Cyrus Core as a real 3D glass sphere, ray-traced per pixel in a WebGL fragment shader.
 *
 * Each pixel's view ray hits the sphere, refracts through the glass and travels through the
 * interior. Along the way it gathers volumetric nebula fog, passes the Cyrus "Y" floating on a
 * gently tilting plane at the centre (so the logo shows lens distortion, colour fringing and
 * parallax), and sees the energy web on the back and front surfaces. The Y is emissive: it lights
 * the fog around it and brightens nearby strands, so it reads as the core's heart rather than a
 * sticker. Fresnel, a window reflection, specular and a double rim sit on top; a filmic curve
 * keeps highlights rich. Rendered at device resolution every frame, so it's sharp at any zoom.
 */
import { Y_ARM, Y_SWEEP } from "@/components/icons/CyrusLogo";

const VERT = `
attribute vec2 aPos;
varying vec2 vUv;
void main() {
  vUv = aPos;
  gl_Position = vec4(aPos, 0.0, 1.0);
}
`;

const FRAG = `
precision highp float;
varying vec2 vUv;
uniform float uTime;
uniform float uRot;
uniform float uTilt;
uniform float uEnergy;
uniform float uPulse;
uniform float uLight;
uniform float uRadius;    // sphere radius in uv units (uv spans -1..1)
uniform float uPx;        // one device pixel in uv units, for anti-aliasing
uniform float uLogoHalf;  // half-size of the logo texture, in sphere units
uniform sampler2D uLogo;
uniform sampler2D uGlow;

float hash(vec3 p) {
  return fract(sin(dot(p, vec3(127.1, 311.7, 74.7))) * 43758.5453123);
}
vec3 hash3(vec3 p) {
  p = vec3(dot(p, vec3(127.1, 311.7, 74.7)), dot(p, vec3(269.5, 183.3, 246.1)), dot(p, vec3(113.5, 271.9, 124.6)));
  return fract(sin(p) * 43758.5453123);
}
float vnoise(vec3 p) {
  vec3 i = floor(p);
  vec3 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(
    mix(mix(hash(i), hash(i + vec3(1, 0, 0)), f.x), mix(hash(i + vec3(0, 1, 0)), hash(i + vec3(1, 1, 0)), f.x), f.y),
    mix(mix(hash(i + vec3(0, 0, 1)), hash(i + vec3(1, 0, 1)), f.x), mix(hash(i + vec3(0, 1, 1)), hash(i + vec3(1, 1, 1)), f.x), f.y),
    f.z);
}
