/** Rasterizes the Y into a crisp colour texture and a soft glow texture. */
function logoCanvases() {
  const SIZE = 1024;
  // Y bounds in its design space: x 288..1016, y 256..668.
  const cx = 652;
  const cy = 462;
  const s = (0.8 * SIZE) / 728;
  const crisp = document.createElement("canvas");
  crisp.width = crisp.height = SIZE;
  const g = crisp.getContext("2d")!;
  g.setTransform(s, 0, 0, s, SIZE / 2 - cx * s, SIZE / 2 - cy * s);
  const sweep = g.createLinearGradient(300, 668, 1016, 256);
  [
    [0, "#c026d3"],
    [0.22, "#ff3df2"],
    [0.45, "#7c3aed"],
    [0.58, "#2563eb"],
    [0.78, "#a855f7"],
    [1, "#ff4fd8"],
  ].forEach(([o, c]) => sweep.addColorStop(o as number, c as string));
  const arm = g.createLinearGradient(288, 256, 600, 450);
  [
    [0, "#22f0ff"],
    [0.45, "#14b8f5"],
    [1, "#1d4fff"],
  ].forEach(([o, c]) => arm.addColorStop(o as number, c as string));
  const sweepPath = new Path2D(Y_SWEEP);
  const armPath = new Path2D(Y_ARM);
  g.fillStyle = sweep;
  g.fill(sweepPath);
  g.fillStyle = arm;
  g.fill(armPath);
  // A bright inner edge so it reads as lit glass from within.
  g.lineWidth = 5;
  g.strokeStyle = "rgba(255,255,255,0.55)";
  g.stroke(sweepPath);
  g.stroke(armPath);

  // Glow: downsample hard, then scale back up — a cheap, cross-browser blur.
  const glow = document.createElement("canvas");
  glow.width = glow.height = 512;
  const gg = glow.getContext("2d")!;
  gg.imageSmoothingEnabled = true;
  gg.imageSmoothingQuality = "high";
  for (const [res, alpha] of [
    [96, 0.9],
    [36, 0.85],
    [16, 0.7],
  ] as const) {
    const tmp = document.createElement("canvas");
    tmp.width = tmp.height = res;
    const tg = tmp.getContext("2d")!;
    tg.imageSmoothingQuality = "high";
    tg.drawImage(crisp, 0, 0, res, res);
    gg.globalAlpha = alpha;
    gg.globalCompositeOperation = "lighter";
    gg.drawImage(tmp, 0, 0, 512, 512);
  }
