  const uRot = u("uRot");
  const uTilt = u("uTilt");
  const uEnergy = u("uEnergy");
  const uPulse = u("uPulse");
  const uLight = u("uLight");
  const uRadius = u("uRadius");
  const uPx = u("uPx");
  let devicePx = 1;

  return {
    resize(cssSize, dpr) {
      const px = Math.max(2, Math.round(cssSize * dpr));
      if (canvas.width !== px) {
        canvas.width = px;
        canvas.height = px;
      }
      canvas.style.width = `${cssSize}px`;
      canvas.style.height = `${cssSize}px`;
      devicePx = px;
      gl.viewport(0, 0, px, px);
    },
    render({ time, rot, tilt, energy, pulse, light, radiusFrac }) {
      if (gl.isContextLost()) return;
      gl.uniform1f(uTime, time);
      gl.uniform1f(uRot, rot);
      gl.uniform1f(uTilt, tilt);
      gl.uniform1f(uEnergy, energy);
      gl.uniform1f(uPulse, pulse);
      gl.uniform1f(uLight, light ? 1 : 0);
      gl.uniform1f(uRadius, radiusFrac);
      gl.uniform1f(uPx, 2 / devicePx);
      gl.clearColor(0, 0, 0, 0);
      gl.clear(gl.COLOR_BUFFER_BIT);
      gl.drawArrays(gl.TRIANGLES, 0, 6);
    },
    dispose() {
      // The canvas is thrown away with the renderer, so releasing the context is safe.
      gl.getExtension("WEBGL_lose_context")?.loseContext();
    },
  };
}

