/**
 * The Cyrus Core as a real 3D sphere, ray-traced per pixel in a WebGL fragment shader:
 * surface normals for lighting and fresnel, a rotating 3D cellular "energy web" on the front
 * and back surfaces (seen through the glass), nebula haze inside, a crisp neon rim and an
 * electric corona. Rendered at device resolution every frame, so it stays sharp at any zoom.
 */

const VERT = `
attribute vec2 aPos;
varying vec2 vUv;
void main() {
  vUv = aPos;
  gl_Position = vec4(aPos, 0.0, 1.0);
}
`;

const FRAG = `
precision highp float;
varying vec2 vUv;
uniform float uTime;
uniform float uRot;
uniform float uEnergy;
uniform float uPulse;
uniform float uLight;
uniform float uRadius;   // sphere radius in uv units (uv spans -1..1)
uniform float uPx;       // one device pixel in uv units, for anti-aliasing

vec3 hash3(vec3 p) {
  p = vec3(dot(p, vec3(127.1, 311.7, 74.7)), dot(p, vec3(269.5, 183.3, 246.1)), dot(p, vec3(113.5, 271.9, 124.6)));
  return fract(sin(p) * 43758.5453123);
}

float vnoise(vec3 p) {
  vec3 i = floor(p);
  vec3 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float n000 = hash3(i).x;
  float n100 = hash3(i + vec3(1, 0, 0)).x;
  float n010 = hash3(i + vec3(0, 1, 0)).x;
  float n110 = hash3(i + vec3(1, 1, 0)).x;
  float n001 = hash3(i + vec3(0, 0, 1)).x;
  float n101 = hash3(i + vec3(1, 0, 1)).x;
  float n011 = hash3(i + vec3(0, 1, 1)).x;
  float n111 = hash3(i + vec3(1, 1, 1)).x;
  return mix(mix(mix(n000, n100, f.x), mix(n010, n110, f.x), f.y), mix(mix(n001, n101, f.x), mix(n011, n111, f.x), f.y), f.z);
}

float fbm(vec3 p) {
  float s = 0.0;
  float a = 0.5;
  for (int i = 0; i < 4; i++) {
    s += a * vnoise(p);
    p *= 2.03;
    a *= 0.5;
  }
  return s;
}

// Distance to the nearest Voronoi cell border: thin bright lines where it is ~0.
float cellEdge(vec3 p, float t) {
  vec3 b = floor(p);
  vec3 f = fract(p);
  float d1 = 8.0;
  float d2 = 8.0;
  for (int k = -1; k <= 1; k++)
  for (int j = -1; j <= 1; j++)
  for (int i = -1; i <= 1; i++) {
    vec3 g = vec3(float(i), float(j), float(k));
    vec3 o = hash3(b + g);
    o = 0.5 + 0.42 * sin(t + 6.2831 * o);
    vec3 r = g + o - f;
    float d = dot(r, r);
    if (d < d1) { d2 = d1; d1 = d; } else if (d < d2) { d2 = d; }
  }
  return sqrt(d2) - sqrt(d1);
}

// Angle colour map: cyan on the left, violet top and bottom, pink on the right.
vec3 palette(float h) {
  vec3 cyan = vec3(0.13, 0.83, 0.93);
  vec3 blue = vec3(0.23, 0.51, 0.96);
  vec3 violet = vec3(0.55, 0.36, 0.97);
  vec3 magenta = vec3(0.85, 0.27, 0.94);
  vec3 pink = vec3(0.93, 0.28, 0.60);
  vec3 left = mix(blue, cyan, smoothstep(0.35, 1.0, -h));
  vec3 right = mix(magenta, pink, smoothstep(0.35, 1.0, h));
  return mix(violet, h < 0.0 ? left : right, smoothstep(0.0, 0.6, abs(h)));
}

mat3 rotY(float a) { float c = cos(a), s = sin(a); return mat3(c, 0.0, -s, 0.0, 1.0, 0.0, s, 0.0, c); }
mat3 rotX(float a) { float c = cos(a), s = sin(a); return mat3(1.0, 0.0, 0.0, 0.0, c, s, 0.0, -s, c); }

void main() {
  vec2 uv = vUv;
  float r = length(uv);
  float R = uRadius;
  float h = r > 0.0 ? uv.x / r : 0.0;
  vec3 tint = palette(h);
  float e = uEnergy;
  float t = uTime;
  vec3 col = vec3(0.0);
  float alpha = 0.0;

  if (r < R + uPx) {
    // ── Inside the sphere ──
    vec2 q = uv / R;
    float z = sqrt(max(0.0, 1.0 - dot(q, q)));
    vec3 n = vec3(q, z);
    float fres = pow(1.0 - z, 2.4);
    mat3 rot = rotY(uRot) * rotX(0.38);
    vec3 pf = rot * n;
    vec3 pb = rot * vec3(q, -z);

    float neb = fbm(pf * 2.1 + vec3(0.0, t * 0.04, 0.0));
    float web = cellEdge(pf * 3.1, t * 0.55);
    float webBack = cellEdge(pb * 3.1, t * 0.55);
    float fine = cellEdge(pf * 7.0 + 11.0, t * 0.8);

    float wFront = 1.0 - smoothstep(0.0, 0.055 + 0.02 * e, web);
    float wGlow = 1.0 - smoothstep(0.0, 0.22, web);
    float wBack = 1.0 - smoothstep(0.0, 0.05, webBack);
    float wFine = 1.0 - smoothstep(0.0, 0.035, fine);
    // Electric flicker travelling along the strands.
    float flick = 0.65 + 0.35 * sin(t * 3.0 + fbm(pf * 4.0 + t * 0.3) * 9.0);

    vec3 lightDir = normalize(vec3(-0.45, 0.55, 0.7));
    float diff = max(dot(n, lightDir), 0.0);
    float spec = pow(max(dot(reflect(-lightDir, n), vec3(0.0, 0.0, 1.0)), 0.0), 28.0);

    if (uLight < 0.5) {
      vec3 deep = mix(vec3(0.015, 0.02, 0.07), vec3(0.05, 0.045, 0.16), neb);
      deep += vec3(0.22, 0.12, 0.5) * pow(neb, 3.0) * 0.9;
      deep *= 0.75 + 0.35 * diff;
      col = deep;
      col += tint * wBack * 0.22;
      col += mix(tint, vec3(0.55, 0.6, 1.0), 0.35) * wGlow * (0.16 + 0.3 * fres) * flick;
      col += mix(tint, vec3(1.0), 0.25) * wFront * (0.55 + 0.7 * fres + e * 0.45 + uPulse * 0.35) * flick;
      col += tint * wFine * 0.12 * (0.4 + fres);
      col += tint * fres * (0.75 + e * 0.35 + uPulse * 0.4);
      col += vec3(0.85, 0.88, 1.0) * spec * 0.4;
    } else {
      vec3 pale = mix(vec3(0.98, 0.97, 1.0), vec3(0.87, 0.83, 1.0), neb);
      pale *= 0.9 + 0.1 * diff;
      col = pale;
      col = mix(col, tint * 0.85, wBack * 0.18);
      col = mix(col, tint * 0.8, wFront * (0.6 + 0.2 * fres) * flick);
      col = mix(col, tint, fres * 0.55);
      col += vec3(1.0) * spec * 0.25;
    }

    // Crisp neon rim on the silhouette.
    float rim = smoothstep(R - 0.05, R - 0.006, r);
    vec3 rimCol = uLight < 0.5 ? mix(tint, vec3(1.0), 0.45) * 1.35 : tint * 0.9;
    col = mix(col, rimCol, rim * 0.9);
    alpha = 1.0 - smoothstep(R - uPx, R + uPx, r);
    col *= alpha;
  }

  // ── Outside: glow and electric corona ──
  float d = max(r - R, 0.0);
  if (r > R - uPx) {
    float a = atan(uv.y, uv.x);
    float glow = exp(-d * 30.0) * 0.55 + exp(-d * 9.0) * (0.16 + e * 0.12 + uPulse * 0.14);
    float rays = fbm(vec3(cos(a) * 7.0, sin(a) * 7.0, t * 0.9 - d * 6.0));
    rays = pow(smoothstep(0.42, 0.82, rays), 2.0) * exp(-d * (16.0 - e * 5.0)) * (0.55 + e * 0.5 + uPulse * 0.3);
    float g = clamp(glow + rays, 0.0, 1.0) * (uLight < 0.5 ? 1.0 : 0.45);
    vec3 gc = mix(tint, vec3(1.0), 0.15) * g;
    // premultiplied "over" the sphere edge
    col = col + gc * (1.0 - alpha);
    alpha = alpha + g * (1.0 - alpha);
  }

  gl_FragColor = vec4(col, alpha);
}
`;

