 *    They're intersected analytically (crisp at any size) and pass in front of and behind the Y.
 *  - Faint, dark nebula for depth. Tone mapping only compresses highlights and preserves hue.
 */
import { MARK_ASPECT, markSvg } from "@/components/icons/cyrusMark";

const VERT = `
attribute vec2 aPos;
varying vec2 vUv;
void main() {
  vUv = aPos;
  gl_Position = vec4(aPos, 0.0, 1.0);
}
`;

const FRAG = `
precision highp float;
varying vec2 vUv;
uniform float uTime;
uniform float uFlow;      // accumulated "energy time" — drives comets without jumps
uniform float uRot;
uniform float uTilt;
uniform float uEnergy;
uniform float uPulse;
uniform float uLight;
uniform float uRadius;    // sphere radius in uv units (uv spans -1..1)
uniform float uPx;        // one device pixel in uv units
uniform vec2 uLogoHalf;   // half-extent of the logo texture, in sphere units
uniform sampler2D uLogo;
uniform sampler2D uGlow;

const float PI = 3.14159265;

float hash(vec3 p) { return fract(sin(dot(p, vec3(127.1, 311.7, 74.7))) * 43758.5453123); }
