  float a2 = 0.5 + 0.5 * cos(th - uFlow * speed + phase + PI);
  float comet = pow(a1, 14.0) + 0.55 * pow(a2, 22.0);
  float core = exp(-pow(dist / 0.0065, 2.0));
  float halo = exp(-pow(dist / 0.045, 2.0));
  float b = (0.16 + 1.9 * comet * (1.0 + uEnergy * 0.6));
  vec3 c = col * (core * b + halo * b * 0.16) + vec3(1.0) * core * comet * 0.6;
  if (s > sLogo) c *= 1.0 - logoA * 0.92;
  return c;
}

void main() {
  vec2 uv = vUv;
  float r = length(uv);
  float R = uRadius;
  float h = r > 0.0 ? uv.x / r : 0.0;
  vec3 tint = palette(h);
  float e = uEnergy;
  float t = uTime;
  bool light = uLight > 0.5;
  vec3 col = vec3(0.0);
  float alpha = 0.0;

  if (r < R + uPx) {
    vec2 q = uv / R;
    float rq = length(q);
    float z = sqrt(max(0.0, 1.0 - rq * rq));
    vec3 n = vec3(q, z);
    float cosv = z;
    float fresThin = pow(1.0 - cosv, 5.0);
    float fresSoft = pow(1.0 - cosv, 2.2);

    // Refracted ray through the glass.
    vec3 dr = refract(vec3(0.0, 0.0, -1.0), n, 0.8);
    float sExit = max(-2.0 * dot(n, dr), 0.0);

    // The logo plane, tilting gently about the vertical axis.
    vec3 np = vec3(sin(uTilt), 0.0, cos(uTilt));
    vec3 ax = vec3(cos(uTilt), 0.0, -sin(uTilt));
    float dn = dot(dr, np);
    float sLogo = -dot(n, np) / (abs(dn) > 0.0001 ? dn : 0.0001);
