    mat3 rot = rotY(uRot) * rotX(0.35);
    float c1 = fbm(rot * (n + dr * 0.55) * 1.7 + vec3(0.0, t * 0.03, 0.0));
    float c2 = fbm(rot * (n + dr * 1.25) * 1.3 + 5.0);
    float neb = smoothstep(0.48, 0.9, c1) * 0.6 + smoothstep(0.5, 0.92, c2) * 0.4;
    vec3 nebCol = mix(vec3(0.10, 0.18, 0.75), vec3(0.55, 0.15, 0.80), smoothstep(0.35, 0.7, c2));

    // Glass lighting.
    vec3 refl = reflect(vec3(0.0, 0.0, -1.0), n);
    float band = smoothstep(0.55, 0.92, refl.y) * smoothstep(-0.35, 0.25, refl.x + 0.2) * smoothstep(1.0, 0.6, refl.x + 0.2);
    vec3 L = normalize(vec3(-0.5, 0.62, 0.6));
    float spec = pow(max(dot(reflect(-L, n), vec3(0.0, 0.0, 1.0)), 0.0), 90.0);
    float caustic = smoothstep(0.62, 0.97, rq) * smoothstep(-0.15, -0.85, q.y) * (1.0 - smoothstep(0.97, 1.0, rq));
    float emis = 1.25 + uPulse * 0.55 + e * 0.25;

    if (!light) {
      col = vec3(0.004, 0.006, 0.022) + nebCol * neb * (0.07 + e * 0.02);
      col += glow.rgb * (0.5 + uPulse * 0.35 + e * 0.15);
      col = col * (1.0 - logo.a) + logo.rgb * emis;
      col += rings;
      col += tint * (fresSoft * 0.22 + fresThin * (1.1 + e * 0.4 + uPulse * 0.5));
      col += mix(tint, vec3(1.0, 0.5, 0.9), 0.35) * caustic * (0.28 + uPulse * 0.2);
      col += vec3(0.75, 0.82, 1.0) * band * 0.16;
      col += vec3(1.0) * spec * 0.9;
      // Highlight-only, hue-preserving tone map: nothing below 0.72 is touched.
      float m = max(max(col.r, col.g), col.b);
      float tm = m < 0.72 ? m : 0.72 + 0.28 * (1.0 - exp(-(m - 0.72) * 3.6));
      col *= tm / max(m, 0.0001);
    } else {
      vec3 pearl = mix(vec3(0.995, 0.99, 1.0), vec3(0.9, 0.88, 1.0), smoothstep(0.2, 1.0, rq));
      col = pearl - vec3(0.06, 0.07, 0.0) * neb;
      col = mix(col, glow.rgb / max(glow.a, 0.001), glow.a * 0.16);
      col = col * (1.0 - logo.a) + logo.rgb;
      vec3 rl = rings;
      float ri = clamp(max(max(rl.r, rl.g), rl.b), 0.0, 1.0);
      col = mix(col, rl / max(ri, 0.001) * 0.82, ri * 0.85);
