/**
 * The Cyrus Core: an obsidian-glass orb, ray-traced per pixel in WebGL.
 *
 * Design goals: deep blacks and vivid colour (no milky haze), one clear hero (the Y), and a
 * few precise, elegant motions instead of noise.
 *
 *  - Glass: each view ray hits the sphere and refracts inward. A thin spectral fresnel rim,
 *    a dark inner edge (the glass thickness), a soft studio reflection band, a sharp specular
 *    and a bottom caustic sell the material.
 *  - The Y floats on a gently tilting plane at the centre, seen through the glass (lens
 *    distortion + parallax), emissive with a tight bloom that lights the interior.
 *  - Three orbit rings of light circle inside the orb in 3D, each carrying travelling comets.
 *    They're intersected analytically (crisp at any size) and pass in front of and behind the Y.
 *  - Faint, dark nebula for depth. Tone mapping only compresses highlights and preserves hue.
 */
import { MARK_ASPECT, markSvg } from "@/components/icons/cyrusMark";

const VERT = `
attribute vec2 aPos;
varying vec2 vUv;
void main() {
  vUv = aPos;
  gl_Position = vec4(aPos, 0.0, 1.0);
}
`;

const FRAG = `
precision highp float;
varying vec2 vUv;
uniform float uTime;
uniform float uFlow;      // accumulated "energy time" — drives comets without jumps
uniform float uRot;
uniform float uTilt;
uniform float uEnergy;
uniform float uPulse;
uniform float uLight;
uniform float uRadius;    // sphere radius in uv units (uv spans -1..1)
uniform float uPx;        // one device pixel in uv units
uniform vec2 uLogoHalf;   // half-extent of the logo texture, in sphere units
uniform sampler2D uLogo;
uniform sampler2D uGlow;

const float PI = 3.14159265;

float hash(vec3 p) { return fract(sin(dot(p, vec3(127.1, 311.7, 74.7))) * 43758.5453123); }
float vnoise(vec3 p) {
  vec3 i = floor(p);
  vec3 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(
    mix(mix(hash(i), hash(i + vec3(1, 0, 0)), f.x), mix(hash(i + vec3(0, 1, 0)), hash(i + vec3(1, 1, 0)), f.x), f.y),
    mix(mix(hash(i + vec3(0, 0, 1)), hash(i + vec3(1, 0, 1)), f.x), mix(hash(i + vec3(0, 1, 1)), hash(i + vec3(1, 1, 1)), f.x), f.y),
    f.z);
}
float fbm(vec3 p) { return 0.55 * vnoise(p) + 0.3 * vnoise(p * 2.03 + 1.7) + 0.15 * vnoise(p * 4.07 + 3.1); }

// Spectral rim colour by screen angle: cyan left, violet top/bottom, pink right.
vec3 palette(float h) {
  vec3 cyan = vec3(0.10, 0.85, 1.00);
  vec3 blue = vec3(0.22, 0.45, 1.00);
  vec3 violet = vec3(0.55, 0.30, 1.00);
  vec3 magenta = vec3(0.90, 0.22, 0.98);
  vec3 pink = vec3(1.00, 0.27, 0.65);
  vec3 left = mix(blue, cyan, smoothstep(0.35, 1.0, -h));
  vec3 right = mix(magenta, pink, smoothstep(0.35, 1.0, h));
  return mix(violet, h < 0.0 ? left : right, smoothstep(0.0, 0.6, abs(h)));
}

mat3 rotX(float a) { float c = cos(a), s = sin(a); return mat3(1.0, 0.0, 0.0, 0.0, c, s, 0.0, -s, c); }
mat3 rotY(float a) { float c = cos(a), s = sin(a); return mat3(c, 0.0, -s, 0.0, 1.0, 0.0, s, 0.0, c); }
mat3 rotZ(float a) { float c = cos(a), s = sin(a); return mat3(c, s, 0.0, -s, c, 0.0, 0.0, 0.0, 1.0); }

vec2 logoUv(vec3 x, vec3 ax) { return vec2(dot(x, ax) / uLogoHalf.x, -x.y / uLogoHalf.y) * 0.5 + 0.5; }
float inBox(vec2 uv) { return step(0.0, uv.x) * step(0.0, uv.y) * step(uv.x, 1.0) * step(uv.y, 1.0); }

// A flat ribbon of light (circle of radius rc in the plane with normal nr), intersected
// analytically by the ray o + d*s. Comets travel round it; it's hidden behind the logo.
vec3 ring(vec3 o, vec3 d, vec3 nr, float rc, float sMax, float sLogo, float logoA, vec3 col, float speed, float phase) {
  float dn = dot(d, nr);
  if (abs(dn) < 0.015) return vec3(0.0);
  float s = -dot(o, nr) / dn;
  if (s < 0.0 || s > sMax) return vec3(0.0);
  vec3 x = o + d * s;
  float dist = abs(length(x) - rc);
  vec3 u = normalize(cross(nr, vec3(0.0, 1.0, 0.001)));
  vec3 v = cross(nr, u);
  float th = atan(dot(x, v), dot(x, u));
  float a1 = 0.5 + 0.5 * cos(th - uFlow * speed + phase);
  float a2 = 0.5 + 0.5 * cos(th - uFlow * speed + phase + PI);
  float comet = pow(a1, 14.0) + 0.55 * pow(a2, 22.0);
  float core = exp(-pow(dist / 0.0065, 2.0));
  float halo = exp(-pow(dist / 0.045, 2.0));
  float b = (0.16 + 1.9 * comet * (1.0 + uEnergy * 0.6));
  vec3 c = col * (core * b + halo * b * 0.16) + vec3(1.0) * core * comet * 0.6;
  if (s > sLogo) c *= 1.0 - logoA * 0.92;
  return c;
}

void main() {
  vec2 uv = vUv;
  float r = length(uv);
  float R = uRadius;
  float h = r > 0.0 ? uv.x / r : 0.0;
  vec3 tint = palette(h);
  float e = uEnergy;
  float t = uTime;
  bool light = uLight > 0.5;
  vec3 col = vec3(0.0);
  float alpha = 0.0;

  if (r < R + uPx) {
    vec2 q = uv / R;
    float rq = length(q);
    float z = sqrt(max(0.0, 1.0 - rq * rq));
    vec3 n = vec3(q, z);
    float cosv = z;
    float fresThin = pow(1.0 - cosv, 5.0);
    float fresSoft = pow(1.0 - cosv, 2.2);

    // Refracted ray through the glass.
    vec3 dr = refract(vec3(0.0, 0.0, -1.0), n, 0.8);
    float sExit = max(-2.0 * dot(n, dr), 0.0);

    // The logo plane, tilting gently about the vertical axis.
    vec3 np = vec3(sin(uTilt), 0.0, cos(uTilt));
    vec3 ax = vec3(cos(uTilt), 0.0, -sin(uTilt));
    float dn = dot(dr, np);
    float sLogo = -dot(n, np) / (abs(dn) > 0.0001 ? dn : 0.0001);
    vec2 tuv = logoUv(n + dr * sLogo, ax);
    float hit = step(0.0, sLogo) * step(sLogo, sExit) * inBox(tuv);
    vec4 logo = texture2D(uLogo, tuv) * hit;
    vec4 glow = texture2D(uGlow, tuv) * hit;

    // Orbit rings, slowly precessing.
    vec3 n1 = rotY(t * 0.11) * rotX(1.05) * vec3(0.0, 1.0, 0.0);
    vec3 n2 = rotY(-t * 0.08 + 2.1) * rotZ(0.95) * vec3(0.0, 1.0, 0.0);
    vec3 n3 = rotX(t * 0.06 + 0.7) * rotZ(-0.55) * vec3(0.0, 1.0, 0.0);
    vec3 rings = vec3(0.0);
    rings += ring(n, dr, n1, 0.80, sExit, sLogo, logo.a, vec3(0.15, 0.82, 1.0), 0.9, 0.0);
    rings += ring(n, dr, n2, 0.72, sExit, sLogo, logo.a, vec3(0.95, 0.28, 0.95), 1.15, 2.0);
    rings += ring(n, dr, n3, 0.88, sExit, sLogo, logo.a, vec3(0.52, 0.36, 1.0), 0.7, 4.1);

    // Faint deep nebula for depth (two depths for parallax), kept dark.
    mat3 rot = rotY(uRot) * rotX(0.35);
    float c1 = fbm(rot * (n + dr * 0.55) * 1.7 + vec3(0.0, t * 0.03, 0.0));
    float c2 = fbm(rot * (n + dr * 1.25) * 1.3 + 5.0);
    float neb = smoothstep(0.48, 0.9, c1) * 0.6 + smoothstep(0.5, 0.92, c2) * 0.4;
    vec3 nebCol = mix(vec3(0.10, 0.18, 0.75), vec3(0.55, 0.15, 0.80), smoothstep(0.35, 0.7, c2));

    // Glass lighting.
    vec3 refl = reflect(vec3(0.0, 0.0, -1.0), n);
    float band = smoothstep(0.55, 0.92, refl.y) * smoothstep(-0.35, 0.25, refl.x + 0.2) * smoothstep(1.0, 0.6, refl.x + 0.2);
    vec3 L = normalize(vec3(-0.5, 0.62, 0.6));
    float spec = pow(max(dot(reflect(-L, n), vec3(0.0, 0.0, 1.0)), 0.0), 90.0);
    float caustic = smoothstep(0.62, 0.97, rq) * smoothstep(-0.15, -0.85, q.y) * (1.0 - smoothstep(0.97, 1.0, rq));
    float emis = 1.25 + uPulse * 0.55 + e * 0.25;

    if (!light) {
      col = vec3(0.004, 0.006, 0.022) + nebCol * neb * (0.07 + e * 0.02);
      col += glow.rgb * (0.5 + uPulse * 0.35 + e * 0.15);
      col = col * (1.0 - logo.a) + logo.rgb * emis;
      col += rings;
      col += tint * (fresSoft * 0.22 + fresThin * (1.1 + e * 0.4 + uPulse * 0.5));
      col += mix(tint, vec3(1.0, 0.5, 0.9), 0.35) * caustic * (0.28 + uPulse * 0.2);
      col += vec3(0.75, 0.82, 1.0) * band * 0.16;
      col += vec3(1.0) * spec * 0.9;
      // Highlight-only, hue-preserving tone map: nothing below 0.72 is touched.
      float m = max(max(col.r, col.g), col.b);
      float tm = m < 0.72 ? m : 0.72 + 0.28 * (1.0 - exp(-(m - 0.72) * 3.6));
      col *= tm / max(m, 0.0001);
    } else {
      vec3 pearl = mix(vec3(0.995, 0.99, 1.0), vec3(0.9, 0.88, 1.0), smoothstep(0.2, 1.0, rq));
      col = pearl - vec3(0.06, 0.07, 0.0) * neb;
      col = mix(col, glow.rgb / max(glow.a, 0.001), glow.a * 0.16);
      col = col * (1.0 - logo.a) + logo.rgb;
      vec3 rl = rings;
      float ri = clamp(max(max(rl.r, rl.g), rl.b), 0.0, 1.0);
      col = mix(col, rl / max(ri, 0.001) * 0.82, ri * 0.85);
      col = mix(col, tint * 0.95, fresThin * 0.85 + fresSoft * 0.1);
      col += vec3(1.0) * (spec * 0.6 + band * 0.18);
    }

    // Glass edge: a dark line of thickness just inside, then a crisp spectral rim.
    float edgeDark = exp(-pow((r - (R - 0.026)) / 0.007, 2.0));
    col *= 1.0 - edgeDark * (light ? 0.12 : 0.55);
    float rim = smoothstep(R - 0.016, R - 0.003, r);
    col = mix(col, light ? tint * 0.9 : mix(tint, vec3(1.0), 0.35), rim);

    alpha = 1.0 - smoothstep(R - uPx, R + uPx, r);
    col *= alpha;
  }

