  if (r > R - uPx) {
    float d = max(r - R, 0.0);
    float bloom = exp(-d * 70.0) * 0.85 + exp(-d * 16.0) * (0.12 + e * 0.06 + uPulse * 0.12);
    float g = clamp(bloom, 0.0, 1.0) * (light ? 0.4 : 1.0);
    col += tint * g * (1.0 - alpha);
    alpha += g * (1.0 - alpha);
