/**
 * Builds a signed-distance-field texture of the Cyrus mark from its vector paths, so the 3D core
 * can ray-march the Y as a solid, razor-sharp extruded shape at any zoom (the same idea engines
 * use for crisp text). Red channel = distance to the sweep, green = distance to the arm.
 */
import { MARK_ARM, MARK_SWEEP } from "@/components/icons/cyrusMark";

/** Texture layout: the mark's 940-wide viewBox (from x=20, y=40) mapped into 1024 px with padding. */
export const SDF_W = 1024;
export const SDF_PAD = 48;
export const SDF_S = (SDF_W - 2 * SDF_PAD) / 940; // texture px per design unit
export const SDF_H = Math.round(520 * SDF_S + 2 * SDF_PAD);
/** Distances are encoded in ±SDF_RANGE texture px. */
export const SDF_RANGE = 40;

const INF = 1e20;

/** Felzenszwalb & Huttenlocher 1D squared distance transform. */
function edt1d(f: Float64Array, n: number, d: Float64Array, v: Int32Array, z: Float64Array) {
  let k = 0;
  v[0] = 0;
  z[0] = -INF;
  z[1] = INF;
  for (let q = 1; q < n; q++) {
    let s = (f[q] + q * q - (f[v[k]] + v[k] * v[k])) / (2 * q - 2 * v[k]);
    while (s <= z[k]) {
      k--;
      s = (f[q] + q * q - (f[v[k]] + v[k] * v[k])) / (2 * q - 2 * v[k]);
    }
    k++;
    v[k] = q;
    z[k] = s;
    z[k + 1] = INF;
  }
  k = 0;
  for (let q = 0; q < n; q++) {
    while (z[k + 1] < q) k++;
    const dq = q - v[k];
    d[q] = dq * dq + f[v[k]];
  }
}

/** In-place 2D squared Euclidean distance transform. */
function edt2d(grid: Float64Array, w: number, h: number) {
  const n = Math.max(w, h);
  const f = new Float64Array(n);
  const d = new Float64Array(n);
  const v = new Int32Array(n);
  const z = new Float64Array(n + 1);
  for (let x = 0; x < w; x++) {
    for (let y = 0; y < h; y++) f[y] = grid[y * w + x];
    edt1d(f, h, d, v, z);
    for (let y = 0; y < h; y++) grid[y * w + x] = d[y];
  }
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) f[x] = grid[y * w + x];
    edt1d(f, w, d, v, z);
    for (let x = 0; x < w; x++) grid[y * w + x] = d[x];
  }
}

function coverage(path: string): Float32Array {
  const c = document.createElement("canvas");
  c.width = SDF_W;
  c.height = SDF_H;
  const g = c.getContext("2d", { willReadFrequently: true })!;
  g.setTransform(SDF_S, 0, 0, SDF_S, SDF_PAD - 20 * SDF_S, SDF_PAD - 40 * SDF_S);
  g.fillStyle = "#fff";
  g.fill(new Path2D(path));
  const data = g.getImageData(0, 0, SDF_W, SDF_H).data;
  const a = new Float32Array(SDF_W * SDF_H);
  for (let i = 0; i < a.length; i++) a[i] = data[i * 4 + 3] / 255;
  return a;
}

/** Signed distance in texture px: negative inside, positive outside, sub-pixel at the edge. */
function signedDistance(a: Float32Array): Float32Array {
  const N = a.length;
  const outside = new Float64Array(N);
  const inside = new Float64Array(N);
  for (let i = 0; i < N; i++) {
    const solid = a[i] > 0.5;
    outside[i] = solid ? 0 : INF;
    inside[i] = solid ? INF : 0;
  }
  edt2d(outside, SDF_W, SDF_H);
  edt2d(inside, SDF_W, SDF_H);
  const out = new Float32Array(N);
  for (let i = 0; i < N; i++) {
    const cov = a[i];
    if (cov > 0.02 && cov < 0.98) out[i] = 0.5 - cov;
    else {
      const d = Math.sqrt(outside[i]) - Math.sqrt(inside[i]);
      out[i] = d > 0 ? d - 0.5 : d + 0.5;
    }
  }
  return out;
}

/** RGBA8 texture data: R = sweep distance, G = arm distance (128 = edge). */
export function buildMarkSdf(): Uint8Array {
  const sweep = signedDistance(coverage(MARK_SWEEP));
  const arm = signedDistance(coverage(MARK_ARM));
  const px = new Uint8Array(SDF_W * SDF_H * 4);
  const enc = (d: number) => Math.max(0, Math.min(255, Math.round(128 + (d / SDF_RANGE) * 127)));
  for (let i = 0; i < sweep.length; i++) {
    px[i * 4] = enc(sweep[i]);
    px[i * 4 + 1] = enc(arm[i]);
    px[i * 4 + 2] = 0;
    px[i * 4 + 3] = 255;
  }
  return px;
}

