void main() {
  vec2 uv = vUv;
  float r = length(uv);
  float R = uRadius;
  float h = r > 0.0 ? uv.x / r : 0.0;
  vec3 tint = palette(h);
  float e = uEnergy;
  float t = uTime;
  bool light = uLight > 0.5;
  vec3 col = vec3(0.0);
  float alpha = 0.0;

  if (r < R + uPx) {
    vec2 q = uv / R;
    float rq = length(q);
    float z = sqrt(max(0.0, 1.0 - rq * rq));
    vec3 n = vec3(q, z);
    float fresThin = pow(1.0 - z, 5.0);
    float fresSoft = pow(1.0 - z, 2.2);
    float pxS = uPx / R;
    vec3 dr = refract(vec3(0.0, 0.0, -1.0), n, 0.82);
    float sExit = max(-2.0 * dot(n, dr), 0.0);
    float sMid = clamp(-dot(n, dr), 0.0, sExit);
    float cd = length(n + dr * sMid);

    // ── The 3D Y ──
    mat3 toLocal = rotX(-uTiltX) * rotY(-uTilt);
    mat3 toView = rotY(uTilt) * rotX(uTiltX);
    vec3 ro = toLocal * n;
    vec3 rd = toLocal * dr;
    float minD = 10.0;
    vec3 pB = vec3(0.0);
