/**
 * Renders any core concept (see cores/) with WebGL. A concept is a fragment shader body that
 * defines `vec4 core(vec2 uv)`; the shared prelude provides the uniforms, noise, colour and the
 * ray-marched 3D Y (whose distance field is built from the vector mark in coreSdf.ts).
 */
import type { CoreFrame } from "./cores/driver";
import { EPILOGUE, PRELUDE } from "./cores/prelude";
import type { CoreConcept } from "./cores/types";
import { SDF_H, SDF_PAD, SDF_RANGE, SDF_S, SDF_W, buildMarkSdf } from "./coreSdf";

const VERT = `
attribute vec2 aPos;
varying vec2 vUv;
void main() {
  vUv = aPos;
  gl_Position = vec4(aPos, 0.0, 1.0);
}
`;

export interface CoreGL {
  render(frame: CoreFrame, light: boolean): void;
  resize(cssSize: number, dpr: number): void;
  dispose(): void;
}

/** How wide the Y is inside the orb, in sphere units (sphere radius = 1). */
const LOGO_WIDTH = 1.16;
/** The mark spans 900 design units (x 40..940), centred on (490, 300). */
const DPU = 900 / LOGO_WIDTH;

let sdfCache: Uint8Array | null = null;

export function createCoreGL(canvas: HTMLCanvasElement, concept: CoreConcept): CoreGL | null {
  const gl = canvas.getContext("webgl", { premultipliedAlpha: true, alpha: true, antialias: false });
  if (!gl) return null;

  const compile = (type: number, src: string) => {
    const s = gl.createShader(type);
    if (!s) return null;
    gl.shaderSource(s, src);
    gl.compileShader(s);
    if (!gl.getShaderParameter(s, gl.COMPILE_STATUS)) {
      console.error(`[core:${concept.id}] shader error\n${gl.getShaderInfoLog(s)}`);
      return null;
    }
    return s;
  };
  const vs = compile(gl.VERTEX_SHADER, VERT);
  const fs = compile(gl.FRAGMENT_SHADER, PRELUDE + "\n" + concept.frag + "\n" + EPILOGUE);
  if (!vs || !fs) return null;
  const prog = gl.createProgram()!;
  gl.attachShader(prog, vs);
  gl.attachShader(prog, fs);
  gl.linkProgram(prog);
  if (!gl.getProgramParameter(prog, gl.LINK_STATUS)) {
    console.error(`[core:${concept.id}] link error\n${gl.getProgramInfoLog(prog)}`);
    return null;
  }
