470	      for (const n of st.order) {
471	        if (n.type === "core") {
472	          n.rx = n.ry = n.x = n.y = 0;
473	          continue;
474	        }
475	        if (n.type === "mod" || n.type === "more") continue;
476	        const amp = n.type === "game" ? 2.5 : 3;
477	        const still = st.drag?.id === n.id;
478	        n.rx = n.x + (still ? 0 : Math.sin(t * 0.5 + n.phase) * amp);
479	        n.ry = n.y + (still ? 0 : Math.cos(t * 0.43 + n.phase * 1.7) * amp);
480	      }
481	
482	      /* energy & core rhythm */
483	      fx.energy = Math.max(0, fx.energy - dt * 0.5);
484	      const e = fx.energy;
485	      const mode = fx.mode;
486	      const pulse =
487	        mode === "forging"
488	          ? Math.pow(0.5 + 0.5 * Math.sin(t * Math.PI * 2 * 1.25), 6)
489	          : mode === "thinking"
490	            ? Math.pow(0.5 + 0.5 * Math.sin(t * Math.PI * 2 * 0.9), 4) * 0.7
491	            : (0.5 + 0.5 * Math.sin(t * Math.PI * 2 * 0.2)) * 0.2;
492	      const f = mode === "forging" ? 1 : mode === "thinking" ? 0.6 : 0;
493	
494	      /* camera */
495	      const vc = viewCenter();
496	      if (st.follow) {
497	        const n = st.nodes.get(st.follow.id);
498	        if (n) {
499	          const p = n.type === "mod" || n.type === "more" ? pillAnchor(n, st.nodes.get(n.parent!)!) : { x: n.x, y: n.y };
500	          const aw = st.W - st.insets.l - st.insets.r;
501	          const ah = st.H - st.insets.t - st.insets.b;
502	          if (st.follow.kind === "path") {
503	            st.target.x = p.x * 0.5;
504	            st.target.y = p.y * 0.5;
505	            st.target.k = clamp(Math.min(aw / (Math.abs(p.x) + 420), ah / (Math.abs(p.y) + 300)), 0.45, 1.3);
506	          } else {
507	            // Bias toward the side a list opens so its pills stay in frame.
508	            const bias =
509	              n.type === "category"
510	                ? { left: [-120, 0], right: [120, 0], up: [0, -70], down: [0, 70] }[n.side]
511	                : n.type === "mod" || n.type === "more"
512	                  ? { left: [-80, 0], right: [80, 0], up: [0, 0], down: [0, 0] }[n.side]
513	                  : [0, 0];
514	            st.target.x = p.x + bias[0];
515	            st.target.y = p.y + bias[1];
516	            st.target.k = st.follow.k * clamp(aw / 1150, 0.65, 1);
517	          }
518	        }
519	      }
520	      const ease = 1 - Math.exp(-dt * 4.2);
521	      const cam = st.cam;
522	      cam.x += (st.target.x - cam.x) * ease;
523	      cam.y += (st.target.y - cam.y) * ease;
524	      cam.k = Math.exp(Math.log(cam.k) + (Math.log(st.target.k) - Math.log(cam.k)) * ease);
525	      // Snap once converged — otherwise the scale changes by a hair forever and every node re-rasterizes.
526	      if (Math.abs(st.target.x - cam.x) < 0.05) cam.x = st.target.x;
527	      if (Math.abs(st.target.y - cam.y) < 0.05) cam.y = st.target.y;
528	      if (Math.abs(st.target.k - cam.k) < 0.0005) cam.k = st.target.k;
529	      camera.x = cam.x;
530	      camera.y = cam.y;
531	      camera.k = cam.k;
532	      const ox = vc.x - cam.x * cam.k;
533	      const oy = vc.y - cam.y * cam.k;
534	      const worldTransform = `translate3d(${ox.toFixed(1)}px, ${oy.toFixed(1)}px, 0) scale(${cam.k.toFixed(4)})`;
535	      if (worldTransform !== st.worldTransform) {
536	        world.style.transform = worldTransform;
537	        st.worldTransform = worldTransform;
538	      }
539	      if (st.rerasterPending && now - st.kChangedAt > 180) {
540	        // will-change layers keep the raster scale they were created at; recreating them
541	        // after a zoom makes Chrome repaint them sharp at the new scale.
542	        st.rerasterPending = false;
543	        world.classList.add("reraster");
544	        requestAnimationFrame(() => world.classList.remove("reraster"));
545	      }
546	      if (Math.abs(cam.k - st.lastK) > 0.003) {
547	        st.lastK = cam.k;
548	        st.kChangedAt = now;
549	        st.rerasterPending = true;
550	        const level = cam.k < 0.8 ? "far" : cam.k < 1.3 ? "mid" : "near";
551	        if (level !== st.zoomLevel) {
552	          st.zoomLevel = level;
553	          stage.dataset.zoom = level;
554	        }
555	        cameraApi.emitZoom(cam.k);
556	      }
557	      if (now > readyAt) {
558	        world.classList.add("is-ready");
559	        readyAt = Infinity;
560	      }
561	
562	      /* DOM nodes */
563	      for (const [id, el] of nodeEls.current) {
564	        const n = st.nodes.get(id);
565	        if (!n) continue;
566	        const p = posOf(n);
567	        el.style.transform = `translate3d(${p.x.toFixed(2)}px, ${p.y.toFixed(2)}px, 0)`;
568	      }
569	
570	      /* core */
571	      const a = st.angles;
572	      a[0] += dt * (9 + e * 40 + f * 60);
573	      a[1] -= dt * (7 + e * 34 + f * 50);
574	      a[2] -= dt * (16 + e * 50 + f * 90);
575	      a[3] += dt * (14 + e * 36 + f * 80);
576	      a[4] -= dt * (4 + e * 10 + f * 20);
577	      const core = coreRef.current;
578	      if (core) {
579	        // Inherited custom properties restyle the whole core subtree, so write them only on change.
580	        const vars = `${e.toFixed(2)}|${pulse.toFixed(2)}|${f}`;
581	        if (vars !== st.coreVars) {
582	          st.coreVars = vars;
583	          core.style.setProperty("--e", e.toFixed(2));
584	          core.style.setProperty("--p", pulse.toFixed(2));
585	          core.style.setProperty("--f", String(f));
586	        }
587	        if (!st.spinEls.length || !st.spinEls[0].el.isConnected) {
588	          st.spinEls = Array.from(core.querySelectorAll<HTMLElement>("[data-spin]")).map((el) => ({
589	            el,
590	            idx: Number(el.dataset.spin),
591	            base: el.dataset.base ?? "",
592	            mult: Number(el.dataset.mult ?? 1),
593	          }));
594	        }
595	        for (const s of st.spinEls) s.el.style.transform = `${s.base} rotate(${((a[s.idx] * s.mult) % 360).toFixed(2)}deg)`;
596	      }
597	      const statusEl = statusRef.current;
598	      if (statusEl) {
599	        const g = fx.stream ? getGame(fx.stream.path[1]) : undefined;
600	        const status =
601	          mode === "forging" ? `forging → ${g?.short ?? "branch"}` : mode === "thinking" ? "thinking…" : e > 0.025 ? "listening…" : `online · ${st.modCount} mods`;
602	        if (statusEl.textContent !== status) statusEl.textContent = status;
603	      }
604	
605	      /* effects bus */
606	      for (const ev of fx.drain()) {
607	        if (ev.type === "ripple") ripple(ev.big, ev.soft);
608	        else if (ev.type === "packets") {
609	          for (let i = 0; i < ev.count; i++)
610	            spawnPacket(ev.path, { rgb: ev.rgb ?? CORE_RGB, speed: ev.speed ?? 1, size: ev.size ?? 1.2, delay: i * (ev.gap ?? 0.16), trail: 0.3 });
611	        } else if (ev.type === "burst") burst(ev.id, ev.rgb ?? CORE_RGB);
612	        else if (ev.type === "flash") flash(ev.id);
613	      }
614	
615	      if (fx.stream) {
616	        st.streamTimer -= dt;
617	        if (st.streamTimer <= 0) {
618	          spawnPacket(fx.stream.path, { rgb: fx.stream.rgb, speed: 1.15, size: 1.6, trail: 0.36 });
619	          st.streamTimer = 0.15;
620	        }
621	      }
622	      let ambient = 0;
623	      for (const p of st.packets) if (p.ambient) ambient++;
624	      if (age > 2 && ambient < 12 && Math.random() < dt * 2.2) {
625	        const path = [CORE_ID];
626	        let cur = CORE_ID;
627	        for (let d = 0; d < 3; d++) {
628	          const kids = st.children.get(cur);
629	          if (!kids?.length) break;
630	          cur = kids[Math.floor(Math.random() * kids.length)];
631	          path.push(cur);
632	        }
633	        const g = st.nodes.get(path[1]);
634	        spawnPacket(path, { ambient: true, rgb: g?.rgb ?? CORE_RGB, speed: 0.35 + Math.random() * 0.25, size: 0.8, trail: 0.14 });
635	      }
636	      st.moteAcc += dt * (mode === "thinking" ? 22 : mode === "forging" ? 14 : 0);
637	      while (st.moteAcc >= 1) {
638	        st.moteAcc -= 1;
639	        st.motes.push({
640	          a: Math.random() * Math.PI * 2,
641	          r: 200 + Math.random() * 140,
642	          va: 0.9 + Math.random() * 0.8,
643	          vr: 70 + Math.random() * 90,
644	          life: 0,
645	          rgb: MOTE_COLORS[Math.floor(Math.random() * MOTE_COLORS.length)],
646	          size: 0.6 + Math.random() * 1,
647	        });
648	      }
649	
650	      /* ───── canvas ───── */
651	      const k = cam.k;
652	      ctx.setTransform(1, 0, 0, 1, 0, 0);
653	      ctx.clearRect(0, 0, canvas.width, canvas.height);
654	      ctx.setTransform(st.dpr * k, 0, 0, st.dpr * k, st.dpr * ox, st.dpr * oy);
655	      ctx.globalCompositeOperation = dark ? "lighter" : "source-over";
656	      ctx.lineCap = "round";
657	      const px = 1 / k;
658	      const col = (rgb: string) => (dark ? rgb : inkOf(rgb));
659	      const stateAlpha = (id: string) => {
660	        const s = st.states.get(id) ?? "on";
661	        return s === "on" ? 1 : s === "near" ? 0.4 : 0.07;
662	      };
663	
664	      // The faint web around the core: concentric rings and radial threads.
665	      ctx.globalAlpha = 1;
666	      ctx.lineWidth = Math.max(0.5, 0.7 * px);
667	      ctx.strokeStyle = dark ? "rgb(147 160 255 / 0.06)" : "rgb(91 33 182 / 0.06)";
668	      for (const r of [150, 192, 255, 345]) {
669	        ctx.beginPath();
670	        ctx.arc(0, 0, r, 0, Math.PI * 2);
671	        ctx.stroke();
672	      }
673	      ctx.setLineDash([2 * px, 10 * px]);
674	      ctx.lineDashOffset = -t * 4;
675	      ctx.beginPath();
676	      ctx.arc(0, 0, 440, 0, Math.PI * 2);
677	      ctx.stroke();
678	      ctx.setLineDash([]);
679	      ctx.strokeStyle = dark ? "rgb(147 160 255 / 0.035)" : "rgb(91 33 182 / 0.04)";
680	      ctx.beginPath();
681	      for (let i = 0; i < 32; i++) {
682	        const ang = (i / 32) * Math.PI * 2;
683	        ctx.moveTo(Math.cos(ang) * 120, Math.sin(ang) * 120);
684	        ctx.lineTo(Math.cos(ang) * 360, Math.sin(ang) * 360);
685	      }
686	      ctx.stroke();
687	
688	      // Halo lights: short bright arcs orbiting on the inner rings, quickening with energy.
689	      st.halo += dt * (0.22 + f * 0.9);
690	      for (const [r, count, dir, span] of [
691	        [150, 2, 1, 0.55],
692	        [192, 3, -0.7, 0.4],
693	      ] as const) {
694	        for (let i = 0; i < count; i++) {
695	          const a0 = st.halo * dir + (i / count) * Math.PI * 2;
696	          const c = rimColor(a0 + span / 2);
697	          for (const [w, al] of [
698	            [5, 0.08],
699	            [1.6, 0.6],
700	          ] as const) {
701	            const grad = ctx.createConicGradient(a0, 0, 0);
702	            const frac = span / (Math.PI * 2);
703	            grad.addColorStop(0, `rgb(${dark ? c : inkOf(c)} / 0)`);
704	            grad.addColorStop(frac * 0.8, `rgb(${dark ? c : inkOf(c)} / ${al * (dark ? 1 : 0.7)})`);
705	            grad.addColorStop(frac, `rgb(${dark ? mix(c, 0.6) : inkOf(c)} / ${al * (dark ? 1 : 0.7)})`);
706	            grad.addColorStop(Math.min(1, frac + 0.001), `rgb(${c} / 0)`);
707	            ctx.strokeStyle = grad;
708	            ctx.lineWidth = w;
709	            ctx.beginPath();
710	            ctx.arc(0, 0, r, a0, a0 + span);
711	            ctx.stroke();
712	          }
713	        }
714	      }
715	
716	      // The 3D core: drawn by WebGL in screen space, so it's sharp at any zoom. Spin is
717	      // accumulated so typing nudges the speed smoothly instead of jumping the angle.
718	      if (st.coreStyle !== builtStyle) mountCore();
719	      const coreFrame = driver(now, dt);
720	      if (!core3d) drawCoreFallback(ctx, t, dark);
721	      if (core3d) {
722	        // The canvas covers the sphere plus the concept's outside effects: half-size = radius * extent.
723	        const size = 2 * RADIUS.core * concept.extent * k;
724	        st.frameAvg = st.frameAvg * 0.92 + dt * 1000 * 0.08;
725	        if (now - st.glQualityAt > 600) {
726	          st.glQualityAt = now;
727	          const q0 = st.glQuality;
728	          // Only give up sharpness when frames are genuinely struggling, and never by much.
729	          if (st.frameAvg > 26) st.glQuality = Math.max(0.75, st.glQuality * 0.92);
730	          else if (st.frameAvg < 19) st.glQuality = Math.min(1, st.glQuality * 1.08);
731	          if (Math.abs(q0 - st.glQuality) > 0.001) st.glSize = 0;
732	        }
733	        if (Math.abs(size - st.glSize) > 0.5) {
734	          st.glSize = size;
735	          const dprGL = Math.max(1, Math.min((window.devicePixelRatio || 1) * st.glQuality, 2, 1800 / Math.max(size, 1)));
736	          core3d.resize(size, dprGL);
737	        }
738	        glCanvas.style.transform = `translate3d(${(ox - size / 2).toFixed(1)}px, ${(oy - size / 2).toFixed(1)}px, 0)`;
739	        core3d.render(coreFrame, !dark);
740	      }
741	
742	      // Ripples off the core's rim.
743	      for (let i = st.ripples.length - 1; i >= 0; i--) {
744	        const rp = st.ripples[i];
745	        const dur = rp.kind === "big" ? 1.9 : rp.kind === "soft" ? 1.5 : 1.3;
746	        rp.t += dt;
747	        if (rp.t > dur) {
748	          st.ripples.splice(i, 1);
749	          continue;
750	        }
751	        const q = rp.t / dur;
752	        const ez = 1 - Math.pow(1 - q, 3);
753	        const reach = rp.kind === "big" ? 150 : rp.kind === "soft" ? 40 : 90;
754	        const rr = RADIUS.core + 4 + ez * reach;
755	        const strength = (1 - q) * (rp.kind === "soft" ? 0.35 : 0.8) * (dark ? 1 : 0.6);
756	        ctx.lineWidth = Math.max(1, 1.4 * px);
757	        for (let sgi = 0; sgi < 24; sgi++) {
758	          const a0 = (sgi / 24) * Math.PI * 2;
759	          const c = rimColor(a0);
760	          ctx.strokeStyle = `rgb(${dark ? c : inkOf(c)} / ${strength})`;
761	          ctx.beginPath();
762	          ctx.arc(0, 0, rr, a0, a0 + (Math.PI * 2) / 24 + 0.01);
763	          ctx.stroke();
764	        }
765	      }
