for (const n of st.order) {
  if (n.type === "core") {
    n.rx = n.ry = n.x = n.y = 0;
    continue;
  }
  if (n.type === "mod" || n.type === "more") continue;
  const amp = n.type === "game" ? 2.5 : 3;
  const still = st.drag?.id === n.id;
  n.rx = n.x + (still ? 0 : Math.sin(t * 0.5 + n.phase) * amp);
  n.ry = n.y + (still ? 0 : Math.cos(t * 0.43 + n.phase * 1.7) * amp);
}

/* energy & core rhythm */
fx.energy = Math.max(0, fx.energy - dt * 0.5);
const e = fx.energy;
const mode = fx.mode;
const pulse =
  mode === "forging"
    ? Math.pow(0.5 + 0.5 * Math.sin(t * Math.PI * 2 * 1.25), 6)
    : mode === "thinking"
      ? Math.pow(0.5 + 0.5 * Math.sin(t * Math.PI * 2 * 0.9), 4) * 0.7
      : (0.5 + 0.5 * Math.sin(t * Math.PI * 2 * 0.2)) * 0.2;
const f = mode === "forging" ? 1 : mode === "thinking" ? 0.6 : 0;

/* camera */
const vc = viewCenter();
if (st.follow) {
  const n = st.nodes.get(st.follow.id);
  if (n) {
    const p = n.type === "mod" || n.type === "more" ? pillAnchor(n, st.nodes.get(n.parent!)!) : { x: n.x, y: n.y };
    const aw = st.W - st.insets.l - st.insets.r;
    const ah = st.H - st.insets.t - st.insets.b;
    if (st.follow.kind === "path") {
      st.target.x = p.x * 0.5;
      st.target.y = p.y * 0.5;
      st.target.k = clamp(Math.min(aw / (Math.abs(p.x) + 420), ah / (Math.abs(p.y) + 300)), 0.45, 1.3);
    } else {
      // Bias toward the side a list opens so its pills stay in frame.
      const bias =
        n.type === "category"
          ? { left: [-120, 0], right: [120, 0], up: [0, -70], down: [0, 70] }[n.side]
          : n.type === "mod" || n.type === "more"
            ? { left: [-80, 0], right: [80, 0], up: [0, 0], down: [0, 0] }[n.side]
            : [0, 0];
      st.target.x = p.x + bias[0];
      st.target.y = p.y + bias[1];
      st.target.k = st.follow.k * clamp(aw / 1150, 0.65, 1);
    }
