  ctx.stroke();
}
ctx.setLineDash([2 * px, 10 * px]);
ctx.lineDashOffset = -t * 4;
ctx.beginPath();
ctx.arc(0, 0, 440, 0, Math.PI * 2);
ctx.stroke();
ctx.setLineDash([]);
ctx.strokeStyle = dark ? "rgb(147 160 255 / 0.035)" : "rgb(91 33 182 / 0.04)";
ctx.beginPath();
for (let i = 0; i < 32; i++) {
  const ang = (i / 32) * Math.PI * 2;
  ctx.moveTo(Math.cos(ang) * 120, Math.sin(ang) * 120);
  ctx.lineTo(Math.cos(ang) * 360, Math.sin(ang) * 360);
}
ctx.stroke();

// Halo lights: short bright arcs orbiting on the inner rings, quickening with energy.
st.halo += dt * (0.22 + f * 0.9);
for (const [r, count, dir, span] of [
  [150, 2, 1, 0.55],
  [192, 3, -0.7, 0.4],
] as const) {
  for (let i = 0; i < count; i++) {
    const a0 = st.halo * dir + (i / count) * Math.PI * 2;
    const c = rimColor(a0 + span / 2);
    for (const [w, al] of [
      [5, 0.08],
      [1.6, 0.6],
    ] as const) {
      const grad = ctx.createConicGradient(a0, 0, 0);
      const frac = span / (Math.PI * 2);
      grad.addColorStop(0, `rgb(${dark ? c : inkOf(c)} / 0)`);
      grad.addColorStop(frac * 0.8, `rgb(${dark ? c : inkOf(c)} / ${al * (dark ? 1 : 0.7)})`);
      grad.addColorStop(frac, `rgb(${dark ? mix(c, 0.6) : inkOf(c)} / ${al * (dark ? 1 : 0.7)})`);
      grad.addColorStop(Math.min(1, frac + 0.001), `rgb(${c} / 0)`);
      ctx.strokeStyle = grad;
      ctx.lineWidth = w;
