// accumulated so typing nudges the speed smoothly instead of jumping the angle.
if (st.coreStyle !== builtStyle) mountCore();
const coreFrame = driver(now, dt);
if (!core3d) drawCoreFallback(ctx, t, dark);
if (core3d) {
