}

// Ripples off the core's rim.
for (let i = st.ripples.length - 1; i >= 0; i--) {
  const rp = st.ripples[i];
  const dur = rp.kind === "big" ? 1.9 : rp.kind === "soft" ? 1.5 : 1.3;
  rp.t += dt;
  if (rp.t > dur) {
    st.ripples.splice(i, 1);
    continue;
  }
  const q = rp.t / dur;
  const ez = 1 - Math.pow(1 - q, 3);
