  const strength = (1 - q) * (rp.kind === "soft" ? 0.35 : 0.8) * (dark ? 1 : 0.6);
  ctx.lineWidth = Math.max(1, 1.4 * px);
  for (let sgi = 0; sgi < 24; sgi++) {
    const a0 = (sgi / 24) * Math.PI * 2;
    const c = rimColor(a0);
    ctx.strokeStyle = `rgb(${dark ? c : inkOf(c)} / ${strength})`;
    ctx.beginPath();
    ctx.arc(0, 0, rr, a0, a0 + (Math.PI * 2) / 24 + 0.01);
    ctx.stroke();
  }
}

