// Real-time screenshots through the Chrome DevTools protocol.
// usage: node shot.mjs <out.png> [waitMs] [js-to-eval-before-capture] [clipX,clipY,clipW,clipH] [width,height]
import { spawn } from "node:child_process";
import { writeFileSync } from "node:fs";

const [out, waitMs = "6000", evalJs = "", clip = "", size = "1600,940"] = process.argv.slice(2);
const [W, H] = size.split(",").map(Number);
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const port = 9333 + Math.floor(Math.random() * 400);
const chrome = spawn("C:/Program Files/Google/Chrome/Application/chrome.exe", [
  "--headless=new",
  `--remote-debugging-port=${port}`,
  "--hide-scrollbars",
  `--window-size=${W},${H}`,
  `--user-data-dir=C:/Users/edmem/AppData/Local/Temp/cyrus-shots/prof-${port}`,
  "about:blank",
]);
let targets;
for (let i = 0; i < 40; i++) {
  await sleep(250);
  try {
    targets = await (await fetch(`http://127.0.0.1:${port}/json`)).json();
    if (targets.some((t) => t.type === "page")) break;
  } catch {}
}
const page = targets.find((t) => t.type === "page");
const ws = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((r) => (ws.onopen = r));
let id = 0;
const pending = new Map();
ws.onmessage = (m) => {
  const msg = JSON.parse(m.data);
  if (msg.id && pending.has(msg.id)) {
    pending.get(msg.id)(msg);
    pending.delete(msg.id);
  }
};
const send = (method, params = {}) =>
  new Promise((r) => {
    const i = ++id;
    pending.set(i, r);
    ws.send(JSON.stringify({ id: i, method, params }));
  });

await send("Emulation.setDeviceMetricsOverride", { width: W, height: H, deviceScaleFactor: 2, mobile: false });
await send("Page.enable");
await send("Page.navigate", { url: "http://localhost:3000" });
await sleep(Number(waitMs));
if (evalJs) {
  const r = await send("Runtime.evaluate", { expression: evalJs, awaitPromise: true, returnByValue: true });
  console.log("eval:", JSON.stringify(r.result?.result?.value ?? r.result));
}
const params = { format: "png" };
if (clip) {
  const [x, y, w, h] = clip.split(",").map(Number);
  params.clip = { x, y, width: w, height: h, scale: 1 };
}
const shot = await send("Page.captureScreenshot", params);
writeFileSync(out, Buffer.from(shot.result.data, "base64"));
console.log("saved", out);
ws.close();
chrome.kill();
process.exit(0);
