import type { CoreGL } from "@/components/cosmos/coreGL";
import { createCoreDriver, decayEnergy } from "@/components/cosmos/cores/driver";

/**
 * One animation loop for every live core on the gallery page: the effects bus is turned into a
 * frame once, then each visible core renders it. Outside the network there's nobody else to
 * decay the typing energy, so the loop does that too.
 */
export interface CoreView {
  gl: CoreGL | null;
  visible: boolean;
  /** Re-applies the canvas size at the current quality. */
  refit(): void;
}

const views = new Set<CoreView>();
const loop = {
  raf: 0,
  last: 0,
  light: false,
  /** When set, only this view renders (the large preview covers the grid). */
  focus: null as CoreView | null,
  /** Render-resolution multiplier, lowered a little when frames struggle. */
  quality: 1,
  frameAvg: 16,
  checkedAt: 0,
  driver: null as ReturnType<typeof createCoreDriver> | null,
};

function tick(now: number) {
  loop.raf = requestAnimationFrame(tick);
  const dt = Math.min(0.05, Math.max(0.001, (now - (loop.last || now)) / 1000));
  loop.last = now;
  decayEnergy(dt);
  loop.driver ??= createCoreDriver();
  const frame = loop.driver(now, dt);

  loop.frameAvg = loop.frameAvg * 0.92 + dt * 1000 * 0.08;
  if (now - loop.checkedAt > 700) {
    loop.checkedAt = now;
    const q0 = loop.quality;
    if (loop.frameAvg > 24) loop.quality = Math.max(0.6, loop.quality * 0.9);
    else if (loop.frameAvg < 18) loop.quality = Math.min(1, loop.quality * 1.06);
    if (Math.abs(q0 - loop.quality) > 0.001) for (const v of views) v.refit();
  }

  for (const v of views) {
    if (!v.gl || !v.visible) continue;
    if (loop.focus && v !== loop.focus) continue;
    v.gl.render(frame, loop.light);
  }
}

export function addView(v: CoreView) {
  views.add(v);
  if (!loop.raf) {
    loop.last = 0;
    loop.raf = requestAnimationFrame(tick);
  }
}

export function removeView(v: CoreView) {
  views.delete(v);
  if (loop.focus === v) loop.focus = null;
  if (!views.size && loop.raf) {
    cancelAnimationFrame(loop.raf);
    loop.raf = 0;
  }
}

export function setFocus(v: CoreView | null) {
  loop.focus = v;
}

export function setLight(light: boolean) {
  loop.light = light;
}

export function renderQuality() {
  return loop.quality;
}

