            spellCheck={false}
          />
          <button
            type="button"
            onClick={() => {
              setAuto((a) => !a);
              if (auto) setText("");
            }}
            className={`cores-chip ${auto ? "is-on" : ""}`}
            title={auto ? "Stop auto-typing" : "Auto-type starter prompts"}
          >
            {auto ? <StopIcon /> : <PlayIcon />}
            <span className="hidden md:inline">Auto-type</span>
          </button>
        </label>

        <div className="glass-soft hidden shrink-0 items-center gap-0.5 rounded-xl p-1 lg:flex" role="radiogroup" aria-label="Core state">
          {(["idle", "thinking", "forging"] as const).map((m) => (
            <button
              key={m}
              type="button"
              role="radio"
              aria-checked={mode === m}
              onClick={() => setModeState(m)}
              className={`cores-seg ${mode === m ? "is-on" : ""}`}
            >
              {m === "idle" ? "Idle" : m === "thinking" ? "Thinking" : "Forging"}
            </button>
          ))}
        </div>

        <button
          type="button"
          onClick={() => setTheme(theme === "dark" ? "light" : "dark")}
          className="glass-soft grid h-10 w-10 shrink-0 place-items-center rounded-xl text-[16px] text-ink-2 transition hover:text-ink"
          aria-label={`Switch to ${theme === "dark" ? "light" : "dark"} mode`}
        >
          {theme === "dark" ? <SunIcon /> : <MoonIcon />}
        </button>
      </header>

      <section className="mx-auto w-full max-w-[1480px] px-4 pb-24 md:px-8">
        <div className="cores-hero animate-rise">
          <p className="cores-eyebrow">Core lab</p>
          <h1 className="font-display text-[clamp(30px,4.4vw,52px)] font-bold leading-[1.02] tracking-tight text-ink">
            Choose the heart of <span className="cores-grad">Cyrus</span>
          </h1>
          <p className="mt-4 max-w-[640px] text-[15px] leading-relaxed text-muted">
            {CORE_CONCEPTS.length} living cores, each reacting to your typing in its own way. Type in the bar above, or leave auto-type running, switch
            between idle, thinking and forging, and pick the one that feels right. Click any core for a closer look.
          </p>
          <div className="mt-5 flex flex-wrap items-center gap-2 text-[12px]">
            {(["3D", "2.5D", "2D"] as const)
              .filter((k) => counts[k])
              .map((k) => (
                <span key={k} className="cores-kind tint" style={{ ["--c" as string]: KIND_RGB[k] }}>
                  {counts[k]} × {k}
                </span>
              ))}
            <span className="ml-1 text-muted">
              Active: <span className="font-medium text-ink">{active.name}</span>
            </span>
          </div>
        </div>

        <div className="grid grid-cols-1 gap-5 sm:grid-cols-2 xl:grid-cols-3">
          {CORE_CONCEPTS.map((c, i) => (
            <ConceptCard key={c.id} concept={c} index={i} active={c.id === coreStyle} onChoose={choose} onPreview={() => setPreview(i)} />
          ))}
        </div>
      </section>

      {preview !== null && (
        <PreviewModal
          index={preview}
          activeId={coreStyle}
          onClose={() => setPreview(null)}
          onIndex={(i) => setPreview((i + CORE_CONCEPTS.length) % CORE_CONCEPTS.length)}
          onChoose={choose}
        />
      )}

      {toast && (
        <div className="cores-toast glass animate-pop" role="status">
          <CheckIcon className="text-[15px] text-cyan" />
          <span>
            <span className="font-semibold text-ink">{toast}</span> is now the Cyrus core
          </span>
          <Link href="/" className="cores-toast-link">
            Back to network <ChevronRightIcon className="text-[12px]" />
          </Link>
        </div>
      )}
    </main>
  );
}

/* ───────────────────────── Card ───────────────────────── */

function ConceptCard({
  concept: c,
  index,
  active,
  onChoose,
  onPreview,
}: {
  concept: CoreConcept;
  index: number;
  active: boolean;
  onChoose: (c: CoreConcept) => void;
  onPreview: () => void;
}) {
  return (
    <article className="core-card animate-rise" data-active={active || undefined} style={{ animationDelay: `${index * 45}ms` }}>
      <button type="button" className="core-card-stage" onClick={onPreview} aria-label={`Preview ${c.name} up close`}>
        <CoreCanvas concept={c} fit={0.27} />
        <span className="core-card-index">{pad(index + 1)}</span>
        <span className="cores-kind tint absolute right-3.5 top-3.5" style={{ ["--c" as string]: KIND_RGB[c.kind] }}>
          {c.kind}
        </span>
        <span className="core-card-zoom">
          <ExpandIcon /> Preview
        </span>
      </button>

      <div className="flex flex-1 flex-col px-5 pb-5 pt-4">
        <div className="flex items-center gap-2">
          <h2 className="font-display text-[18px] font-semibold tracking-tight text-ink">{c.name}</h2>
          {active && (
            <span className="core-card-active">
              <CheckIcon /> Active
            </span>
          )}
        </div>
        <p className="mt-0.5 text-[13px] font-medium text-ink-2">{c.tagline}</p>
        <p className="mt-2.5 text-[12.5px] leading-relaxed text-muted">{c.description}</p>
        <p className="core-card-typing">
          <KeyboardIcon className="mt-px shrink-0 text-[14px]" />
          <span>{c.typing}</span>
        </p>
        <div className="mt-auto flex items-center gap-2 pt-4">
          <button type="button" onClick={() => onChoose(c)} disabled={active} className="cores-primary">
            {active ? (
              <>
                <CheckIcon /> In use
              </>
            ) : (
              "Use this core"
            )}
          </button>
          <button type="button" onClick={onPreview} className="btn-ghost h-9 px-3 text-[12.5px]">
            <ExpandIcon /> Preview
          </button>
        </div>
      </div>
    </article>
  );
}

/* ───────────────────────── Preview ───────────────────────── */

function PreviewModal({
  index,
  activeId,
  onClose,
  onIndex,
  onChoose,
}: {
  index: number;
  activeId: string;
  onClose: () => void;
  onIndex: (i: number) => void;
  onChoose: (c: CoreConcept) => void;
}) {
  const c = CORE_CONCEPTS[index];
  const [text, setText] = useState("");
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    inputRef.current?.focus({ preventScroll: true });
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose();
      const inInput = e.target === inputRef.current && (inputRef.current?.value ?? "") !== "";
      if (inInput) return;
      if (e.key === "ArrowRight") onIndex(index + 1);
      if (e.key === "ArrowLeft") onIndex(index - 1);
    };
    window.addEventListener("keydown", onKey);
    const prev = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => {
      window.removeEventListener("keydown", onKey);
      document.body.style.overflow = prev;
    };
  }, [index, onClose, onIndex]);

  const active = c.id === activeId;
  return (
    <div className="cores-modal animate-fade" role="dialog" aria-modal="true" aria-label={`${c.name} preview`} onPointerDown={onClose}>
      <div className="cores-modal-inner" onPointerDown={(e) => e.stopPropagation()}>
        <div className="cores-modal-stage">
          {/* key: a fresh renderer per concept, so its shader compiles from scratch. */}
          <CoreCanvas key={c.id} concept={c} fit={0.24} maxDpr={2} focus />
          <button type="button" className="cores-nav left-4" onClick={() => onIndex(index - 1)} aria-label="Previous core">
            <ChevronLeftIcon />
          </button>
          <button type="button" className="cores-nav right-4" onClick={() => onIndex(index + 1)} aria-label="Next core">
            <ChevronRightIcon />
          </button>
          <div className="cores-dots" aria-hidden>
            {CORE_CONCEPTS.map((x, i) => (
              <span key={x.id} className={i === index ? "is-on" : ""} />
            ))}
          </div>
        </div>

        <aside className="cores-modal-side">
          <div className="flex items-center justify-between">
            <span className="font-mono text-[11px] tracking-[0.2em] text-faint">
              {pad(index + 1)} / {pad(CORE_CONCEPTS.length)}
            </span>
            <button type="button" onClick={onClose} className="btn-ghost h-8 w-8 text-[15px]" aria-label="Close preview">
              <CloseIcon />
            </button>
          </div>
          <div className="mt-5 flex items-center gap-2">
            <span className="cores-kind tint" style={{ ["--c" as string]: KIND_RGB[c.kind] }}>
              {c.kind}
            </span>
            {active && (
              <span className="core-card-active">
                <CheckIcon /> Active
              </span>
            )}
          </div>
          <h2 className="mt-3 font-display text-[30px] font-bold leading-tight tracking-tight text-ink">{c.name}</h2>
          <p className="mt-1 text-[14px] font-medium text-ink-2">{c.tagline}</p>
          <p className="mt-4 text-[13.5px] leading-relaxed text-muted">{c.description}</p>
          <p className="core-card-typing mt-5">
            <KeyboardIcon className="mt-px shrink-0 text-[14px]" />
            <span>{c.typing}</span>
          </p>

          <label className="cores-input glass-soft mt-6 w-full">
            <KeyboardIcon className="shrink-0 text-[16px] text-muted" />
            <input
              ref={inputRef}
              value={text}
              onChange={(e) => {
                onTyped(text, e.target.value);
                setText(e.target.value);
              }}
              placeholder="Type to see it react…"
              aria-label="Type to charge this core"
              spellCheck={false}
            />
          </label>

          <div className="mt-auto flex items-center gap-2 pt-6">
            <button type="button" onClick={() => onChoose(c)} disabled={active} className="cores-primary flex-1">
              {active ? (
                <>
                  <CheckIcon /> In use
                </>
              ) : (
                "Use this core"
              )}
            </button>
          </div>
          <p className="mt-3 text-center text-[11px] text-faint">
            <span className="kbd">←</span> <span className="kbd">→</span> to browse · <span className="kbd">Esc</span> to close
          </p>
        </aside>
      </div>
    </div>
  );
}

