/* ───────────────────────── Core lab (/cores) ───────────────────────── */

.core-host {
  position: absolute;
  inset: 0;
  pointer-events: none;
}
.core-host > canvas {
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
}

.cores-page {
  position: relative;
  min-height: 100vh;
  background: var(--bg);
  color: var(--ink);
  isolation: isolate;
}

.cores-backdrop {
  position: fixed;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  background:
    radial-gradient(60vw 42vh at 12% -6%, rgb(91 33 182 / 0.22), transparent 70%),
    radial-gradient(48vw 40vh at 92% 4%, rgb(8 145 178 / 0.13), transparent 70%),
    radial-gradient(70vw 60vh at 50% 120%, rgb(76 29 149 / 0.16), transparent 70%),
    var(--bg);
}
.light .cores-backdrop {
  background:
    radial-gradient(60vw 42vh at 12% -6%, rgb(167 139 250 / 0.2), transparent 70%),
    radial-gradient(48vw 40vh at 92% 4%, rgb(103 232 249 / 0.16), transparent 70%),
    var(--bg);
}

/* ── Sticky control bar ── */

.cores-bar {
  position: sticky;
  top: 0;
  z-index: 30;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 16px;
  background: linear-gradient(180deg, rgb(5 3 11 / 0.92), rgb(5 3 11 / 0.72));
  backdrop-filter: blur(14px) saturate(140%);
  -webkit-backdrop-filter: blur(14px) saturate(140%);
  border-bottom: 1px solid var(--line);
}
.light .cores-bar {
  background: linear-gradient(180deg, rgb(253 252 255 / 0.94), rgb(253 252 255 / 0.78));
}
@media (min-width: 768px) {
  .cores-bar {
    padding: 12px 32px;
  }
}

.cores-input {
  display: flex;
  flex: 1;
  min-width: 0;
  max-width: 720px;
  align-items: center;
  gap: 10px;
  height: 42px;
  padding: 0 6px 0 14px;
  border-radius: 14px;
  transition:
    border-color 0.2s,
    box-shadow 0.2s;
}
.cores-input:focus-within {
  border-color: rgb(var(--glow) / 0.5);
  box-shadow: 0 0 0 3px rgb(var(--glow) / 0.12), 0 0 24px -6px rgb(var(--glow) / 0.5);
}
.cores-input input {
  flex: 1;
  min-width: 0;
  background: transparent;
  outline: none;
  font-size: 14px;
  color: var(--ink);
}
.cores-input input::placeholder {
  color: var(--faint);
}

.cores-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 30px;
  padding: 0 10px;
  border-radius: 10px;
  font-size: 12px;
  font-weight: 500;
  color: var(--muted);
  transition:
    background-color 0.2s,
    color 0.2s;
}
.cores-chip:hover {
  color: var(--ink);
  background: rgb(var(--glow) / 0.1);
}
.cores-chip.is-on {
  color: var(--accent-ink);
  background: rgb(var(--glow) / 0.14);
}

.cores-seg {
  height: 32px;
  padding: 0 12px;
  border-radius: 9px;
  font-size: 12.5px;
  color: var(--muted);
  transition:
    background-color 0.2s,
    color 0.2s;
}
.cores-seg:hover {
  color: var(--ink);
}
.cores-seg.is-on {
  color: var(--ink);
  background: rgb(var(--glow) / 0.16);
  box-shadow: inset 0 0 0 1px rgb(var(--glow) / 0.3);
}

/* ── Hero ── */

.cores-hero {
  padding: 56px 0 36px;
}
.cores-eyebrow {
  margin-bottom: 14px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.32em;
  text-transform: uppercase;
  color: var(--accent-ink);
}
.cores-grad {
  background: linear-gradient(100deg, #67e8f9 0%, #a78bfa 45%, #f0abfc 90%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  filter: drop-shadow(0 0 22px rgb(167 139 250 / 0.35));
}
.light .cores-grad {
  background: linear-gradient(100deg, #0891b2 0%, #7c3aed 50%, #c026d3 95%);
  -webkit-background-clip: text;
  background-clip: text;
  filter: none;
}

.cores-kind {
  display: inline-flex;
  align-items: center;
  height: 22px;
  padding: 0 9px;
  border-radius: 999px;
  font-family: var(--font-jb), monospace;
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.06em;
  color: var(--cc-ink);
  background: color-mix(in oklab, var(--cc) 12%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in oklab, var(--cc) 34%, transparent);
}

/* ── Cards ── */

.core-card {
  position: relative;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  border-radius: 24px;
  background: linear-gradient(180deg, rgb(18 12 38 / 0.72), rgb(10 7 22 / 0.86));
  border: 1px solid var(--line);
  box-shadow: 0 30px 70px -40px rgb(0 0 0 / 0.9);
  transition:
    border-color 0.3s,
    box-shadow 0.3s,
    transform 0.4s var(--ease-out-expo);
}
.core-card:hover {
  border-color: var(--line-2);
  transform: translateY(-2px);
  box-shadow: 0 36px 80px -40px rgb(0 0 0 / 0.95), 0 0 0 1px rgb(var(--glow) / 0.08);
}
.core-card[data-active] {
  border-color: rgb(var(--glow) / 0.55);
  box-shadow:
    0 0 0 1px rgb(var(--glow) / 0.35),
    0 30px 80px -36px rgb(var(--glow) / 0.55);
}
.light .core-card {
  background: linear-gradient(180deg, #ffffff, #faf8ff);
  box-shadow: 0 24px 60px -36px rgb(76 29 149 / 0.32);
}

.core-card-stage {
  position: relative;
  display: block;
  width: 100%;
  aspect-ratio: 5 / 4;
  overflow: hidden;
  cursor: zoom-in;
  background:
    radial-gradient(55% 55% at 50% 50%, rgb(76 29 149 / 0.16), transparent 72%),
    radial-gradient(1px 1px at 18% 24%, rgb(255 255 255 / 0.45), transparent 60%),
    radial-gradient(1px 1px at 76% 18%, rgb(255 255 255 / 0.35), transparent 60%),
    radial-gradient(1px 1px at 84% 72%, rgb(255 255 255 / 0.3), transparent 60%),
    radial-gradient(1px 1px at 28% 82%, rgb(255 255 255 / 0.3), transparent 60%),
    radial-gradient(1px 1px at 58% 8%, rgb(255 255 255 / 0.25), transparent 60%),
    linear-gradient(180deg, #0a0618, #05030b);
  border-bottom: 1px solid var(--line);
}
.light .core-card-stage {
  background:
    radial-gradient(55% 55% at 50% 50%, rgb(167 139 250 / 0.14), transparent 72%),
    linear-gradient(180deg, #fbfaff, #f3efff);
}

.core-card-index {
  position: absolute;
  left: 16px;
  top: 14px;
  font-family: var(--font-jb), monospace;
  font-size: 11px;
  letter-spacing: 0.2em;
  color: var(--faint);
}

.core-card-zoom {
  position: absolute;
  right: 12px;
  bottom: 12px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 28px;
  padding: 0 10px;
  border-radius: 9px;
  font-size: 11.5px;
  color: var(--ink-2);
  background: var(--surface-soft);
  border: 1px solid var(--line);
  opacity: 0;
  transform: translateY(4px);
  transition:
    opacity 0.25s,
    transform 0.35s var(--ease-out-expo);
}
.core-card-stage:hover .core-card-zoom,
.core-card-stage:focus-visible .core-card-zoom {
  opacity: 1;
  transform: none;
}

.core-card-active {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  height: 20px;
  padding: 0 8px;
  border-radius: 999px;
  font-size: 10.5px;
  font-weight: 600;
  color: var(--accent-ink);
  background: rgb(var(--glow) / 0.14);
}

.core-card-typing {
  display: flex;
  gap: 8px;
  margin-top: 12px;
  padding: 9px 11px;
  border-radius: 12px;
  font-size: 12px;
  line-height: 1.5;
  color: var(--ink-2);
  background: rgb(var(--glow) / 0.06);
  border: 1px solid var(--line);
}
.core-card-typing svg {
  color: var(--cyan);
}

.cores-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  height: 36px;
  padding: 0 16px;
  border-radius: 11px;
  font-size: 13px;
  font-weight: 600;
  color: white;
  background: linear-gradient(100deg, #7c3aed, #a855f7 55%, #0ea5e9);
  box-shadow:
    0 10px 26px -10px rgb(124 58 237 / 0.8),
    inset 0 1px 0 rgb(255 255 255 / 0.22);
  transition:
    transform 0.2s var(--ease-spring),
    filter 0.2s,
    box-shadow 0.2s;
}
.cores-primary:hover:not(:disabled) {
  filter: brightness(1.12);
  box-shadow:
    0 14px 32px -10px rgb(124 58 237 / 0.95),
    inset 0 1px 0 rgb(255 255 255 / 0.22);
}
.cores-primary:active:not(:disabled) {
  transform: scale(0.96);
}
.cores-primary:disabled {
  cursor: default;
  color: var(--accent-ink);
  background: rgb(var(--glow) / 0.12);
  box-shadow: inset 0 0 0 1px rgb(var(--glow) / 0.3);
}

/* ── Preview modal ── */

.cores-modal {
  position: fixed;
  inset: 0;
  z-index: 60;
  display: grid;
  place-items: center;
  padding: 16px;
  background: rgb(3 2 8 / 0.78);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
}
.light .cores-modal {
  background: rgb(237 231 255 / 0.7);
}

.cores-modal-inner {
  display: flex;
  flex-direction: column;
  width: min(1320px, 100%);
  height: min(860px, 100%);
  overflow: hidden;
  border-radius: 28px;
  border: 1px solid var(--line-2);
  background: #05030b;
  box-shadow: 0 50px 120px -30px rgb(0 0 0 / 0.9);
}
.light .cores-modal-inner {
  background: #fdfcff;
  box-shadow: 0 50px 120px -40px rgb(76 29 149 / 0.4);
}
@media (min-width: 900px) {
  .cores-modal-inner {
    flex-direction: row;
  }
}

.cores-modal-stage {
  position: relative;
  flex: 1;
  min-height: 52vh;
  overflow: hidden;
  background:
    radial-gradient(50% 50% at 50% 50%, rgb(76 29 149 / 0.2), transparent 72%),
    radial-gradient(1px 1px at 14% 22%, rgb(255 255 255 / 0.5), transparent 60%),
    radial-gradient(1px 1px at 82% 16%, rgb(255 255 255 / 0.4), transparent 60%),
    radial-gradient(1px 1px at 88% 78%, rgb(255 255 255 / 0.35), transparent 60%),
    radial-gradient(1px 1px at 22% 86%, rgb(255 255 255 / 0.35), transparent 60%),
    radial-gradient(1.5px 1.5px at 64% 6%, rgb(255 255 255 / 0.3), transparent 60%),
    radial-gradient(1px 1px at 6% 58%, rgb(255 255 255 / 0.3), transparent 60%),
    #05030b;
}
.light .cores-modal-stage {
  background:
    radial-gradient(50% 50% at 50% 50%, rgb(167 139 250 / 0.16), transparent 72%),
    #fbfaff;
}

.cores-modal-side {
  display: flex;
  flex-direction: column;
  padding: 24px;
  border-top: 1px solid var(--line);
  background: linear-gradient(180deg, rgb(18 12 38 / 0.6), rgb(10 7 22 / 0.9));
}
.light .cores-modal-side {
  background: linear-gradient(180deg, #ffffff, #faf8ff);
}
@media (min-width: 900px) {
  .cores-modal-side {
    width: 380px;
    border-top: 0;
    border-left: 1px solid var(--line);
    padding: 28px;
  }
}

.cores-nav {
  position: absolute;
  top: 50%;
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  margin-top: -21px;
