  border-bottom: 1px solid var(--line);
}
.light .core-card-stage {
  background:
    radial-gradient(55% 55% at 50% 50%, rgb(167 139 250 / 0.14), transparent 72%),
    linear-gradient(180deg, #fbfaff, #f3efff);
}

.core-card-index {
  position: absolute;
  left: 16px;
  top: 14px;
  font-family: var(--font-jb), monospace;
  font-size: 11px;
  letter-spacing: 0.2em;
  color: var(--faint);
}

.core-card-zoom {
  position: absolute;
  right: 12px;
  bottom: 12px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 28px;
  padding: 0 10px;
  border-radius: 9px;
  font-size: 11.5px;
  color: var(--ink-2);
  background: var(--surface-soft);
  border: 1px solid var(--line);
  opacity: 0;
  transform: translateY(4px);
  transition:
    opacity 0.25s,
    transform 0.35s var(--ease-out-expo);
}
.core-card-stage:hover .core-card-zoom,
.core-card-stage:focus-visible .core-card-zoom {
  opacity: 1;
  transform: none;
}

.core-card-active {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  height: 20px;
  padding: 0 8px;
  border-radius: 999px;
  font-size: 10.5px;
  font-weight: 600;
  color: var(--accent-ink);
  background: rgb(var(--glow) / 0.14);
}

.core-card-typing {
  display: flex;
  gap: 8px;
  margin-top: 12px;
  padding: 9px 11px;
  border-radius: 12px;
  font-size: 12px;
  line-height: 1.5;
  color: var(--ink-2);
  background: rgb(var(--glow) / 0.06);
  border: 1px solid var(--line);
}
.core-card-typing svg {
  color: var(--cyan);
}

.cores-primary {
  display: inline-flex;
