"use client";

import { useEffect, useRef } from "react";
import { camera } from "@/lib/camera";
import { useStore } from "@/lib/store";

interface Star {
  x: number;
  y: number;
  r: number;
  a: number;
  tw: number;
  ph: number;
  d: number;
  tint: number;
}

const TINTS_DARK = ["255 255 255", "221 214 254", "196 181 253", "165 243 252", "251 207 232"];
const TINTS_LIGHT = ["124 58 237", "139 92 246", "8 145 178", "192 38 211", "99 102 241"];

function Wisp({
  w,
  h,
  r,
  c,
  thin,
  delay = 0,
  ...pos
}: {
  w: string;
  h: string;
  r: number;
  c: string;
  thin?: boolean;
  delay?: number;
  left?: string;
  right?: string;
  top?: string;
  bottom?: string;
}) {
  return (
    <div
      className={`wisp${thin ? " thin" : ""}`}
      style={{
        ...pos,
        width: w,
        height: h,
        background: `linear-gradient(90deg, transparent, ${c}, transparent)`,
        ["--r" as string]: `${r}deg`,
        ["--wd" as string]: `${46 + Math.abs(r) * 0.9}s`,
        ["--wb" as string]: `${13 + ((Math.abs(r) * 7) % 11)}s`,
        transform: `rotate(${r}deg)`,
        animationDelay: `${delay}s, ${delay * 0.6}s`,
      }}
    />
  );
}

export function CosmosBackground() {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const wispsRef = useRef<HTMLDivElement>(null);
  const theme = useStore((s) => s.theme);
  const themeRef = useRef(theme);
  themeRef.current = theme;

  useEffect(() => {
    const canvas = canvasRef.current!;
    const ctx = canvas.getContext("2d")!;
    let W = 0;
    let H = 0;
    let dpr = 1;
    let stars: Star[] = [];
    let shooting: { x: number; y: number; vx: number; vy: number; life: number } | null = null;
    let nextShot = performance.now() + 6000;
    let raf = 0;
    let last = 0;
    let layerTransform = "";

    const resize = () => {
      dpr = Math.min(window.devicePixelRatio || 1, 2);
      W = window.innerWidth;
      H = window.innerHeight;
      canvas.width = W * dpr;
      canvas.height = H * dpr;
      canvas.style.width = `${W}px`;
      canvas.style.height = `${H}px`;
      const count = Math.min(320, Math.round((W * H) / 6500));
      stars = Array.from({ length: count }, () => {
        const big = Math.random() < 0.035;
        return {
          x: Math.random(),
          y: Math.random(),
          r: big ? 0.8 + Math.random() * 0.6 : 0.25 + Math.random() * 0.5,
          a: big ? 0.45 + Math.random() * 0.25 : 0.08 + Math.random() * 0.28,
          tw: 0.15 + Math.random() * 0.5,
          ph: Math.random() * Math.PI * 2,
          d: 0.2 + Math.random() * 0.8,
          tint: Math.random() < 0.7 ? 0 : 1 + Math.floor(Math.random() * 4),
        };
      });
    };
    resize();
    window.addEventListener("resize", resize);

    const frame = (now: number) => {
      raf = requestAnimationFrame(frame);
      // Stars don't need 120fps.
      // Aurora parallax runs every frame so panning feels attached; stars can tick at 30fps.
      const layer = wispsRef.current;
      if (layer) {
        const tx = Math.max(-0.3 * W, Math.min(0.3 * W, -camera.x * camera.k * 0.3));
        const ty = Math.max(-0.3 * H, Math.min(0.3 * H, -camera.y * camera.k * 0.3));
        const sc = Math.max(0.9, Math.min(1.2, 1 + (camera.k - 0.7) * 0.14));
        const tf = `translate3d(${tx.toFixed(1)}px, ${ty.toFixed(1)}px, 0) scale(${sc.toFixed(3)})`;
        if (tf !== layerTransform) {
          layer.style.transform = tf;
          layerTransform = tf;
        }
      }
      if (now - last < 32) return;
      last = now;
      const dark = themeRef.current === "dark";
      const t = now / 1000;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, W, H);
      const tints = dark ? TINTS_DARK : TINTS_LIGHT;
      const lightScale = dark ? 1 : 0.32;

      for (const s of stars) {
        // Gentle parallax against the network camera.
        const px = (((s.x * W - camera.x * 0.1 * s.d * camera.k) % W) + W) % W;
        const py = (((s.y * H - camera.y * 0.1 * s.d * camera.k) % H) + H) % H;
        const alpha = s.a * (0.82 + 0.18 * Math.sin(t * s.tw + s.ph)) * lightScale;
        ctx.fillStyle = `rgb(${tints[s.tint]} / ${alpha})`;
        ctx.beginPath();
        ctx.arc(px, py, s.r, 0, Math.PI * 2);
        ctx.fill();
        if (s.r > 1 && dark) {
          ctx.fillStyle = `rgb(${tints[s.tint]} / ${alpha * 0.12})`;
          ctx.beginPath();
          ctx.arc(px, py, s.r * 4, 0, Math.PI * 2);
          ctx.fill();
        }
      }

      if (!shooting && now > nextShot) {
        const fromLeft = Math.random() < 0.5;
        shooting = {
          x: fromLeft ? Math.random() * W * 0.4 : W * (0.6 + Math.random() * 0.4),
          y: Math.random() * H * 0.35,
          vx: (fromLeft ? 1 : -1) * (520 + Math.random() * 260),
          vy: 180 + Math.random() * 120,
          life: 1,
        };
        nextShot = now + 25000 + Math.random() * 30000;
      }
      if (shooting) {
        const s = shooting;
        s.x += s.vx * 0.032;
        s.y += s.vy * 0.032;
        s.life -= 0.032 / 1.1;
        const len = 0.14;
        const g = ctx.createLinearGradient(s.x, s.y, s.x - s.vx * len, s.y - s.vy * len);
        const c = dark ? "230 225 255" : "124 58 237";
        g.addColorStop(0, `rgb(${c} / ${0.5 * s.life * (dark ? 1 : 0.4)})`);
        g.addColorStop(1, `rgb(${c} / 0)`);
        ctx.strokeStyle = g;
        ctx.lineWidth = 1.2;
        ctx.lineCap = "round";
        ctx.beginPath();
        ctx.moveTo(s.x, s.y);
        ctx.lineTo(s.x - s.vx * len, s.y - s.vy * len);
        ctx.stroke();
        if (s.life <= 0) shooting = null;
      }
    };
    raf = requestAnimationFrame(frame);
    return () => {
      cancelAnimationFrame(raf);
      window.removeEventListener("resize", resize);
    };
  }, []);

  return (
    <div className="cosmos" aria-hidden="true">
      {/* Smoky nebula ribbons hugging the corners, like light leaking in from deep space. */}
      {/* Aurora on a parallax layer 170% the size of the screen: it pans and zooms with the
          network at a slower rate, as if it's further away. Positions are % of that layer. */}
      <div ref={wispsRef} className="wisps">
        <Wisp left="12.4%" bottom="11.2%" w="58vw" h="24vw" r={-28} c="rgb(59 130 246 / 0.55), rgb(139 92 246 / 0.5) 45%, rgb(217 70 239 / 0.32)" />
        <Wisp left="15.9%" bottom="24.1%" w="44vw" h="5vw" r={-31} c="rgb(34 211 238 / 0.45), rgb(139 92 246 / 0.4)" thin delay={-18} />
        <Wisp right="11.2%" top="12.4%" w="58vw" h="22vw" r={-30} c="rgb(139 92 246 / 0.5), rgb(59 130 246 / 0.45) 50%, rgb(217 70 239 / 0.3)" delay={-30} />
        <Wisp right="17.1%" top="25.3%" w="40vw" h="4.5vw" r={-34} c="rgb(96 165 250 / 0.4), rgb(192 132 252 / 0.4)" thin delay={-8} />
        <Wisp right="13.5%" bottom="12.4%" w="40vw" h="16vw" r={24} c="rgb(217 70 239 / 0.3), rgb(99 102 241 / 0.28)" delay={-45} />
        <Wisp left="14.7%" top="13.5%" w="34vw" h="14vw" r={22} c="rgb(59 130 246 / 0.24), rgb(139 92 246 / 0.2)" delay={-12} />
        {/* Out of frame at rest — revealed as you pan. */}
        <Wisp left="1%" top="40%" w="40vw" h="14vw" r={18} c="rgb(34 211 238 / 0.32), rgb(59 130 246 / 0.3)" delay={-26} />
        <Wisp right="2%" top="52%" w="38vw" h="12vw" r={-20} c="rgb(217 70 239 / 0.3), rgb(139 92 246 / 0.28)" delay={-38} />
        <Wisp left="38%" top="2%" w="44vw" h="9vw" r={-8} c="rgb(139 92 246 / 0.32), rgb(96 165 250 / 0.28)" thin delay={-4} />
        <Wisp left="36%" bottom="1%" w="46vw" h="12vw" r={10} c="rgb(236 72 153 / 0.26), rgb(139 92 246 / 0.26)" delay={-50} />
      </div>

      <canvas ref={canvasRef} className="absolute inset-0" />
      <div className="vignette" />
    </div>
  );
}
