/* ───────────────────────── Cosmos backdrop ───────────────────────── */

.cosmos {
  position: fixed;
  inset: 0;
  overflow: hidden;
  pointer-events: none;
  background:
    radial-gradient(90% 70% at 50% 46%, #0d1030 0%, #080a1f 38%, #04050f 72%, #020309 100%),
    var(--bg);
}
.light .cosmos {
  background:
    radial-gradient(110% 85% at 50% 46%, #ffffff 0%, #fafaff 50%, #f1efff 100%),
    var(--bg);
}

.wisps {
  position: absolute;
  inset: -35%;
  will-change: transform;
}

/* Smoky nebula ribbons in the corners. Transform-only drift keeps them on the compositor. */
.wisp {
  position: absolute;
  border-radius: 50%;
  filter: blur(48px);
  opacity: 0.55;
  will-change: transform, opacity;
  /* Two slow, unrelated rhythms: a drift and a breath. Each wisp gets its own timing inline. */
  animation:
    wisp-drift var(--wd, 52s) ease-in-out infinite alternate,
    wisp-breathe var(--wb, 17s) ease-in-out infinite alternate;
}
.wisp.thin {
  filter: blur(16px);
  --wo: 0.4;
}
.light .wisp {
  --wo: 0.2;
}
.light .wisp.thin {
  --wo: 0.14;
}

.vignette {
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 50% 48%, transparent 50%, rgb(1 1 5 / 0.7) 100%);
}
.light .vignette {
  background: radial-gradient(ellipse at 50% 50%, transparent 60%, rgb(124 58 237 / 0.05) 100%);
}

/* ───────────────────────── Network stage ───────────────────────── */

.stage {
  position: absolute;
  inset: 0;
.core-label .s {
  font-family: var(--font-jb), monospace;
  font-size: 10.5px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--muted);
}


@keyframes wisp-drift {
  0% { transform: rotate(var(--r, 0deg)) translate3d(-3%, 1.5%, 0) scaleX(0.96) scaleY(1); }
  35% { transform: rotate(calc(var(--r, 0deg) + 1.5deg)) translate3d(2%, -1%, 0) scaleX(1.04) scaleY(1.12); }
  70% { transform: rotate(calc(var(--r, 0deg) - 1deg)) translate3d(5%, 1%, 0) scaleX(1.02) scaleY(0.92); }
  100% { transform: rotate(calc(var(--r, 0deg) + 2deg)) translate3d(1%, -2%, 0) scaleX(1.06) scaleY(1.05); }
}
@keyframes wisp-breathe {
  0% { opacity: var(--wo, 0.55); }
  100% { opacity: calc(var(--wo, 0.55) * 0.62); }
}
@keyframes pill-forge {
  0%, 100% { box-shadow: 0 0 0 1px rgb(var(--c) / 0.4), 0 0 10px rgb(var(--c) / 0.4); }
  50% { box-shadow: 0 0 0 1px rgb(var(--c)), 0 0 26px rgb(var(--c) / 0.85); }
}
@keyframes spark-flicker {
  0%, 100% { opacity: 1; }
  12% { opacity: 0.15; }
