/**
 * The background aurora: curtains of light with a bright lower edge, rays streaming off it and
 * slow folds along their length, drawn by a small WebGL shader. It renders at low resolution and a
 * low frame rate (it's soft and slow), onto a canvas larger than the screen so the parallax can
 * be a cheap CSS transform every frame.
 */

const VERT = `
attribute vec2 aPos;
void main() { gl_Position = vec4(aPos, 0.0, 1.0); }
`;

const FRAG = /* glsl */ `
precision highp float;
uniform vec2 uRes;      // canvas size in device pixels
uniform float uSpan;    // layer size relative to the screen (1.7 = 170%)
uniform float uAspect;  // screen width / height
uniform float uTime;
uniform float uLight;

float h21(vec2 p) {
  p = fract(p * vec2(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}
float n2(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(mix(h21(i), h21(i + vec2(1.0, 0.0)), f.x), mix(h21(i + vec2(0.0, 1.0)), h21(i + vec2(1.0, 1.0)), f.x), f.y);
}

// The curtain's lower edge, as a height above its baseline at position u along it.
float edgeLine(float u, float seed, float t) {
  return 0.085 * sin(u * 1.9 + t * 0.045 + seed * 6.1)
       + 0.045 * sin(u * 4.3 - t * 0.07 + seed * 2.7)
       + 0.022 * sin(u * 9.7 + t * 0.11 + seed * 9.3)
       + 0.05 * (n2(vec2(u * 2.4 + seed * 13.0, t * 0.035 + seed)) - 0.5);
}

/*
 * One curtain. o = a point on its baseline, ang = baseline direction (rays stream toward the
 * left-hand normal), len = length, hgt = typical ray height, k = brightness.
 */
vec4 curtain(vec2 s, vec2 o, float ang, float len, float hgt, float seed, float k, float t) {
  vec2 dir = vec2(cos(ang), sin(ang));
  vec2 nrm = vec2(-dir.y, dir.x);
  vec2 d = s - o;
  float u = dot(d, dir);
  float v = dot(d, nrm);
  float hl = len * 0.5;
  if (abs(u) > hl || v < -0.25 || v > hgt * 3.0) return vec4(0.0);

  float e = edgeLine(u, seed, t);
  float h = v - e;
  // Fold glints: where the sheet turns edge-on to us its lower edge looks brighter.
  float slope = (edgeLine(u + 0.01, seed, t) - edgeLine(u - 0.01, seed, t)) / 0.02;
  float fold = smoothstep(0.12, 0.55, abs(slope));

  // Rays: fine streaks across the curtain, stretched along the ray direction, drifting sideways.
  float r1 = n2(vec2(u * 34.0 + t * 0.12 + seed * 21.0, h * 1.2 - t * 0.04));
  float r2 = n2(vec2(u * 83.0 - t * 0.2 + seed * 7.0, h * 2.6 + seed));
  float rays = 0.32 + 0.9 * r1 * r1 + 0.45 * r2 * r2 * r2;
  // Some rays reach much further than others.
  float reach = hgt * (0.55 + 0.9 * r1);
  float hn = max(h, 0.0) / reach;
  float fall = exp(-hn * 2.4) * smoothstep(1.6, 0.6, hn);
  float edge = smoothstep(-0.014, 0.008, h);
  float under = exp(min(h, 0.0) / 0.018);
  // Patches of activity drifting along the curtain, and its two fading ends.
  float act = 0.3 + 0.7 * smoothstep(0.22, 0.78, n2(vec2(u * 1.25 - t * 0.022 + seed * 5.0, seed * 3.0 + t * 0.01)));
  float ends = smoothstep(-hl, -hl * 0.45, u) * (1.0 - smoothstep(hl * 0.45, hl, u));
  float I = k * ends * act * mix(under * 0.6, fall * rays, edge) * (1.0 + fold * 0.9 * exp(-max(h, 0.0) / 0.03));

  // Teal at the lower edge, violet through the rays, magenta at their tips.
  float c = max(h, 0.0) / hgt;
  vec3 col = mix(vec3(0.22, 0.98, 0.86), vec3(0.32, 0.62, 1.0), smoothstep(0.0, 0.22, c));
  col = mix(col, vec3(0.56, 0.34, 1.0), smoothstep(0.18, 0.6, c));
  col = mix(col, vec3(0.93, 0.32, 0.86), smoothstep(0.55, 1.25, c));
  return vec4(col * I, I);
}

void main() {
  // s: screen-height units, origin at the screen centre, y up. The layer extends past the screen.
  vec2 q = gl_FragCoord.xy / uRes;
  vec2 s = (q - 0.5) * uSpan;
  s.x *= uAspect;
  float t = uTime;

  vec4 a = vec4(0.0);
  // Lower left: rays stream down and away from the network.
  a += curtain(s, vec2(-0.5, -0.36), 3.55, 1.9, 0.26, 0.13, 0.95, t);
  a += curtain(s, vec2(-0.42, -0.44), 3.62, 1.5, 0.2, 0.71, 0.55, t);
  // Upper right: rays stream up and out.
  a += curtain(s, vec2(0.52, 0.36), 0.42, 1.9, 0.28, 0.37, 0.9, t);
  a += curtain(s, vec2(0.62, 0.45), 0.36, 1.4, 0.18, 0.93, 0.5, t);
  // Fainter arcs in the other corners, and some beyond the screen edges to find when panning.
  a += curtain(s, vec2(-0.62, 0.42), 2.72, 1.3, 0.2, 0.52, 0.42, t);
  a += curtain(s, vec2(0.66, -0.43), -0.42, 1.2, 0.18, 0.24, 0.4, t);
  a += curtain(s, vec2(-1.25, 0.05), 1.75, 1.2, 0.24, 0.81, 0.55, t);
  a += curtain(s, vec2(1.28, -0.05), -1.4, 1.2, 0.22, 0.66, 0.5, t);

  // Gentle breathing so the whole sky is never static, and a soft cap so overlaps don't blow out.
  a *= 0.88 + 0.12 * sin(t * 0.13);
  float I = a.a;
  float capped = 1.0 - exp(-I * 1.15);
  vec3 col = a.rgb / max(I, 1e-4);

  float alpha;
  if (uLight > 0.5) {
    // On white the aurora is a pale ink wash: deeper hues, low alpha.
    col = mix(col, vec3(0.42, 0.24, 0.92), 0.35) * 0.85;
    alpha = capped * 0.2;
  } else {
    alpha = capped * 0.5;
  }
