precision highp float;
uniform vec2 uRes;      // canvas size in device pixels
uniform float uSpan;    // layer size relative to the screen (1.7 = 170%)
uniform float uAspect;  // screen width / height
uniform float uTime;
uniform float uLight;

float h21(vec2 p) {
  p = fract(p * vec2(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}
float n2(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(mix(h21(i), h21(i + vec2(1.0, 0.0)), f.x), mix(h21(i + vec2(0.0, 1.0)), h21(i + vec2(1.0, 1.0)), f.x), f.y);
}

// The curtain's lower edge, as a height above its baseline at position u along it.
float edgeLine(float u, float seed, float t) {
  return 0.085 * sin(u * 1.9 + t * 0.045 + seed * 6.1)
       + 0.045 * sin(u * 4.3 - t * 0.07 + seed * 2.7)
       + 0.022 * sin(u * 9.7 + t * 0.11 + seed * 9.3)
       + 0.05 * (n2(vec2(u * 2.4 + seed * 13.0, t * 0.035 + seed)) - 0.5);
}

/*
 * One curtain. o = a point on its baseline, ang = baseline direction (rays stream toward the
 * left-hand normal), len = length, hgt = typical ray height, k = brightness.
 */
vec4 curtain(vec2 s, vec2 o, float ang, float len, float hgt, float seed, float k, float t) {
  vec2 dir = vec2(cos(ang), sin(ang));
  vec2 nrm = vec2(-dir.y, dir.x);
  vec2 d = s - o;
  float u = dot(d, dir);
  float v = dot(d, nrm);
  float hl = len * 0.5;
  if (abs(u) > hl || v < -0.25 || v > hgt * 3.0) return vec4(0.0);

  float e = edgeLine(u, seed, t);
  float h = v - e;
  // Fold glints: where the sheet turns edge-on to us its lower edge looks brighter.
  float slope = (edgeLine(u + 0.01, seed, t) - edgeLine(u - 0.01, seed, t)) / 0.02;
  float fold = smoothstep(0.12, 0.55, abs(slope));

  // Rays: fine streaks across the curtain, stretched along the ray direction, drifting sideways.
  float r1 = n2(vec2(u * 34.0 + t * 0.12 + seed * 21.0, h * 1.2 - t * 0.04));
  float r2 = n2(vec2(u * 83.0 - t * 0.2 + seed * 7.0, h * 2.6 + seed));
  float rays = 0.32 + 0.9 * r1 * r1 + 0.45 * r2 * r2 * r2;
