  a += curtain(s, vec2(0.52, 0.36), 0.42, 1.9, 0.28, 0.37, 0.9, t);
  a += curtain(s, vec2(0.62, 0.45), 0.36, 1.4, 0.18, 0.93, 0.5, t);
