  a += curtain(s, vec2(-0.62, 0.42), 2.72, 1.3, 0.2, 0.52, 0.42, t);
  a += curtain(s, vec2(0.66, -0.43), -0.42, 1.2, 0.18, 0.24, 0.4, t);
