  // Some rays reach much further than others.
  float reach = hgt * (0.55 + 0.9 * r1);
  float hn = max(h, 0.0) / reach;
  float fall = exp(-hn * 2.4) * smoothstep(1.6, 0.6, hn);
  float edge = smoothstep(-0.014, 0.008, h);
  float under = exp(min(h, 0.0) / 0.018);
