// Loads a URL in headless Chrome and prints console warnings/errors plus main-thread long tasks.
// usage: node probe.mjs <url> [waitMs] [width,height]
import { spawn } from "node:child_process";
import { mkdirSync, rmSync } from "node:fs";

const [url, waitMs = "8000", size = "1600,1000"] = process.argv.slice(2);
const [W, H] = size.split(",").map(Number);
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const port = 9500 + Math.floor(Math.random() * 200);
const profile = `C:/Users/edmem/AppData/Local/Temp/cyrus-shots/prof-probe-${port}`;
mkdirSync(profile, { recursive: true });
const chrome = spawn("C:/Program Files/Google/Chrome/Application/chrome.exe", [
  "--headless=new",
  `--remote-debugging-port=${port}`,
  "--hide-scrollbars",
  `--window-size=${W},${H}`,
  `--user-data-dir=${profile}`,
  "about:blank",
]);
let targets;
for (let i = 0; i < 60; i++) {
  await sleep(250);
  try {
    targets = await (await fetch(`http://127.0.0.1:${port}/json`)).json();
    if (targets.some((t) => t.type === "page")) break;
  } catch {}
}
const ws = new WebSocket(targets.find((t) => t.type === "page").webSocketDebuggerUrl);
await new Promise((r) => (ws.onopen = r));
let id = 0;
const pending = new Map();
const t0 = Date.now();
ws.onmessage = (m) => {
  const msg = JSON.parse(m.data);
  if (msg.method === "Runtime.consoleAPICalled" && msg.params.type !== "log" && msg.params.type !== "info" && msg.params.type !== "debug")
    console.log(`+${Date.now() - t0}ms`, msg.params.type, msg.params.args.map((a) => a.value ?? a.description).join(" ").slice(0, 300));
  if (msg.method === "Runtime.exceptionThrown") console.log("EXC", msg.params.exceptionDetails.exception?.description?.slice(0, 300));
  if (msg.id && pending.has(msg.id)) {
    pending.get(msg.id)(msg);
    pending.delete(msg.id);
  }
};
const send = (method, params = {}) =>
  new Promise((r) => {
    const i = ++id;
    pending.set(i, r);
    ws.send(JSON.stringify({ id: i, method, params }));
  });
await send("Runtime.enable");
await send("Emulation.setDeviceMetricsOverride", { width: W, height: H, deviceScaleFactor: 1, mobile: false });
await send("Page.addScriptToEvaluateOnNewDocument", {
  source: `window.__longs=[];new PerformanceObserver(l=>l.getEntries().forEach(e=>window.__longs.push([Math.round(e.startTime),Math.round(e.duration)]))).observe({type:'longtask',buffered:true});`,
});
