"use client";

import { useEffect, useRef } from "react";
import { createCoreGL } from "@/components/cosmos/coreGL";
import type { CoreConcept } from "@/components/cosmos/cores";
import { addView, removeView, renderQuality, setFocus, type CoreView } from "./coreLoop";

/**
 * A live core, centred in its parent. `fit` is the sphere's radius as a fraction of the smaller
 * side of the box; the canvas itself is larger (radius × extent) so outside effects have room,
 * and it overflows the box rather than squeezing them.
 *
 * The renderer is only created once the box scrolls near the viewport: shader compiles are the
 * expensive part, and WebGL contexts are a limited resource. It fades in once its shader is ready.
 */
export function CoreCanvas({
  concept,
  fit,
  maxDpr = 1.5,
  focus = false,
  className = "",
}: {
  concept: CoreConcept;
  fit: number;
  maxDpr?: number;
  /** Render only this core while it's mounted (pauses the rest). */
  focus?: boolean;
  className?: string;
}) {
  const hostRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const host = hostRef.current;
    if (!host) return;
    let box = 0;
    let canvas: HTMLCanvasElement | null = null;
    const view: CoreView = {
      gl: null,
      visible: false,
      shown: false,
      refit() {
        if (!box || !view.gl) return;
        const size = Math.round(2 * box * fit * concept.extent);
        const dpr = Math.max(0.75, Math.min((window.devicePixelRatio || 1) * renderQuality(), maxDpr, 1800 / Math.max(size, 1)));
        view.gl.resize(size, dpr);
      },
      reveal() {
        canvas?.classList.add("is-ready");
      },
    };

    const create = () => {
      // A fresh canvas per renderer: a released WebGL context can't be revived.
      const c = document.createElement("canvas");
      c.setAttribute("aria-hidden", "true");
      c.addEventListener("webglcontextlost", (e) => {
        e.preventDefault();
        view.gl = null;
      });
      c.addEventListener("webglcontextrestored", () => {
        view.gl = createCoreGL(c, concept);
        view.refit();
      });
      host.appendChild(c);
      canvas = c;
      view.gl = createCoreGL(c, concept);
      view.refit();
      addView(view);
      if (focus) setFocus(view);
    };

    const ro = new ResizeObserver(() => {
      const next = Math.min(host.clientWidth, host.clientHeight);
      if (Math.abs(next - box) < 0.5) return;
      box = next;
      view.refit();
    });
    ro.observe(host);
    // Observer callbacks arrive asynchronously, so a mount that's torn down straight away (React's
    // dev double-mount) never creates a context at all.
    const io = new IntersectionObserver(
      ([en]) => {
        view.visible = en.isIntersecting;
        if (en.isIntersecting && !canvas) create();
      },
      { rootMargin: "200px" },
    );
    io.observe(host);

    return () => {
      removeView(view);
      ro.disconnect();
      io.disconnect();
      view.gl?.dispose();
      canvas?.remove();
    };
  }, [concept, fit, maxDpr, focus]);

  return <div ref={hostRef} className={`core-host ${className}`} />;
}

