    canvas.addEventListener("webglcontextlost", (e) => {
      e.preventDefault();
      view.gl = null;
    });
    canvas.addEventListener("webglcontextrestored", () => {
      view.gl = createCoreGL(canvas, concept);
      view.refit();
    });

    const ro = new ResizeObserver(() => {
      const next = Math.min(host.clientWidth, host.clientHeight);
      if (Math.abs(next - box) < 0.5) return;
      box = next;
      view.refit();
    });
    ro.observe(host);
    const io = new IntersectionObserver(([en]) => (view.visible = en.isIntersecting), { rootMargin: "120px" });
    io.observe(host);
    addView(view);
    if (focus) setFocus(view);

    return () => {
      removeView(view);
      ro.disconnect();
      io.disconnect();
      view.gl?.dispose();
      canvas.remove();
    };
  }, [concept, fit, maxDpr, focus]);

  return <div ref={hostRef} className={`core-host ${className}`} />;
}

