1	import type { CoreConcept } from "../types";
2	
3	/**
4	 * Particle Nebula — three nested shells of glowing dots on spherical Fibonacci lattices (looked up
5	 * per pixel, front and back hemispheres), wrapped by flowing dotted ribbons, around a crisp Y.
6	 * Keystrokes push a radial wave front through the dot field: dots are thrown outward past the
7	 * sphere's edge and spring back into formation.
8	 */
9	export const particles: CoreConcept = {
10	  id: "particles",
11	  name: "Particle Nebula",
12	  kind: "2.5D",
13	  tagline: "Thousands of points, one pulse",
14	  description:
15	    "Nested shells of fine glowing points, split cyan to magenta, with flowing dotted ribbons wrapping the sphere around a crisp Y. Keystrokes blast shockwaves through the field: dots streak out past the edge, then spring back into formation.",
16	  typing: "Each keystroke bursts the dot shells outward in a streaking wave that snaps back.",
17	  extent: 1.75,
18	  frag: /* glsl */ `
19	const float PN_PHI = 1.61803398875;
20	
21	float pnMadfrac(float a, float b) { float x = a * b; return x - floor(x); }
22	
23	// Nearest point of an n-point spherical Fibonacci lattice (Keinert et al. 2015) to unit vector p.
24	// Lattice point i sits at cos(theta) = 1 - (2i + 1) / n, phi = 2pi * frac(i * (PHI - 1)).
25	// Returns the point's index; its centre goes to qBest.
26	float pnNearest(vec3 p, float n, out vec3 qBest) {
27	  float m = 1.0 - 1.0 / n;
28	  float phi = min(atan(p.y, abs(p.x) + abs(p.y) < 1e-7 ? 1e-7 : p.x), PI);
29	  float cosT = p.z;
30	  float k = max(2.0, floor(log(n * PI * 2.2360679 * max(1.0 - cosT * cosT, 1e-6)) / log(PN_PHI * PN_PHI)));
31	  float Fk = pow(PN_PHI, k) / 2.2360679;
32	  float F0 = floor(Fk + 0.5);
33	  float F1 = floor(Fk * PN_PHI + 0.5);
34	  // Basis of the local lattice in (phi, cos theta): column j = step along F_j.
35	  float A0 = TAU * pnMadfrac(F0 + 1.0, PN_PHI - 1.0) - TAU * (PN_PHI - 1.0);
36	  float A1 = TAU * pnMadfrac(F1 + 1.0, PN_PHI - 1.0) - TAU * (PN_PHI - 1.0);
37	  float C0 = -2.0 * F0 / n;
38	  float C1 = -2.0 * F1 / n;
39	  float det = A0 * C1 - A1 * C0;
40	  det = abs(det) < 1e-12 ? 1e-12 : det;
41	  float X = phi;
42	  float Y = cosT - m;
43	  vec2 c = floor(vec2(C1 * X - A1 * Y, -C0 * X + A0 * Y) / det);
44	  float dBest = 8.0;
45	  float jBest = 0.0;
46	  qBest = vec3(0.0, 0.0, 1.0);
47	  for (int s = 0; s < 4; s++) {
48	    vec2 o = vec2(s == 1 || s == 3 ? 1.0 : 0.0, s >= 2 ? 1.0 : 0.0);
49	    float ct = dot(vec2(C0, C1), o + c) + m;
50	    ct = clamp(ct, -1.0, 1.0) * 2.0 - ct;
51	    float i = clamp(floor(n * 0.5 - ct * n * 0.5), 0.0, n - 1.0);
52	    float ph = TAU * pnMadfrac(i, PN_PHI - 1.0);
53	    ct = 1.0 - (2.0 * i + 1.0) / n;
54	    float st = sqrt(max(0.0, 1.0 - ct * ct));
55	    vec3 q = vec3(cos(ph) * st, sin(ph) * st, ct);
56	    vec3 dq = q - p;
57	    float d2 = dot(dq, dq);
58	    if (d2 < dBest) { dBest = d2; jBest = i; qBest = q; }
59	  }
60	  return jBest;
61	}
62	
63	// Keystroke impact point on the visible hemisphere.
64	vec3 pnImpact(float s) {
65	  float a = fract(s * 5.17 + 0.31) * TAU;
66	  float b = fract(s * 11.39 + 0.77);
67	  float rho = 0.35 + 0.6 * b;
68	  return vec3(cos(a) * rho, sin(a) * rho, sqrt(max(1.0 - rho * rho, 0.0)));
69	}
70	float pnFade(float age) { return 1.0 - smoothstep(0.75, 1.1, age); }
71	
72	// Radial burst of the dot field in view direction n: a front races out from each impact, throws
73	// the dots outward and lets them spring back with a damped wobble.
74	float pnBurst(vec3 n) {
75	  float d = 0.0;
76	  for (int k = 0; k < 4; k++) {
77	    float S = k == 0 ? uWaveS.x : k == 1 ? uWaveS.y : k == 2 ? uWaveS.z : uWaveS.w;
78	    if (S <= 0.0) continue;
79	    float age = k == 0 ? uWaveAge.x : k == 1 ? uWaveAge.y : k == 2 ? uWaveAge.z : uWaveAge.w;
80	    float seed = k == 0 ? uWaveSeed.x : k == 1 ? uWaveSeed.y : k == 2 ? uWaveSeed.z : uWaveSeed.w;
81	    float g = acos(clamp(dot(n, pnImpact(seed)), -1.0, 1.0));
82	    float x = 0.08 + age * 2.4 - g;
83	    float xp = max(x, 0.0);
84	    float push = smoothstep(-0.42, 0.02, x) * exp(-xp * 2.4) * cos(xp * 5.5);
85	    d += push * S * pnFade(age) / (0.75 + age * 0.7);
86	  }
87	  return d;
88	}
89	
90	// Shared dot colour: cyan/blue on one side, magenta/pink with a warm red edge on the other.
91	vec3 pnColor(vec3 nv, float hj, bool light) {
92	  float side = clamp(nv.x * 1.25 + (hj - 0.5) * 0.5, -1.0, 1.0);
93	  vec3 cold = mix(vec3(0.15, 0.45, 1.0), vec3(0.1, 0.85, 1.0), smoothstep(0.0, 1.0, nv.y * 0.5 + 0.5 - side * 0.3));
94	  vec3 warm = mix(vec3(0.95, 0.22, 0.85), vec3(1.0, 0.25, 0.45), smoothstep(0.2, 1.0, side));
95	  warm = mix(warm, vec3(1.0, 0.3, 0.24), smoothstep(0.75, 1.0, side) * 0.6);
96	  vec3 c = mix(cold, warm, smoothstep(-0.35, 0.35, side));
97	  if (light) c = c * vec3(0.62, 0.58, 0.82);
98	  return c;
99	}
100	
101	// One hemisphere (sgn = +1 front, -1 back) of a dot shell. Returns colour (premultiplied) + alpha.
102	vec4 pnShell(vec2 P, float R, float N, mat3 M, float sgn, float amp, float dotR, float pxW, float sid, bool light, float yMask) {
103	  vec2 Q = P / R;
104	  if (dot(Q, Q) > 2.4) return vec4(0.0);
105	  float d0 = uImpulse * 0.07;
106	  vec3 n = vec3(0.0, 0.0, 1.0);
107	  bool burst = uWaveS.x + uWaveS.y + uWaveS.z + uWaveS.w > 0.0;
108	  for (int it = 0; it < 3; it++) {
109	    vec2 q2 = Q / (1.0 + d0);
110	    float l2 = dot(q2, q2);
111	    if (l2 > 0.9999) { q2 *= 0.99995 * inversesqrt(l2); l2 = 0.9999; }
112	    n = vec3(q2, sgn * sqrt(1.0 - l2));
113	    if (!burst) break;
114	    d0 = mix(d0, amp * pnBurst(n) + uImpulse * 0.07, it == 0 ? 1.0 : 0.7);
115	  }
116	  vec3 ql;
117	  float j = pnNearest(M * n, N, ql);
118	  vec3 nq = ql * M;
119	  if (nq.z * sgn < -0.02) return vec4(0.0);
120	  float hj = fract(sin(j * 12.9898 + sid * 78.233) * 43758.5453);
121	  float dq = (burst ? amp * pnBurst(nq) * (0.88 + 0.24 * hj) : 0.0) + uImpulse * 0.07;
122	  vec2 sp = R * (1.0 + dq) * nq.xy;
123	  float hot = clamp(abs(dq - uImpulse * 0.07) * 2.6, 0.0, 1.0);
124	  // Moving dots streak along their (radial) path.
125	  vec2 rdir = sp / max(length(sp), 1e-4);
126	  vec2 dv = P - sp;
127	  float dr = dot(dv, rdir);
128	  float dd = length(vec2(dr / (1.0 + hot * 1.6), dv.x * rdir.y - dv.y * rdir.x));
129	  float rad = dotR * (sgn > 0.0 ? 1.0 : 0.55) * (0.75 + 0.5 * hj) * (1.0 + hot * 0.5);
130	  float cov = 1.0 - smoothstep(rad - pxW * 0.7, rad + pxW * 0.7, dd);
131	  cov *= min(1.0, rad / pxW);
132	  float glow = exp(-dd * dd / (rad * rad * 7.0)) * 0.25;
133	  // Flowing sheets of lit dots across the shell over a dim field, plus a slow twinkle.
134	  vec3 fq = ql * 1.9 + vec3(sid * 3.7, uTime * 0.06, -uTime * 0.045);
135	  float f = fbm2(fq + 0.6 * sin(fq.yzx * 1.7 + uTime * 0.2));
136	  float ridge = 1.0 - abs(2.0 * f - 1.0);
137	  float sheet = smoothstep(0.78, 0.97, ridge);
138	  float lit = 0.1 + 0.9 * sheet + 0.25 * smoothstep(0.5, 0.78, ridge);
139	  lit *= 0.7 + 0.3 * sin(uTime * 2.3 + hj * TAU);
140	  // Forging: bands of dots pulse in rhythm.
141	  float band = pow(0.5 + 0.5 * sin(nq.y * 7.0 - uTime * 3.2 + sid * 0.6), 6.0);
142	  float beat = uPulse * band;
143	  lit = mix(lit, 1.0, beat * 0.8) * (1.0 + beat * 2.2);
144	  lit *= sgn > 0.0 ? 1.0 : 0.33;
145	  lit *= 1.0 + hot * 2.2;
146	  vec3 c = pnColor(nq, hj, light);
147	  c = mix(c, light ? vec3(0.85, 0.1, 0.35) : vec3(1.0, 0.75, 0.9), hot * 0.45);
148	  c = mix(c, light ? c * 0.8 : mix(c, vec3(1.0), 0.5), beat * 0.6);
149	  float a = (cov + (light ? glow * 0.2 : glow)) * lit * yMask;
150	  return vec4(c * a, a);
151	}
152	
153	// A dotted ribbon wrapping the sphere on a tilted shell of radius Rr. Returns colour + alpha.
154	vec4 pnRibbon(vec2 P, float Rr, mat3 M, float sgn, float flow, float nU, float seed, vec3 rc, float pxW, bool light, float yMask) {
155	  float l2 = dot(P, P) / (Rr * Rr);
156	  if (l2 >= 1.0) return vec4(0.0);
157	  vec3 p = vec3(P / Rr, sgn * sqrt(1.0 - l2));
158	  vec3 lp = M * p;
159	  float az = atan(lp.z, abs(lp.x) + abs(lp.z) < 1e-7 ? 1e-7 : lp.x);
160	  float uu = az / TAU * nU - flow;
161	  float jI = floor(uu + 0.5);
162	  float azJ = (jI + flow) / nU * TAU;
163	  float cl = 0.24 * sin(2.0 * azJ + seed) + 0.1 * sin(3.0 * azJ - uTime * 0.4 + seed * 2.0);
164	  float w = 0.11 + 0.05 * sin(azJ * 3.0 + uTime * 0.3 + seed);
165	  float lat = asin(clamp(lp.y, -1.0, 1.0));
166	  float v = (lat - cl) / w * 3.0;
167	  float kI = clamp(floor(v + 0.5), -3.0, 3.0);
168	  float latK = cl + kI * w / 3.0;
169	  vec3 dl = vec3(cos(latK) * cos(azJ), sin(latK), cos(latK) * sin(azJ));
170	  vec3 dv = dl * M;
171	  if (dv.z * sgn < -0.02) return vec4(0.0);
172	  vec2 sp = Rr * (1.0 + uImpulse * 0.05) * dv.xy;
173	  float dd = length(P - sp);
174	  float rad = (sgn > 0.0 ? 0.0135 : 0.0085) * (1.0 - abs(kI) * 0.08);
175	  float cov = 1.0 - smoothstep(rad - pxW * 0.7, rad + pxW * 0.7, dd);
176	  cov *= min(1.0, rad / pxW);
177	  float glow = exp(-dd * dd / (rad * rad * 9.0)) * 0.2;
178	  float head = pow(0.5 + 0.5 * sin(azJ - flow * 0.35 + seed), 2.0);
179	  float lit = (0.3 + 0.9 * head) * (1.0 - abs(kI) * 0.09) * (sgn > 0.0 ? 1.15 : 0.4);
180	  lit *= 1.0 + uPulse * 0.8 + uEnergy * 0.4;
181	  vec3 c = light ? rc * vec3(0.62, 0.58, 0.82) : rc;
182	  float a = (cov + (light ? glow * 0.3 : glow)) * lit * yMask;
183	  return vec4(c * a, a);
184	}
185	
186	void pnAdd(inout vec3 col, inout float alpha, vec4 s, bool light) {
187	  if (light) { col = s.rgb + col * (1.0 - s.a); alpha = s.a + alpha * (1.0 - s.a); }
188	  else { col += s.rgb; alpha += s.a; }
189	}
190	
191	vec4 core(vec2 uv) {
192	  vec2 P = uv / uRadius;
193	  float rP = length(P);
194	  float pxW = uPx / uRadius;
195	  bool light = uLight > 0.5;
196	  float e = uEnergy;
197	  vec3 col = vec3(0.0);
198	  float alpha = 0.0;
199	
200	  // Nebula haze behind the dots.
201	  float hz = exp(-rP * rP * 1.6) * 0.22 + exp(-pow(max(rP - 0.92, 0.0) * 6.0, 2.0)) * smoothstep(0.5, 1.0, rP) * 0.1;
202	  vec3 hzc = mix(vec3(0.15, 0.3, 1.0), vec3(0.85, 0.2, 0.75), smoothstep(-0.8, 0.8, P.x));
203	  float hza = hz * (light ? 0.25 : 1.0) * (1.0 + uPulse * 0.5 + e * 0.4);
204	  pnAdd(col, alpha, vec4(hzc * hza * (light ? 0.7 : 0.6), hza * 0.6), light);
205	
206	  vec4 yf = yFlat(P, 0.9, pxW);
207	  // Distance to the Y (valid out to ~0.045): clear the dots around it so it reads crisply.
208	  float ysd = 1.0;
209	  if (uReady > 0.5) { vec2 yd2 = ySdf2(P / 0.9); ysd = min(yd2.x, yd2.y) * 0.9; }
210	  float yMask = smoothstep(0.006, 0.04, ysd);
211	  float yHalo = (1.0 - smoothstep(0.0, 0.042, ysd)) * step(0.0, ysd);
212	
213	  mat3 M0 = rotY(uSwirl * 0.55) * rotX(0.5);
214	  mat3 M1 = rotY(-uSwirl * 0.8) * rotZ(0.9) * rotX(-0.3);
215	  mat3 M2 = rotY(uSwirl * 1.1 + 1.0) * rotX(1.2);
216	  mat3 RA = rotX(-0.35) * rotZ(0.32);
217	  mat3 RB = rotX(0.5) * rotZ(-0.55);
218	  float flowA = uSwirl * 9.0;
219	  float flowB = -uSwirl * 7.0 + 40.0;
220	  vec3 cA = vec3(0.2, 0.75, 1.0);
221	  vec3 cB = vec3(1.0, 0.3, 0.7);
222	  float pxD = pxW;
223	
224	  // Back to front.
225	  pnAdd(col, alpha, pnRibbon(P, 1.12, RA, -1.0, flowA, 260.0, 0.0, cA, pxD, light, 1.0), light);
226	  pnAdd(col, alpha, pnRibbon(P, 1.04, RB, -1.0, flowB, 240.0, 2.0, cB, pxD, light, 1.0), light);
227	  pnAdd(col, alpha, pnShell(P, 1.0, 3200.0, M0, -1.0, 0.6, 0.0105, pxD, 0.0, light, yMask), light);
228	  pnAdd(col, alpha, pnShell(P, 0.8, 2000.0, M1, -1.0, 0.46, 0.0095, pxD, 1.0, light, yMask), light);
229	  pnAdd(col, alpha, pnShell(P, 0.6, 1100.0, M2, -1.0, 0.34, 0.009, pxD, 2.0, light, yMask), light);
230	
231	  // The Y with a halo.
232	  vec3 ybase = yf.rgb;
233	  float yg = yHalo * (1.0 - yf.a);
234	  vec3 yGlowC = mix(vec3(0.35, 0.6, 1.0), vec3(0.9, 0.35, 1.0), smoothstep(-0.4, 0.4, P.x));
235	  pnAdd(col, alpha, vec4(yGlowC * yg * yg * (light ? 0.2 : 0.4), yg * yg * (light ? 0.15 : 0.35)) * (1.0 + uPulse * 0.5 + uKick * 0.6), light);
236	  vec3 yc = yf.rgb * (1.1 + uPulse * 0.35 + uKick * 0.3);
237	  if (light && uReady > 0.5) {
238	    // On white: deeper ink edges instead of a whitened rim, and a soft ink shadow below.
239	    vec2 yd = ySdf2(P / 0.9);
240	    float arm = yd.y < yd.x ? 1.0 : 0.0;
241	    vec3 base = yColor(P / 0.9, arm);
242	    yc = mix(base * 0.68, base * 0.98, smoothstep(0.0, 0.028, -ysd));
243	    vec2 ys = ySdf2((P + vec2(0.012, 0.028)) / 0.9);
244	    float sh = (1.0 - smoothstep(-0.01, 0.04, min(ys.x, ys.y) * 0.9)) * 0.16 * (1.0 - yf.a);
245	    pnAdd(col, alpha, vec4(vec3(0.16, 0.08, 0.36) * sh, sh), light);
246	  }
247	  col = mix(col, yc * yf.a, yf.a);
248	  alpha = mix(alpha, 1.0, yf.a);
249	
250	  pnAdd(col, alpha, pnShell(P, 0.6, 1100.0, M2, 1.0, 0.34, 0.009, pxD, 2.0, light, yMask), light);
251	  pnAdd(col, alpha, pnShell(P, 0.8, 2000.0, M1, 1.0, 0.46, 0.0095, pxD, 1.0, light, yMask), light);
252	  pnAdd(col, alpha, pnShell(P, 1.0, 3200.0, M0, 1.0, 0.6, 0.0105, pxD, 0.0, light, yMask), light);
253	  pnAdd(col, alpha, pnRibbon(P, 1.04, RB, 1.0, flowB, 240.0, 2.0, cB, pxD, light, mix(1.0, yMask, 0.7)), light);
254	  pnAdd(col, alpha, pnRibbon(P, 1.12, RA, 1.0, flowA, 260.0, 0.0, cA, pxD, light, mix(1.0, yMask, 0.7)), light);
255	
256	  // Fade everything well before the canvas edge.
257	  float edge = 1.0 - smoothstep(1.45, 1.72, rP);
258	  alpha = clamp(alpha, 0.0, 1.0) * edge;
259	  col = tonemap(col) * edge;
260	  float dith = (hash2(gl_FragCoord.xy) - 0.5) / 255.0;
261	  col = clamp(col + dith * alpha, 0.0, 1.0);
262	  return vec4(min(col, vec3(alpha)), alpha);
263	}
264	`,
265	};
