import type { CoreConcept } from "../types";

/**
 * Particle Nebula — three nested shells of glowing dots on spherical Fibonacci lattices (looked up
 * per pixel, front and back hemispheres), wrapped by flowing dotted ribbons, around a crisp Y.
 * Keystrokes push a radial wave front through the dot field: dots are thrown outward past the
 * sphere's edge and spring back into formation.
 */
export const particles: CoreConcept = {
  id: "particles",
  name: "Particle Nebula",
  kind: "2.5D",
  tagline: "Thousands of points, one pulse",
  description:
    "Nested shells of fine glowing points, split cyan to magenta, with flowing dotted ribbons wrapping the sphere around a crisp Y. Keystrokes blast shockwaves through the field: dots streak out past the edge, then spring back into formation.",
  typing: "Each keystroke bursts the dot shells outward in a streaking wave that snaps back.",
  extent: 1.75,
  frag: /* glsl */ `
const float PN_PHI = 1.61803398875;

float pnMadfrac(float a, float b) { float x = a * b; return x - floor(x); }

// Nearest point of an n-point spherical Fibonacci lattice (Keinert et al. 2015) to unit vector p.
// Lattice point i sits at cos(theta) = 1 - (2i + 1) / n, phi = 2pi * frac(i * (PHI - 1)).
// Returns the point's index; its centre goes to qBest.
float pnNearest(vec3 p, float n, out vec3 qBest) {
  float m = 1.0 - 1.0 / n;
  float phi = min(atan(p.y, abs(p.x) + abs(p.y) < 1e-7 ? 1e-7 : p.x), PI);
  float cosT = p.z;
  float k = max(2.0, floor(log(n * PI * 2.2360679 * max(1.0 - cosT * cosT, 1e-6)) / log(PN_PHI * PN_PHI)));
  float Fk = pow(PN_PHI, k) / 2.2360679;
  float F0 = floor(Fk + 0.5);
  float F1 = floor(Fk * PN_PHI + 0.5);
  // Basis of the local lattice in (phi, cos theta): column j = step along F_j.
  float A0 = TAU * pnMadfrac(F0 + 1.0, PN_PHI - 1.0) - TAU * (PN_PHI - 1.0);
  float A1 = TAU * pnMadfrac(F1 + 1.0, PN_PHI - 1.0) - TAU * (PN_PHI - 1.0);
  float C0 = -2.0 * F0 / n;
  float C1 = -2.0 * F1 / n;
  float det = A0 * C1 - A1 * C0;
  det = abs(det) < 1e-12 ? 1e-12 : det;
  float X = phi;
  float Y = cosT - m;
  vec2 c = floor(vec2(C1 * X - A1 * Y, -C0 * X + A0 * Y) / det);
  float dBest = 8.0;
  float jBest = 0.0;
  qBest = vec3(0.0, 0.0, 1.0);
  for (int s = 0; s < 4; s++) {
    vec2 o = vec2(s == 1 || s == 3 ? 1.0 : 0.0, s >= 2 ? 1.0 : 0.0);
    float ct = dot(vec2(C0, C1), o + c) + m;
    ct = clamp(ct, -1.0, 1.0) * 2.0 - ct;
    float i = clamp(floor(n * 0.5 - ct * n * 0.5), 0.0, n - 1.0);
    float ph = TAU * pnMadfrac(i, PN_PHI - 1.0);
    ct = 1.0 - (2.0 * i + 1.0) / n;
