  vec3 base = yColor(hit.xy, arm);
  // Luminous: a white-hot rim, saturated body and a bright core along the stroke's spine.
  float depth = -sd / ys;
  vec3 c = mix(mix(base, vec3(1.0), 0.6), base * 1.25, smoothstep(0.0, 0.012, depth)) * emis;
  c += mix(base, vec3(1.0), 0.5) * smoothstep(0.01, 0.035, depth) * 0.45 * emis;

