"use client";

import { useEffect, useRef, useState } from "react";
import { ModelGlyph } from "@/components/icons/ModelGlyphs";
import { CheckIcon, ChevronDownIcon, CloseIcon, CodeIcon } from "@/components/icons/ui";
import { MODEL_BY_ID } from "@/lib/data";
import { jobRouteLabel } from "@/lib/forge";
import { getGame, isJobLive, useStore, type Job, type ThinkItem } from "@/lib/store";

/** A tiny neural net whose nodes fire in sequence — Cyrus's "thinking" glyph. */
function NeuralGlyph({ active }: { active: boolean }) {
  const nodes = [
    [5, 6],
    [5, 18],
    [17, 3],
    [17, 12],
    [17, 21],
    [30, 8],
    [30, 17],
    [41, 12],
  ];
  const edges = [
    [0, 2], [0, 3], [1, 3], [1, 4], [2, 5], [3, 5], [3, 6], [4, 6], [5, 7], [6, 7],
  ];
  return (
    <svg width="46" height="24" viewBox="0 0 46 24" aria-hidden className="shrink-0">
      <defs>
        <linearGradient id="ng" x1="0" x2="1">
          <stop offset="0%" stopColor="var(--accent)" />
          <stop offset="100%" stopColor="var(--cyan)" />
        </linearGradient>
      </defs>
      {edges.map(([a, b], i) => (
        <line
          key={i}
          x1={nodes[a][0]}
          y1={nodes[a][1]}
          x2={nodes[b][0]}
          y2={nodes[b][1]}
          stroke="url(#ng)"
          strokeWidth="0.9"
          strokeOpacity={active ? 0.75 : 0.35}
          className={active ? "think-edge" : undefined}
          style={{ animationDelay: `${i * 0.08}s` }}
        />
      ))}
      {nodes.map(([x, y], i) => (
        <circle
          key={i}
          cx={x}
          cy={y}
          r={i === 7 ? 2.6 : 2}
          fill={i === 7 ? "var(--cyan)" : "var(--accent)"}
          className={active ? "think-node" : undefined}
          style={{ animationDelay: `${(x / 41) * 0.8}s`, transformOrigin: `${x}px ${y}px`, transformBox: "view-box" }}
        />
      ))}
    </svg>
  );
}

/** Reveals text character-by-character, like it's being thought. */
function TypeText({ text, speed = 14 }: { text: string; speed?: number }) {
  const [n, setN] = useState(0);
  useEffect(() => {
    setN(0);
    const id = window.setInterval(() => {
      setN((v) => {
        if (v >= text.length) {
          window.clearInterval(id);
          return v;
        }
        return v + 2;
      });
    }, speed);
    return () => window.clearInterval(id);
  }, [text, speed]);
  return <>{text.slice(0, n)}</>;
}

function Spinner() {
  return (
    <span className="relative grid h-4 w-4 place-items-center">
      <span className="absolute inset-0 rounded-full border border-accent/25" />
      <span className="absolute inset-0 animate-spin rounded-full border border-transparent border-t-cyan" />
      <span className="h-1 w-1 rounded-full bg-cyan shadow-[0_0_6px_var(--cyan)]" />
    </span>
  );
}

function StepRow({ s, job, last }: { s: ThinkItem; job: Job; last: boolean }) {
  const file = s.id.startsWith("w") ? job.files.find((f) => f.path === s.detail) : undefined;
  const lines = file ? file.content.split("\n").length : 0;
  return (
    <li className="animate-rise flex items-start gap-2.5 py-[5px]">
      <span className="mt-[1px] shrink-0">
        {s.done ? (
          <span className="grid h-4 w-4 place-items-center rounded-full bg-accent/15 text-[10px] text-accent">
            <CheckIcon />
          </span>
        ) : (
          <Spinner />
        )}
      </span>
      <span className="min-w-0 flex-1">
        <span className={`block text-[12.5px] font-medium ${s.done ? "text-ink-2" : last ? "shimmer-text" : "text-ink"}`}>{s.label}</span>
        {s.detail && (
          <span className="block truncate font-mono text-[11px] text-muted">
            {s.done ? s.detail : <TypeText text={s.detail} />}
            {file && !s.done && <span className="ml-2 text-cyan">{lines} lines</span>}
          </span>
        )}
      </span>
      {s.done && s.endedAt && <span className="shrink-0 pt-[2px] font-mono text-[10px] text-faint">{((s.endedAt - s.startedAt) / 1000).toFixed(1)}s</span>}
    </li>
  );
}

export function ThinkingTrace() {
  const job = useStore((s) => s.job);
  const setPanelTab = useStore((s) => s.setPanelTab);
  const [open, setOpen] = useState(true);
  const [now, setNow] = useState(() => Date.now());
  const listRef = useRef<HTMLUListElement>(null);
  const live = isJobLive(job);

  useEffect(() => {
    if (!live) return;
    const id = window.setInterval(() => setNow(Date.now()), 100);
    return () => window.clearInterval(id);
  }, [live]);

  useEffect(() => {
    listRef.current?.scrollTo({ top: listRef.current.scrollHeight, behavior: "smooth" });
  }, [job?.steps.length]);

  if (!job) return null;
  const model = MODEL_BY_ID[job.model];
  const elapsed = (((job.finishedAt ?? now) - job.startedAt) / 1000).toFixed(1);
  const route = jobRouteLabel(job);
  const rgb = getGame(job.gameId)?.rgb ?? model.rgb;

  if (!live) {
    const ok = job.status === "done";
    return (
      <div className="glass animate-rise mb-2.5 flex items-center gap-3 rounded-2xl px-3.5 py-2.5 tint" style={{ ["--c" as string]: rgb }}>
        <span
          className="grid h-7 w-7 shrink-0 place-items-center rounded-lg text-[13px]"
          style={{ background: ok ? `rgb(${rgb} / 0.16)` : "rgb(244 63 94 / 0.14)", color: ok ? "var(--cc)" : "#f43f5e" }}
        >
          {ok ? <CheckIcon /> : <CloseIcon />}
        </span>
        <div className="min-w-0 flex-1 text-[12.5px]">
          <div className="truncate font-medium text-ink">
            {ok ? (
              <>
                Forged <span style={{ color: "var(--cc-ink)" }}>{job.modName}</span> v{job.version}
              </>
            ) : job.status === "cancelled" ? (
              "Forge stopped"
            ) : (
              "Forge failed"
            )}
          </div>
          <div className="truncate text-[11px] text-muted">
            {ok ? `${job.files.length} files · ${route} · ${model.name} · ${elapsed}s` : (job.error ?? "No credits were spent on unfinished work.")}
          </div>
        </div>
        {ok && (
          <button type="button" onClick={() => setPanelTab("code")} className="btn-ghost h-8 px-2.5 text-[12px]">
            <CodeIcon /> View code
          </button>
        )}
        <button type="button" aria-label="Dismiss" onClick={() => useStore.setState({ job: null })} className="btn-ghost h-8 w-8 text-muted">
          <CloseIcon />
        </button>
      </div>
    );
  }

  return (
    <div className="glass animate-rise hairline-top mb-2.5 overflow-hidden rounded-2xl">
      <button type="button" onClick={() => setOpen((o) => !o)} className="flex w-full items-center gap-3 px-3.5 py-2.5 text-left">
        <NeuralGlyph active />
        <div className="min-w-0 flex-1">
          <div className="shimmer-text font-display text-[13px] font-semibold">
            {job.status === "writing" ? "Cyrus is writing code" : job.status === "connecting" ? "Waking the core" : "Cyrus is thinking"}
          </div>
          <div className="truncate text-[11px] text-muted">{route ? `Cyrus Core › ${route}` :"Routing your idea through the network…"}</div>
        </div>
        <span className="tint flex items-center gap-1.5 rounded-lg px-2 py-1 text-[11px] text-ink-2" style={{ ["--c" as string]: model.rgb, background: `rgb(${model.rgb} / 0.1)` }}>
          <span style={{ color: "var(--cc)" }}>
            <ModelGlyph id={model.id} />
          </span>
          {model.name}
        </span>
        <span className="w-11 text-right font-mono text-[11px] tabular-nums text-muted">{elapsed}s</span>
        <ChevronDownIcon className={`text-muted transition ${open ? "" : "-rotate-90"}`} />
      </button>
      <div className="relative h-[2px] overflow-hidden bg-[rgb(var(--glow)/0.08)]">
        <div className="absolute inset-y-0 w-1/3 bg-gradient-to-r from-transparent via-cyan to-transparent" style={{ animation: "progress-sheen 1.3s ease-in-out infinite" }} />
      </div>
      {open && (
        <ul
          ref={listRef}
          className="max-h-[188px] overflow-y-auto px-3.5 py-2"
          style={{ maskImage: "linear-gradient(180deg, transparent 0, #000 14px, #000 100%)" }}
        >
          {job.steps.map((s, i) => (
            <StepRow key={s.id} s={s} job={job} last={i === job.steps.length - 1} />
          ))}
          {job.steps.length === 0 && (
            <li className="flex items-center gap-2.5 py-1.5 text-[12.5px]">
              <Spinner />
              <span className="shimmer-text">Opening a channel to the core…</span>
            </li>
          )}
        </ul>
      )}
    </div>
  );
}

