import { useId } from "react";
import { BRAIN, BRAIN_STROKE, type IconProps } from "./ui";

/** Seconds between neighbouring traces firing: one sweep round all eight is 1.6s (see .brain-* CSS). */
const STAGGER = 0.2;

/**
 * The circuit brain in the brand gradient. While `active` it thinks: signals fire out from the chip
 * along each trace in a clockwise sweep, lighting every node they reach, as the chip's core pulses.
 * With `gradient={false}` it takes the text colour instead, like any other icon.
 */
export function ThinkingBrain({
  active = true,
  gradient = true,
  className = "",
  ...props
}: IconProps & { active?: boolean; gradient?: boolean }) {
  // Gradient ids must be unique per instance; useId's punctuation isn't safe inside url().
  const gid = `brain-g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  const ink = gradient ? `url(#${gid})` : "currentColor";
  const { chip, core } = BRAIN;
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox="0 0 24 24"
      width="1em"
      height="1em"
      fill="none"
      stroke={ink}
      strokeWidth={BRAIN_STROKE}
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden
      focusable="false"
      className={`brain${active ? " is-thinking" : ""} ${className}`}
      {...props}
    >
      {gradient && (
        <defs>
          <linearGradient id={gid} x1="2" y1="0" x2="22" y2="0" gradientUnits="userSpaceOnUse">
            <stop offset="0" className="brain-stop-1" />
            <stop offset="0.38" className="brain-stop-2" />
            <stop offset="0.68" className="brain-stop-3" />
            <stop offset="1" className="brain-stop-4" />
          </linearGradient>
        </defs>
      )}
      <path d={BRAIN.outline} />
      <rect x={chip.x} y={chip.y} width={chip.size} height={chip.size} rx={chip.r} />
      <rect className="brain-core" x={core.x} y={core.y} width={core.size} height={core.size} rx={core.r} fill={ink} fillOpacity={0.2} />
      {BRAIN.traces.map((d, i) => (
        <path key={i} className="brain-trace" d={d} />
      ))}
      {BRAIN.nodes.map(([x, y], i) => (
        <circle key={i} className="brain-node" cx={x} cy={y} r={0.8} style={{ animationDelay: `${i * STAGGER}s` }} />
      ))}
      {active &&
        BRAIN.traces.map((d, i) => (
          <path key={i} className="brain-signal" d={d} pathLength={1} style={{ animationDelay: `${i * STAGGER}s` }} />
        ))}
    </svg>
  );
}

