import { BRAIN, DUO_STROKED, type IconProps } from "./ui";

/** Seconds between neighbouring neurons firing; one full round takes 1.6s (see .brain-* CSS). */
const STAGGER = 0.2;
/** How long a signal takes to cross a synapse (40% of the round). */
const TRAVEL = 0.64;

/**
 * The brain icon, alive: while `active`, the hub breathes and signals race out along each synapse
 * in turn, lighting every neuron as they arrive. Static (identical to BrainIcon) otherwise.
 */
export function ThinkingBrain({ active = true, className = "", ...props }: IconProps & { active?: boolean }) {
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox="0 0 24 24"
      width="1em"
      height="1em"
      fill="none"
      stroke="currentColor"
      strokeWidth={1.7}
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden
      focusable="false"
      className={`brain${active ? " is-thinking" : ""} ${className}`}
      {...props}
    >
      <circle className="brain-hub" cx={BRAIN.hub.x} cy={BRAIN.hub.y} r={BRAIN.hub.r} {...DUO_STROKED} />
      {BRAIN.links.map(([x1, y1, x2, y2], i) => (
        <line key={i} className="brain-link" x1={x1} y1={y1} x2={x2} y2={y2} />
      ))}
      {BRAIN.nodes.map(([x, y], i) => (
        <circle key={i} className="brain-node" cx={x} cy={y} r={1.9} style={{ animationDelay: `${i * STAGGER}s` }} />
      ))}
      {active &&
        BRAIN.links.map(([x1, y1, x2, y2], i) => (
          // The last synapse links two neurons: it fires once the first of them has lit.
          <line
            key={i}
            className="brain-signal"
            x1={x1}
            y1={y1}
            x2={x2}
            y2={y2}
            pathLength={1}
            style={{ animationDelay: `${i < 5 ? i * STAGGER : TRAVEL}s` }}
          />
        ))}
    </svg>
  );
}

