  );
}

/** Seedling with two leaves rising from a soil mound under a small sun. */
export function SproutEmblem(props: P) {
  return (
    <IconBase {...props}>
      <path d="M12 14.4C8.6 14.6 6.2 12.6 6 9.2c3.4-.1 5.8 1.9 6 5.2Z" {...DUO_STROKED} />
      <path d="M12 11.6c.1-3.8 2.7-6.3 6.6-6.4.1 3.9-2.6 6.4-6.6 6.4Z" {...DUO_STROKED} />
      <path d="M12 19V11.6" />
      <path d="M3.5 20.5h5c1-1.6 6-1.6 7 0h5" />
      <circle cx={5.4} cy={4.4} r={1.6} {...SOLID} />
    </IconBase>
  );
}

/** Pixel-stepped tree with a sword planted in the ground beside it. */
export function TreeEmblem(props: P) {
  return (
    <IconBase {...props}>
      <path d="M7 3h5v2h2.5v2.5h2v4h-2v2H4.5v-2h-2v-4h2V5H7Z" {...DUO_STROKED} />
      <rect x={6} y={8.5} width={2} height={2} {...SOLID} />
      <path d="M8.3 13.5v7M10.7 13.5v7M2.5 20.5h19" />
      <g transform="rotate(16 18.4 20.5)">
        <path d="M18.4 20.5v-6M16.4 14.5h4M18.4 14.5v-2.2" />
        <path d="M18.4 11.3h.01" strokeWidth={2.4} />
      </g>
    </IconBase>
  );
}

/** Circuit chip with pins on every side and a glowing core. */
export function ChipEmblem(props: P) {
  return (
    <IconBase {...props}>
      <rect x={6.5} y={6.5} width={11} height={11} rx={2} />
      <rect x={9} y={9} width={6} height={6} rx={1.2} {...DUO} />
      <path d="M9.5 3.5v3M14.5 3.5v3M9.5 17.5v3M14.5 17.5v3M3.5 9.5h3M3.5 14.5h3M17.5 9.5h3M17.5 14.5h3" />
      <path d={sparkPath(12, 12, 2.6)} {...SOLID} />
    </IconBase>
  );
}

export const GAME_EMBLEMS: Record<EmblemKey, (p: P) => JSX.Element> = {
  cube: CubeEmblem,
  dragon: DragonEmblem,
  sprout: SproutEmblem,
  tree: TreeEmblem,
  chip: ChipEmblem,
};

/** Renders the abstract emblem for a game. */
export function GameEmblem({ emblem, ...props }: { emblem: EmblemKey } & P) {
  const Emblem = GAME_EMBLEMS[emblem];
  return <Emblem {...props} />;
}

