144	      const catMods = gameMods.filter((m) => m.category === key).sort((a, b) => b.createdAt - a.createdAt);
145	      const shown = catMods.slice(0, VISIBLE_MODS);
146	      const rows = shown.length + 1;
147	      shown.forEach((m, row) => {
148	        nodes.push({ ...base, id: m.id, type: "mod", parent: cid, gameId: game.id, category: key, modId: m.id, rgb: game.rgb, label: m.name, side, row, rows });
149	        links.push({ id: `${cid}>${m.id}`, from: cid, to: m.id, kind: "mod" });
