173	interface Box {
174	  x0: number;
175	  x1: number;
176	  y0: number;
177	  y1: number;
178	}
179	
180	/** How far `a` must move to stop overlapping `b` (along the cheaper axis), or null if clear. */
181	function separation(a: Box, b: Box, pad = 6): [number, number] | null {
182	  const ox = Math.min(a.x1, b.x1) - Math.max(a.x0, b.x0);
183	  const oy = Math.min(a.y1, b.y1) - Math.max(a.y0, b.y0);
184	  if (ox <= 0 || oy <= 0) return null;
185	  const acx = (a.x0 + a.x1) / 2;
186	  const bcx = (b.x0 + b.x1) / 2;
187	  const acy = (a.y0 + a.y1) / 2;
188	  const bcy = (b.y0 + b.y1) / 2;
189	  if (ox < oy) return [(acx < bcx ? -1 : 1) * (ox + pad), 0];
190	  return [0, (acy < bcy ? -1 : 1) * (oy + pad)];
191	}
192	
193	/**
194	 * Nudges categories apart so their discs, labels and mod lists never overlap each other, a
195	 * game or the core. Runs on the default layout only; dragged positions are the user's call.
196	 */
197	function relax(nodes: LNode[]) {
198	  const games = nodes.filter((n) => n.type === "game");
199	  const cats = nodes.filter((n) => n.type === "category");
200	  const gameById = new Map(games.map((g) => [g.id, g]));
201	  const rows = new Map<string, number>();
202	  const listW = new Map<string, number>();
203	  for (const n of nodes) {
204	    if (n.type !== "mod" && n.type !== "more") continue;
205	    rows.set(n.parent!, n.rows);
206	    listW.set(n.parent!, Math.max(listW.get(n.parent!) ?? 90, Math.min(200, 44 + n.label.length * 6.4)));
207	  }
208	  const pos = new Map(cats.map((c) => [c.id, { x: gameById.get(c.parent!)!.hx + c.hx, y: gameById.get(c.parent!)!.hy + c.hy }]));
209	  const boxOf = (c: LNode): Box => {
210	    const p = pos.get(c.id)!;
211	    const r = rows.get(c.id) ?? 1;
212	    const lw = listW.get(c.id) ?? 120;
213	    const labelW = 36 + c.label.length * 7.6 + 24;
214	    const half = Math.max(30, (r * ROW_H) / 2 + 4);
215	    if (c.side === "right") return { x0: p.x - 28 - labelW, x1: p.x + 78 + lw, y0: p.y - half, y1: p.y + half };
216	    if (c.side === "left") return { x0: p.x - 78 - lw, x1: p.x + 28 + labelW, y0: p.y - half, y1: p.y + half };
217	    const hw = Math.max(lw / 2, labelW / 2, 40);
218	    if (c.side === "up") return { x0: p.x - hw, x1: p.x + hw, y0: p.y - 60 - r * ROW_H, y1: p.y + 52 };
219	    return { x0: p.x - hw, x1: p.x + hw, y0: p.y - 52, y1: p.y + 60 + r * ROW_H };
220	  };
221	  const fixed: Box[] = [
222	    { x0: -132, x1: 132, y0: -132, y1: 150 },
223	    ...games.map((g) => ({ x0: g.hx - 62, x1: g.hx + 62, y0: g.hy - 62, y1: g.hy + 78 })),
224	  ];
225	  for (let it = 0; it < 90; it++) {
226	    let moved = false;
227	    for (let i = 0; i < cats.length; i++) {
228	      const pi = pos.get(cats[i].id)!;
229	      for (const f of fixed) {
230	        const d = separation(boxOf(cats[i]), f);
231	        if (d) {
232	          pi.x += d[0];
233	          pi.y += d[1];
234	          moved = true;
235	        }
236	      }
237	      for (let j = i + 1; j < cats.length; j++) {
238	        const d = separation(boxOf(cats[i]), boxOf(cats[j]));
239	        if (!d) continue;
240	        const pj = pos.get(cats[j].id)!;
241	        pi.x += d[0] / 2;
242	        pi.y += d[1] / 2;
243	        pj.x -= d[0] / 2;
244	        pj.y -= d[1] / 2;
245	        moved = true;
246	      }
247	    }
248	    if (!moved) break;
249	  }
250	  for (const c of cats) {
251	    const g = gameById.get(c.parent!)!;
252	    const p = pos.get(c.id)!;
253	    c.hx = Math.round(p.x - g.hx);
254	    c.hy = Math.round(p.y - g.hy);
255	  }
256	}
257	
258	/** Half-extents of the whole layout at rest, for fitting the overview camera. */
259	export function layoutExtent(nodes: LNode[]) {
260	  const byId = new Map(nodes.map((n) => [n.id, n]));
261	  let halfW = 260;
262	  let halfH = 260;
263	  for (const n of nodes) {
264	    if (n.type !== "category") continue;
265	    const g = byId.get(n.parent!)!;
266	    const x = g.hx + n.hx;
267	    const y = g.hy + n.hy;
268	    const rows = nodes.filter((m) => m.parent === n.id).length;
269	    if (n.side === "left" || n.side === "right") {
270	      halfW = Math.max(halfW, Math.abs(x) + 78 + 185);
271	      halfH = Math.max(halfH, Math.abs(y) + (rows * ROW_H) / 2 + 10);
272	    } else {
273	      halfW = Math.max(halfW, Math.abs(x) + 110);
274	      halfH = Math.max(halfH, Math.abs(y) + 60 + rows * ROW_H);
275	    }
276	  }
277	  return { halfW, halfH };
278	}
279	
280	export type NodeState = "on" | "near" | "off";
281	
282	export function selectedNodeId(sel: Selection): string {
283	  if (sel.level === "mod" && sel.modId) return sel.modId;
284	  if (sel.level === "category" && sel.gameId && sel.category) return categoryNodeId(sel.gameId, sel.category);
285	  if (sel.level === "game" && sel.gameId) return sel.gameId;
286	  return CORE_ID;
287	}
288	
289	/** Dims everything outside the branch you've jumped into. */
290	export function computeStates(nodes: LNode[], sel: Selection): Map<string, NodeState> {
291	  const state = new Map<string, NodeState>();
292	  for (const n of nodes) {
293	    if (sel.level === "core" || n.type === "core") {
294	      state.set(n.id, "on");
295	      continue;
296	    }
297	    const sameGame = n.gameId === sel.gameId;
298	    const sameCat = sameGame && n.category === sel.category;
299	    let s: NodeState = "off";
300	    if (sel.level === "game") s = sameGame ? "on" : "off";
301	    else if (n.type === "game") s = sameGame ? "on" : "off";
302	    else if (n.type === "category") s = sameCat ? "on" : sameGame ? "near" : "off";
303	    else if (sel.level === "category") s = sameCat ? "on" : sameGame ? "near" : "off";
304	    else s = n.id === sel.modId || (sameCat && n.type === "more") ? "on" : sameCat ? "near" : sameGame ? "near" : "off";
305	    state.set(n.id, s);
306	  }
307	  return state;
308	}
