export function GameEmblem({ emblem, ...props }: { emblem: EmblemKey } & P) {
  const Emblem = GAME_EMBLEMS[emblem];
  return <Emblem {...props} />;
}''', '''/**
 * A game's mark: its real logo when it has one, otherwise its drawn emblem. Logos are sized in em,
 * like the icons, so they drop in anywhere an emblem did.
 */
export function GameEmblem({
  emblem,
  logo,
  logoTone,
  className = "",
  ...props
}: { emblem: EmblemKey; logo?: string; logoTone?: "light" } & P) {
  if (logo) {
    // eslint-disable-next-line @next/next/no-img-element -- tiny static marks; next/image adds nothing here
    return <img src={logo} alt="" aria-hidden draggable={false} className={`game-logo ${className}`} data-tone={logoTone} />;
  }
  const Emblem = GAME_EMBLEMS[emblem];
  return <Emblem className={className} {...props} />;
}'''),
])

