// Forges a mod through the running app and prints the files it streams back.
// usage: node forge.mjs "<prompt>" [model] [maxLinesPerFile]
const [prompt, model = "sokka", maxLines = "60"] = process.argv.slice(2);
const res = await fetch("http://localhost:3000/api/generate", {
  method: "POST",
  headers: { "content-type": "application/json" },
  body: JSON.stringify({ prompt, model }),
});
const text = await res.text();
const files = new Map();
let route;
for (const line of text.split("\n")) {
  if (!line.trim()) continue;
  const ev = JSON.parse(line);
  if (ev.type === "route") route = ev;
  if (ev.type === "file") files.set(ev.path, "");
  if (ev.type === "chunk") files.set(ev.path, (files.get(ev.path) ?? "") + ev.text);
  if (ev.type === "error") console.log("ERROR", ev.message);
}
console.log(`route: ${route?.gameId} / ${route?.category} · ${route?.modName}`);
for (const [path, content] of files) {
  const lines = content.split("\n");
  console.log(`\n===== ${path} (${lines.length} lines)`);
  console.log(lines.slice(0, Number(maxLines)).join("\n"));
}

