// TEMPORARY: renders every icon so the handoff can export them as standalone SVGs. Delete after use.
import type { JSX, SVGProps } from "react";
import { CATEGORY_ICONS } from "@/components/icons/CategoryIcons";
import { GAME_EMBLEMS } from "@/components/icons/GameEmblems";
import { MODEL_GLYPHS } from "@/components/icons/ModelGlyphs";
import { ThinkingBrain } from "@/components/icons/ThinkingBrain";
import * as UI from "@/components/icons/ui";
import { markSvg } from "@/components/icons/cyrusMark";

type Icon = (p: SVGProps<SVGSVGElement>) => JSX.Element;

export default function IconExport() {
  const ui = Object.entries(UI).filter(([k, v]) => k.endsWith("Icon") && k !== "IconBase" && typeof v === "function") as [string, Icon][];
  const groups: [string, [string, Icon][]][] = [
    ["ui", ui],
    ["categories", Object.entries(CATEGORY_ICONS) as [string, Icon][]],
    ["game-emblems", Object.entries(GAME_EMBLEMS) as [string, Icon][]],
    ["models", Object.entries(MODEL_GLYPHS) as [string, Icon][]],
  ];
  return (
    <main style={{ padding: 20, display: "flex", flexWrap: "wrap", gap: 12, background: "#05030b", color: "#c4b5fd", fontSize: 32 }}>
      {groups.flatMap(([group, icons]) =>
        icons.map(([name, Icon]) => (
          <div key={`${group}/${name}`} data-export={`${group}/${name}`}>
            <Icon />
          </div>
        )),
      )}
      <div data-export="brand/circuit-brain">
        <ThinkingBrain active={false} />
      </div>
      <div data-export="brand/circuit-brain-mono">
        <ThinkingBrain active={false} gradient={false} />
      </div>
      <div data-export="brand/cyrus-y-mark" dangerouslySetInnerHTML={{ __html: markSvg(940, 520, "cyrus-mark-export") }} />
    </main>
  );
}

