    ["ui", ui],
    ["categories", Object.entries(CATEGORY_ICONS) as [string, Icon][]],
    ["game-emblems", Object.entries(GAME_EMBLEMS) as [string, Icon][]],
    ["models", Object.entries(MODEL_GLYPHS) as [string, Icon][]],
  ];
  return (
    <main style={{ padding: 20, display: "flex", flexWrap: "wrap", gap: 12, background: "#05030b", color: "#c4b5fd", fontSize: 32 }}>
      {groups.flatMap(([group, icons]) =>
        icons.map(([name, Icon]) => (
          <div key={`${group}/${name}`} data-export={`${group}/${name}`}>
            <Icon />
          </div>
        )),
