// A fresh canvas per mount or concept switch: a released context can't be reused, and React's
// dev double-mount would otherwise hand the second mount a dead one.
let glCanvas!: HTMLCanvasElement;
let core3d: CoreGL | null = null;
let concept = getConcept(st.coreStyle);
let builtStyle = "";
const onLost = (ev: Event) => {
  ev.preventDefault();
  core3d = null;
  glCanvas.style.visibility = "hidden";
};
const onRestored = () => {
  core3d = createCoreGL(glCanvas, concept);
  st.glSize = 0;
  glCanvas.style.visibility = core3d ? "visible" : "hidden";
};
const unmountCore = () => {
  if (!glCanvas) return;
  glCanvas.removeEventListener("webglcontextlost", onLost);
  glCanvas.removeEventListener("webglcontextrestored", onRestored);
  core3d?.dispose();
  core3d = null;
  glCanvas.remove();
};
const mountCore = () => {
  unmountCore();
  concept = getConcept(st.coreStyle);
  builtStyle = st.coreStyle;
